// ── データ読み込み ──
const root = process.cwd();
const cardMap = new Map<string, CardData>();
for (const f of [...Array.from({ length: 11 }, (_, i) => `CardData_Sheet${i + 1}.csv`), 'CardData_TK.csv']) {
  const p = join(root, 'public/data', f);
  if (!fs.existsSync(p)) continue;
  const { data } = Papa.parse<Record<string, string>>(fs.readFileSync(p, 'utf-8').replace(/^﻿/, ''), { header: true, skipEmptyLines: true });
  for (const r of data) { const id = r.CardNum?.trim(); if (id && !cardMap.has(id)) cardMap.set(id, r as unknown as CardData); }
}
const effectsMap = new Map<string, CardEffect[]>();
for (const f of ['effects_WX.json', 'effects_WXDi.json', 'effects_WX24_26.json', 'effects_WXK.json', 'effects_misc.json']) {
  const j = JSON.parse(fs.readFileSync(join(root, 'public/data', f), 'utf-8'));
  for (const [id, effs] of Object.entries(j)) effectsMap.set(id, effs as CardEffect[]);
}
for (const [id, card] of cardMap) {
  const merged = mergeManualEffects(id, (effectsMap.get(id) ?? []) as never[]);
  if (merged.length > 0) (card as { effects?: CardEffect[] }).effects = merged as CardEffect[];
}

// ── カード選定ヘルパー（属性の決まった実カードを使う）──
const findCard = (pred: (c: CardData) => boolean): string => {
  for (const c of cardMap.values()) if (pred(c)) return c.CardNum;
  throw new Error('該当カードなし');
};
const isSigni = (c: CardData) => c.Type === 'シグニ';
const SIGNI = findCard(c => isSigni(c) && parseInt(c.Power || '0') > 0);
const SIGNI_P3000 = findCard(c => isSigni(c) && c.Power === '3000');
const SIGNI_P12000 = findCard(c => isSigni(c) && c.Power === '12000');
const SIGNI_L1 = findCard(c => isSigni(c) && c.Level === '1');
const SIGNI_L2 = findCard(c => isSigni(c) && c.Level === '2');
const SIGNI_L3 = findCard(c => isSigni(c) && c.Level === '3');
const SIGNI_L4 = findCard(c => isSigni(c) && c.Level === '4');
// engine は cardMap.get(インスタンスID) で照合するため、インスタンスID＝素のCardNum（#suffixなし）を使う。
// 重複でゾーン間が混ざらないよう、全シグニから distinct に払い出すカーソル方式。
const POOL = [...cardMap.values()].filter(isSigni).map(c => c.CardNum);
let cursor = 0;
const fresh = () => { const v = POOL[cursor % POOL.length]; cursor++; return v; };
const fill = (n: number) => Array.from({ length: n }, () => fresh());
const withSavedCursor = (fn: () => void) => {
  const savedCursor = cursor;
  try { fn(); } finally { cursor = savedCursor; }
};

// ── 盤面ビルダー ──
interface StateOpts { signi?: (string | null)[]; deckTop?: string[]; hand?: number; trash?: number; energy?: number; life?: number; coins?: number; down?: boolean[]; lrig?: string[]; assistL?: string[]; assistR?: string[]; }
function mkState(o: StateOpts = {}): PlayerState {
  return {
    deck: [...(o.deckTop ?? []), ...fill(20)],
    lrig_deck: [], hand: fill(o.hand ?? 5), life_cloth: fill(o.life ?? 7),
    trash: fill(o.trash ?? 3), lrig_trash: [], energy: fill(o.energy ?? 5), coins: o.coins ?? 3, bonds: [],
    field: {
      lrig: o.lrig ?? [], signi: o.signi ? o.signi.map(s => (s ? [s] : null)) : [null, null, null],
      signi_down: o.down ?? [false, false, false], signi_frozen: [false, false, false],
      assist_lrig_l: o.assistL ?? [], assist_lrig_r: o.assistR ?? [], check: null, key_piece: null, free_zone: [], signi_traps: [null, null, null],
    },
  } as unknown as PlayerState;
}
function mkCtx(owner: StateOpts, other: StateOpts, sourceInst?: string): ExecCtx {
  return {
    ownerState: mkState(owner), otherState: mkState(other),
    cardMap: cardMap as Map<string, CardData>, logs: [],
    sourceCardNum: sourceInst, triggeringCardNum: sourceInst, currentPhase: 'MAIN',
  } as unknown as ExecCtx;
}

// ── オートパイロット（最終 ExecResult を返す）──
function run(eff: EffectAction, ctx: ExecCtx): ExecResult {
  const result = executeEffect({ effectId: 't', effectType: 'AUTO', action: eff, duration: 'INSTANT', mandatory: true } as CardEffect, ctx);
  return finish(result, ctx);
}
function finish(initial: ExecResult, ctx: ExecCtx): ExecResult {
  let result = initial;
  let steps = 0;
  while (!result.done) {
    if (++steps > 40) throw new Error('autopilot hang');
    const pending = (result as { pending: { type: string; [k: string]: unknown } }).pending;
    const p = pending as Record<string, unknown>;
    const c: ExecCtx = {
      ...ctx, ownerState: result.ownerState, otherState: result.otherState, logs: result.logs,
      lastProcessedCards: result.lastProcessedCards,
      storedTargetCards: result.storedTargetCards ?? ctx.storedTargetCards,
    };
    switch (pending.type) {
      case 'SELECT_TARGET': { const cands = (p.candidates as string[]) ?? []; result = resumeSelectTarget(cands.slice(0, Math.min((p.count as number) ?? 1, cands.length)), pending as never, c); break; }
      case 'SEARCH': { const vis = (p.visibleCards as string[]) ?? []; result = resumeSearch(vis.slice(0, Math.min((p.maxPick as number) ?? 0, vis.length)), pending as never, c); break; }
      case 'CHOOSE': { const opts = (p.options as { id: string; available?: boolean }[]) ?? []; const pick = opts.find(o => o.available !== false) ?? opts[0]; result = resumeChoose(pick.id, pending as never, c); break; }
      case 'LOOK_AND_REORDER': result = resumeLookAndReorder((p.cards as string[]) ?? [], [], pending as never, c); break;
      case 'REVEAL_CARDS': result = resumeRevealCards(pending as never, c); break;
      case 'SELECT_ZONE': result = resumeSelectZone(steps % 3, pending as never, c); break;
      case 'SELECT_SIGNI_ZONE': result = resumeSelectSigniZone(steps % 3, pending as never, c); break;
      case 'SELECT_VIRUS_ZONE': result = resumeSelectVirusZone(steps % 3, pending as never, c); break;
      default: throw new Error(`unhandled pending ${pending.type}`);
    }
  }
  return result;
}

function finishPayingCosts(initial: ExecResult, ctx: ExecCtx): ExecResult {
  let result = initial;
  for (let steps = 0; !result.done; steps++) {
    if (steps > 40) throw new Error('cost autopilot hang');
    const pending = result.pending;
    const c: ExecCtx = {
      ...ctx, ownerState: result.ownerState, otherState: result.otherState, logs: result.logs,
      lastProcessedCards: result.lastProcessedCards,
      storedTargetCards: result.storedTargetCards ?? ctx.storedTargetCards,
    };
    if (pending.type === 'SELECT_TARGET') {
      result = resumeSelectTarget(pending.candidates.slice(0, pending.count), pending, c);
    } else if (pending.type === 'CHOOSE') {
      const pick = pending.options.find(o => o.available !== false) ?? pending.options[0];
      const n = pick.costColors?.length ?? 0;
      result = pending.opponentResponds
        ? resumeOpponentPayOptional(pick.id, c.otherState.energy.slice(0, n), pending, c)
        : n > 0
          ? resumeOptionalCost(pick.id, c.ownerState.energy.slice(0, n), pending, c)
          : resumeChoose(pick.id, pending, c);
    } else {
      throw new Error(`unhandled cost pending ${pending.type}`);
    }
  }
  return result;
}

// GRANT_LRIG_ABILITY / GRANT_FIELD_SIGNI_ABILITY 等の `abilities` へ入れ子化された付与能力も
// effectId で引ける深さ優先探索（タスク12(l) で 47 効果がトップレベルから入れ子へ移った）。
function findEffectDeep(effects: readonly CardEffect[], effectId: string): CardEffect | undefined {
  for (const e of effects) {
    if (e.effectId === effectId) return e;
    const abilities = (e.action as { abilities?: CardEffect[] } | undefined)?.abilities;
    if (Array.isArray(abilities)) {
      const hit = findEffectDeep(abilities, effectId);
      if (hit) return hit;
    }
  }
  return undefined;
}
function manualEffect(cardNum: string, effectId: string): CardEffect {
  const effect = findEffectDeep(mergeManualEffects(cardNum, effectsMap.get(cardNum) ?? []), effectId);
  if (!effect) throw new Error(`${effectId} not found`);
  return effect;
}

// ── テストフレームワーク ──
//
// 開発ループ用のテスト名フィルタ（2026-08-25 追加。全件は1回 約88秒かかるので、1本直すたびに全部走らせない）
//   npm run golden                          … 従来どおり全件（引数なし＝挙動も出力行数も一切変わらない）
//   npm run golden -- --only "O-65"         … テスト名の部分一致で絞る（--only は複数指定可＝OR）
//   npm run golden -- --list                … 全テスト名を列挙する（フィルタ文字列を探すのに使う）
//
// 🔴 フィルタ実行の PASS/FAIL は全件実行と等価ではない。下の POOL カーソル `cursor` は
//    モジュールグローバルの可変状態で、`fill()`／`mkState()` 経由でテストごとに前進する
//    ＝テストをスキップすると後続テストが引くカードが変わる（一部のテストが `withSavedCursor`
//    で退避しているのはこのため）。**通るはずのテストが落ちる／落ちるはずのテストが通る**の
//    両方向に化けうるので、**1巡を閉じる前に必ずフィルタなしで全件を回すこと**（PLAN §2.1 ④）。
// 🔴 0件マッチは exit 1 で落とす（タイプミスが「PASS 0 / FAIL 0」＝緑に見える vacuous PASS を作らない）。
// ⚠ `npm run gates`（scripts/runGates.mjs:38）と CI は引数なしで spawn する＝常に全件。ここは変えない。
const goldenArgv = process.argv.slice(2);
const onlyFilters: string[] = [];
for (let i = 0; i < goldenArgv.length; i++) {
  const a = goldenArgv[i] ?? '';
  if (a === '--only') { const v = goldenArgv[i + 1]; if (v) { onlyFilters.push(v); i++; } }
  else if (a.startsWith('--only=')) { const v = a.slice('--only='.length); if (v) onlyFilters.push(v); }
}
const listMode = goldenArgv.includes('--list');
const listedNames: string[] = [];
let ranCount = 0, skippedCount = 0;

let pass = 0; const fails: string[] = [];
function test(name: string, fn: () => void) {
  if (listMode) { listedNames.push(name); return; }
  if (onlyFilters.length && !onlyFilters.some(f => name.includes(f))) { skippedCount++; return; }
  ranCount++;
  try { fn(); pass++; } catch (e) { fails.push(`${name}: ${(e as Error).message}`); }
}
function eq(a: unknown, b: unknown, m = '') { if (a !== b) throw new Error(`${m} expected=${b} got=${a}`); }
function ok(c: boolean, m = '') { if (!c) throw new Error(m || 'assert false'); }
const tops = (st: PlayerState) => st.field.signi.map(s => s?.at(-1) ?? null);

// ── task12(lxxxii) 第6波：CHOOSE ヘッダの「まで」＝upTo と、文中 CHOOSE 救済の前置拡張 ──
// buildChoose の全呼び出し元が「Mつ**まで**選ぶ」の「まで」を捨てて丁度M個必須に潰していた
// （ベット/リコレクト経路だけが upTo を立てていた）。live 32効果が upTo 欠落だった。
{
  const findChooses = (a: unknown, out: Record<string, unknown>[] = []): Record<string, unknown>[] => {
    if (!a || typeof a !== 'object') return out;
    const o = a as Record<string, unknown>;
    if (o.type === 'CHOOSE') out.push(o);
    for (const v of Object.values(o)) {
      if (Array.isArray(v)) v.forEach(x => findChooses(x, out));
      else if (v && typeof v === 'object') findChooses(v, out);
    }
    return out;
  };
  const freshEff = (card: string, effId: string) => {
    const e = parseCardEffects(cardMap.get(card)!).find(x => x.effectId === effId);
    if (!e) throw new Error(`${effId} not found in fresh`);
    return e;
  };

  test('task12(lxxxii) wave6: 「Mつまで選ぶ」は upTo=true、「Mつ選ぶ」は upTo を立てない', () => {
    // 先頭形「以下の４つから２つまで選ぶ」（live JSON へ採用済み）
    const burst = findChooses(manualEffect('WX21-058', 'WX21-058-BURST').action);
    eq(burst.length, 1, 'WX21-058-BURST の CHOOSE 本数');
    eq(burst[0].choose_count, 2, 'choose_count');
    eq(burst[0].from_count, 4, 'from_count');
    eq(burst[0].upTo, true, '「２つまで」は upTo=true');
    // 「まで」が無い形は upTo を立てない（過剰な緩和の防止）
    const strict = findChooses(manualEffect('WD21-008', 'WD21-008-E1').action);
    eq(strict.length, 1, 'WD21-008-E1 の CHOOSE 本数');
    eq(strict[0].choose_count, 1, 'choose_count');
    ok(strict[0].upTo === undefined, '「１つを選ぶ」に upTo を付けてはいけない');
  });

  test('task12(lxxxii) wave6: WX20-007-E1 は前置の任意支払いSTUB＋コストmarkerを残して文中CHOOSEを復元する', () => {
    const action = freshEff('WX20-007', 'WX20-007-E1').action as unknown as { type: string; steps: Record<string, unknown>[] };
    eq(action.type, 'SEQUENCE', 'トップは SEQUENCE');
    // ⚠タスク12(lxxxv) で前置は1本になった＝「＜精像＞のシグニを２枚まで捨ててもよい」は**使用時**の
    //   支払い（`useTimeCost.ts` ＋ ArtsModal）へ移したので、解決中の `OPTIONAL_DISCARD_CLASS_SIGNI` は落とす。
    //   残さないと使用時に払った上で解決中にもう一度払わされる（engine 側は実装済みで実際に払わせる）。
    eq(action.steps.length, 2, 'コスト減marker＋CHOOSE');
    eq(action.steps[0].type, 'STUB', 'step0 は STUB');
    eq(action.steps[0].id, 'ARTS_COST_REDUCTION_BY_EFFECT', 'コスト減 marker は前段に残す');
    ok(!JSON.stringify(action.steps).includes('OPTIONAL_DISCARD_CLASS_SIGNI'),
      '解決中の任意支払いSTUBは残さない（使用時に支払い済み）');
    const choose = action.steps[1] as Record<string, unknown>;
    eq(choose.type, 'CHOOSE', 'step2 は CHOOSE');
    eq(choose.choose_count, 2, '「３つから２つまで」の選択数');
    eq(choose.from_count, 3, '選択肢は3本');
    eq(choose.upTo, true, '「２つまで」は upTo=true');
    const choices = choose.choices as { action: Record<string, unknown> }[];
    eq(choices[0].action.type, 'BANISH', '①レベル３以下バニッシュ');
    eq(choices[1].action.type, 'POWER_MODIFY', '②パワー修正');
    eq((choices[1].action as { delta: number }).delta, -12000, '②は－12000');
    // ③「それを場に出す。それの【出】能力は発動しない」＝配置アンカーへ畳まれる（宙に浮く BLOCK を残さない）
    const third = JSON.stringify(choices[2].action);
    ok(third.includes('"suppressOnPlay":true'), '③は suppressOnPlay へ畳む');
    ok(!third.includes('ON_PLAY_ABILITY'), '③に宙ぶらりんの BLOCK_ACTION を残さない');
  });

  test('task12(lxxxii) wave6: 採用した文中CHOOSE 5効果は選択肢が復元され平坦化した強制実行に戻らない', () => {
    // live は「選択肢が1本だけ残って平坦化＝強制実行」だった（幻覚混線を含む）。
    const expected: [string, string, number, number][] = [
      ['WXK05-002', 'WXK05-002-E1', 3, 3],
      ['WXK05-004', 'WXK05-004-E1', 2, 4],
      ['WXK07-002', 'WXK07-002-E1', 2, 4],
      ['WXK08-001', 'WXK08-001-E1', 2, 3],
      ['WXK08-003', 'WXK08-003-E1', 2, 3],
    ];
    for (const [card, effId, chooseCount, fromCount] of expected) {
      const chooses = findChooses(manualEffect(card, effId).action);
      eq(chooses.length, 1, `${effId}: CHOOSE 本数`);
      eq(chooses[0].choose_count, chooseCount, `${effId}: choose_count`);
      eq(chooses[0].from_count, fromCount, `${effId}: from_count`);
      eq(chooses[0].upTo, true, `${effId}: 「まで」＝upTo`);
      // 使用コスト修飾 marker は CHOOSE の前段に残す（消すと減額が読めなくなる）
      const steps = (manualEffect(card, effId).action as unknown as { steps?: { type: string; id?: string }[] }).steps ?? [];
      ok(steps.some(s => s.type === 'STUB' && s.id === 'ARTS_COST_REDUCTION_BY_CENTER_LRIG'),
        `${effId}: センタールリグ条件のコスト減 marker を前段に保持`);
    }
  });

  test('task12(lxxxii) wave6: WXK08-003-E1 ③ は「対戦相手がアーツかスペル使用」ORゲートを保つ（無条件トラッシュにしない）', () => {
    const choose = findChooses(manualEffect('WXK08-003', 'WXK08-003-E1').action)[0];
    const third = (choose.choices as { action: Record<string, unknown> }[])[2].action;
    eq(third.type, 'CONDITIONAL', '③は条件つき');
    const cond = third.condition as { type: string; conditions: { type: string; owner: string }[] };
    eq(cond.type, 'OR', 'アーツ「か」スペル＝OR');
    eq(cond.conditions.length, 2, 'OR の枝は2本');
    eq(cond.conditions[0].type, 'ARTS_USED_THIS_TURN', '枝1＝アーツ使用');
    eq(cond.conditions[0].owner, 'opponent', '主語は対戦相手');
    eq(cond.conditions[1].type, 'SPELL_USED_THIS_TURN', '枝2＝スペル使用');
    eq(cond.conditions[1].owner, 'opponent', '主語は対戦相手');
    eq((third.then as { type: string }).type, 'TRASH', '成立時のみトラッシュ');
  });

  test('task12(lxxxii) wave6: curated 直書き上書き（WX05系）と MANUAL 温存分にも upTo が乗る', () => {
    // effectParser の STATE_COND_BATCH4_ACTIONS 直書き＝upTo 対応前の記述だった
    for (const card of ['WX05-052', 'WX05-059', 'WX05-066', 'WX05-073']) {
      const chooses = findChooses(manualEffect(card, `${card}-E1`).action);
      eq(chooses.length, 1, `${card}: CHOOSE 本数`);
      eq(chooses[0].upTo, true, `${card}: 「２つまで」＝upTo`);
    }
    // MANUAL（PRESERVE 保護）は build:effects で fresh が届かないため外科パッチ済み
    for (const [card, effId] of [['WXDi-P10-004', 'WXDi-P10-004-E1'], ['WXDi-P16-048', 'WXDi-P16-048-E1']]) {
      const chooses = findChooses(manualEffect(card, effId).action);
      eq(chooses.length, 1, `${effId}: CHOOSE 本数`);
      eq(chooses[0].upTo, true, `${effId}: 「２つまで」＝upTo`);
    }
  });
}

test('task12(lxxxii) wave4: FISHING optional discard changes 1/2 choices and both life-burst branches resolve', () => withSavedCursor(() => {
  const SOURCE = 'WD23-044-EA';
  const effect = manualEffect(SOURCE, 'WD23-044-EA-E1');
  const burstTrash = findCard(c => !!c.BurstText && c.BurstText !== '-' && c.CardNum !== SOURCE);
  const burstDeck = burstTrash;
  const costCard = SIGNI;

  const open = (pay: boolean) => {
    const base = mkCtx({}, {}, SOURCE);
    base.ownerState = { ...base.ownerState, hand: [costCard], trash: [SOURCE, burstTrash], deck: [burstDeck] };
    const first = executeEffect(effect, base);
    ok(!first.done && first.pending.type === 'SELECT_TARGET', 'スペルの任意手札捨てが最初に提示される');
    if (first.done || first.pending.type !== 'SELECT_TARGET') throw new Error('discard pending missing');
    const discarded = resumeSelectTarget(pay ? [costCard] : [], first.pending, execCtxFrom(first, base));
    ok(!discarded.done && discarded.pending.type === 'CHOOSE', '①②の選択肢が提示される');
    if (discarded.done || discarded.pending.type !== 'CHOOSE') throw new Error('choice pending missing');
    return { base, result: discarded, pending: discarded.pending };
  };

  const unpaidTrash = open(false);
  eq(unpaidTrash.pending.count, 1, '追加コスト未払いは1つ選ぶ');
  eq(unpaidTrash.pending.options.length, 2, '未払いでも①②の2候補を提示');
  const trashPick = resumeChoose('cae_life_burst_from_trash', unpaidTrash.pending, execCtxFrom(unpaidTrash.result, unpaidTrash.base));
  const trashDone = trashPick.done
    ? trashPick
    : trashPick.pending.type === 'SELECT_TARGET'
      ? resumeSelectTarget([burstTrash], trashPick.pending, execCtxFrom(trashPick, unpaidTrash.base))
      : (() => { throw new Error('trash target missing'); })();
  ok(trashDone.done && trashDone.ownerState.hand.includes(burstTrash), '①トラッシュのLB持ちが手札へ移る');
  ok(!trashDone.ownerState.trash.includes(burstTrash), '①回収元から除かれる');

  const unpaidDeck = open(false);
  const deckPick = resumeChoose('cae_life_burst_from_deck', unpaidDeck.pending, execCtxFrom(unpaidDeck.result, unpaidDeck.base));
  ok(!deckPick.done && deckPick.pending.type === 'SEARCH', '②はデッキ探索を提示');
  if (deckPick.done || deckPick.pending.type !== 'SEARCH') throw new Error('deck search missing');
  const deckDone = resumeSearch([burstDeck], deckPick.pending, execCtxFrom(deckPick, unpaidDeck.base));
  ok(deckDone.done && deckDone.ownerState.hand.includes(burstDeck), '②デッキのLB持ちが手札へ移る');
  ok(!deckDone.ownerState.deck.includes(burstDeck), '②探索元から除かれる');

  const paid = open(true);
  eq(paid.pending.count, 2, '追加コスト支払いは2つ選ぶ');
  eq(paid.pending.multiSelect, true, '支払い時は複数選択');
  eq(paid.pending.options.length, 2, '支払い時も①②の2候補');
  ok(paid.result.ownerState.trash.includes(costCard), '追加コストの手札1枚が実際にトラッシュへ移る');
}));

test('task12(lxxxii) wave4: ARTS class-energy optional cost records payment for 1/2 choice count', () => withSavedCursor(() => {
  const SOURCE = 'WX26-CP1-024';
  const effect = manualEffect(SOURCE, 'WX26-CP1-024-E1');
  const prioke = [...cardMap.values()].filter(c => (c.CardClass ?? '').includes('プリオケ')).slice(0, 3).map(c => c.CardNum);
  ok(prioke.length === 3, '＜プリオケ＞を3枚用意');
  const open = (pay: boolean) => {
    const base = mkCtx({}, {}, SOURCE);
    base.ownerState = { ...base.ownerState, energy: [...prioke], trash: [], field: { ...base.ownerState.field, check: SOURCE } };
    const first = executeEffect(effect, base);
    ok(!first.done && first.pending.type === 'CHOOSE', '任意支払いを提示');
    if (first.done || first.pending.type !== 'CHOOSE') throw new Error('arts pay pending missing');
    const selected = resumeChoose(pay ? 'pay' : 'skip', first.pending, execCtxFrom(first, base));
    if (!pay) return { base, result: selected };
    ok(!selected.done && selected.pending.type === 'SELECT_TARGET', '支払う3枚を選択');
    if (selected.done || selected.pending.type !== 'SELECT_TARGET') throw new Error('arts energy target missing');
    return { base, result: resumeSelectTarget(prioke, selected.pending, execCtxFrom(selected, base)) };
  };
  const unpaid = open(false).result;
  ok(!unpaid.done && unpaid.pending.type === 'CHOOSE', '未払い後に効果選択');
  if (unpaid.done || unpaid.pending.type !== 'CHOOSE') throw new Error('unpaid arts choice missing');
  eq(unpaid.pending.count, 1, '未払いは1つ選ぶ');
  const paid = open(true).result;
  ok(!paid.done && paid.pending.type === 'CHOOSE', '支払い後に効果選択');
  if (paid.done || paid.pending.type !== 'CHOOSE') throw new Error('paid arts choice missing');
  eq(paid.pending.count, 2, '支払いは2つ選ぶ');
  eq(paid.pending.multiSelect, true, '支払い時は複数選択');
  eq(paid.ownerState.energy.length, 0, '＜プリオケ＞3枚を実際にエナから支払う');
  eq(paid.ownerState.trash.length, 3, '支払った3枚がトラッシュへ移る');
  eq(paid.ownerState.self_optional_effect_taken, false, '支払いフラグは選択数へ反映後に消費する');
}));

test('task12(lxxxii) wave4 guard: existing conditional multi-choose cards remain 2 choices after payment', () => withSavedCursor(() => {
  for (const [SOURCE, effectId] of [['SP26-005', 'SP26-005-E1'], ['SP38-004', 'SP38-004-E1']] as const) {
    const effect = manualEffect(SOURCE, effectId);
    const base = mkCtx({}, {}, SOURCE);
    base.ownerState = { ...base.ownerState, energy: fill(8), field: { ...base.ownerState.field, check: SOURCE } };
    const pay = executeEffect(effect, base);
    ok(!pay.done && pay.pending.type === 'CHOOSE', `${effectId}: 追加コスト選択`);
    if (pay.done || pay.pending.type !== 'CHOOSE') throw new Error(`${effectId}: pay pending missing`);
    const actualCost = resumeChoose('pay', pay.pending, execCtxFrom(pay, base));
    ok(!actualCost.done && actualCost.pending.type === 'CHOOSE', `${effectId}: 実コスト選択`);
    if (actualCost.done || actualCost.pending.type !== 'CHOOSE') throw new Error(`${effectId}: actual cost pending missing`);
    const choices = resumeChoose('pay', actualCost.pending, execCtxFrom(actualCost, base));
    ok(!choices.done && choices.pending.type === 'CHOOSE', `${effectId}: 支払い後の効果選択`);
    if (choices.done || choices.pending.type !== 'CHOOSE') throw new Error(`${effectId}: effect choices missing`);
    eq(choices.pending.count, 2, `${effectId}: count=2`);
    eq(choices.pending.options.length, 2, `${effectId}: 選択肢2個`);
    eq(choices.pending.multiSelect, true, `${effectId}: multiSelect=true`);
  }
}));

test('task12(lxxxii) wave5: PR-Di013 manual and live JSON grant 3 attack abilities, paid multi-choice grants both, once/turn and EOT apply', () => withSavedCursor(() => {
  const SOURCE = 'PR-Di013';
  const liveEffect = effectsMap.get(SOURCE)?.find(e => e.effectId === 'PR-Di013-E1');
  ok(!!liveEffect, '実機JSONにPR-Di013-E1が存在する');
  const verify = (effect: CardEffect) => {
  const open = (pay: boolean) => {
    const base = mkCtx({ deckTop: fill(4), hand: 0, lrig: fill(5) }, { signi: [SIGNI, null, null] }, SOURCE);
    // スペルの実戦発生源ゾーン（使用中カード）は check。
    base.ownerState = { ...base.ownerState, field: { ...base.ownerState.field, check: SOURCE } };
    const offered = executeEffect(effect, base);
    ok(!offered.done && offered.pending.type === 'CHOOSE', 'エクシード4のpay/skip提示');
    if (offered.done || offered.pending.type !== 'CHOOSE') throw new Error('optional exceed missing');
    const afterCost = resumeChoose(pay ? 'pay' : 'skip', offered.pending, execCtxFrom(offered, base));
    ok(!afterCost.done && afterCost.pending.type === 'CHOOSE', '能力3択を提示');
    if (afterCost.done || afterCost.pending.type !== 'CHOOSE') throw new Error('ability choice missing');
    eq(afterCost.pending.options.length, 3, '①②③の3候補');
    eq(afterCost.pending.count, pay ? 2 : 1, pay ? '支払い時は2つ' : '未払い時は1つ');
    eq(afterCost.pending.multiSelect, pay ? true : undefined, '支払い時だけ複数選択');
    return { base, afterCost };
  };

  const unpaid = open(false);
  const handBefore = unpaid.afterCost.ownerState.hand.length;
  const grantedDraw = resumeChoose('draw', unpaid.afterCost.pending as never, execCtxFrom(unpaid.afterCost, unpaid.base));
  ok(grantedDraw.done, '①付与は即時解決');
  eq(grantedDraw.ownerState.hand.length, handBefore, '選択直後はドローしない');
  const drawAbility = grantedDraw.ownerState.lrig_granted_auto_effects?.find(e => e.effectId === 'PR-Di013-E1-G-DRAW');
  ok(!!drawAbility, 'センタールリグへ①AUTOを付与');
  eq(drawAbility!.usageLimit, 'once_per_turn', '《ターン1回》');
  const attackCtx = { ...unpaid.base, ownerState: grantedDraw.ownerState, otherState: grantedDraw.otherState };
  const firstAttack = finish(executeEffect(drawAbility!, attackCtx), attackCtx);
  eq(firstAttack.ownerState.hand.length, handBefore + 1, 'ルリグアタック時に1枚引く');
  const used = { ...firstAttack.ownerState, actions_done: [...(firstAttack.ownerState.actions_done ?? []), drawAbility!.effectId] };
  const secondAttackCandidates = (used.lrig_granted_auto_effects ?? []).filter(e =>
    e.timing?.includes('ON_ATTACK_LRIG') && !used.actions_done.includes(e.effectId));
  eq(secondAttackCandidates.length, 0, '同一ターン2回目は発火しない');
  const nextTurn = { ...used, actions_done: [], lrig_granted_auto_effects: used.lrig_granted_auto_effects?.filter(e => e.permanentGrant) };
  eq(nextTurn.lrig_granted_auto_effects?.length ?? 0, 0, 'ターン終了時に付与能力が消える');

  const paid = open(true);
  const both = resumeChoose(['energy', 'trash'], paid.afterCost.pending as never, execCtxFrom(paid.afterCost, paid.base));
  ok(both.done, '複数選択した2枝を両方実行');
  const ids = (both.ownerState.lrig_granted_auto_effects ?? []).map(e => e.effectId);
  ok(ids.includes('PR-Di013-E1-G-ENERGY') && ids.includes('PR-Di013-E1-G-TRASH'), '②③を両方付与');
  eq(both.ownerState.self_optional_effect_taken, false, '支払い結果フラグを選択数反映後に消費');
  };
  verify(manualEffect(SOURCE, 'PR-Di013-E1'));
  verify(liveEffect!);
}));

test('frontOfSelf WXK11-029-E2: only the opposing front SIGNI loses abilities; empty front is no-op', () => {
  const host = 'WXK11-029';
  const front = SIGNI_L2;
  const side = SIGNI_L3;
  const ownOther = SIGNI_L4;
  const effect = manualEffect(host, 'WXK11-029-E2');
  const hit = finish(executeEffect(effect, mkCtx({ signi: [host, ownOther, null] }, { signi: [side, null, front] }, host)), mkCtx({}, {}, host));
  ok(hit.otherState.abilities_removed?.includes(front), 'front opponent loses abilities');
  ok(!hit.otherState.abilities_removed?.includes(side), 'non-front opponent is unaffected');
  ok(!hit.ownerState.abilities_removed?.includes(ownOther), 'own SIGNI is unaffected');
  const emptyCtx = mkCtx({ signi: [host, ownOther, null] }, { signi: [side, null, null] }, host);
  const empty = finish(executeEffect(effect, emptyCtx), emptyCtx);
  eq(empty.otherState.abilities_removed?.length ?? 0, 0, 'empty front is no-op');
  ok(tops(empty.ownerState).includes(ownOther), 'empty front does not harm own SIGNI');
});

test('frontOfSelf WXK04-072-E2: front-only BANISH keeps powerRange as an AND filter', () => {
  const host = 'WXK04-072';
  const side = SIGNI_L3;
  const ownOther = SIGNI_L4;
  const effect = manualEffect(host, 'WXK04-072-E2');
  const hitCtx = mkCtx({ signi: [host, ownOther, null] }, { signi: [side, null, SIGNI_P3000] }, host);
  const hit = finish(executeEffect(effect, hitCtx), hitCtx);
  eq(tops(hit.otherState)[2], null, 'front power 3000 is banished');
  eq(tops(hit.otherState)[0], side, 'non-front opponent is unaffected');
  ok(tops(hit.ownerState).includes(ownOther), 'own SIGNI is unaffected');
  const highCtx = mkCtx({ signi: [host, ownOther, null] }, { signi: [side, null, SIGNI_P12000] }, host);
  const high = finish(executeEffect(effect, highCtx), highCtx);
  eq(tops(high.otherState)[2], SIGNI_P12000, 'front power over 3000 is not banished');
  const emptyCtx = mkCtx({ signi: [host, ownOther, null] }, { signi: [side, null, null] }, host);
  const empty = finish(executeEffect(effect, emptyCtx), emptyCtx);
  eq(tops(empty.otherState)[0], side, 'empty front does not fall back to another opponent');
});

