// ── SELF_PLAY_RESTRICT（自身出撃制限・Opusタスク12(xlix)）──
// 「【常】：このシグニは〜（新たに）場に出すことができない」を SELF_PLAY_RESTRICT へ正 parse し、
// canSelfPlay が never/condition で通常召喚可否をゲートする（旧来は bare ADD_TO_FIELD へ誤 parse＝inert no-op）。
test('(xlix) parse: 11枚が SELF_PLAY_RESTRICT へ（ADD_TO_FIELD 誤 parse を解消）', () => {
  const ids = ['PR-470B', 'WD16-016', 'WDK16-05H', 'WDK16-05S', 'WDK16-05T', 'WX08-025', 'WX12-022', 'WX14-033', 'WX18-075', 'WX19-030', 'WXK05-032'];
  for (const id of ids) {
    const e1 = (effectsMap.get(id) ?? [])[0];
    ok(e1?.action?.type === 'SELF_PLAY_RESTRICT', `${id}-E1 は SELF_PLAY_RESTRICT (実際:${e1?.action?.type})`);
    ok(e1?.effectType === 'CONTINUOUS', `${id}-E1 は CONTINUOUS`);
  }
  // never（無条件・効果でのみ配置可）
  ok((effectsMap.get('WXK05-032')![0].action as { never?: boolean }).never === true, 'WXK05-032 は never');
  ok((effectsMap.get('PR-470B')![0].action as { never?: boolean }).never === true, 'PR-470B（効果以外によっては）は never');
  // condition（WX12-022=パワー10000以上のシグニ / WX14-033=＜アーム＞2体以上）
  eq((effectsMap.get('WX12-022')![0].action as { condition?: { type: string } }).condition?.type, 'FIELD_SIGNI_POWER_COUNT', 'WX12-022 は FIELD_SIGNI_POWER_COUNT');
  eq((effectsMap.get('WX14-033')![0].action as { condition?: { type: string } }).condition?.type, 'FIELD_CLASS_COUNT', 'WX14-033 は FIELD_CLASS_COUNT');
});

test('レゾナ出現条件: 全55枚を実効果と分離したメタデータへ構造化', () => {
  const savedCursor = cursor;
  try {
    const resonaCards = [...cardMap.values()].filter(c => c.EffectText?.includes('【出現条件】'));
    eq(resonaCards.length, 55, 'CSV母集団');
    const appearances = resonaCards.map(card => {
      const parsed = parseCardEffects(card);
      const appearance = parsed.find(e => e.appearanceCondition)?.appearanceCondition;
      ok(!!appearance, `${card.CardNum}: appearanceCondition`);
      // 出現条件のために実効果件数を増やしていないことも固定する。
      eq(parsed.filter(e => e.effectId.endsWith('-APPEAR')).length, 0, `${card.CardNum}: 擬似実効果なし`);
      return appearance!;
    });
    eq(appearances.filter(a => a.paymentShape === 'SINGLE_ZONE').length, 14, 'メイン＋単一ゾーン文型');
    eq(appearances.filter(a => a.paymentShape === 'REQUIRES_NEW_FLOW').length, 41, '複数グループ混在3枚を含む共通支払いフロー文型');

    const field = parseCardEffects(cardMap.get('WX08-006')!).find(e => e.appearanceCondition)!.appearanceCondition!;
    eq(field.timings[0], 'MAIN', 'WX08-006 timing');
    eq(field.cost.fieldTrash?.count, 2, 'WX08-006 場2体');
    eq(field.cost.fieldTrash?.filter?.story, '凶蟲', 'WX08-006 クラス');
    eq(field.cost.fieldTrash?.filter?.excludeResona, true, 'WX08-006 非レゾナ');

    const crossZone = parseCardEffects(cardMap.get('WX12-006')!).find(e => e.appearanceCondition)!.appearanceCondition!;
    eq(crossZone.combinedTrash?.count, 3, 'WX12-006 合計3枚');
    eq(crossZone.combinedTrash?.zones.join(','), 'hand,energy', 'WX12-006 手札＋エナ');
    eq(crossZone.combinedTrash?.filter.story, '遊具', 'WX12-006 クラス');

    const aggregate = parseCardEffects(cardMap.get('WX07-006')!).find(e => e.appearanceCondition)!.appearanceCondition!;
    eq(aggregate.combinedTrash?.count, 3, 'WX07-006 3体');
    eq(aggregate.combinedTrash?.totalLevelMin, 7, 'WX07-006 レベル合計7以上');

    const choice = parseCardEffects(cardMap.get('WD11-008')!).find(e => e.appearanceCondition)!.appearanceCondition!;
    eq(choice.choice?.choose, 2, 'WD11-008 3項目から2つ');
    eq(choice.choice?.options.length, 3, 'WD11-008 選択肢3件');

    const builtCount = [...effectsMap.values()].filter(es => es.some(e => e.appearanceCondition)).length;
    eq(builtCount, 55, '生成effects JSONにも55枚すべて収録');
  } finally {
    cursor = savedCursor;
  }
});
test('レゾナ召喚: 条件を払える時だけ候補になり、原子的支払い・配置後に既存ON_PLAY効果を解決', () => {
  const savedCursor = cursor;
  try {
    const resona = 'WX07-009'; // 白の非レゾナシグニ2体を場からトラッシュ
    const whiteA = findCard(c => c.Type === 'シグニ' && c.Color?.includes('白'));
    const whiteB = findCard(c => c.Type === 'シグニ' && c.Color?.includes('白') && c.CardNum !== whiteA);
    const base = mkState({ signi: [whiteA, null, null] });
    base.lrig_deck = [resona];
    eq(getMainSingleZoneResonaCandidate(resona, base, cardMap, effectsMap), null, '支払い対象1体では候補外');

    const payable: PlayerState = {
      ...base,
      field: { ...base.field, signi: [[whiteA], [whiteB], null] },
    };
    const candidate = getMainSingleZoneResonaCandidate(resona, payable, cardMap, effectsMap);
    ok(!!candidate, '白の非レゾナ2体があれば候補');
    const placed = payResonaAppearanceAndPlace(
      payable, resona, candidate!.payment, { zone: 'field', indices: [0, 1] }, 2, cardMap,
    );
    ok(!!placed, '支払いと配置が同時に成功');
    eq(placed!.state.lrig_deck.includes(resona), false, 'ルリグデッキから除去');
    eq(placed!.state.field.signi[0], null, '支払い1体目を場から除去');
    eq(placed!.state.field.signi[1], null, '支払い2体目を場から除去');
    eq(placed!.state.field.signi[2]?.at(-1), resona, '空きシグニゾーンへレゾナ配置');
    ok(placed!.state.trash.includes(whiteA) && placed!.state.trash.includes(whiteB), '支払いカードはトラッシュ');
    eq(placed!.fieldTrashCostCards.join(','), `${whiteA},${whiteB}`, '中央盤面差分へ渡す場コスト識別を返す');
    eq(placed!.discardedCostCards.length, 0, '場支払いでは手札コスト識別なし');

    const onPlay = effectsMap.get(resona)!.find(e => e.effectType === 'AUTO' && e.timing?.includes('ON_PLAY'))!;
    const beforeEnergy = placed!.state.energy.length;
    const ctx = {
      ownerState: placed!.state, otherState: mkState({}), cardMap, logs: [],
      sourceCardNum: resona, triggeringCardNum: resona, currentPhase: 'MAIN',
    } as unknown as ExecCtx;
    const resolved = finish(executeEffect(onPlay, ctx), ctx);
    // 🆕§5.3 `O-122`（2026-08-28）で**この assert は反転した**。原文は
    //   「このレゾナの**出現条件で同じ名前のシグニ２体**をトラッシュに置いていた場合」なので、
    //   **別名の白シグニ2体で払ったここでは発火しない**のが正しい（旧 golden は過剰実行を固定していた）。
    eq(resolved.ownerState.energy.length, beforeEnergy,
      '🔴別名2体で払った＝出現条件の同名指定を満たさないのでチャージしない');

    // 対照＝**同名2体**で払えば従来どおり2枚チャージする（正方向）。
    const sameName: PlayerState = { ...base, field: { ...base.field, signi: [[whiteA], [whiteA], null] } };
    const cand2 = getMainSingleZoneResonaCandidate(resona, sameName, cardMap, effectsMap);
    ok(!!cand2, '同名2体でも候補になる');
    const placed2 = payResonaAppearanceAndPlace(
      sameName, resona, cand2!.payment, { zone: 'field', indices: [0, 1] }, 2, cardMap,
    );
    ok(!!placed2, '同名2体でも支払いと配置が成功');
    eq((placed2!.state.last_appearance_cost_cards ?? []).join(','), `${whiteA},${whiteA}`,
      '支払い内容が last_appearance_cost_cards に刻まれる（記録の funnel は payResonaAppearanceAndPlace の1本）');
    const ctx2 = {
      ownerState: placed2!.state, otherState: mkState({}), cardMap, logs: [],
      sourceCardNum: resona, triggeringCardNum: resona, currentPhase: 'MAIN',
    } as unknown as ExecCtx;
    const before2 = placed2!.state.energy.length;
    const resolved2 = finish(executeEffect(onPlay, ctx2), ctx2);
    eq(resolved2.ownerState.energy.length, before2 + 2, '同名2体で払えば2枚チャージする');
  } finally {
    cursor = savedCursor;
  }
});
test('レゾナ出現条件ON_TRASH: 実召喚支払いだけ発火し、通常トラッシュ・バトル・他コストでは不発', () => {
  const savedCursor = cursor;
  try {
    const hostId = 'H', guestId = 'G';
    const fires = (entries: StackEntry[], effectId: string) => entries.some(e => e.effectId === effectId);
    const paidInst = 'WX10-055#1';
    const otherWhite = 'WX10-056#1';
    const resonaInst = 'WX07-009#1'; // 白の非レゾナ2体を場からトラッシュ
    const before = mkState({ signi: [paidInst, otherWhite, null] });
    before.lrig_deck = [resonaInst];
    const candidate = getMainSingleZoneResonaCandidate(resonaInst, before, cardMap, effectsMap);
    ok(!!candidate, 'instanceId＋実戦ゾーンでレゾナ候補');
    const paid = payResonaAppearanceAndPlace(
      before, resonaInst, candidate!.payment, { zone: 'field', indices: [0, 1] }, 2, cardMap,
    );
    ok(!!paid, '実際のレゾナ召喚支払い経路を完走');
    const after = paid!.state;
    const ctx: TrigCtx = {
      hostId, guestId, activeUserId: hostId, turnPhase: 'MAIN',
      effectsMap, cardMap: cardMap as Map<string, CardData>, genId: () => 'resona-trigger',
    };
    const positive = collectTrashTriggers(ctx, paidInst, hostId, after, mkState({}), false, true, false, resonaInst);
    eq(fires(positive.entries, 'WX10-055-E1'), true, 'レゾナ出現条件の場支払いは発火');
    eq(positive.entries[0]?.cardNum, paidInst, '効果元instanceIdを保持');
    eq(positive.entries[0]?.triggeringCardNum, resonaInst, '今出たレゾナinstanceIdを保持');

    eq(fires(collectTrashTriggers(ctx, paidInst, hostId, after, mkState({}), false, true, true).entries, 'WX10-055-E1'), false, '通常の効果トラッシュは不発');
    eq(fires(collectTrashTriggers(ctx, paidInst, hostId, after, mkState({}), false, false, false).entries, 'WX10-055-E1'), false, 'バトル/ルール処理は不発');
    eq(fires(collectTrashTriggers(ctx, paidInst, hostId, after, mkState({}), false, true, false).entries, 'WX10-055-E1'), false, '他の能力コストは不発');
  } finally {
    cursor = savedCursor;
  }
});
test('レゾナ出現条件ON_TRASH: 「そのレゾナ」参照と＜クラス＞限定を保持', () => {
  const savedCursor = cursor;
  try {
    const hostId = 'H', guestId = 'G';
    const fires = (entries: StackEntry[], effectId: string) => entries.some(e => e.effectId === effectId);
    const merged = new Map(effectsMap);
    for (const id of ['WXEX1-58', 'WXEX1-72']) merged.set(id, mergeManualEffects(id, effectsMap.get(id) ?? []));
    const ctx: TrigCtx = {
      hostId, guestId, activeUserId: hostId, turnPhase: 'MAIN',
      effectsMap: merged, cardMap: cardMap as Map<string, CardData>, genId: () => 'resona-ref-trigger',
    };
    const guest = mkState({});

    const spaceCost = 'WXEX1-58#1';
    const spaceResona = 'WX07-009#1';
    const toyResona = 'WX10-019#1';
    const spaceAfter = mkState({ signi: [spaceResona, 'WX10-056#1', null] });
    const spaceEntries = collectTrashTriggers(ctx, spaceCost, hostId, spaceAfter, guest, false, true, false, spaceResona).entries;
    eq(fires(spaceEntries, 'WXEX1-58-E1'), true, '＜宇宙＞レゾナなら発火');
    eq(fires(collectTrashTriggers(ctx, spaceCost, hostId, spaceAfter, guest, false, true, false, toyResona).entries, 'WXEX1-58-E1'), false, '＜遊具＞レゾナでは不発');
    const spaceEff = spaceEntries.find(e => e.effectId === 'WXEX1-58-E1')!;
    const spaceResolved = finish(executeEffect(spaceEff.effect, {
      ownerState: spaceAfter, otherState: guest, cardMap, logs: [],
      sourceCardNum: spaceCost, triggeringCardNum: spaceEff.triggeringCardNum,
    } as unknown as ExecCtx), {
      ownerState: spaceAfter, otherState: guest, cardMap, logs: [],
      sourceCardNum: spaceCost, triggeringCardNum: spaceEff.triggeringCardNum,
    } as unknown as ExecCtx);
    ok(spaceResolved.ownerState.keyword_grants_until_opp_turn?.[spaceResona]?.some(k => k === 'PROTECTION:ルリグ:opponent'), 'そのレゾナだけに対戦相手ルリグ効果耐性');
    eq(spaceResolved.ownerState.keyword_grants_until_opp_turn?.['WX10-056#1'], undefined, '他の自シグニへは付与しない');

    const toyCost = 'WXEX1-72#1';
    const toyAfter = mkState({ signi: [toyResona, 'WX10-076#2', null] });
    const toyEntries = collectTrashTriggers(ctx, toyCost, hostId, toyAfter, guest, false, true, false, toyResona).entries;
    eq(fires(toyEntries, 'WXEX1-72-E1'), true, '＜遊具＞レゾナなら発火');
    eq(fires(collectTrashTriggers(ctx, toyCost, hostId, toyAfter, guest, false, true, false, spaceResona).entries, 'WXEX1-72-E1'), false, '＜宇宙＞レゾナでは不発');
    const toyEff = toyEntries.find(e => e.effectId === 'WXEX1-72-E1')!;
    const toyCtx = {
      ownerState: toyAfter, otherState: guest, cardMap, logs: [],
      sourceCardNum: toyCost, triggeringCardNum: toyEff.triggeringCardNum,
    } as unknown as ExecCtx;
    const toyResolved = finish(executeEffect(toyEff.effect, toyCtx), toyCtx);
    ok(toyResolved.ownerState.keyword_grants_until_opp_turn?.[toyResona]?.includes('バニッシュされない'), 'そのレゾナだけに全バニッシュ耐性');
  } finally {
    cursor = savedCursor;
  }
});
test('レゾナ出現条件 段階3: ゾーン横断・複数グループ・合計制約・3択2選を支払い確定時に再検証', () => {
  const savedCursor = cursor;
  try {
    const appearance = (id: string) =>
      parseCardEffects(cardMap.get(id)!).find(e => e.appearanceCondition)!.appearanceCondition!;
    const signis = [...cardMap.values()].filter(c => c.Type === 'シグニ');

    const toys = signis.filter(c => c.CardClass?.includes('遊具')).slice(0, 3).map(c => c.CardNum);
    const crossState = mkState({});
    crossState.hand = toys.slice(0, 2);
    crossState.energy = toys.slice(2);
    const crossPlan = appearancePayment(appearance('WX12-006'))!;
    ok(validateResonaSelection(crossState, crossPlan, { items: [
      { zone: 'hand', index: 0 }, { zone: 'hand', index: 1 }, { zone: 'energy', index: 0 },
    ] }, cardMap), '手札＋エナから合計3枚を横断選択');
    ok(!validateResonaSelection(crossState, crossPlan, { items: [
      { zone: 'hand', index: 0 }, { zone: 'energy', index: 0 },
    ] }, cardMap), '合計枚数不足は確定不可');

    const named = ['幻獣　ハチ', '幻獣　モンキ', '幻獣　キジ'].map(name =>
      signis.find(c => c.CardName === name)!.CardNum);
    const groupState = mkState({});
    groupState.field = { ...groupState.field, signi: named.map(n => [n]) };
    const groupPlan = appearancePayment(appearance('WX09-013'))!;
    ok(validateResonaSelection(groupState, groupPlan, { items: named.map((_, group) =>
      ({ zone: 'field' as const, index: group, group })) }, cardMap), '固有名3グループを1体ずつ');
    ok(!validateResonaSelection(groupState, groupPlan, { items: [
      { zone: 'field', index: 0, group: 0 }, { zone: 'field', index: 1, group: 0 }, { zone: 'field', index: 2, group: 2 },
    ] }, cardMap), '別グループへの代用は不可');

    const highPower = signis.find(c => (parseInt(c.Power ?? '0', 10) || 0) >= 10000)!.CardNum;
    const lowPower = signis.find(c => (parseInt(c.Power ?? '0', 10) || 0) < 10000)!.CardNum;
    const powerState = mkState({});
    powerState.energy = [lowPower, highPower];
    const powerPlan = appearancePayment(appearance('PR-470A'))!;
    ok(!validateResonaSelection(powerState, powerPlan, { items: [{ zone: 'energy', index: 0 }] }, cardMap), '好きな数でもパワー合計未満は不可');
    ok(validateResonaSelection(powerState, powerPlan, { items: [{ zone: 'energy', index: 1 }] }, cardMap), 'パワー合計10000以上で確定可');

    const insects = signis.filter(c => c.CardClass?.includes('凶蟲')).slice(0, 3).map(c => c.CardNum);
    const choiceState = mkState({});
    choiceState.hand = [insects[0]];
    choiceState.energy = [insects[1], insects[2]];
    const choicePlan = appearancePayment(appearance('WD11-008'))!;
    eq(choicePlan.chooseGroups, 2, '3択から2項目');
    ok(validateResonaSelection(choiceState, choicePlan, { items: [
      { zone: 'hand', index: 0, group: 0 },
      { zone: 'energy', index: 0, group: 1 }, { zone: 'energy', index: 1, group: 1 },
    ] }, cardMap), '手札1枚＋エナ2枚の2項目で確定');
  } finally {
    cursor = savedCursor;
  }
});
