  const ctx = { ...mkCtx({ deckTop: [SIGNI_L3], energy: 3 }, { signi: [SIGNI_L4, SIGNI_L1, null] }), sourceCardNum: 'WXK10-031', triggeringCardNum: 'WXK10-031' } as ExecCtx;
