// §6.4 ターン限定 PlayerState funnel（続き446の副次発見）。
// フィールド名の唯一の一覧は funnel に置き、ここでは型由来24件の包含と規約外10件という集合性を固定する。
test('§6.4 turn-scoped T1: PlayerState のターン限定フィールドと funnel レジストリが一致', () => {
  const typeSource = fs.readFileSync(join(root, 'src/types/index.ts'), 'utf8');
  const declared = [...typeSource.matchAll(/^ {2}([A-Za-z0-9_]+)\??:/gm)].map(m => m[1]);
  const convention = declared.filter(k => k.endsWith('_this_turn') || k.endsWith('_this_attack_phase'));
  const registered = Object.keys(TURN_SCOPED_STATE_FIELDS).sort();
  const missingConvention = convention.filter(field => !registered.includes(field));
  const irregular = registered.filter(field => !convention.includes(field));
  // 25 → 26（§6.4 O-3 で extra_attack_phases_this_turn を追加）
  // 26 → 27（§6.4 O-3 続き498 で arts_name_whitelist_this_turn を追加）
  // 27 → 29（§6.4 O-10 続き507 で lost_ability_effect_ids_this_turn ＝「代わりに…この能力を失う」の
  //          効果単位の自壊、power_minus_multipliers_this_turn ＝「代わりに３倍－される」を追加）
  // 29 → 30（§6.4 O-10 続き510 で own_effects_cannot_negate_signi_attack_this_turn を追加）
  // 30 → 31（§6.4 O-10 続き512 で cannot_pay_colorless_this_attack_phase を追加）
  // 31 → 32（§6.4 O-10 続き515 で lrig_grew_this_turn を追加）
  // 32 → 33（§6.4 O-11 続き533 で signi_downed_this_turn を追加＝「このターンでN回目」の台帳）
  // 33 → 34（§8／§6.4 O-1 続き551 で cpu_activated_effect_ids_this_turn を追加＝CPU の【起】重複起動止め）
  // 34 → 35（§8／§6.4 O-1 (a) 続き552 で cpu_used_card_nums_this_turn を追加＝CPU の応答アーツ選び直し止め）
  // 35 → 36（段2 第35バッチで cards_drawn_this_attack_phase を追加）
  // 39 → 40（2026-08-27 B8 で signi_placed_origin_this_turn を追加＝ON_PLAY の**由来ゾーン限定**の解決用。
  //   `execAddToField` がゾーン選択インタラクションの前に元の領域からカードを取り除くため、
  //   盤面差分だけでは resume 後に由来が復元できない＝配置時に記録するしかない）
  eq(convention.length, 41, 'PlayerState の命名規約由来フィールド数（41＝§5.3 O-121 で opp_signi_banished_this_turn を追加）');
  eq(missingConvention.join('|'), '', '命名規約由来フィールドはすべて funnel に登録');
  // 8 → 10（§6.4 O-3 で abilities_removed / keyword_abilities_removed を登録）
  // 11 → 12（§6.4 O-3 で pending_extra_attack_phase_start_effects を追加）
  // 12 → 14（§6.4 O-3 続き489 で negated_attacks / negated_attacks_escape を追加＝永続バグの解消）
  // 14 → 16（§6.4 O-3 続き492 で lrig_base_limit_override / draw_phase_replacement を追加＝
  //          境界は turn-end ではなく **main-phase-start**＝「次のあなたのメインフェイズまで」）
  // 16 → 17（§6.4 O-3 続き498 で blocked_card_names を登録＝turn-end で**両プレイヤー**失効。
  //          登録前はターンプレイヤー側しか手書きクリアされず、相手に課した分が1ターン長く残っていた）
  // 17→20（§6.4 O-10 続き509）＝`lrig_abilities_disabled`〔手書きクリアが**自分側の2経路だけ**で、
  //   `OPP_LRIG_LOSE_ABILITY` が書く**相手側**は一度も落ちず永続しうる穴だった〕／
  //   `turn_end_return_to_hand`〔新設〕／`attack_phase_level_overrides`〔失効地点が1つも無く永続していた〕。
  eq(irregular.length, 25, '命名規約外のターン限定フィールド数（25＝§5.3 O-117 で last_paid_energy_colors を追加）');  // +1＝続き518 の team_piece_cutin_window
  // 20 → 22（§6.4 O-10 続き512 で declared_guard_restrict_level / _levels を登録＝
  //   手書きクリアが turn-end の一部経路にしか無く、宣言側と読み手が別プレイヤーなので残りうる穴だった）
  eq(registered.length, 66, '型由来38件＋命名規約外25件の母集団（66＝§5.3 O-117 で +1）');  // +1＝2026-08-27 B8 の signi_placed_origin_this_turn（ON_PLAY 由来ゾーン限定）
});

function tsSourceFiles(dir: string): string[] {
  const files: string[] = [];
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const path = join(dir, entry.name);
    if (entry.isDirectory()) files.push(...tsSourceFiles(path));
    else if (/\.tsx?$/.test(entry.name)) files.push(path);
  }
  return files;
}

test('§6.4 turn-scoped T2: funnel 外のターン限定フィールド手書きクリアは0件', () => {
  const funnelPath = join(root, 'src/screens/battle/turnScopedState.ts');
  const resetLiteral = '(?:undefined|0|false|null|\\[\\])';
  const hits: string[] = [];
  for (const path of tsSourceFiles(join(root, 'src'))) {
    if (path === funnelPath) continue;
    const source = fs.readFileSync(path, 'utf8');
    for (const field of Object.keys(TURN_SCOPED_STATE_FIELDS)) {
      const escaped = field.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      const pattern = new RegExp(`(?:\\b${escaped}\\s*:|\\.${escaped}\\s*=)\\s*${resetLiteral}`, 'g');
      for (const match of source.matchAll(pattern)) {
        const line = source.slice(0, match.index).split('\n').length;
        hits.push(`${path.replace(root, '')}:${line}:${match[0]}`);
      }
    }
  }
  eq(hits.join('\n'), '', 'リセットは turnScopedState.ts の戻り値だけで行う');
});

test('§6.4 turn-scoped T3: PvP通常終了→次ターン開始で全turn-end値が消える', () => withSavedCursor(() => {
  const ending = mkState() as PlayerState & Record<string, unknown>;
  for (const [field, spec] of Object.entries(TURN_SCOPED_STATE_FIELDS)) {
    if ((spec.boundaries as readonly string[]).includes('turn-end')) ending[field] = spec.reset === 0 ? 9 : spec.reset instanceof Array ? ['stale'] : true;
  }
  ending.life_crashed_this_turn = 3;
  const ended = clearTurnEndScopedState(ending);
  for (const [field, spec] of Object.entries(TURN_SCOPED_STATE_FIELDS)) {
    if (!(spec.boundaries as readonly string[]).includes('turn-end')) continue;
    eq(JSON.stringify((ended as unknown as Record<string, unknown>)[field]), JSON.stringify(spec.reset), `${field} cleared`);
  }
  eq(ended.life_crashed_last_turn, 3, 'life_crashed_this_turn は last_turn へ写してから消す');
  const started = activateTurnStartScopedState(ended);
  eq(started.refresh_count_this_turn, 0, '次ターンのrefresh_countは0');
  eq(started.signi_played_from_non_hand_this_turn, undefined, '次ターンの非手札出自は空');
}));

