// §6.4 O-3: `RemoveAbilitiesAction.until` は長らく engine から**一切読まれない死フィールド**で、
// `PERMANENT` / `UNTIL_OPP_TURN_END` / `NEXT_TURN` が全部「このターン終了時まで」に丸まっていた。
// ⚠ここで固定するのは **3語彙が別々の寿命になること**＝「型に値がある＝動く」ではないので、
//   書き込み先（現ターン／予約）と、ターン境界を跨いだあとの生死の両方を見る。
test('§6.4 O-3 REMOVE_ABILITIES: until が現ターン／次ターン予約を書き分ける', () => withSavedCursor(() => {
  const victim = findCard(c => c.Type === 'シグニ');
  const mkCase = (until: string) => {
    const ctx = mkCtx({}, {}, 'WX05-019');
    ctx.otherState.field.signi = [[victim], null, null];
    const action = {
      type: 'REMOVE_ABILITIES',
      target: { type: 'SIGNI', owner: 'opponent', count: 'ALL' },
      until,
    } as unknown as EffectAction;
    return run(action, ctx).otherState;
  };
  const eot = mkCase('UNTIL_END_OF_TURN');
  ok(eot.abilities_removed?.includes(victim), 'UNTIL_END_OF_TURN: 現ターンに効く');
  eq(eot.abilities_removed_next_turn, undefined, 'UNTIL_END_OF_TURN: 次ターン予約はしない');

  const next = mkCase('NEXT_TURN');
  eq((next.abilities_removed ?? []).includes(victim), false, 'NEXT_TURN: **現ターンには効かない**');
  ok(next.abilities_removed_next_turn?.includes(victim), 'NEXT_TURN: 次ターンへ予約する');

  const untilOpp = mkCase('UNTIL_OPP_TURN_END');
  ok(untilOpp.abilities_removed?.includes(victim), 'UNTIL_OPP_TURN_END: 残りの現ターンに効く');
  ok(untilOpp.abilities_removed_next_turn?.includes(victim), 'UNTIL_OPP_TURN_END: 次ターンにも効く');

  // PERMANENT は CONTINUOUS 宣言でしか使われない（そちらは collectContinuousAbilitiesRemovedSigni が
  // 毎回再評価するのでこの経路を通らない）＝ここへ来る PERMANENT は「このターン」の書き間違い。
  const perm = mkCase('PERMANENT');
  ok(perm.abilities_removed?.includes(victim), 'PERMANENT: 現ターン扱い（従来と同じ）');
  eq(perm.abilities_removed_next_turn, undefined, 'PERMANENT: 予約はしない');
}));

test('§6.4 O-3 ターン境界: 予約は1ターンだけ生きて次の境界で消える', () => withSavedCursor(() => {
  const victim = 'VICTIM-1';
  const reserved = { ...mkState(), abilities_removed_next_turn: [victim] } as PlayerState;
  const ended = clearTurnEndScopedState(reserved);
  eq(JSON.stringify(ended.abilities_removed), JSON.stringify([victim]), '境界で予約が active へ昇格');
  eq(ended.abilities_removed_next_turn, undefined, '昇格後は予約を消費');
  const ended2 = clearTurnEndScopedState(ended);
  eq(JSON.stringify(ended2.abilities_removed), JSON.stringify([]), '次の境界で失効（2スロット式）');
  // ⚠旧実装は turn-end 経路のうち2本でしか手書きクリアしておらず、普通にターンを終えると
  //   「ターン終了時まで能力を失う」が次のターン以降も残っていた。funnel 化がその再発防止。
  const stale = { ...mkState(), abilities_removed: [victim], keyword_abilities_removed: { [victim]: ['ランサー'] } } as PlayerState;
  const cleaned = clearTurnEndScopedState(stale);
  eq(JSON.stringify(cleaned.abilities_removed), JSON.stringify([]), '予約が無ければ境界で空になる');
  eq(cleaned.keyword_abilities_removed, undefined, 'キーワード限定の喪失も同じ期限で失効');
}));

test('§6.4 O-3 live: 「次のあなたのターン」の能力喪失が NEXT_TURN で表されている', () => {
  for (const [cardNum, effectId] of [
    ['WX05-019', 'WX05-019-BURST'],
    ['WX18-029', 'WX18-029-BURST'],
  ] as const) {
    const ra = findActionByType(manualEffect(cardNum, effectId).action, 'REMOVE_ABILITIES')!;
    eq((ra as unknown as { until: string }).until, 'NEXT_TURN', `${effectId}: 次のターンだけ`);
  }
  // ⚠据置1件＝**期間だけ直すと誤った対象の効果が長持ちする**ので触らない（PLAN §6.4 O-3 に登録）。
  //   `WX11-038-E2`＝「次のターンの**メインフェイズ**の間」＝フェイズ限定の受け皿が無い
  //   （全ターンへ丸めるとアタックフェイズまで能力を奪う過剰実行になる）。
  {
    const ra = findActionByType(manualEffect('WX11-038', 'WX11-038-E2').action, 'REMOVE_ABILITIES')!;
    eq((ra as unknown as { until: string }).until, 'PERMANENT', 'WX11-038-E2: フェイズ限定の受け皿が無いので据置');
  }
  // 🏁続き455 で据置解除＝指定ゾーン軸が入ったので「このターンと次のターンの間」を2スロット寿命で表せる。
  for (const [cardNum, effectId] of [
    ['WXEX2-04', 'WXEX2-04-E3'],
    ['WX25-P3-014', 'WX25-P3-014-E2'],
  ] as const) {
    const ra = findActionByType(manualEffect(cardNum, effectId).action, 'REMOVE_ABILITIES')!;
    eq((ra as unknown as { until: string }).until, 'UNTIL_OPP_TURN_END', `${effectId}: 現ターン＋次ターン`);
    eq(ra.target.zoneSource, 'designated', `${effectId}: 指定ゾーンに紐づく`);
    eq(ra.target.count, 'ALL', `${effectId}: ゾーン継続なので count は ALL`);
  }
});

const nextTurnLiveAction = (cardNum: string, effectId: string): EffectAction => {
  const effect = (effectsMap.get(cardNum) ?? []).find(e => e.effectId === effectId);
  if (!effect) throw new Error(`${effectId}: live effect not found`);
  return effect.action;
};

test('§6.4 NEXT_TURN WX12-Re05-E1: 発動ターンは場出し可／次相手ターンだけ12000以上を封じる', () => withSavedCursor(() => {
  const action = nextTurnLiveAction('WX12-Re05', 'WX12-Re05-E1');
  const applied = run(action, mkCtx({}, {}));
  eq(JSON.stringify(applied.otherState.blocked_actions), '["PLAY_SIGNI_POWER_12000_OR_MORE:NEXT_TURN"]', '予約suffix');
  ok(!isHandSigniPlayBlockedByPower(applied.otherState, 12000), '発動ターンには効かない');
  const started = activateTurnStartScopedState(clearTurnEndScopedState(applied.otherState));
  ok(isHandSigniPlayBlockedByPower(started, 12000), '次ターンは12000を封じる');
  ok(isHandSigniPlayBlockedByPower(started, 15000), '閾値以上も封じる');
  ok(!isHandSigniPlayBlockedByPower(started, 11999), '閾値未満は通す');
  ok(!isHandSigniPlayBlockedByPower(clearTurnEndScopedState(started), 12000), '対象ターン終了で失効');
  const battleSource = fs.readFileSync(join(root, 'src/screens/BattleScreen.tsx'), 'utf8');
  const executorSource = fs.readFileSync(join(root, 'src/engine/effectExecutor.ts'), 'utf8');
  eq((battleSource.match(/isHandSigniPlayBlockedByPower\(/g) ?? []).length, 2, '人間／CPUの手札召喚入口で消費');
  eq((executorSource.match(/isHandSigniPlayBlockedByPower\(/g) ?? []).length, 1, '効果による手札場出し入口でも消費');
  eq((battleSource.match(/blocked_actions:\s*\[\]/g) ?? []).length, 0, '予約をfunnel手前の手書きclearで落とさない');
}));

function assertNextOpponentShadow(cardNum: string, effectId: string, action: EffectAction): void {
  const protectedSigni = SIGNI_P3000;
  const applied = run(action, mkCtx({ signi: [protectedSigni, null, null] }, {}, cardNum));
  eq(applied.ownerState.field_grants_active, undefined, `${effectId}: 発動ターンactiveなし`);
  ok((applied.ownerState.field_grants_next_opp_turn ?? []).length === 1, `${effectId}: 次相手ターン予約`);
  const targetNow = { ...mkCtx({}, {}, SIGNI), otherState: applied.ownerState } as ExecCtx;
  const hitNow = run({ type: 'TRASH', target: { type: 'SIGNI', owner: 'opponent', count: 1 } }, targetNow);
  eq(hitNow.otherState.field.signi[0], null, `${effectId}: 発動ターンにはシャドウが効かない`);
  const activated = clearTurnEndScopedState(applied.ownerState);
  ok((activated.field_grants_active ?? []).length === 1, `${effectId}: 次相手ターンにactive`);
  const targetNext = { ...mkCtx({}, {}, SIGNI), otherState: activated } as ExecCtx;
  const blockedNext = run({ type: 'TRASH', target: { type: 'SIGNI', owner: 'opponent', count: 1 } }, targetNext);
  ok(blockedNext.otherState.field.signi[0] !== null, `${effectId}: 次相手ターンは対象効果をシャドウで拒否`);
  eq(clearTurnEndScopedState(activated).field_grants_active, undefined, `${effectId}: 次相手ターン終了で失効`);
}

