// §6.4 O-16(a): ゾーン継続の**動的 delta**。「指定されたシグニゾーンにあるシグニのパワーを
// **そのシグニのレベル１につき**－2000する」＝`FieldGrant{kind:'power'}` は固定 delta しか持てず、
// この語形は `STUB{POWER_MOD_PER_COUNT}`（ACTIVATED 経路に消費地点なし＝真 no-op）へ落ちていた。
// ⚠ここで見るのは **①レベル倍率が乗る ②入れ替わったら新しいシグニ自身のレベルで再計算される
//   （適用時に固定 delta へ焼き込んでいない） ③次の相手ターンまで生き、その終了で切れる**。
test('§6.4 O-16 E2E WDK10-009-E2: 指定ゾーンのパワーがレベル比例で下がる', () => withSavedCursor(() => {
  const action = nextTurnLiveAction('WDK10-009', 'WDK10-009-E2');
  const lv3 = SIGNI_L3, lv1 = SIGNI_L1;
  const applied = run(action, { ...mkCtx({}, { signi: [lv3, lv3, lv3] }, 'WDK10-009'), isOwnerTurn: true });
  const zone = designatedZones(applied.otherState)[0];
  ok(zone !== undefined, 'ゾーン指定が実行される');
  const only = <T>(nums: Array<T | null>, v: T): Array<T | null> =>
    nums.map((_, i) => (i === zone ? v : null));
  const lv3Only = withFieldSigni(applied.otherState, only([null, null, null], lv3));
  eq(fieldPower(lv3Only, applied.ownerState, lv3),
    fieldGrantPrintedPower(lv3) - 2000 * 3, 'レベル3なら－6000');
  // ⭐固定 delta へ焼き込んでいたら、ここも－6000のままになる。
  const lv1Only = withFieldSigni(applied.otherState, only([null, null, null], lv1));
  eq(fieldPower(lv1Only, applied.ownerState, lv1),
    fieldGrantPrintedPower(lv1) - 2000 * 1, '入れ替わったらそのシグニのレベルで再計算（－2000）');
  const otherZone = zone === 0 ? 1 : 0;
  const offZone: Array<string | null> = [null, null, null];
  offZone[otherZone] = lv3;
  eq(fieldPower(withFieldSigni(applied.otherState, offZone), applied.ownerState, lv3),
    fieldGrantPrintedPower(lv3), '非指定ゾーンには効かない');
  // 「次のあなたのターンまで」＝このターン＋次の相手ターン。相手ターン開始で予約が昇格する。
  const oppTurn = activateTurnStartScopedState(
    withFieldSigni(clearTurnEndScopedState(applied.otherState), only([null, null, null], lv3)));
  eq(fieldPower(oppTurn, applied.ownerState, lv3),
    fieldGrantPrintedPower(lv3) - 2000 * 3, '次の相手ターンでも効く');
  eq(fieldPower(clearTurnEndScopedState(oppTurn), applied.ownerState, lv3),
    fieldGrantPrintedPower(lv3), '相手ターン終了（＝自分の次のターン）で失効');
}));

test('§6.4 O-16 live WDK10-009-E2: 動的 delta が単価のまま保存され指定ゾーンに紐づく', () => {
  const action = nextTurnLiveAction('WDK10-009', 'WDK10-009-E2');
  const pm = findActionByType(action, 'POWER_MODIFY')!;
  eq(pm.delta, -2000, 'delta はレベル1あたりの単価');
  eq((pm as { deltaPerTargetLevel?: boolean }).deltaPerTargetLevel, true, '倍率は対象シグニ自身のレベル');
  eq(pm.target.zoneSource, 'designated', '指定ゾーンを読む');
  eq(pm.target.count, 'ALL', 'ゾーン継続なので count は ALL');
  eq(pm.duration, 'NEXT_TURN', '「次のあなたのターンまで」＝次ターンへも予約する');
  eq(pm.nextTurnOwner, 'opponent', '次のターン＝相手のターン');
  eq((pm as { appliesThisTurn?: boolean }).appliesThisTurn, true, 'このターンにも効く');
  const designate = findStubById(action, 'DESIGNATE_SIGNI_ZONE');
  eq((designate as { owner?: string }).owner, pm.target.owner, '保存先が読み手と一致');
});

// §6.4 O-16(b): 「このターン、対戦相手の場に**ある キーと**シグニは能力を失い、新たに得られない」
// （`SP38-006-E1` の1つ目の内側能力）。旧 live は `SIGNI / count:1 / until:PERMANENT`＝
// **対象種別（キーが丸ごと落ちる）・体数（1体だけ）・期間（永続）の3軸とも別物**だった。
// ⚠キーは `field.signi` に居ないので per-card の `abilities_removed` では表せない＝
//   `keys_abilities_disabled` ＋ `activeKeyAbilitySources` funnel で表す。
{
  // 【常】：あなたのすべてのシグニのパワーを＋1000する、を持つキー。喪失の可視化に使う。
  const POWER_KEY = 'WDK08-Y09';
  const livePower = (state: PlayerState, other: PlayerState, num: string): number | undefined =>
    calcFieldPowers(state, other, true, effectsMap, cardMap as Map<string, CardData>).get(num);
  const innerAbility = (cardNum: string, innerId: string): EffectAction => {
    const grant = (effectsMap.get(cardNum) ?? [])
      .map(e => e.action).find(a => a.type === 'GRANT_LRIG_ABILITY') as { abilities: CardEffect[] } | undefined;
    const inner = grant?.abilities.find(ab => ab.effectId === innerId);
    if (!inner) throw new Error(`${innerId}: live inner ability not found`);
    return inner.action;
  };

  test('§6.4 O-16(b) E2E SP38-006-E1-G: 相手の場のキーとシグニがこのターンだけ能力を失う', () => withSavedCursor(() => {
    const a = fresh(), b = fresh();
    const ctx = mkCtx({}, { signi: [a, b, null] }, 'SP38-006');
    ctx.otherState.field.key_piece = POWER_KEY;
    eq(livePower(ctx.otherState, ctx.ownerState, a), fieldGrantPrintedPower(a) + 1000, '喪失前はキーの＋1000が乗る');

    const r = run(innerAbility('SP38-006', 'SP38-006-E1-G'), ctx);
    eq((r.otherState as { keys_abilities_disabled?: boolean }).keys_abilities_disabled, true, '相手のキーが能力を失う');
    ok((r.otherState.abilities_removed ?? []).includes(a)
      && (r.otherState.abilities_removed ?? []).includes(b), 'シグニは1体ではなく全体が対象');
    eq((r.ownerState as { keys_abilities_disabled?: boolean }).keys_abilities_disabled, undefined, '自分のキーは巻き込まない');
    // ⭐ここが「キーの能力が実際に消える」ことの確認＝フラグを立てただけでは足りない。
    eq(livePower(r.otherState, r.ownerState, a), fieldGrantPrintedPower(a), 'キーの＋1000が消える');

    // 「このターン」＝ターン終了で戻る。⚠登録前は BattleScreen の turn-end 4経路のうち2経路でしか
    //   手書きクリアされておらず、普通にターンを終えるとキー能力が永久に戻らなかった。
    const ended = clearTurnEndScopedState(r.otherState);
    eq((ended as { keys_abilities_disabled?: boolean }).keys_abilities_disabled, undefined, 'ターン終了でフラグが落ちる');
    eq(livePower(ended, r.ownerState, a), fieldGrantPrintedPower(a) + 1000, 'ターン終了でキーの能力が戻る');
  }));

  test('§6.4 O-16(b) funnel: keys_abilities_disabled は key_piece_extra も止める', () => withSavedCursor(() => {
    const st = mkState();
    st.field.key_piece = POWER_KEY;
    st.field.key_piece_extra = ['EXTRA_KEY'];
    eq(JSON.stringify(activeKeyAbilitySources(st)), JSON.stringify([POWER_KEY, 'EXTRA_KEY']), '通常時は両方が能力源');
    // ⚠従来 `keys_abilities_disabled` は CONT 収集8箇所でしか見られておらず、`key_piece_extra` と
    //   `triggerCollect` の AUTO は素通りしていた（「すべてのキー」が半分しか効いていない）。
    eq(JSON.stringify(activeKeyAbilitySources({ ...st, keys_abilities_disabled: true })), '[]', '喪失中はどちらも能力源にならない');
  }));

  test('§6.4 O-16(b) live SP38-006-E1-G: 3軸（キー／すべて／このターン）が保存されている', () => {
    const ra = innerAbility('SP38-006', 'SP38-006-E1-G') as Extract<EffectAction, { type: 'REMOVE_ABILITIES' }>;
    eq(ra.type, 'REMOVE_ABILITIES', 'REMOVE_ABILITIES のまま');
    eq((ra as { alsoKeys?: boolean }).alsoKeys, true, '対象種別＝キーも含む');
    eq(ra.target.count, 'ALL', '体数＝すべて');
    eq(ra.target.owner, 'opponent', '対戦相手の場');
    eq(ra.until, 'UNTIL_END_OF_TURN', '期間＝このターン');
  });
}

// §6.4 O-17（続き458）: 能力喪失の**対象軸**が落ちていた2件。O-16 とは別軸（ゾーンではなく対象種別・領域）。
{
  test('§6.4 O-17 E2E WXK05-010-E2: キー1枚を選んで能力を失わせる（シグニではない）', () => withSavedCursor(() => {
    const KEY_A = 'WDK08-Y09', KEY_B = 'WDK08-L09';
    const signi = fresh();
    const ctx = mkCtx({}, { signi: [signi, null, null] }, 'WXK05-010');
    ctx.otherState.field.key_piece = KEY_A;
    ctx.otherState.field.key_piece_extra = [KEY_B];
    const r = run(nextTurnLiveAction('WXK05-010', 'WXK05-010-E2'), ctx);
    const removed = r.otherState.abilities_removed ?? [];
    // オートパイロットは候補の先頭を選ぶ＝1枚だけ落ちる（「すべてのキー」ではない）。
    eq(removed.length, 1, '選んだ1枚だけが能力を失う');
    ok([KEY_A, KEY_B].includes(removed[0]), '対象はキー（シグニではない）');
    ok(!removed.includes(signi), '相手シグニは巻き込まない');
    // ⭐funnel が per-key の喪失も読む＝選ばれたキーだけが能力源から外れる。
    const sources = activeKeyAbilitySources(r.otherState);
    eq(sources.length, 1, '残り1枚のキーだけが能力源');
    ok(!sources.includes(removed[0]), '能力を失ったキーは能力源から外れる');
  }));

  test('§6.4 O-17 E2E SPDi47-01-E2: 手札・エナ・トラッシュのシグニも能力を失う', () => withSavedCursor(() => {
    const onField = fresh();
    const ctx = mkCtx({ trash: 4 }, { signi: [onField, null, null], hand: 3, energy: 3, trash: 3 }, 'SPDi47-01');
    // リコレクト条件（ルリグトラッシュのアーツ4枚以上）を満たす。
    (ctx.ownerState as { lrig_trash: string[] }).lrig_trash =
      [...cardMap.values()].filter(c => c.Type === 'アーツ').slice(0, 4).map(c => c.CardNum);
    const r = run(nextTurnLiveAction('SPDi47-01', 'SPDi47-01-E2'), ctx);
    const removed = new Set(r.otherState.abilities_removed ?? []);
    ok(removed.has(onField), '場のシグニ');
    const zoneSigni = [...r.otherState.hand, ...r.otherState.energy, ...r.otherState.trash]
      .filter(n => cardMap.get(getCardNumG(n))?.Type === 'シグニ');
    ok(zoneSigni.length > 0, '前提: 場以外の領域にシグニがある');
    // ⭐ここが「場だけ」実装との差＝旧 live は count:1 で場のシグニ1体しか対象にできなかった。
    ok(zoneSigni.every(n => removed.has(n)), '手札・エナ・トラッシュのシグニも全部対象');
    // ⚠シグニ以外（スペル等）は巻き込まない＝allZones は cardType を明示しないと領域ごと全部さらう。
    const nonSigni = [...r.otherState.hand, ...r.otherState.energy, ...r.otherState.trash]
      .filter(n => cardMap.get(getCardNumG(n))?.Type !== 'シグニ');
    ok(nonSigni.every(n => !removed.has(n)), 'シグニ以外は対象外');
  }));

  test('§6.4 O-17 live: 対象軸の3点（KEY／allZones／レベル等値）が保存されている', () => {
    const key = findActionByType(nextTurnLiveAction('WXK05-010', 'WXK05-010-E2'), 'REMOVE_ABILITIES')!;
    eq(key.target.type, 'KEY', 'WXK05-010-E2: 対象種別はキー');
    eq(key.target.count, 1, 'WXK05-010-E2: 1枚を選ぶ（全キーではない）');

    const spdi = findActionByType(nextTurnLiveAction('SPDi47-01', 'SPDi47-01-E2'), 'REMOVE_ABILITIES')!;
    eq((spdi.target as { allZones?: boolean }).allZones, true, 'SPDi47-01-E2: 領域を跨ぐ');
    eq(spdi.target.count, 'ALL', 'SPDi47-01-E2: すべて（旧 live は count:1 の過少）');
    eq(spdi.target.filter?.cardType, 'シグニ', 'SPDi47-01-E2: シグニ限定');

    // 「この方法で公開されたシグニと同じレベルの」＝レベル条件が落ちると相手シグニ全体を奪う過剰効果。
    const wx24 = nextTurnLiveAction('WX24-P4-013', 'WX24-P4-013-E3');
    const ra = findActionByType(wx24, 'REMOVE_ABILITIES')!;
    eq(ra.target.filter?.levelEqLastProcessed, true, 'WX24-P4-013-E3: 公開シグニと同じレベル限定');
    eq((ra.target as { allZones?: boolean }).allZones, true, 'WX24-P4-013-E3: すべての領域');
    const bounce = findActionByType(wx24, 'BOUNCE')!;
    eq(bounce.target.filter?.levelEqLastProcessed, true, 'WX24-P4-013-E3: 後段の手札戻しも同じレベル限定');
  });
}

// §6.4 O-3（続き459）: 「〜を使用できない」の**期間**と**合成 actionId** が2つとも死んでいた。
test('§6.4 O-3 live: アーツ／スペル使用禁止の期間と actionId（合成IDは誰も読まない）', () => {
  // 🔴`ARTS_AND_SPELL` は封じ判定（actionId の完全一致）のどちらにも当たらない死 ID だった。
  //   live に1件でも残っていたらまた真 no-op が生えている。
  for (const [cardNum, effs] of effectsMap) {
    ok(!JSON.stringify(effs).includes('ARTS_AND_SPELL'), `${cardNum}: 合成 actionId は使わない`);
  }
  // 🔴「次の**あなたの**ターンまで」を読めず PERMANENT へ倒れて**恒久スペルロック**になっていた。
  const ex166 = nextTurnLiveAction('WXEX1-66', 'WXEX1-66-E1') as Extract<EffectAction, { type: 'BLOCK_ACTION' }>;
  eq(ex166.actionId, 'USE_SPELL', 'WXEX1-66-E1: スペル封じ');
  eq(ex166.until, 'NEXT_TURN', 'WXEX1-66-E1: 恒久ロックではなく次ターンまで');
  // 合成IDを割った2本＝どちらも live に消費地点がある actionId。
  const pr427 = nextTurnLiveAction('PR-427', 'PR-427-E1');
  eq(pr427.type, 'SEQUENCE', 'PR-427-E1: 2本に割る');
  const ids = (pr427 as Extract<EffectAction, { type: 'SEQUENCE' }>).steps
    .map(st => (st as { actionId?: string }).actionId).sort();
  eq(JSON.stringify(ids), JSON.stringify(['USE_ARTS', 'USE_SPELL']), 'PR-427-E1: USE_ARTS と USE_SPELL');
  for (const st of (pr427 as Extract<EffectAction, { type: 'SEQUENCE' }>).steps) {
    eq((st as { until?: string }).until, 'NEXT_TURN', 'PR-427-E1: 期間は両方とも次ターンまで');
  }
});

test('§6.4 O-3 live: 未パース節の受け皿が honest な id を名乗る（LRIG_GROW_RESTRICT の乗っ取り解消）', () => {
  // 🔴`LRIG_GROW_RESTRICT` は本来「このルリグは〜のルリグにしかグロウできない」専用の id なのに、
  //   parser の8箇所が**まったく無関係な未パース節**を同じ名前で捨てていた。ハンドラは log を1行出すだけの
  //   no-op なので、`census:stubs` は「D 健全（実装あり）」と誤分類し、**27効果の真 no-op が計器から消えて**いた。
  const growOnly: string[] = [];
  for (const [cardNum, effs] of effectsMap) {
    if (JSON.stringify(effs).includes('"LRIG_GROW_RESTRICT"')) growOnly.push(cardNum);
  }
  // 残ってよいのは本来の用法（【常】：このルリグは〜のルリグにしかグロウできない）だけ。
  for (const cardNum of growOnly) {
    ok(/このルリグは.+のルリグにしかグロウできない/.test(cardMap.get(cardNum)?.EffectText ?? ''),
      `${cardNum}: LRIG_GROW_RESTRICT は本来のグロウ制限文にだけ付く`);
  }
  ok(growOnly.length > 0, '本来の用法は live に残っている（規則ごと消していない）');
});

test('§6.4 NEXT_TURN 非採用 WX24-P4-024-E3 / WXK10-011-E1: パワー節は現ターン限定', () => {
  const wx24 = findActionByType(nextTurnLiveAction('WX24-P4-024', 'WX24-P4-024-E3'), 'POWER_MODIFY')!;
  ok(wx24.delta === -3000 && wx24.duration !== 'NEXT_TURN' && wx24.nextTurnOwner === undefined, 'WX24-P4-024-E3の－3000を予約しない');
  // 🔑`WXK10-011-E1` の＋5000 は §6.4 O-33（続き502）で**選択肢②の中へ戻した**＝top-level には無い。
  //   旧アサートは「top-level の POWER_MODIFY を NEXT_TURN 予約しない」だったが、その top-level 自体が
  //   **選択肢本文の漏れ**（＝選ばなくても常に全シグニ＋5000）だったので、正方向へ置き換える。
  // 🆕§6.4 O-11（続き531）＝この効果は engine の全文 regex STUB から**構造化 CHOOSE**へ移った。
  //   「JSON 全体に POWER_MODIFY が出ない」では選択肢②の中身まで禁じてしまうので、
  //   **top-level に無いこと**＋**選択肢②の中に在ること**の2本で見る。
  {
    const wxk = nextTurnLiveAction('WXK10-011', 'WXK10-011-E1') as unknown as
      { type: string; choices?: { action: EffectAction }[] };
    eq(wxk.type, 'CHOOSE', 'WXK10-011-E1: 構造化 CHOOSE になっている');
    const { choices: _c, ...wxkTop } = wxk;
    ok(!JSON.stringify(wxkTop).includes('POWER_MODIFY'), 'WXK10-011-E1: ＋5000 が top-level へ漏れていない');
    const wxkPower = findActionByType(wxk.choices![1].action, 'POWER_MODIFY')!;
    ok(wxkPower.delta === 5000 && wxkPower.duration !== 'NEXT_TURN' && wxkPower.nextTurnOwner === undefined,
      'WXK10-011-E1②の＋5000を予約しない');
  }
});

