test('(xlvi) WXDi-P03-061-E2: 2枚pickなら手札純増0・2枚捨て、0枚pickなら0枚捨て', () => {
  const savedCursor = cursor;
  try {
    const eff = effectsMap.get('WXDi-P03-061')?.find(e => e.effectId === 'WXDi-P03-061-E2');
    if (!eff) throw new Error('WXDi-P03-061-E2 が存在');
    const spells = [...cardMap.values()].filter(c => c.Type === 'スペル').slice(0, 2).map(c => c.CardNum);
    eq(spells.length, 2, 'スペルを2枚確保');
    const nonSpells = [...cardMap.values()].filter(c => c.Type === 'シグニ').slice(0, 3).map(c => c.CardNum);

    const ctx = mkCtx({ deckTop: [...spells, ...nonSpells] }, {}, 'WXDi-P03-061');
    const before = {
      deck: ctx.ownerState.deck.length,
      hand: ctx.ownerState.hand.length,
      trash: ctx.ownerState.trash.length,
    };
    const r0 = executeEffect(eff, ctx);
    ok(!r0.done && r0.pending.type === 'SEARCH', 'スペルだけを選ぶSEARCHで停止');
    eq(r0.pending.visibleCards.length, 2, 'filter落ちでシグニを拾えない');
    const r1 = resumeSearch(spells, r0.pending, {
      ...ctx, ownerState: r0.ownerState, otherState: r0.otherState, logs: r0.logs,
    });
    ok(!r1.done && r1.pending.type === 'SELECT_TARGET', 'pick後に同数の手札捨て選択へ進む');
    eq(r1.pending.count, 2, '🔴捨てる枚数はpickした2枚に比例');
    const r2 = resumeSelectTarget(r1.pending.candidates.slice(0, 2), r1.pending, {
      ...ctx, ownerState: r1.ownerState, otherState: r1.otherState, logs: r1.logs,
      lastProcessedCards: r1.lastProcessedCards,
    });
    ok(r2.done, '2枚捨てまで完走');
    eq(r2.ownerState.hand.length, before.hand, '🔴2枚加えて2枚捨てるため手札は純増しない');
    eq(r2.ownerState.deck.length, before.deck - 2, 'デッキは手札へ加えた2枚分だけ減る');
    eq(r2.ownerState.trash.length, before.trash + 2, '手札から2枚がトラッシュへ');
    eq(r2.ownerState.deck.length + r2.ownerState.hand.length + r2.ownerState.trash.length,
      before.deck + before.hand + before.trash,
      'デッキ・手札・トラッシュ間でカード総数保存（複製0）');

    const zeroCtx = mkCtx({ deckTop: [...spells, ...nonSpells] }, {}, 'WXDi-P03-061');
    const zeroHand = zeroCtx.ownerState.hand.length, zeroTrash = zeroCtx.ownerState.trash.length;
    const z0 = executeEffect(eff, zeroCtx);
    const z1 = resumeSearch([], z0.pending as never, {
      ...zeroCtx, ownerState: z0.ownerState, otherState: z0.otherState, logs: z0.logs,
    });
    if (!z1.done) {
      eq(z1.pending.type, 'SELECT_TARGET', '0枚参照の後段は対象選択経路へ入る場合もある');
      eq(z1.pending.count, 0, '0枚pickの動的捨て枚数は0');
    }
    const z2 = finish(z1, zeroCtx);
    ok(z2.done, '0枚pickは0枚選択で完走');
    eq(z2.ownerState.hand.length, zeroHand, '0枚pickなら手札増減0');
    eq(z2.ownerState.trash.length, zeroTrash, '0枚pickなら捨ても0');
  } finally { cursor = savedCursor; }
});

test('(xlvi) WX11-074-E1: 宣言した2色ごとにシグニ1枚を手札/エナへ', () => {
  const savedCursor = cursor;
  try {
    const effect = effectsMap.get('WX11-074')?.find(e => e.effectId === 'WX11-074-E1');
    if (!effect) throw new Error('WX11-074-E1 が存在');
    const seq = effect.action as SequenceAction;
    const decl = seq.steps[0] as import('../src/types/effects').StubAction;
    const chain = seq.steps[1] as import('../src/types/effects').LookPickChainAction;
    eq(`${decl.id}|${decl.declareOptions?.join(',')}|${decl.count}`, 'DECLARE_COLORS|白,赤,青,黒|2',
      '原文列挙4色から必ず2色を宣言');
    eq(`${chain.revealCount}|${chain.stages.length}|${chain.remainder.position}`, '2|2|top',
      '動的stageではなく固定2段・残りはデッキ上');
    eq(JSON.stringify(chain.stages.map(s => [s.filter, s.pickCount, s.handOrEnergy])),
      JSON.stringify([
        [{ cardType: 'シグニ', colorEqDeclaredColorIndex: 0 }, 1, true],
        [{ cardType: 'シグニ', colorEqDeclaredColorIndex: 1 }, 1, true],
      ]), '各宣言色を別段で参照し、各1枚を手札/エナへ');

    const white = findCard(c => c.Type === 'シグニ' && (c.Color ?? '').includes('白'));
    const red = findCard(c => c.Type === 'シグニ' && (c.Color ?? '').includes('赤') && c.CardNum !== white);
    const green = findCard(c => c.Type === 'シグニ' && (c.Color ?? '').includes('緑')
      && !(c.Color ?? '').includes('白') && !(c.Color ?? '').includes('赤'));
    const ctx = mkCtx({ deckTop: [white, red] }, {}, 'WX11-074');
    const total0 = ctx.ownerState.deck.length + ctx.ownerState.hand.length + ctx.ownerState.energy.length;
    const r0 = executeEffect(effect, ctx);
    ok(!r0.done && r0.pending.type === 'CHOOSE', '色宣言の複数選択で停止');
    eq(r0.pending.count, 2, '宣言数は必ず2');
    eq(r0.pending.options.map(o => o.label).join(','), '白,赤,青,黒', '候補は原文の4色だけ');
    const r1 = resumeChoose(['dcolor_白', 'dcolor_赤'], r0.pending,
      { ...ctx, ownerState: r0.ownerState, otherState: r0.otherState, logs: r0.logs });
    ok(!r1.done && r1.pending.type === 'SEARCH', '第1宣言色のpickへ');
    eq(r1.pending.visibleCards.join(','), white, '🔴第1段は白シグニだけ（filter落ちで赤も拾えない）');
    const r2 = resumeSearch([white], r1.pending,
      { ...ctx, ownerState: r1.ownerState, otherState: r1.otherState, logs: r1.logs });
    ok(!r2.done && r2.pending.type === 'CHOOSE', '白札の手札/エナ選択');
    const r3 = resumeChoose('hand', r2.pending,
      { ...ctx, ownerState: r2.ownerState, otherState: r2.otherState, logs: r2.logs, lastProcessedCards: r2.lastProcessedCards });
    ok(!r3.done && r3.pending.type === 'SEARCH', '第2宣言色のpickへ');
    eq(r3.pending.visibleCards.join(','), red, '🔴第2段は赤シグニだけ（宣言色の混同なし）');
    const r4 = resumeSearch([red], r3.pending,
      { ...ctx, ownerState: r3.ownerState, otherState: r3.otherState, logs: r3.logs, lastProcessedCards: r3.lastProcessedCards });
    ok(!r4.done && r4.pending.type === 'CHOOSE', '赤札の手札/エナ選択');
    const donePick = resumeChoose('energy', r4.pending,
      { ...ctx, ownerState: r4.ownerState, otherState: r4.otherState, logs: r4.logs, lastProcessedCards: r4.lastProcessedCards });
    ok(donePick.done, '2段を完走');
    ok(donePick.ownerState.hand.includes(white), '白札は選択どおり手札へ');
    ok(donePick.ownerState.energy.includes(red), '赤札は選択どおりエナへ');
    eq(donePick.ownerState.deck.length + donePick.ownerState.hand.length + donePick.ownerState.energy.length, total0,
      'デッキ・手札・エナ間でカード総数保存（複製0）');

    const noDeclCtx = mkCtx({ deckTop: [green] }, {}, 'WX11-074');
    const noDecl = run(chain as EffectAction, noDeclCtx);
    ok(!noDecl.ownerState.hand.includes(green) && !noDecl.ownerState.energy.includes(green),
      '🔴宣言色参照なしでは何も拾わない（filter落ちの無差別pick禁止）');
    eq(noDecl.ownerState.deck[0], green, '非対象の残りはデッキの一番上へ戻る');
  } finally { cursor = savedCursor; }
});

test('(xlvi) 第14波 WXK04-045-E1: 場で対象にした別シグニと同名だけを拾う', () => {
  const savedCursor = cursor;
  try {
    const effect = effectsMap.get('WXK04-045')?.find(e => e.effectId === 'WXK04-045-E1');
    if (!effect) throw new Error('WXK04-045-E1 が存在');
    const target = findCard(c => c.Type === 'シグニ'
      && ((c.CardClass ?? '').includes('紅蓮') || (c.CardClass ?? '').includes('古代兵器'))
      && c.CardNum !== 'WXK04-045');
    const miss = findCard(c => c.Type === 'シグニ' && c.CardName !== cardMap.get(target)?.CardName);
    const ctx = mkCtx({ signi: ['WXK04-045', target, null], deckTop: [miss, target] }, {}, 'WXK04-045');
    const hand0 = ctx.ownerState.hand.length;
    const total0 = ctx.ownerState.deck.length + ctx.ownerState.hand.length;

    const r0 = executeEffect(effect, ctx);
    ok(!r0.done && r0.pending.type === 'SELECT_TARGET', '場の参照元を先に対象選択する');
    eq(r0.pending.candidates.join(','), target, '🔴自身を除く＜紅蓮＞/＜古代兵器＞だけが参照候補');
    const r1 = resumeSelectTarget([target], r0.pending, {
      ...ctx, ownerState: r0.ownerState, otherState: r0.otherState, logs: r0.logs,
    });
    ok(!r1.done && r1.pending.type === 'SEARCH', '同名pickへ進む');
    eq(r1.pending.visibleCards.join(','), target, '🔴対象と同名のシグニだけが候補（filter落ち禁止）');
    const r2 = resumeSearch([target], r1.pending, {
      ...ctx, ownerState: r1.ownerState, otherState: r1.otherState, logs: r1.logs,
      lastProcessedCards: r1.lastProcessedCards,
    });
    ok(r2.done, 'pick完走');
    eq(r2.ownerState.hand.length, hand0 + 1, '同名1枚を手札へ');
    ok(r2.ownerState.hand.includes(target), '対象と同名の公開札が手札にある');
    eq(r2.ownerState.deck.length + r2.ownerState.hand.length, total0, 'デッキ・手札のカード総数保存（複製0）');
    ok(r2.ownerState.deck.includes(miss), '非対象札はデッキ下へ残る');

    const noRefCtx = mkCtx({ signi: ['WXK04-045', null, null], deckTop: [target, miss] }, {}, 'WXK04-045');
    const noRefHand = noRefCtx.ownerState.hand.length;
    const noRef = run(effect.action, noRefCtx);
    eq(noRef.ownerState.hand.length, noRefHand,
      '🔴場に参照元が無いとき候補ゼロ（同名札が公開されても拾わない）');
  } finally { cursor = savedCursor; }
});

