test('task12(xcix): 主語なし「シグニN体がアタックしたとき」は triggerScope:any になる', () => withSavedCursor(() => {
  for (const [card, effId] of [
    ['WXDi-P06-033', 'WXDi-P06-033-E2'], ['WXDi-CP02-053', 'WXDi-CP02-053-E1'], ['WXEX2-04', 'WXEX2-04-E1'],
  ] as const) {
    const eff = (effectsMap.get(card) ?? []).find(e => e.effectId === effId);
    eq(eff?.triggerScope, 'any', `${effId}: 主語なしは any（self に潰さない）`);
  }
  // 相手ターン限定は2枚だけ（`WXEX2-04-E1` は原文に前置きが無いので付けない＝過剰に絞らない）
  eq((effectsMap.get('WXDi-P06-033') ?? []).find(e => e.effectId === 'WXDi-P06-033-E2')?.triggerCondition?.turnOwner,
    'opponent', 'アイコン形《相手ターン》');
  eq((effectsMap.get('WXDi-CP02-053') ?? []).find(e => e.effectId === 'WXDi-CP02-053-E1')?.triggerCondition?.turnOwner,
    'opponent', '散文形「対戦相手のターンの間、」');
  eq((effectsMap.get('WXEX2-04') ?? []).find(e => e.effectId === 'WXEX2-04-E1')?.triggerCondition?.turnOwner,
    undefined, '前置きが無い札にターン限定を付けない');
}));

test('task12(xcix): any スコープで「相手のアタック」を watcher が拾い、ターン限定は turnGateOk が落とす', () => withSavedCursor(() => {
  // ⚠**ターン限定は collector では見ない**＝収集後段の `effectStack.turnGateOk` が entry.playerId 基準で
  //   全コレクタ共通に落とす（ここで二重に足すと ON_PLAY の「相手ターン中の特殊召喚」等が壊れる。
  //   実際に一度 collectFieldTriggers へ足して既存2テストを落としたので差し戻した）。
  // collectFieldTriggers(ctx, event, triggeringCardNum, myState=攻撃側, opState=watcher側, ownerId=攻撃側)
  const attacker = mkState({ signi: [SIGNI, null, null] });
  const watcher = mkState({ signi: ['WXDi-P06-033', null, null] });
  // ① scope:any になったので **watcher 側（＝相手のアタック）でも収集される**（従来 self で collector に載らなかった）
  const collected = cftEntries(trigCtx(GUEST), 'ON_ATTACK_SIGNI', SIGNI, attacker, watcher, GUEST)
    .filter(e => e.effectId === 'WXDi-P06-033-E2');
  eq(collected.length, 1, '相手のアタックで watcher が収集される（scope:any の効き目）');
  eq(collected[0].playerId, HOST, 'entry の主体は watcher の持ち主');
  // ② そのままスタックへ積むと、guest ターンでは turnOwner:opponent を満たすので残る
  eq(initStack(GUEST, collected).pendingOpp.length, 1, '相手ターンなら turnGateOk を通る');
  // ③ host（watcher 側）のターンだと turnGateOk が落とす＝自分のターンには発火しない
  eq(initStack(HOST, collected).pendingTurn.length + initStack(HOST, collected).pendingOpp.length, 0,
    '自分のターンでは turnGateOk が落とす');
  // ④ ターン限定を持たない `WXEX2-04-E1` はどちらのターンでも残る
  const w2 = mkState({ signi: ['WXEX2-04', null, null] });
  const c2 = cftEntries(trigCtx(GUEST), 'ON_ATTACK_SIGNI', SIGNI, attacker, w2, GUEST)
    .filter(e => e.effectId === 'WXEX2-04-E1');
  eq(c2.length, 1, 'ターン限定なしも相手のアタックで収集される');
  eq(initStack(HOST, c2).pendingTurn.length + initStack(HOST, c2).pendingOpp.length, 1,
    'ターン限定が無ければ自ターンでも落とされない');
}));

// ── 続き376b: ON_ATTACK_SIGNI の主語「あなたの[＜X＞の]シグニN体が」＝any_ally＋triggerFilter。
//    従来 `effectParser.ts` の抽出が**「他の」があるときだけ**動いており、「他の」無しは triggerScope が
//    既定 `self` に落ちて **watcher 自身がアタックしたときしか発火しない過小実行**だった（実測16効果）。
//    engine（collectFieldTriggers の any_ally path）は元から対応済みで、落ちていたのは parser の1行だけ。
test('続き376b: 「あなたの＜X＞のシグニN体がアタックしたとき」は any_ally＋triggerFilter.story', () => withSavedCursor(() => {
  const classCases: [string, string, string][] = [
    ['WX13-037', 'WX13-037-E2', '凶蟲'], ['WX17-032', 'WX17-032-E2', '英知'],
    ['WX18-054', 'WX18-054-E1', '悪魔'], ['WX19-072', 'WX19-072-E1', '地獣'],
    ['WXEX2-13', 'WXEX2-13-E1', '水獣'], ['WXEX2-18', 'WXEX2-18-E1', '遊具'],
    ['WXEX2-20', 'WXEX2-20-E1', '英知'], ['WX25-CP1-091', 'WX25-CP1-091-E1', 'ブルアカ'],
    ['WXDi-D09-P17', 'WXDi-D09-P17-E2', '天使'],
  ];
  for (const [card, effId, story] of classCases) {
    const e = (effectsMap.get(card) ?? []).find(x => x.effectId === effId);
    eq(e?.triggerScope, 'any_ally', `${effId}: scope=any_ally（旧: 既定 self へ潰れ自身のアタックでしか発火しなかった）`);
    eq(e?.triggerFilter?.story, story, `${effId}: triggerFilter.story=${story}`);
    // 「他の」が無い＝**自身も引き金になる**ので excludeSelf を付けてはいけない
    eq(e?.triggerFilter?.excludeSelf, undefined, `${effId}: 「他の」が無いので excludeSelf は付けない`);
  }
  // 主語がクラス無し「あなたのシグニN体が」＝any_ally・フィルタ無し
  for (const [card, effId] of [
    ['WD23-032-A', 'WD23-032-A-E2'], ['WX14-006A', 'WX14-006A-E1'], ['WXEX2-16', 'WXEX2-16-E2'],
    ['WX25-P2-022', 'WX25-P2-022-E1'], ['WXDi-P10-054', 'WXDi-P10-054-E1'], ['WXK07-030', 'WXK07-030-E1'],
    ['WX25-P3-023', 'WX25-P3-023-E1'],
  ] as const) {
    const e = (effectsMap.get(card) ?? []).find(x => x.effectId === effId);
    eq(e?.triggerScope, 'any_ally', `${effId}: scope=any_ally（クラス無しの素の主語）`);
    eq(e?.triggerFilter, undefined, `${effId}: フィルタは付けない`);
  }
}));

// ⚠トリップワイヤ＝**語彙化できていない修飾つきの主語を any_ally に広げてはいけない**。
//   「【ソウル】が付いているあなたのシグニ」を修飾ごと無視して any_ally にすると、
//   **過小実行を過剰発火へ付け替えるだけ**になる（「条件を満たすシグニだけ」が「味方シグニ全部」へ広がる）。
//   `parseAllyAttackSubject` は**未知の修飾語が1文字でも残れば null を返す**ことでこれを構造的に防ぐ。
//   配線したくなったら、先に triggerFilter 側へ語彙（【ソウル】が付いている＝盤面状態）を載せてからにする。
test('続き376b トリップワイヤ: 語彙の無い修飾つきのアタック主語は any_ally に広げない', () => withSavedCursor(() => {
  for (const [card, effId] of [['WXDi-P04-016', 'WXDi-P04-016-E1']] as const) {
    const e = (effectsMap.get(card) ?? []).find(x => x.effectId === effId);
    eq(e?.triggerScope ?? 'self', 'self', `${effId}: 【ソウル】が付いている＝フィルタ語彙が無いので広げない`);
  }
}));

// ── 続き377f: アタック主語の修飾語を統合抽出（被覆マトリクス `cardClass × (filter無)` の全数分類から）。
//    従来は「クラスのみ」「パワーのみ」「色のみ」が**別々の regex**に分かれており、
//    修飾が2つ以上（パワー＋クラス等）だと**どちらにも当たらず既定 self へ潰れて**いた＝
//    ①watcher 自身のアタックでしか発火しない過小実行 かつ ②その自身に対して主語の限定（パワー等）が
//    一切効かない、という二重のズレ。`parseAllyAttackSubject` へ統合し修飾を順不同で取る。
// ── 続き377j: `docs/_partial_fresh.json`（混在カードのレビュー行列）から見つけた parser 側の2系統。
//    どちらも **live には正しい形があるのに parser だけが退化**していた＝行列に居続ける原因。
//    parser を直すと live と一致して行列から落ち、以後の改善も自動で届く（効果単位マージ）。
test('続き377j: 「(あなた|対戦相手)のエナゾーンにあるカードがN枚以上/以下であるかぎり」を activeCondition へ', () => withSavedCursor(() => {
  // ⚠旧規則は **「あなたの」「N枚以上」「あるかぎり」** の1形だけを見ており、所有者・不等号・語尾の
  //   変種が丸ごと素通り＝条件が無言で落ちて**無条件発火**していた（「相手のエナが少ないときだけ
  //   強くなる」札が常時強い）。
  const cases: [string, string, 'self' | 'opponent', 'gte' | 'lte', number][] = [
    ['WX04-002', 'WX04-002-E1', 'opponent', 'lte', 4],
    ['WX10-042', 'WX10-042-E1', 'opponent', 'lte', 3],
    ['WX10-064', 'WX10-064-E1', 'opponent', 'lte', 2],
    ['WX24-P2-067', 'WX24-P2-067-E1', 'opponent', 'lte', 3],
  ];
  for (const [card, effId, owner, op, val] of cases) {
    const e = (effectsMap.get(card) ?? []).find(x => x.effectId === effId);
    const ac = e?.activeCondition as { type?: string; location?: string; owner?: string; operator?: string; value?: number } | undefined;
    eq(ac?.type, 'COUNT_THRESHOLD', `${effId}: activeCondition が付く（旧: 条件が落ちて無条件発火）`);
    eq(ac?.location, 'energy', `${effId}: location=energy`);
    eq(ac?.owner, owner, `${effId}: owner=${owner}`);
    eq(ac?.operator, op, `${effId}: operator=${op}`);
    eq(ac?.value, val, `${effId}: value=${val}`);
  }
}));

test('続き377j: 「〔X〕以外の効果を受けない」は fromAll＋exceptSource（from:[X] は意味が逆）', () => withSavedCursor(() => {
  // 🔴素の `t.includes('アーツ')` 判定は「対戦相手の、**アーツ以外の**効果を受けない」を
  //   `from:['アーツ']`＝「アーツの効果**だけ**受けない」と読み、保護範囲が原文とちょうど反対だった。
  for (const [card, effId] of [['WX12-018', 'WX12-018-E1'], ['WX09-017', 'WX09-017-E2']] as const) {
    const e = (effectsMap.get(card) ?? []).find(x => x.effectId === effId);
    const a = e?.action as { type?: string; fromAll?: boolean; from?: string[]; exceptSource?: { sourceType?: string } } | undefined;
    eq(a?.type, 'GRANT_PROTECTION', `${effId}: GRANT_PROTECTION`);
    eq(a?.fromAll, true, `${effId}: fromAll＝アーツ以外の全部から守る`);
    eq(a?.exceptSource?.sourceType, 'アーツ', `${effId}: exceptSource=アーツ（アーツからは受ける）`);
    eq(a?.from, undefined, `${effId}: from:['アーツ'] は付けない（意味が逆になる）`);
  }
  // ⚠トリップワイヤ＝「**自身**以外の効果を受けない」は sourceType の語彙が無いので触らない（WX17-001-E1）。
  const self = (effectsMap.get('WX17-001') ?? []).find(x => x.effectId === 'WX17-001-E1');
  eq((self?.action as { exceptSource?: unknown } | undefined)?.exceptSource, undefined,
    'WX17-001-E1: 「自身以外」は種別語ではないので exceptSource を作らない');
}));

// ── 続き377l: **左右のシグニゾーン（zoneSide / IS_SELF_IN_SIDE_ZONE）機構**を新設（被覆マトリクス
//    `cardClass × POWER_MODIFY{SIGNI}` の全数分類から）。`centerZoneOnly` / `IS_SELF_IN_CENTER_ZONE` の
//    兄弟が無く、左右を指す全効果が**限定ごと落ちて過剰発火**していた。
test('続き377l: 「あなたの〔左|右〕のシグニゾーンにある〈X〉のシグニ」を zoneSide フィルタへ', () => withSavedCursor(() => {
  const cases: [string, string, Record<string, unknown>][] = [
    ['WXK10-078', 'WXK10-078-E1', { cardType: 'シグニ', zoneSide: 'right', story: '怪異' }],
    ['WXK10-078', 'WXK10-078-E2', { cardType: 'シグニ', zoneSide: 'left', story: '怪異' }],
    ['WX25-P3-093', 'WX25-P3-093-E1', { cardType: 'シグニ', zoneSide: 'left', story: '迷宮' }],
    ['WX25-P3-093', 'WX25-P3-093-E2', { cardType: 'シグニ', zoneSide: 'right', story: '迷宮' }],
  ];
  for (const [card, effId, want] of cases) {
    const e = (effectsMap.get(card) ?? []).find(x => x.effectId === effId);
    const tgt = (e?.action as { target?: EffectTarget } | undefined)?.target;
    eq(JSON.stringify(tgt?.filter), JSON.stringify(want), `${effId}: filter=${JSON.stringify(want)}`);
    // 旧は owner:'any'/count:1＝CONTINUOUS では効果元自身へ解決＝**自分にバフ**していた
    eq(tgt?.owner, 'self', `${effId}: owner=self`);
    eq(tgt?.count, 'ALL', `${effId}: count=ALL（該当ゾーンのシグニ全体）`);
  }
}));

