// ── Opusタスク12 (clii)：collectLeaveFieldTriggers の self スコープに面で欠けていたゲート群 ──
// この collector は「watcher ループにはあるゲートが self ループに無い」穴を通算5回出した
//（turnOwner／leftStateFilter／byOpponentEffect／outsideMainPhase／leftToZone）。
// ⚠ゲートが無い＝JSON に条件を足しても恒久 no-op（条件が効かないまま過剰発火し、計器にも映らない）。
test('タスク12(clii) ON_LEAVE_FIELD outsideMainPhase: 自分のメインフェイズ中だけ非発火・相手のメインフェイズでは発火（WXDi-P06-035-E1）', () => {
  const parsed = parseCardEffects(cardMap.get('WXDi-P06-035')!).find(e => e.effectId === 'WXDi-P06-035-E1')!;
  eq(parsed.triggerCondition?.outsideMainPhase, true, 'parser が「あなたのメインフェイズ以外で」→outsideMainPhase を出さない');
  const host = mkState({}); const guest = mkState({});
  const at = (activeUserId: string, turnPhase: string) => ({ ...trigCtx(activeUserId), turnPhase });
  const fired = (activeUserId: string, turnPhase: string) =>
    has(collectLeaveFieldTriggers(at(activeUserId, turnPhase), 'WXDi-P06-035', [], HOST, host, guest).entries, 'WXDi-P06-035-E1');
  eq(fired(HOST, 'MAIN'), false, '自分のメインフェイズ中の離脱で発火した（outsideMainPhase 違反）');
  eq(fired(HOST, 'ATTACK_SIGNI'), true, '自分のアタックフェイズ中の離脱で発火しない');
  // 「**あなたの**メインフェイズ以外」＝ターンプレイヤーも見る。相手のメインフェイズは「あなたのメイン以外」。
  eq(fired(GUEST, 'MAIN'), true, '対戦相手のメインフェイズ中の離脱で発火しない（フェイズだけを見る旧実装の穴）');
});
test('タスク12(clii) ON_LEAVE_FIELD self スコープの cause ゲート: byOwnEffect/byEffect を評価する', () => {
  const LEAVER = 'SYNTH-LEAVE-01';
  const mkEff = (id: string, tc: Record<string, boolean>): CardEffect => ({
    effectId: id, effectType: 'AUTO', timing: ['ON_LEAVE_FIELD'], triggerScope: 'self',
    triggerCondition: tc, action: { type: 'DRAW', owner: 'self', count: 1 },
    duration: 'INSTANT', mandatory: true, parseStatus: 'MANUAL',
  } as unknown as CardEffect);
  const augmented = new Map(effectsMap);
  augmented.set(LEAVER, [mkEff('SYN-OWN', { byOwnEffect: true }), mkEff('SYN-ANY', { byEffect: true })]);
  const host = mkState({}); const guest = mkState({});
  const ctxOf = (cause?: string) => collectLeaveFieldTriggers(
    { ...trigCtx(HOST), effectsMap: augmented }, LEAVER, [], HOST, host, guest, cause,
  ).entries;
  eq(has(ctxOf(HOST), 'SYN-OWN'), true, 'byOwnEffect: 自分の効果が原因でも発火しない');
  eq(has(ctxOf(GUEST), 'SYN-OWN'), false, 'byOwnEffect: 対戦相手の効果が原因でも発火した');
  eq(has(ctxOf(undefined), 'SYN-OWN'), false, 'byOwnEffect: バトル/ルール処理（原因なし）でも発火した');
  eq(has(ctxOf(HOST), 'SYN-ANY'), true, 'byEffect: 効果起因なのに発火しない');
  eq(has(ctxOf(GUEST), 'SYN-ANY'), true, 'byEffect: 相手の効果起因なのに発火しない');
  eq(has(ctxOf(undefined), 'SYN-ANY'), false, 'byEffect: バトル/ルール処理（原因なし）でも発火した');
});
// ── Opusタスク12 (clii)/E018：離場・バニッシュ**直前**の下カードをスナップショットして候補を限定する ──
test('タスク12(clii) ON_BANISH fromLeftFieldUnder: バニッシュ直前に下にあったカードだけを回収する（WXK10-054-E1）', () => {
  const parsed = parseCardEffects(cardMap.get('WXK10-054')!).find(e => e.effectId === 'WXK10-054-E1')!;
  eq((parsed.action as { source: { fromLeftFieldUnder?: boolean } }).source.fromLeftFieldUnder, true,
    'parser が「このシグニの下にあった」→source.fromLeftFieldUnder を出さない');
  const weapons = [...cardMap.values()].filter(c => isSigni(c) && (c.CardClass ?? '').includes('ウェポン') && c.CardNum !== 'WXK10-054');
  ok(weapons.length >= 2, '＜ウェポン＞テストカード不足');
  const under = weapons[0].CardNum;   // 下にあった＝回収できる
  const decoy = weapons[1].CardNum;   // 無関係な＜ウェポン＞＝回収できてはいけない
  const prev = mkState({});
  prev.field.signi[0] = [under, 'WXK10-054'];
  const after = mkState({});
  after.trash = [decoy, under]; // decoy を先頭に置く＝限定が効かなければ decoy が選ばれる
  const guest = mkState({});
  const entry = collectBanishTriggers(trigCtx(HOST, HOST), 'WXK10-054', HOST, after, guest, prev)
    .entries.find(e => e.effectId === 'WXK10-054-E1');
  ok(!!entry, 'WXK10-054-E1 が収集されない');
  eq(entry!.leftFieldUnderCards?.join(','), under, 'バニッシュ直前の下カードが StackEntry に載らない');
  const ctx: ExecCtx = { ...mkCtx({}, {}, 'WXK10-054'), ownerState: after, otherState: guest,
    leftFieldUnderCards: entry!.leftFieldUnderCards };
  const res = run(entry!.effect.action, ctx);
  ok(res.ownerState.hand.includes(under), '下にあった＜ウェポン＞を回収できない');
  ok(!res.ownerState.hand.includes(decoy), '下にあったカード以外の＜ウェポン＞まで回収した（過剰実行）');
});
// ── Opusタスク12 (cli)：TAKE_FROM_UNDER_SIGNI が処理カードを記録し「そうした場合」が条件として効く ──
test('タスク12(cli) TAKE_FROM_UNDER_SIGNI の did-it ゲート: 下にカードがある時だけ「そうした場合」が走る（WX21-042-E2）', () => {
  const eff = parseCardEffects(cardMap.get('WX21-042')!).find(e => e.effectId === 'WX21-042-E2')!;
  const underCard = findCard(c => isSigni(c) && c.CardNum !== 'WX21-042');
  const withUnder = mkCtx({}, {}, 'WX21-042');
  withUnder.ownerState.field.signi[0] = [underCard, 'WX21-042'];
  const before = withUnder.ownerState.energy.length;
  const hit = run(eff.action, withUnder);
  ok(hit.ownerState.trash.includes(underCard), '下のカードがトラッシュに置かれていない');
  eq(hit.ownerState.energy.length, before + 1, '「そうした場合」のエナチャージが走らない（記録漏れ＝過小実行）');
  // 空振り側＝下にカードが無ければ「そうした場合」は走らない。
  const noUnder = mkCtx({}, {}, 'WX21-042');
  noUnder.ownerState.field.signi[0] = ['WX21-042'];
  const before2 = noUnder.ownerState.energy.length;
  const miss = run(eff.action, noUnder);
  eq(miss.ownerState.energy.length, before2, '下にカードが無いのに「そうした場合」が走った（過剰実行）');
});
test('Stage2 ON_LEAVE_FIELD levelEqTrigger: ルリグ《ママ♥５》がアタック中の英知離脱だけを同レベルへ解決（WX21-004-E2）', () => {
  const savedCursor = cursor;
  try {
    const parsed = parseCardEffects(cardMap.get('WX21-004')!).find(e => e.effectId === 'WX21-004-E2')!;
    const parsedFilter = (parsed.action as { source: { filter: Record<string, unknown> } }).source.filter;
    eq(parsedFilter.levelEqTrigger, true, 'parser は「そのシグニと同じレベル」→levelEqTrigger');

    const eichiLv2 = findCard(c => isSigni(c) && (c.CardClass ?? '').includes('英知') && c.Level === '2');
    const eichiLv3 = findCard(c => isSigni(c) && (c.CardClass ?? '').includes('英知') && c.Level === '3');
    const nonEichiLv2 = findCard(c => isSigni(c) && !(c.CardClass ?? '').includes('英知') && c.Level === '2');
    const host = mkState({});
    host.field.lrig = ['WX21-004']; // 発生源はルリグ。シグニゾーンに置く偽陽性テストにしない
    const guest = mkState({});
    const localEffects = new Map(effectsMap);
    localEffects.set('WX21-004', parseCardEffects(cardMap.get('WX21-004')!));
    const atk = { ...trigCtx(HOST), effectsMap: localEffects, turnPhase: 'ATTACK_SIGNI' };
    const main = { ...trigCtx(HOST), effectsMap: localEffects, turnPhase: 'MAIN' };

    const entry = collectLeaveFieldTriggers(atk, eichiLv2, [], HOST, host, guest).entries.find(e => e.effectId === 'WX21-004-E2');
    ok(!!entry, 'アタックフェイズ×英知離脱でルリグ watcher が発火');
    const filter = (entry!.effect.action as { source: { filter: Record<string, unknown> } }).source.filter;
    eq(filter.levelEqTrigger, undefined, 'levelEqTrigger は収集時に具体レベルへ解決され除去');
    eq(filter.level, 2, '離脱した英知Lv2を基準に level:2 へ解決');
    ok(matchesFilter(cardMap.get(eichiLv2), filter), '同レベルの英知は配置候補');
    ok(!matchesFilter(cardMap.get(eichiLv3), filter), 'レベル不一致の英知は配置候補外');
    ok(!matchesFilter(cardMap.get(nonEichiLv2), filter), '同レベルでもクラス不一致は配置候補外');

    eq(has(collectLeaveFieldTriggers(main, eichiLv2, [], HOST, host, guest).entries, 'WX21-004-E2'), false,
      'メインフェイズでは duringAttackPhase により非発火');
    eq(has(collectLeaveFieldTriggers(atk, nonEichiLv2, [], HOST, host, guest).entries, 'WX21-004-E2'), false,
      '英知以外の離脱では triggerFilter により非発火');
  } finally {
    cursor = savedCursor;
  }
});
test('INSTALL_DELAYED_TRIGGER ON_LEAVE_FIELD: 《悲願の駄姫 グズ子》を設置→遊具離脱時だけ低レベル遊具を手札候補化・APS終了で消滅（WX22-001-E3）', () => {
  const savedCursor = cursor;
  try {
    const parsed = parseCardEffects(cardMap.get('WX22-001')!).find(e => e.effectId === 'WX22-001-E3')!;
    const install = parsed.action as import('../src/types/effects').InstallDelayedTriggerAction;
    eq(install.type, 'INSTALL_DELAYED_TRIGGER', 'parser は即時配置/STUBでなく遅延 watcher を生成');
    eq(install.duration, 'THIS_ATTACK_PHASE', '寿命はこのアタックフェイズだけ');
    eq(install.trigger.timing, 'ON_LEAVE_FIELD', '離脱イベントを監視');

    const yuguLv3 = findCard(c => isSigni(c) && (c.CardClass ?? '').includes('遊具') && c.Level === '3');
    const yuguLv2 = findCard(c => isSigni(c) && (c.CardClass ?? '').includes('遊具') && c.Level === '2');
    const yuguLv4 = findCard(c => isSigni(c) && (c.CardClass ?? '').includes('遊具') && c.Level === '4');
    const nonYuguLv2 = findCard(c => isSigni(c) && !(c.CardClass ?? '').includes('遊具') && c.Level === '2');
    const installCtx = mkCtx({}, {}, 'WX22-001');
    installCtx.ownerState.field.lrig = ['WX22-001']; // 実戦どおり発生源はルリグゾーン
    const installed = run(install as unknown as EffectAction, installCtx);
    eq(installed.ownerState.delayed_triggers?.length, 1, '起動解決時に player state へ watcher を設置');

    const atk = { ...trigCtx(HOST), turnPhase: 'ATTACK_SIGNI' };
    const main = { ...trigCtx(HOST), turnPhase: 'MAIN' };
    const entry = collectLeaveFieldTriggers(atk, yuguLv3, [], HOST, installed.ownerState, installed.otherState)
      .entries.find(e => e.effectId === 'DELAYED_TRIGGER');
    ok(!!entry, '設置後のアタックフェイズ中、味方遊具離脱で発火');
    const filter = (entry!.effect.action as { source: { filter: Record<string, unknown> } }).source.filter;
    eq(filter.levelLtTrigger, undefined, '離脱基準の levelLtTrigger は収集時に除去');
    eq((filter.level as { max: number }).max, 2, '離脱Lv3→手札のLv2以下へ解決');
    ok(matchesFilter(cardMap.get(yuguLv2), filter), '低レベル遊具は候補');
    ok(!matchesFilter(cardMap.get(yuguLv4), filter), '同値以上の遊具は候補外');
    ok(!matchesFilter(cardMap.get(nonYuguLv2), filter), '低レベルでも遊具以外は候補外');

    eq(collectLeaveFieldTriggers(main, yuguLv3, [], HOST, installed.ownerState, installed.otherState)
      .entries.some(e => e.effectId === 'DELAYED_TRIGGER'), false, 'メインフェイズでは stale watcher が残っても非発火');
    eq(collectLeaveFieldTriggers(atk, nonYuguLv2, [], HOST, installed.ownerState, installed.otherState)
      .entries.some(e => e.effectId === 'DELAYED_TRIGGER'), false, '遊具以外の離脱では非発火');
    eq(collectLeaveFieldTriggers(atk, yuguLv3, [], GUEST, installed.ownerState, installed.otherState)
      .entries.some(e => e.effectId === 'DELAYED_TRIGGER'), false, '相手の遊具離脱では leftOwner:self により非発火');

    const turnLong = { ...install, duration: 'THIS_TURN' as const };
    const withBoth = { ...installed.ownerState, delayed_triggers: [install, turnLong] };
    const cleared = clearEndOfAttackPhaseDelayedTriggers(withBoth);
    eq(cleared.delayed_triggers?.length, 1, 'APS終了で THIS_ATTACK_PHASE だけ消滅');
    eq(cleared.delayed_triggers?.[0].duration, 'THIS_TURN', '既存 THIS_TURN watcher は保持');
  } finally {
    cursor = savedCursor;
  }
});
// 「このアタックフェイズの間、〜が場を離れたとき、〜を場に出す」規則がカード決め打ちでないことを固定する。
// クラス（＜X＞）・離脱側オーナー・配置元ゾーン・レベル比較・枚数・任意/ダウンを**すべて原文から読む**。
// ⚠parse のみ（mkState/mkCtx を呼ばない）ので共有 cursor は消費しない。
test('INSTALL_DELAYED_TRIGGER ON_LEAVE_FIELD: 監視クラス・ゾーン・比較を原文から読む（カード決め打ちにしない）', () => {
  const parseOne = (num: string, text: string) =>
    parseCardEffects({ CardNum: num, Type: 'ルリグ', EffectText: text } as unknown as CardData)[0]
      .action as import('../src/types/effects').InstallDelayedTriggerAction;

  // ①別クラス＜精羅＞＋トラッシュ由来＋「同じレベル」＋ダウン配置
  const a = parseOne('TEST-APSW1',
    '【起】《アタックフェイズアイコン》：このアタックフェイズの間、あなたの＜精羅＞のシグニ１体が場を離れたとき、あなたのトラッシュからそのシグニと同じレベルの＜精羅＞のシグニ１枚をダウン状態で場に出す。');
  eq(a.type, 'INSTALL_DELAYED_TRIGGER', '別クラスでも watcher 設置として解ける');
  eq(a.trigger.triggerFilter?.story, '精羅', '監視クラスを原文から読む（遊具の決め打ちでない）');
  const aSrc = (a.effect as { source: { type: string; filter: Record<string, unknown> } }).source;
  eq(aSrc.type, 'TRASH_CARD', '配置元ゾーンを原文から読む');
  eq(aSrc.filter.levelEqTrigger, true, '「同じレベル」は levelEqTrigger');
  eq((a.effect as { asDown?: boolean }).asDown, true, '「ダウン状態で場に出す」を保持');

  // ②相手側の離脱を監視＋クラス無指定＋エナ由来＋色フィルタ＋「N枚まで」＋任意
  const b = parseOne('TEST-APSW2',
    '【起】《アタックフェイズアイコン》：このアタックフェイズの間、対戦相手のシグニ１体が場を離れたとき、あなたのエナゾーンから青のシグニを２枚まで場に出してもよい。');
  eq(b.trigger.leftOwner, 'opponent', '離脱側オーナーを原文から読む');
  eq(b.trigger.triggerFilter?.story, undefined, 'クラス無指定ならクラス条件を作らない');
  const bSrc = (b.effect as { source: { type: string; count: number; upToCount?: boolean; filter: Record<string, unknown> } }).source;
  eq(bSrc.type, 'ENERGY_CARD', 'エナ由来を原文から読む');
  eq(bSrc.count, 2, '「２枚まで」の枚数');
  eq(bSrc.upToCount, true, '「まで」は上限選択');
  eq(bSrc.filter.color, '青', '色フィルタを原文から読む');
  eq((b.effect as { optional?: boolean }).optional, true, '「してもよい」は任意');

  // ③「この」の無い「アタックフェイズの間」は【自】の常時条件＝この規則では拾わない（WX21-004-E2 型）
  const c = parseCardEffects({ CardNum: 'TEST-APSW3', Type: 'ルリグ',
    EffectText: '【自】：アタックフェイズの間、あなたの＜英知＞のシグニが場を離れたとき、あなたの手札からそのシグニより低いレベルを持つ＜英知＞のシグニ１枚を場に出す。' } as unknown as CardData)[0];
  eq(c.action.type, 'ADD_TO_FIELD', '「この」無しは設置型でなく【自】の即時配置');
  eq(c.timing?.[0], 'ON_LEAVE_FIELD', '【自】ON_LEAVE_FIELD として解ける');
  eq(c.triggerCondition?.duringAttackPhase, true, 'アタックフェイズ限定は triggerCondition 側');
});

// §6.3 機構待ち解消: ON_LEAVE_FIELD any_opp（跨サイド watcher）の byEffect / leftStateFilter ゲート。
// WXK11-017-E1「あなたのターンの間、対戦相手のシグニが効果によって場を離れたとき、エナチャージ」
//   ＝any_opp + byEffect + turnOwner:self。watcher(WXK11-017) は離脱した相手シグニの反対側（HOST）に居る。
test('§6.3 ON_LEAVE_FIELD any_opp byEffect: 相手シグニが効果離脱かつ自ターンのみ発火（WXK11-017-E1）', () => {
  const host = mkState({ signi: ['WXK11-017', null, null] }); const guest = mkState({});
  // leftPlayerId=GUEST（相手シグニが離脱）／oppId=HOST（watcher）／activeUserId=HOST（あなたのターン）
  const fire = collectLeaveFieldTriggers(trigCtx(HOST), SIGNI, [], GUEST, host, guest, HOST).entries;
  eq(has(fire, 'WXK11-017-E1'), true, '効果離脱×自ターンで発火');
  eq(fire.find(e => e.effectId === 'WXK11-017-E1')?.playerId, HOST, 'エントリの playerId は watcher(HOST)');
  // causeOwnerId 未指定（バトル/ルール離脱）＝byEffect ゲートで非発火
  eq(has(collectLeaveFieldTriggers(trigCtx(HOST), SIGNI, [], GUEST, host, guest).entries, 'WXK11-017-E1'), false, 'バトル離脱は byEffect で非発火');
  // 相手ターン（activeUserId=GUEST）＝turnOwner:self ゲートで非発火
  eq(has(collectLeaveFieldTriggers(trigCtx(GUEST), SIGNI, [], GUEST, host, guest, HOST).entries, 'WXK11-017-E1'), false, '相手ターンは turnOwner:self で非発火');
});
// WXEX1-30-E2 / WXDi-P03-040-E1「対戦相手の凍結状態のシグニが場を離れたとき」＝any_opp + leftStateFilter{isFrozen}。
//   凍結状態は離脱直前の盤面（leftBeforeState の signi_frozen[leftZoneIdx]）で判定する。
test('§6.3 ON_LEAVE_FIELD any_opp leftStateFilter(isFrozen): 凍結シグニ離脱のみ発火（WXEX1-30-E2/WXDi-P03-040-E1）', () => {
  const host = mkState({ signi: ['WXDi-P03-040', null, null] }); const guest = mkState({});
  const frozenBefore = mkState({ signi: [SIGNI, null, null] }); frozenBefore.field.signi_frozen = [true, false, false];
  const upBefore = mkState({ signi: [SIGNI, null, null] }); // signi_frozen 全 false
  // 凍結×離脱直前 state 渡し＝発火
  eq(has(collectLeaveFieldTriggers(trigCtx(HOST), SIGNI, [], GUEST, host, guest, undefined, frozenBefore, 0).entries, 'WXDi-P03-040-E1'), true, '凍結離脱で発火');
  // 非凍結＝leftStateFilter で非発火
  eq(has(collectLeaveFieldTriggers(trigCtx(HOST), SIGNI, [], GUEST, host, guest, undefined, upBefore, 0).entries, 'WXDi-P03-040-E1'), false, '非凍結離脱は非発火');
  // before-state 未渡し（バトル離脱）＝判定材料無しで保守的に非発火
  eq(has(collectLeaveFieldTriggers(trigCtx(HOST), SIGNI, [], GUEST, host, guest).entries, 'WXDi-P03-040-E1'), false, 'before-state 無しは保守的に非発火');
});

