// CONDITIONAL_GROW_AND_KEY_DISABLE: WXK02-029 ビカム・ユー①。「自センターが相手センターのレベル以下なら
// グロウ（コスト支払い）。ターン終了時まで、あなたのすべてのキーは能力を失う。」条件付きグロウ＋keys_abilities_disabled。
const LRIG_BY_LV = (lv: string) => findCard(c => c.Type === 'ルリグ' && c.Level === lv);
test('CONDITIONAL_GROW_AND_KEY_DISABLE: 自Lv≤相手→グロウ＋キー能力喪失', () => {
  const MYL = LRIG_BY_LV('1'), OPPL = LRIG_BY_LV('3'), NEXT = LRIG_BY_LV('2');
  const ctx = mkCtx({}, {});
  ctx.ownerState.field.lrig = [MYL];
  (ctx.ownerState as { lrig_deck: string[] }).lrig_deck = [NEXT];
  ctx.otherState.field.lrig = [OPPL];
  const r = run({ type: 'STUB', id: 'CONDITIONAL_GROW_AND_KEY_DISABLE' } as unknown as EffectAction, ctx);
  eq(r.ownerState.field.lrig.length, 2, 'グロウしていない');
  eq(r.ownerState.field.lrig.at(-1), NEXT, '次ルリグへグロウしていない');
  eq((r.ownerState as { keys_abilities_disabled?: boolean }).keys_abilities_disabled, true, 'キー能力喪失フラグ');
});
test('CONDITIONAL_GROW_AND_KEY_DISABLE: 自Lv>相手→グロウせずキー能力喪失のみ', () => {
  const MYL = LRIG_BY_LV('3'), OPPL = LRIG_BY_LV('1'), NEXT = LRIG_BY_LV('4');
  const ctx = mkCtx({}, {});
  ctx.ownerState.field.lrig = [MYL];
  (ctx.ownerState as { lrig_deck: string[] }).lrig_deck = [NEXT];
  ctx.otherState.field.lrig = [OPPL];
  const r = run({ type: 'STUB', id: 'CONDITIONAL_GROW_AND_KEY_DISABLE' } as unknown as EffectAction, ctx);
  eq(r.ownerState.field.lrig.length, 1, '条件不成立なのにグロウした');
  eq((r.ownerState as { keys_abilities_disabled?: boolean }).keys_abilities_disabled, true, 'キー能力喪失フラグ');
});

// この方法で＜X＞のシグニがN枚トラッシュに置かれた場合＝MILL(DECK_CARD)→lastProcessedCards→TRASHED_STORY_COUNT_GTE。
// IS_MY_TURN 誤変換系統（WX20-075 等）の回帰資産。デッキトップ3枚をトラッシュし、悪魔3枚のときだけ then が発火する。
{
  const DEMON = findCard(c => isSigni(c) && (c.CardClass ?? '').includes('悪魔'));
  const NONDEMON = findCard(c => isSigni(c) && !!c.CardClass && !(c.CardClass ?? '').includes('悪魔'));
  const millThenDraw = { type: 'SEQUENCE', steps: [
    { type: 'TRASH', target: { type: 'DECK_CARD', owner: 'self', count: 3 } },
    { type: 'CONDITIONAL', condition: { type: 'TRASHED_STORY_COUNT_GTE', story: '悪魔', count: 3 }, then: { type: 'DRAW', owner: 'self', count: 1 } },
  ] } as unknown as EffectAction;
  test('TRASHED_STORY_COUNT_GTE: MILL3で悪魔3枚→then発火（WX20-075）', () => {
    const ctx = mkCtx({ deckTop: [DEMON, DEMON, DEMON], hand: 5 }, {});
    const r = run(millThenDraw, ctx);
    eq(r.ownerState.hand.length, 6, '悪魔3枚→ドロー発火');
  });
  test('TRASHED_STORY_COUNT_GTE: MILL3で悪魔0枚→then不発（無条件発火バグの回帰）', () => {
    const ctx = mkCtx({ deckTop: [NONDEMON, NONDEMON, NONDEMON], hand: 5 }, {});
    const r = run(millThenDraw, ctx);
    eq(r.ownerState.hand.length, 5, '悪魔0枚→ドローしない');
  });
  // LAST_PROCESSED_ALL_MATCH: この方法で処理したカードが**すべて**フィルタ一致（WXDi-P05-042/WXK09-097）。
  // ≥N一致（TRASHED_STORY_COUNT_GTE/LAST_PROCESSED_MATCHES）と異なり、1枚でも外れると不発。空集合も不発。
  const millThenDrawAll = { type: 'SEQUENCE', steps: [
    { type: 'TRASH', target: { type: 'DECK_CARD', owner: 'self', count: 3 } },
    { type: 'CONDITIONAL', condition: { type: 'LAST_PROCESSED_ALL_MATCH', filter: { cardType: 'シグニ', story: '悪魔' } }, then: { type: 'DRAW', owner: 'self', count: 1 } },
  ] } as unknown as EffectAction;
  test('LAST_PROCESSED_ALL_MATCH: MILL3で全て悪魔→then発火', () => {
    const ctx = mkCtx({ deckTop: [DEMON, DEMON, DEMON], hand: 5 }, {});
    eq(run(millThenDrawAll, ctx).ownerState.hand.length, 6, '全て悪魔→ドロー発火');
  });
  test('LAST_PROCESSED_ALL_MATCH: MILL3で1枚だけ非悪魔→then不発（全一致でないと発火しない）', () => {
    const ctx = mkCtx({ deckTop: [DEMON, DEMON, NONDEMON], hand: 5 }, {});
    eq(run(millThenDrawAll, ctx).ownerState.hand.length, 5, '1枚外れ→ドローしない');
  });
  // LOOK_AND_REORDER（公開）も閲覧カードを lastProcessedCards に記録する（resumeLookAndReorder）。
  // 「この方法で公開されたN枚/すべて〜の場合」（WX12-Re10/WXDi-P07-064）が参照する。
  const lookThenAll = { type: 'SEQUENCE', steps: [
    { type: 'LOOK_AND_REORDER', source: { location: 'deck', owner: 'self' }, count: 3, private: false, reorder: false, canTrash: false, destination: { location: 'deck', owner: 'self', position: 'top' } },
    { type: 'CONDITIONAL', condition: { type: 'LAST_PROCESSED_ALL_MATCH', filter: { cardType: 'シグニ', story: '悪魔' } }, then: { type: 'DRAW', owner: 'self', count: 1 } },
  ] } as unknown as EffectAction;
  test('LOOK_AND_REORDER 記録: 公開3枚が全て悪魔→ALL_MATCH発火', () => {
    const ctx = mkCtx({ deckTop: [DEMON, DEMON, DEMON], hand: 5 }, {});
    eq(run(lookThenAll, ctx).ownerState.hand.length, 6, '全て悪魔→ドロー発火');
  });
  test('LOOK_AND_REORDER 記録: 公開3枚に非悪魔混在→ALL_MATCH不発', () => {
    const ctx = mkCtx({ deckTop: [DEMON, NONDEMON, DEMON], hand: 5 }, {});
    eq(run(lookThenAll, ctx).ownerState.hand.length, 5, '1枚外れ→ドローしない');
  });
}

// O-53: LOOK_AND_REORDER の hand source は deck へ暗黙フォールバックさせない。
// 群Aは閲覧専用 REVEAL_CARDS、群Bは既存 TRANSFER_TO_DECK{HAND_CARD} が正準形。
{
  const walkActions = (node: unknown, pred: (a: Record<string, unknown>) => boolean, out: Record<string, unknown>[] = []): Record<string, unknown>[] => {
    if (!node || typeof node !== 'object') return out;
    if (Array.isArray(node)) { node.forEach(v => walkActions(v, pred, out)); return out; }
    const obj = node as Record<string, unknown>;
    if (typeof obj.type === 'string' && pred(obj)) out.push(obj);
    Object.values(obj).forEach(v => walkActions(v, pred, out));
    return out;
  };
  // 🆕**`WX11-018-E1` を 2026-08-27（Sheet1 B11）で追加**＝③「対戦相手の手札と、対戦相手のデッキの
  //   一番上を見る」の**手札側**を配線した（それまでデッキ側しか木に出ておらず finding を閉じられずにいた）。
  //   ⚠この集合は**両方向 assert**（増えても減っても FAIL）＝hand-source を足したら必ずここへ載せる。
  const opponentHandLookIds = [
    'SPDi43-27-E2', 'WD16-010-E1', 'WX06-CB02-E2', 'WX11-018-E1', 'WX17-002-E4', 'WX17-042-E2',
    'WX17-069-E1', 'WXDi-P03-025-E1', 'WXDi-P09-065-E1', 'WXDi-P09-067-E1',
    'WXK09-039-E2', 'WXK11-061-E1',
  ].sort();
  const handToDeckSpecs = new Map([
    ['WDK05-R01-E2', 2], ['WDK05-R14-E1', 1], ['WDK05-R17-E1', 1],
    ['WXK02-089-E1', 2], ['WXK05-025-E1', 2],
  ]);

  test('O-53 構造集合: hand-source LOOK_AND_REORDER は相手手札閲覧12効果だけ', () => {
    const actual: string[] = [];
    for (const effects of effectsMap.values()) for (const effect of effects) {
      const hits = walkActions(effect.action, a => a.type === 'LOOK_AND_REORDER'
        && (a.source as { location?: string } | undefined)?.location === 'hand');
      if (hits.length > 0) actual.push(effect.effectId);
    }
    eq(actual.sort().join(','), opponentHandLookIds.join(','), '群Bが LOOK_AND_REORDER に戻った／群Aが欠けた');
  });

  test('O-53 構造集合: 手札→デッキ5効果は TRANSFER_TO_DECK{HAND_CARD,bottom} と原文枚数', () => {
    for (const [effectId, count] of handToDeckSpecs) {
      const effect = [...effectsMap.values()].flat().find(e => e.effectId === effectId);
      ok(!!effect, `${effectId}: live effectなし`);
      const hits = walkActions(effect!.action, a => a.type === 'TRANSFER_TO_DECK'
        && (a.source as { type?: string } | undefined)?.type === 'HAND_CARD');
      eq(hits.length, 1, `${effectId}: HAND_CARD transfer数`);
      const source = hits[0].source as { owner?: string; count?: unknown };
      eq(source.owner, 'self', `${effectId}: owner`);
      eq(source.count, count, `${effectId}: 原文枚数`);
      eq(hits[0].position, 'bottom', `${effectId}: bottom`);
      eq(hits[0].shuffle, false, `${effectId}: shuffleなし`);
    }
  });

  test('O-53 engine群A E2E: 相手手札だけをREVEAL_CARDSで見て両デッキ不変・lastProcessedCards記録', () => {
    withSavedCursor(() => {
    const effect = effectsMap.get('WX06-CB02')!.find(e => e.effectId === 'WX06-CB02-E2')!;
    const ctx = mkCtx({ deckTop: [fresh(), fresh()], hand: 3 }, { deckTop: [fresh(), fresh(), fresh()], hand: 4 });
    const ownerDeck = [...ctx.ownerState.deck];
    const otherDeck = [...ctx.otherState.deck];
    const otherHand = [...ctx.otherState.hand];
    const first = executeAction(effect.action, ctx);
    ok(!first.done && first.pending.type === 'REVEAL_CARDS', '閲覧専用REVEAL_CARDSで停止');
    const pending = first.pending as PendingInteractionDef & { type: 'REVEAL_CARDS' };
    eq([...pending.cards].sort().join(','), [...otherHand].sort().join(','), '表示カード＝相手手札の集合');
    eq(first.ownerState.deck.join(','), ownerDeck.join(','), '自分デッキ不変');
    eq(first.otherState.deck.join(','), otherDeck.join(','), '相手デッキ不変（旧実装の実害）');
    eq([...(first.lastProcessedCards ?? [])].sort().join(','), [...otherHand].sort().join(','), 'lastProcessedCards＝相手手札');
    const doneResult = resumeRevealCards(pending, { ...ctx, ownerState: first.ownerState, otherState: first.otherState,
      logs: first.logs, lastProcessedCards: first.lastProcessedCards });
    ok(doneResult.done, '閲覧確認後に完了');
    eq(doneResult.otherState.hand.join(','), otherHand.join(','), '閲覧後も相手手札不変');
    eq(doneResult.otherState.deck.join(','), otherDeck.join(','), '閲覧後も相手デッキ不変');
    });
  });

  test('O-53 engine群B E2E: 2枚DRAW後に手札2枚を選択順どおりデッキ下へ戻す', () => {
    withSavedCursor(() => {
    const effect = effectsMap.get('WXK02-089')!.find(e => e.effectId === 'WXK02-089-E1')!;
    const ctx = mkCtx({ deckTop: [fresh(), fresh(), fresh(), fresh()], hand: 4 }, {});
    const initialHandCount = ctx.ownerState.hand.length;
    const initialDeckCount = ctx.ownerState.deck.length;
    const first = executeEffect(effect, ctx);
    ok(!first.done && first.pending.type === 'SELECT_TARGET', 'DRAW後に手札選択で停止');
    const pending = first.pending as PendingInteractionDef & { type: 'SELECT_TARGET' };
    eq(first.ownerState.hand.length, initialHandCount + 2, 'DRAW直後の手札');
    eq(first.ownerState.deck.length, initialDeckCount - 2, 'DRAW直後のデッキ');
    const selected = [pending.candidates[1], pending.candidates[0]];
    const result = resumeSelectTarget(selected, pending, { ...ctx, ownerState: first.ownerState, otherState: first.otherState,
      logs: first.logs, lastProcessedCards: first.lastProcessedCards });
    ok(result.done, '選択後に完了');
    eq(result.ownerState.hand.length, first.ownerState.hand.length - 2, '手札がN枚減る');
    eq(result.ownerState.deck.length, first.ownerState.deck.length + 2, 'デッキがN枚増える');
    eq(result.ownerState.deck.slice(-2).join(','), selected.join(','), 'bottomへの挿入が選択順を保存');
    });
  });

  test('O-53 fail-loud: 未対応source/destinationをデッキへ暗黙フォールバックしない', () => {
    withSavedCursor(() => {
    const ctx = mkCtx({ deckTop: [fresh(), fresh()] }, {});
    const before = ctx.ownerState.deck.join(',');
    const badSource = run({ type: 'LOOK_AND_REORDER', source: { location: 'trash', owner: 'self' }, count: 1,
      private: true, reorder: false, destination: { location: 'deck', owner: 'self', position: 'top' } } as unknown as EffectAction, ctx);
    eq(badSource.ownerState.deck.join(','), before, '未知sourceでデッキを触らない');
    ok(badSource.logs.some(l => l.includes('未対応')), '未知sourceをログへ出す');
    const badDest = run({ type: 'LOOK_AND_REORDER', source: { location: 'deck', owner: 'self' }, count: 1,
      private: true, reorder: false, destination: { location: 'hand', owner: 'self', position: 'top' } } as unknown as EffectAction, ctx);
    eq(badDest.ownerState.deck.join(','), before, '未対応destinationでデッキを触らない');
    ok(badDest.logs.some(l => l.includes('未対応')), '未対応destinationをログへ出す');
    });
  });
}

// GRANT_LRIG_ABILITY: abilities を lrig_granted_auto_effects へ追加。permanent（「このゲームの間」＝WXDi-P06-004等）は
// 各能力に permanentGrant が刻まれ、ターン境界リセット（filter e.permanentGrant）で生き残る。
test('GRANT_LRIG_ABILITY: 付与能力が登録され permanent は permanentGrant を刻む', () => {
  const subEff = {
    effectId: 'TEST-sub-E1', effectType: 'ACTIVATED', timing: ['MAIN'], cost: { exceed: 4 },
    action: { type: 'DRAW', owner: 'self', count: 1 }, duration: 'INSTANT', mandatory: false,
  } as unknown as CardEffect;
  // ターン終了時まで型（permanent なし）
  const ctx1 = mkCtx({}, {});
  const r1 = run({ type: 'GRANT_LRIG_ABILITY', abilities: [subEff], rawText: '【起】…' } as unknown as EffectAction, ctx1);
  const g1 = (r1.ownerState as { lrig_granted_auto_effects?: CardEffect[] }).lrig_granted_auto_effects ?? [];
  eq(g1.length, 1, '付与能力が登録されていない');
  eq((g1[0] as { permanentGrant?: boolean }).permanentGrant, undefined, '非permanentにpermanentGrantが付いた');
  // このゲームの間型（permanent:true）
  const ctx2 = mkCtx({}, {});
  const r2 = run({ type: 'GRANT_LRIG_ABILITY', abilities: [subEff], rawText: '【起】…', permanent: true } as unknown as EffectAction, ctx2);
  const g2 = (r2.ownerState as { lrig_granted_auto_effects?: CardEffect[] }).lrig_granted_auto_effects ?? [];
  eq(g2.length, 1, 'permanent付与能力が登録されていない');
  eq((g2[0] as { permanentGrant?: boolean }).permanentGrant, true, 'permanentGrantが刻まれていない');
  // doPhaseAdvance / confirmEndDiscard / cpuTurnAction が共通利用する実リセット関数を通す。
  const after = clearTurnGrantedLrigAbilities({
    ...mkState({}),
    lrig_granted_auto_effects: g2.concat(g1),
  }).lrig_granted_auto_effects ?? [];
  eq(after.length, 1, 'ターン終了処理でpermanentのみ残っていない');
  eq(after[0].effectId, 'TEST-sub-E1', 'ターン終了処理がpermanent能力を取り違えた');
});

test('§6.3 E-2 WXK07-001-E1: 自ルリグへ恒久付与し、APS collectorへ載る（内側制限はhonest defer）', () => {
  const effect = (MANUAL_EFFECTS['WXK07-001'] ?? []).find(e => e.effectId === 'WXK07-001-E1')!;
  const flower = mkState({ lrig: ['WXK07-001'] });
  const noGrant = collectTurnTriggers(trigCtx(HOST, HOST), 'ON_ATTACK_PHASE_START', flower, mkState({})).entries;
  ok(!hasEffect(noGrant, 'WXK07-001-E1-GRANT'), '付与前に引用AUTOが発火した');

  const installed = run(effect.action, mkCtx({ lrig: ['WXK07-001'] }, {}, 'WXK07-001'));
  const granted = installed.ownerState.lrig_granted_auto_effects ?? [];
  eq(granted.length, 1, '引用AUTOが自ルリグの付与ストアへ入らない');
  eq(granted[0].permanentGrant, true, '引用AUTOにpermanentGrantが刻まれない');
  // §6.4 O-10（続き512）＝内側の3制限を実装した（旧アサートは defer であることを固定していた）。
  {
    const inner = JSON.stringify(granted[0].action);
    ok(inner.includes('"id":"DECLARE_NUMBER"'), '①数字を宣言する（→ declared_guard_restrict_level）');
    ok(inner.includes('"id":"BLOCK_COLORLESS_ENERGY_PAY"'), '②無色のカードでエナコストを支払えない');
    ok(inner.includes('"actionId":"ARTS_LIMIT_1"'), '③一度しかアーツを使用できない');
    ok(inner.includes('"type":"LRIG_LEVEL"') && inner.includes('"owner":"opponent"') && inner.includes('"value":4'),
       '🔴③は「**自身の**センタールリグがレベル４以上の場合」限定＝落とすと常時1回制限になる');
    ok(!inner.includes('DEFERRED_'), 'defer は残っていない');
  }

  const afterTurn = clearTurnGrantedLrigAbilities(installed.ownerState);
  eq(afterTurn.lrig_granted_auto_effects?.length, 1, 'ターン終了時に恒久付与が消えた');
  const collected = collectTurnTriggers(trigCtx(HOST, HOST), 'ON_ATTACK_PHASE_START', afterTurn, installed.otherState).entries;
  ok(hasEffect(collected, 'WXK07-001-E1-GRANT'), '付与AUTOが自アタックフェイズ開始collectorへ載らない');
});

test('§6.3 E-2 WXDi-P03-003-E1: プレイヤー恒久【常】が中央＜武勇＞だけを強化し、非メイン時バニッシュでEC1', () => withSavedCursor(() => {
  const effect = (MANUAL_EFFECTS['WXDi-P03-003'] ?? []).find(e => e.effectId === 'WXDi-P03-003-E1')!;
  const warriors = [...cardMap.values()].filter(c => c.Type === 'シグニ' && (c.CardClass ?? '').includes('武勇') && Number.isFinite(parseInt(c.Power ?? '', 10)));
  const nonWarrior = [...cardMap.values()].find(c => c.Type === 'シグニ' && !(c.CardClass ?? '').includes('武勇') && Number.isFinite(parseInt(c.Power ?? '', 10)))!;
  ok(warriors.length >= 2, '＜武勇＞テストカード不足');
  const side = warriors[0].CardNum;
  const center = warriors[1].CardNum;
  const ctx = mkCtx({ signi: [side, center, nonWarrior.CardNum] }, {}, 'WXDi-P03-003');
  const installed = run(effect.action, ctx);
  eq(installed.ownerState.game_granted_effects?.length, 1, 'プレイヤー付与【常】が永続ストアへ入らない');
  eq(installed.ownerState.lrig_granted_auto_effects?.length ?? 0, 0, 'プレイヤー能力をルリグ付与ストアへ誤格納した');
  eq(clearTurnGrantedLrigAbilities(installed.ownerState).game_granted_effects?.length, 1, 'ターン終了処理でプレイヤー恒久能力が消えた');

  const without = { ...installed.ownerState, game_granted_effects: undefined };
  const basePowers = calcFieldPowers(without, installed.otherState, true, effectsMap, cardMap);
  const grantedPowers = calcFieldPowers(installed.ownerState, installed.otherState, true, effectsMap, cardMap);
  eq(grantedPowers.get(center), (basePowers.get(center) ?? 0) + 1000, '中央＜武勇＞が+1000されない');
  eq(grantedPowers.get(side), basePowers.get(side), '側面＜武勇＞まで過剰に+1000された');
  eq(grantedPowers.get(nonWarrior.CardNum), basePowers.get(nonWarrior.CardNum), '非＜武勇＞まで過剰に+1000された');

  const layer = collectGrantedFromLayer(installed.ownerState, installed.otherState, true, effectsMap, cardMap, grantedPowers);
  ok(layer.has(center), '中央＜武勇＞へ内側AUTOが付与されない');
  ok(!layer.has(side) && !layer.has(nonWarrior.CardNum), '中央＜武勇＞以外へ内側AUTOが過剰付与された');
  const augmented = new Map(effectsMap);
  for (const [num, extras] of layer) augmented.set(num, [...(augmented.get(num) ?? []), ...extras]);
  const afterBanish = {
    ...installed.ownerState,
    field: { ...installed.ownerState.field, signi: [installed.ownerState.field.signi[0], null, installed.ownerState.field.signi[2]] },
  };
  const main = collectBanishTriggers({ ...trigCtx(HOST, HOST), turnPhase: 'MAIN', effectsMap: augmented }, center, HOST, afterBanish, installed.otherState, installed.ownerState).entries;
  ok(!hasEffect(main, 'WXDi-P03-003-E1-GRANT-BANISH'), 'メインフェイズ中のバニッシュで過剰発火した');
  const attack = collectBanishTriggers({ ...trigCtx(HOST, HOST), turnPhase: 'ATTACK_SIGNI', effectsMap: augmented }, center, HOST, afterBanish, installed.otherState, installed.ownerState).entries;
  const entry = attack.find(e => e.effectId === 'WXDi-P03-003-E1-GRANT-BANISH');
  ok(!!entry, 'メインフェイズ以外のバニッシュで付与AUTOが発火しない');
  const resolved = run(entry!.effect.action, { ...ctx, ownerState: afterBanish, otherState: installed.otherState, sourceCardNum: center });
  eq(resolved.ownerState.energy.length, afterBanish.energy.length + 1, '付与AUTOのエナチャージ1が実行されない');
}));

test('§6.3 E-2 WXK03-001-E3: 相手ルリグへ2能力を恒久付与し、引用内の「あなた」を付与先として実行', () => withSavedCursor(() => {
  const effect = (MANUAL_EFFECTS['WXK03-001'] ?? []).find(e => e.effectId === 'WXK03-001-E3')!;
  eq(effect.cost, undefined, '《コイン×0》を実コストとして追加した');
  const colorless = [...cardMap.values()].find(c => c.Color === '無' && c.Type !== 'ルリグ')!;
  ok(!!colorless, '無色手札コスト用カード不足');
  const ctx = mkCtx({ lrig: ['WXK03-001'] }, { lrig: ['WXK03-001'], hand: 2, life: 3 }, 'WXK03-001');
  ctx.otherState = { ...ctx.otherState, hand: [colorless.CardNum, ...ctx.otherState.hand.slice(1)] };
  const installed = run(effect.action, ctx);
  eq(installed.ownerState.lrig_granted_auto_effects?.length ?? 0, 0, '能力を効果使用者のルリグへ誤付与した');
  const targetGrants = installed.otherState.lrig_granted_auto_effects ?? [];
  eq(targetGrants.length, 2, '対戦相手ルリグへ引用2能力が付与されない');
  ok(targetGrants.every(e => e.permanentGrant), '相手への付与能力にpermanentGrantが刻まれない');
  const afterTurn = clearTurnGrantedLrigAbilities(installed.otherState);
  eq(afterTurn.lrig_granted_auto_effects?.length, 2, '付与先のターン終了で恒久能力が消えた');

  eq(applyLrigDrawPhaseReplacement({ ...afterTurn, lrig_granted_auto_effects: [] }, 1), 1, '付与なしで通常1ドローが変化した');
  eq(applyLrigDrawPhaseReplacement(afterTurn, 1), 2, '通常1ドローが2ドローへ置換されない');
  eq(applyLrigDrawPhaseReplacement(afterTurn, 2), 2, '通常2ドローまで過剰増加した');

  const turnEnd = collectTurnTriggers(trigCtx(GUEST, GUEST), 'ON_TURN_END', afterTurn, installed.ownerState).entries;
  const entry = turnEnd.find(e => e.effectId === 'WXK03-001-E3-GRANT-END');
  ok(!!entry, '付与先自身のターン終了collectorへ引用AUTOが載らない');

  const paidCtx = { ...ctx, ownerState: afterTurn, otherState: installed.ownerState, sourceCardNum: 'WXK03-001' };
  const paidOffer = executeEffect(entry!.effect, paidCtx);
  ok(!paidOffer.done && paidOffer.pending.type === 'CHOOSE', '無色手札1枚の任意支払いが提示されない');
  const paidResume = resumeOptionalCost('pay', [], (paidOffer as Extract<ExecResult, { done: false }>).pending as never,
    { ...paidCtx, ownerState: paidOffer.ownerState, otherState: paidOffer.otherState, logs: paidOffer.logs });
  const paid = finish(paidResume, paidCtx);
  eq(paid.ownerState.life_cloth.length, afterTurn.life_cloth.length, '無色カードを捨てたのに自傷した');
  ok(paid.ownerState.trash.includes(colorless.CardNum), '支払った無色カードがトラッシュへ行かない');
  eq(paid.otherState.life_cloth.length, installed.ownerState.life_cloth.length, '引用内の「あなた」を効果使用者へ誤適用した');

  const skipCtx = { ...ctx, ownerState: afterTurn, otherState: installed.ownerState, sourceCardNum: 'WXK03-001' };
  const skipOffer = executeEffect(entry!.effect, skipCtx);
  const skippedResume = resumeOptionalCost('skip', [], (skipOffer as Extract<ExecResult, { done: false }>).pending as never,
    { ...skipCtx, ownerState: skipOffer.ownerState, otherState: skipOffer.otherState, logs: skipOffer.logs });
  const skipped = finish(skippedResume, skipCtx);
  eq(skipped.ownerState.life_cloth.length, afterTurn.life_cloth.length - 1, '未払い時に付与先が1ダメージを受けない');
  eq(skipped.otherState.life_cloth.length, installed.ownerState.life_cloth.length, '未払い自傷を元の効果使用者へ誤適用した');
}));

// タスク12(xxiii): 「センタールリグ１体を対象とし、ターン終了時まで、それは以下の能力を得る。『【起】エクシード…』」
// （WX25-P1-001/003/005/007/009）。従来は付与構造が丸ごと欠落し、3能力をコストゲートも選択も無く
// 即時連続実行する過剰実行バグだった＝GRANT_LRIG_ABILITY（targetedCenter）＋ACTIVATED×3（exceedコスト）へ固定。
test('引用付与（対象形式）: WX25-P1-001 が RECOLLECT_GATE + GRANT_LRIG_ABILITY(【起】×3・エクシード1/1/2) にパースされる', () => {
  const parsed = parseCardEffects(cardMap.get('WX25-P1-001')!);
  const act = parsed.find(e => e.effectId === 'WX25-P1-001-E1')?.action as import('../src/types/effects').SequenceAction;
  eq(act?.type, 'SEQUENCE', '外形');
  eq(act?.steps?.[0]?.type, 'RECOLLECT_GATE', 'リコレクトゲート');
  const gla = act?.steps?.[1] as import('../src/types/effects').GrantLrigAbilityAction;
  eq(gla?.type, 'GRANT_LRIG_ABILITY', '付与アクション');
  eq(gla?.targetedCenter, true, 'targetedCenter 刻印');
  eq(gla?.abilities?.length, 3, '付与能力3本');
  eq(gla?.abilities?.every(a => a.effectType === 'ACTIVATED' && a.timing?.[0] === 'MAIN'), true, '全て【起】MAIN');
  eq(gla?.abilities?.map(a => a.cost?.exceed).join(','), '1,1,2', 'エクシードコスト1/1/2');
  // 内側1本目は「5枚見て2枚まで手札・残りをデッキ下」＝REVEAL_AND_PICK（LOOK_AND_REORDER 縮退＝pick脱落の回帰防止）
  const sub1 = gla?.abilities?.[0]?.action as import('../src/types/effects').RevealAndPickAction;
  eq(sub1?.type, 'REVEAL_AND_PICK', '内側1本目の型');
  eq(`${sub1?.revealCount}/${sub1?.pickCount}/${sub1?.pickUpTo}`, '5/2/true', '5枚見て2枚まで');
});

// タスク12(xxiii)残・SPDi47-03: 「手札を好きな枚数捨てる」＝TRASH{HAND_CARD, count:'ALL', upToCount}の対話分岐
// （SIGNI分岐と同形の移植）＋捨て枚数を LAST_PROCESSED_COUNT_GTE の2段閾値（8→ライフ→デッキ下／1→シグニ→デッキ下）
// が連鎖で読めること。⚠LIFE_CLOTH_CARD 転送は lastProcessedCards を上書きしない設計（GTE8発火後も GTE1 が捨て枚数を見る）。
{
  const spdi47Chain = (): EffectAction => ({ type: 'SEQUENCE', steps: [
    { type: 'TRASH', target: { type: 'HAND_CARD', owner: 'self', count: 'ALL', upToCount: true } },
    { type: 'CONDITIONAL', condition: { type: 'LAST_PROCESSED_COUNT_GTE', value: 8 },
      then: { type: 'TRANSFER_TO_DECK', source: { type: 'LIFE_CLOTH_CARD', owner: 'opponent', count: 1 }, shuffle: false, position: 'bottom' } },
    { type: 'CONDITIONAL', condition: { type: 'LAST_PROCESSED_COUNT_GTE', value: 1 },
      then: { type: 'TRANSFER_TO_DECK', source: { type: 'SIGNI', owner: 'opponent', count: 1, filter: { cardType: 'シグニ' } }, shuffle: false, position: 'bottom' } },
  ] }) as unknown as EffectAction;
  test('TRASH 手札好きな枚数（ALL+upTo）: 5枚捨て→GTE8不発・GTE1発火（相手シグニ→デッキ下）', () => {
    const ctx = mkCtx({ hand: 5 }, { signi: [SIGNI, null, null] });
    const r = run(spdi47Chain(), ctx);
    eq(r.ownerState.hand.length, 0, '手札が全部捨てられていない');
    eq(r.otherState.life_cloth.length, 7, 'GTE8が誤発火（ライフが減った）');
    eq(r.otherState.field.signi.filter(s => (s?.length ?? 0) > 0).length, 0, 'GTE1不発（シグニが場に残った）');
    eq(r.otherState.deck.at(-1), SIGNI, 'シグニがデッキ下に置かれていない');
  });
  test('TRASH 手札好きな枚数（ALL+upTo）: 8枚捨て→GTE8発火（ライフ→デッキ下）かつGTE1も発火（非上書き）', () => {
    const ctx = mkCtx({ hand: 8 }, { signi: [SIGNI_P3000, null, null] });
    const r = run(spdi47Chain(), ctx);
    eq(r.ownerState.hand.length, 0, '手札が全部捨てられていない');
    eq(r.otherState.life_cloth.length, 6, 'GTE8不発（ライフが減っていない）');
    eq(r.otherState.field.signi.filter(s => (s?.length ?? 0) > 0).length, 0, 'GTE1不発＝LIFE転送がlastProcessedCardsを上書きした');
  });
}

// タスク12(xxiii)残・SPDi47-05: BANISH_REDIRECT{redirectTo:'exile'}＝「エナゾーンに置かれる代わりにゲームから除外」。
// フラグ設定（executor）と行き先解決（banishDestination＝どのゾーンにも置かない）の両方を固定。
test('BANISH_REDIRECT exile: フラグ設定＋バニッシュ先がどのゾーンにも置かれない', () => {
  const ctx = mkCtx({}, {});
  const r = run({ type: 'BANISH_REDIRECT', target: { type: 'SIGNI', owner: 'opponent', count: 'ALL' }, redirectTo: 'exile', until: 'END_OF_TURN' } as unknown as EffectAction, ctx);
  eq((r.ownerState as PlayerState).banish_redirect_to_exile, true, 'フラグ未設定');
  const banished = mkState({});
  const { state: after } = banishDestination(banished, r.ownerState as PlayerState, 'TEST-CARD');
  eq(after.energy.length, banished.energy.length, 'エナに置かれた');
  eq(after.trash.length, banished.trash.length, 'トラッシュに置かれた');
  eq(after.hand.length, banished.hand.length, '手札に置かれた');
});

// タスク12(xxiii)副産物: 「その中からカードをN枚まで手札に加え、残りを好きな順番でデッキの一番上/下に置く」が
// 汎用デッキ/トラッシュ規則（LOOK_AND_REORDER）に先に飲まれて pick（手札加え）が丸ごと脱落する規則順序バグの回帰防止。
