  eq(dn.triggerScope, 'any_ally', 'あなたのシグニ→any_ally');
  eq(dn.triggerCondition?.byEffect, true, '効果によって→byEffect');
  // ON_SIGNI_DOWN＋excludeSelf＋story filter（「あなたの他の＜植物＞のシグニ」）
