  eq(ml.timing?.[0], 'ON_CARD_MILLED_FROM_DECK', '合計N枚以上トラッシュ→ON_CARD_MILLED_FROM_DECK');
  eq(ml.triggerCondition?.milledMinCount, 2, '合計２枚以上→milledMinCount=2');
