// ── PLACE_TRASH_SIGNI_FACING_SAME_POWER（§6.4 O-32・`WXDi-CP01-024-E1`）──
// 🔑相手ゾーン zi の正面は自分ゾーン 2-zi。**同じパワー**のトラッシュ札しか出せない。
test('PLACE_TRASH_SIGNI_FACING_SAME_POWER: 同パワーの札だけが候補になり正面ゾーンへ出る', () => withSavedCursor(() => {
  const virtual = findCard(c => c.Type === 'シグニ' && (c.CardClass ?? '').includes('バーチャル') && !!c.Power);
  const power = cardMap.get(virtual)!.Power!;
  const oppSame = findCard(c => c.Type === 'シグニ' && c.Power === power && c.CardNum !== virtual);
  const oppDiff = findCard(c => c.Type === 'シグニ' && !!c.Power && c.Power !== power);
  const otherVirtual = findCard(c => c.Type === 'シグニ' && (c.CardClass ?? '').includes('バーチャル')
    && !!c.Power && c.Power !== power);
  const act = { type: 'STUB', id: 'PLACE_TRASH_SIGNI_FACING_SAME_POWER', value: 'バーチャル' } as EffectAction;
  // 相手はゾーン0＝正面は自分ゾーン2。トラッシュには同パワー1枚＋別パワー1枚。
  const ctx = mkCtx({}, { signi: [oppSame, null, null] });
  ctx.ownerState.trash = [virtual, otherVirtual];
  const r = executeEffect({ effectId: 't', effectType: 'AUTO', action: act, duration: 'INSTANT', mandatory: true } as CardEffect, ctx);
  ok(!r.done && r.pending.type === 'SELECT_TARGET', 'トラッシュ選択が出る');
  eq((r.pending as { candidates: string[] }).candidates.join('|'), virtual, '同じパワーの札だけ候補');
  const c = { ...ctx, ownerState: r.ownerState, otherState: r.otherState, logs: r.logs } as ExecCtx;
  const placed = finish(resumeSelectTarget([virtual], r.pending as never, c), c);
  eq(placed.ownerState.field.signi[2]?.at(-1) ?? '', virtual, '相手ゾーン0の正面＝自分ゾーン2へ');
  ok(!placed.ownerState.trash.includes(virtual), 'トラッシュから抜ける');
  // 対照＝パワーが一致する相手シグニがいなければ何も起きない
  const ctx2 = mkCtx({}, { signi: [oppDiff, null, null] });
  ctx2.ownerState.trash = [virtual];
  const r2 = finish(executeEffect({ effectId: 't', effectType: 'AUTO', action: act, duration: 'INSTANT', mandatory: true } as CardEffect, ctx2), ctx2);
  ok(r2.ownerState.trash.includes(virtual), 'パワー不一致なら場に出ない');
  eq(r2.ownerState.field.signi.filter(z => z && z.length > 0).length, 0, '盤面は動かない');
}));
// 「それの【出】能力は発動しない」が配置 STUB へ畳み込まれること（旧＝engine 未参照の死 BLOCK_ACTION）。
test('WXDi-CP01-024-E1 live: 配置 STUB に suppressOnPlay が畳み込まれ死 BLOCK_ACTION が消えている', () => {
  const eff = (effectsMap.get('WXDi-CP01-024') ?? []).find(e => e.effectId === 'WXDi-CP01-024-E1')!;
  const s = JSON.stringify(eff.action);
  ok(s.includes('"suppressOnPlay":true'), '配置アンカーに suppressOnPlay');
  ok(!s.includes('ON_PLAY_ABILITY'), '死 BLOCK_ACTION が残っている');
});
// ── REPEAT.optional（§6.4 O-32・`WX16-042-E1`「あと2回まで繰り返してもよい」）──
// 🔴旧 `STUB{REPEAT_EFFECT}` は共有ハンドラのどのパターンにも当たらず**ログだけの無言 no-op**＝
//    1回で終わっていた（過少）。あわせて「捨てたシグニと同じレベルの」条件も落ちていた（過剰）。
test('REPEAT optional: 断れば打ち切り／続ければ最大3回（WX16-042-E1 live・対の検証）', () => withSavedCursor(() => {
  const eff = (effectsMap.get('WX16-042') ?? []).find(e => e.effectId === 'WX16-042-E1')!;
  const s = JSON.stringify(eff.action);
  ok(s.includes('"optional":true'), '任意反復として表現されている');
  ok(s.includes('levelEqLastProcessed'), '「捨てたシグニと同じレベル」条件が載っている');
  ok(!s.includes('REPEAT_EFFECT'), '旧受け皿 STUB が残っている');
  // 「繰り返さない」を最初に選ぶ＝1回だけ（手札は1枚だけ減る）
  const lv3a = SIGNI_L3, lv3b = SIGNI_L3;
  const mk = () => {
    const c = mkCtx({}, { signi: [lv3a, null, null] });
    c.ownerState.hand = [lv3b, lv3b, lv3b];
    return c;
  };
  const stopCtx = mk();
  let r = executeEffect(eff, stopCtx);
  // 1周目（強制）を消化し、最初に現れる「繰り返す/繰り返さない」で止める
  let cur = { ...stopCtx } as ExecCtx;
  let guard = 0;
  while (!r.done) {
    if (++guard > 20) throw new Error('autopilot hang');
    cur = { ...cur, ownerState: r.ownerState, otherState: r.otherState, logs: r.logs,
      lastProcessedCards: r.lastProcessedCards } as ExecCtx;
    const p = r.pending as { type: string; options?: { id: string }[]; candidates?: string[]; count?: number };
    if (p.type === 'CHOOSE' && (p.options ?? []).some(o => o.id === 'stop')) { r = resumeChoose('stop', r.pending as never, cur); continue; }
    if (p.type === 'SELECT_TARGET') { r = resumeSelectTarget((p.candidates ?? []).slice(0, p.count ?? 1), r.pending as never, cur); continue; }
    throw new Error(`unexpected pending ${p.type}`);
  }
  eq(r.ownerState.hand.length, 2, '断れば手札は1枚しか減らない（1回だけ）');
  // 「繰り返す」を選び続ける＝合計3回（autopilot は先頭の available を選ぶ＝'repeat'）
  const goCtx = mk();
  const rAll = finish(executeEffect(eff, goCtx), goCtx);
  eq(rAll.ownerState.hand.length, 0, '続ければ合計3回で手札3枚を消費');
}));
// ── DECLARED_ICON_HAND_DISCARD_BANISH（§6.4 O-34(e)・`WXDi-P12-055-E1`）──
// 🔴回帰ガード＝従来は効果が丸ごと UNKNOWN に落ち、汎用 `OPP_DECLARE_CHOICE`（外れると**相手の
//    全シグニをトラッシュ**する別カード用）と `BANISH{owner:'self'}`（＝**自分のシグニ**）だけが残っていた。
//    **外れ（バニッシュされる）／当たり（されない）の対**＋「捨てる処理は必ず走る」を固定する。
test('DECLARED_ICON_HAND_DISCARD_BANISH: 宣言色と手札の色が外れたときだけ対象をバニッシュ（対の検証）', () => withSavedCursor(() => {
  const whiteCard = findCard(c => c.Type === 'シグニ' && (c.Color ?? '') === '白');
  const oppSigni = findCard(c => c.Type === 'シグニ' && (c.Color ?? '') === '赤');
  const eff = (effectsMap.get('WXDi-P12-055') ?? []).find(e => e.effectId === 'WXDi-P12-055-E1')!;
  const source = 'WXDi-P12-055';
  const play = (declared: string) => {
    const ctx = mkCtx({ signi: [source, null, null] }, { signi: [oppSigni, null, null] }, source);
    ctx.ownerState.hand = [whiteCard];
    let r = executeEffect(eff, ctx);
    // ① 相手シグニの対象選択
    ok(!r.done && r.pending.type === 'SELECT_TARGET', '相手シグニの対象選択');
    let c = { ...ctx, ownerState: r.ownerState, otherState: r.otherState, logs: r.logs } as ExecCtx;
    r = resumeSelectTarget([oppSigni], r.pending as never, c);
    // ② 手札1枚の選択（任意）
    ok(!r.done && r.pending.type === 'SELECT_TARGET', '手札の選択');
    c = { ...ctx, ownerState: r.ownerState, otherState: r.otherState, logs: r.logs } as ExecCtx;
    r = resumeSelectTarget([whiteCard], r.pending as never, c);
    // ③ 相手のアイコン宣言（6択＝《無》を含む）
    ok(!r.done && r.pending.type === 'CHOOSE', '相手のアイコン宣言');
    eq((r.pending as { options: unknown[] }).options.length, 6, '白/赤/青/緑/黒/無の6択');
    c = { ...ctx, ownerState: r.ownerState, otherState: r.otherState, logs: r.logs } as ExecCtx;
    return finish(resumeChoose(`declared_icon_${declared}`, r.pending as never, c), c);
  };
  // 外れ（手札は白／宣言は赤）＝対象がバニッシュされる。手札は必ず捨てる。
  const miss = play('赤');
  ok(!miss.otherState.field.signi.some(s => s?.at(-1) === oppSigni), '外れ＝対象をバニッシュ');
  ok(miss.ownerState.trash.includes(whiteCard), '外れでも選んだカードは捨てる');
  ok(!miss.ownerState.hand.includes(whiteCard), '手札に残らない');
  // 当たり（手札は白／宣言も白）＝バニッシュされない。捨てる処理は同じく走る。
  const hit = play('白');
  ok(hit.otherState.field.signi.some(s => s?.at(-1) === oppSigni), '当たり＝対象は場に残る');
  ok(hit.ownerState.trash.includes(whiteCard), '当たりでも選んだカードは捨てる');
  // 🔴自分のシグニは一切減らない（旧実装は `BANISH{owner:'self'}` で自分を撃っていた）
  ok(miss.ownerState.field.signi.some(s => s?.at(-1) === source), '自分のシグニは減らない');
}));
// ── USE_SEARCHED_SPELL_OR_TRASH（§6.4 O-34(b)「それをコストを支払わずに使用するかトラッシュに置く」）──
// 🔴回帰ガード＝従来は先頭の「トラッシュに《リカブト》がある場合、デッキから《バイオレンス・スプラッシュ》
//    を探す」節ごと catch-all `STUB{CONDITIONAL_POWER_BONUS}` に飲まれ、**サーチも使用も一度も走らなかった**。
test('USE_SEARCHED_SPELL_OR_TRASH: サーチ→「使う/トラッシュ」の二択（WX20-077-E2 live・両枝の対）', () => withSavedCursor(() => {
  const target = findCard(c => c.CardName === 'バイオレンス・スプラッシュ');
  const rikabuto = findCard(c => (c.CardName ?? '').includes('リカブト'));
  const eff = (effectsMap.get('WX20-077') ?? []).find(e => e.effectId === 'WX20-077-E2')!;
  const mk = () => {
    const c = mkCtx({}, {});
    c.ownerState.deck = [target, ...c.ownerState.deck];
    c.ownerState.trash = [rikabuto];
    return c;
  };
  // ① SEARCH で当たり札が見える／② 「トラッシュに置く」枝＝手札にもデッキにも残らない
  const c1 = mk();
  let r = executeEffect(eff, c1);
  ok(!r.done && r.pending.type === 'SEARCH', 'デッキサーチが走る');
  eq(r.pending.visibleCards.join('|'), target, '名指しの1枚だけ候補');
  let cc = { ...c1, ownerState: r.ownerState, otherState: r.otherState, logs: r.logs } as ExecCtx;
  r = resumeSearch([target], r.pending, cc);
  ok(!r.done && r.pending.type === 'CHOOSE', '使う/トラッシュの二択が出る');
  cc = { ...c1, ownerState: r.ownerState, otherState: r.otherState, logs: r.logs,
    lastProcessedCards: r.lastProcessedCards } as ExecCtx;
  const trashed = finish(resumeChoose('trash', r.pending, cc), cc);
  ok(trashed.ownerState.trash.includes(target), 'トラッシュ枝＝トラッシュへ');
  ok(!trashed.ownerState.hand.includes(target), 'トラッシュ枝＝手札に残さない');
  ok(!trashed.ownerState.deck.includes(target), 'トラッシュ枝＝デッキに残さない');
  // ③ 対照＝トラッシュに《リカブト》が無ければサーチ自体が走らない
  const c3 = mkCtx({}, {});
  c3.ownerState.deck = [target, ...c3.ownerState.deck];
  c3.ownerState.trash = [];
  const r3 = finish(executeEffect(eff, c3), c3);
  ok(r3.ownerState.deck.includes(target), '条件を満たさなければデッキから動かない');
}));
// ── PER_OWN_LRIG_COLOR_SCALE（§6.4 O-34(d)「あなたの場にいる〈色〉のルリグ１体につき〈効果〉」）──
// 🔴回帰ガード＝従来は「1体につき」が丸ごと落ち、`WX25-P3-050-E1` はバニッシュ／ドロー3／
//    エナチャージ3／相手デッキ10枚ミルが**ルリグの色に関係なく無条件で1回ずつ**走っていた。
//    **負方向（該当色0体＝何も起きない）＋対照（2体＝2回）の対**で固定する。
test('PER_OWN_LRIG_COLOR_SCALE: 該当色のルリグ体数だけ本体が走る（0体/1体/2体の対）', () => withSavedCursor(() => {
  const blueLrig = findCard(c => c.Type === 'ルリグ' && (c.Color ?? '').includes('青'));
  const redLrig = findCard(c => c.Type === 'ルリグ' && (c.Color ?? '').includes('赤') && !(c.Color ?? '').includes('青'));
  const scale = { type: 'STUB', id: 'PER_OWN_LRIG_COLOR_SCALE', scaleColor: '青',
    scaleAction: { type: 'DRAW', owner: 'self', count: 3 } } as EffectAction;
  // 0体＝一度も走らない（＝「無条件で1回」への退行ガード）
  const none = mkCtx({ lrig: [redLrig] }, {});
  const h0 = none.ownerState.hand.length;
  eq(run(scale, none).ownerState.hand.length, h0, '青ルリグ0体では引かない');
  // 1体＝1回
  const one = mkCtx({ lrig: [blueLrig] }, {});
  eq(run(scale, one).ownerState.hand.length, one.ownerState.hand.length + 3, '青ルリグ1体で3枚');
  // 2体（センター＋アシスト）＝2回
  const two = mkCtx({ lrig: [blueLrig], assistL: [blueLrig] }, {});
  eq(run(scale, two).ownerState.hand.length, two.ownerState.hand.length + 6, '青ルリグ2体で6枚');
}));
// live 不変条件＝`WX25-P3-050-E1` の5色すべてがスケール節として載り、赤節が合計パワーゲートを持つこと。
// 🔴従来は【使用条件】節がゴミ `GRANT_KEYWORD{使用条件}` に化けて**白節ごと消えて**おり、
//    赤節は `totalPowerMax` が落ちて**パワー無制限で2体バニッシュ**だった。
test('WX25-P3-050-E1 live: 5色ぶんのスケール節＋赤節の合計パワーゲート＋チーム使用条件', () => {
  const eff = (effectsMap.get('WX25-P3-050') ?? []).find(e => e.effectId === 'WX25-P3-050-E1')!;
  const steps = (eff.action as unknown as { steps: { id?: string; scaleColor?: string; scaleAction?: unknown }[] }).steps;
  eq(steps.map(s => s.scaleColor ?? '').join(''), '白赤青緑黒', '5色ぶんのスケール節');
  eq((eff.condition as { type?: string } | undefined)?.type ?? '', 'LRIG_ANY_TEAM_COUNT', '【チーム】いずれかのチームが使用条件へ');
  const red = steps.find(s => s.scaleColor === '赤')!.scaleAction as { target: { totalPowerMax?: number; count?: number } };
  eq(red.target.totalPowerMax ?? 0, 12000, '赤節の合計パワーゲート');
  eq(red.target.count ?? 0, 2, '赤節は2体まで');
});
// ── DECK_SIGNI_LEVEL_OVERRIDE_ALL（§6.4 O-34(c)「このターン、あなたのデッキにあるシグニのレベルは4になる」）──
// 🔴回帰ガード＝`deck_signi_level_override` は**setter だけあって読み手が1つも無い死フィールド**だった。
//    `WXK07-034-E1` は①でレベルを上書きし②で「レベル4のシグニが2枚めくれるまで公開」する自己完結の
//    コンボなので、読み手が無いと②が本来の当たり札を素通りする（＝過少）。**負方向＋対照の対**で固定する。
test('DECK_SIGNI_LEVEL_OVERRIDE_ALL: ①のレベル上書きを②の REVEAL_UNTIL が読む（WXK07-034-E1 live）', () => withSavedCursor(() => {
  const lv1a = SIGNI_L1, lv1b = SIGNI_L2, lv1c = SIGNI_L3;
  const eff = (effectsMap.get('WXK07-034') ?? []).find(e => e.effectId === 'WXK07-034-E1')!;
  const choose = eff.action as unknown as { choices: { action: EffectAction }[] };
  const setLevel = choose.choices[0].action;   // ①「デッキにあるシグニのレベルは4になる」
  const reveal = choose.choices[1].action;     // ②「レベル4のシグニが2枚めくれるまで公開」
  // 対照＝上書きが無いとき（Lv1/2/3 しかないデッキ）は当たりが1枚も出ない。
  const plain = mkCtx({}, {});
  // ⚠デッキは**明示的に Lv4 を含まない3枚だけ**にする（`mkState` の詰め物には Lv4 が混ざる）。
  plain.ownerState.deck = [lv1a, lv1b, lv1c];
  const hand0 = plain.ownerState.hand.length;
  const rPlain = finish(executeEffect({ ...eff, action: reveal } as CardEffect, plain), plain);
  eq(rPlain.ownerState.hand.length, hand0, '上書き前は Lv4 が無く手札は増えない');
  // 本命＝①を先に解決すると同じデッキで2枚が Lv4 として当たる。
  const boosted = mkCtx({}, {});
  boosted.ownerState.deck = [lv1a, lv1b, lv1c];
  const afterSet = run(setLevel, boosted);
  eq(afterSet.ownerState.deck_signi_level_override?.level ?? 0, 4, 'override が載る');
  eq(afterSet.ownerState.deck_signi_level_override?.class ?? '', '*', 'クラス指定なし＝全シグニ');
  const ctx2 = { ...boosted, ownerState: afterSet.ownerState } as ExecCtx;
  const hand1 = ctx2.ownerState.hand.length;
  const r2 = finish(executeEffect({ ...eff, action: reveal } as CardEffect, ctx2), ctx2);
  eq(r2.ownerState.hand.length, hand1 + 2, '上書き後は Lv4 扱いのシグニ2枚が手札へ');
}));
// ── STRIP_ATTACHED_AND_UNDER（§6.4 O-34(a)「それに付いているすべてのカードと、下に置かれている
//    すべてのカードをトラッシュに置く」＝原文 regex の母集団3効果）──
// 🔴回帰ガード＝`WX18-029-E1` は従来 `TRASH{SIGNI opponent}`＝**相手シグニ本体をトラッシュに置いて**
//    いた（【出】でノーコストの除去＝重い過剰実行）。**シグニが場に残ること**まで assert する。
test('STRIP_ATTACHED_AND_UNDER: 付随物と下カードだけ剥がしシグニは場に残る（WX18-029-E1 live）', () => withSavedCursor(() => {
  const host = fresh(), charm = fresh(), acce = fresh(), soul = fresh(), under = fresh();
  const ctx = mkCtx({}, {});
  ctx.otherState.field.signi = [[under, host], null, null];
  ctx.otherState.field.signi_charms = [charm, null, null];
  ctx.otherState.field.signi_acce = [[acce], null, null];
  ctx.otherState.field.signi_soul = [soul, null, null];
  const trash0 = ctx.otherState.trash.length, lrigTrash0 = ctx.otherState.lrig_trash.length;
  const eff = (effectsMap.get('WX18-029') ?? []).find(e => e.effectId === 'WX18-029-E1')!;
  const r = finish(executeEffect(eff, ctx), ctx);
  eq(r.otherState.field.signi[0]?.join(',') ?? '', host, 'シグニ本体は場に残り下カードだけ消える');
  eq(r.otherState.field.signi_charms?.[0] ?? null, null, 'チャーム除去');
  eq(r.otherState.field.signi_acce?.[0] ?? null, null, 'アクセ除去');
  eq(r.otherState.field.signi_soul?.[0] ?? null, null, 'ソウル除去');
  // チャーム＋アクセ＋下カード＝3枚がトラッシュへ、ソウルだけルリグトラッシュへ（removeFromField と同規約）
  eq(r.otherState.trash.length, trash0 + 3, 'トラッシュ+3');
  eq(r.otherState.lrig_trash.length, lrigTrash0 + 1, 'ルリグトラッシュ+1（ソウル）');
}));
// 対照＝何も付いていないシグニでは盤面が動かない（＝「本体を巻き込む」退行の逆方向ガード）。
