// 続き218: BANISH_REDIRECT の whenPowerZero（バニッシュ**される側**の限定）。
// 「このターン、パワーが０以下の対戦相手のシグニがバニッシュされる場合…」（WXDi-P10-009-E3／WXDi-CP02-102-E2）は
// パワー0消滅経路にだけ効く＝無条件 banish_redirect を立てると相手の全バニッシュがトラッシュ送りになる過剰発火。
test('BANISH_REDIRECT whenPowerZero: 無条件フラグを立てず対戦相手限定のパワー0フラグだけを立てる（続き218）', () => {
  const ctx = mkCtx({}, {});
  const r = run({ type: 'BANISH_REDIRECT', target: { type: 'SIGNI', owner: 'opponent', count: 'ALL', filter: { cardType: 'シグニ' } }, redirectTo: 'trash', until: 'END_OF_TURN', whenPowerZero: true } as unknown as EffectAction, ctx);
  const st = r.ownerState as PlayerState;
  eq(st.power0_banish_to_trash_opp_only, true, 'パワー0（対戦相手限定）フラグが立つ');
  ok(st.banish_redirect !== true, '無条件 banish_redirect は立てない（全バニッシュへの過剰発火防止）');
  ok(st.power0_banish_to_trash !== true, '所有者問わず版（WX04-038-E1 のSTUB用）は立てない');
  // 限定なしは従来どおり無条件フラグ＝既存挙動を壊していないこと
  const r2 = run({ type: 'BANISH_REDIRECT', target: { type: 'SIGNI', owner: 'opponent', count: 'ALL' }, redirectTo: 'trash', until: 'END_OF_TURN' } as EffectAction, mkCtx({}, {}));
  eq((r2.ownerState as PlayerState).banish_redirect, true, '限定なしは従来どおり無条件');
});
// 続き217: BANISH_REDIRECT の bySource（バニッシュ元の限定）。
// これが無いと「能力持ちが場に1体いるだけで相手の全バニッシュが常時トラッシュ送り」に過剰発火する
// （WXDi-CP02-072-E3「【絆常】：対戦相手のシグニがこのシグニとのバトルによってバニッシュされる場合…」等10効果）。
test('BANISH_REDIRECT bySource: 限定なしは常に適用／battle_with_this は当事者のみ・非バトル経路は不適用', () => {
  const plain = { type: 'BANISH_REDIRECT', target: { type: 'SIGNI', owner: 'opponent', count: 'ALL' }, redirectTo: 'trash', until: 'PERMANENT' } as EffectAction;
  const byBattle = { ...plain, bySource: 'battle_with_this' } as EffectAction;
  const byThis = { ...plain, bySource: 'by_this' } as EffectAction;
  // 限定なし＝バトル当事者でなくても、バトル経路でなくても適用（従来挙動を維持）
  ok(banishRedirectAppliesFrom(plain, 'HOLDER', 'OTHER'), '限定なし: 当事者でなくても適用');
  ok(banishRedirectAppliesFrom(plain, 'HOLDER', null), '限定なし: 非バトル経路でも適用');
  // battle_with_this＝能力の持ち主がバトル当事者のときだけ
  ok(banishRedirectAppliesFrom(byBattle, 'HOLDER', 'HOLDER'), 'battle_with_this: 当事者なら適用');
  ok(!banishRedirectAppliesFrom(byBattle, 'HOLDER', 'OTHER'), 'battle_with_this: 別のシグニのバトルでは不適用');
  ok(!banishRedirectAppliesFrom(byBattle, 'HOLDER', null), 'battle_with_this: パワー0以下等の非バトル経路では不適用');
  ok(!banishRedirectAppliesFrom(byThis, 'HOLDER', null), 'by_this: 非バトル経路では不適用');
  // SEQUENCE に内包されていても取り出せる
  const seq = { type: 'SEQUENCE', steps: [{ type: 'DRAW', owner: 'self', count: 1 }, byBattle] } as EffectAction;
  ok(banishRedirectAppliesFrom(seq, 'HOLDER', 'HOLDER'), 'SEQUENCE内: 当事者なら適用');
  ok(!banishRedirectAppliesFrom(seq, 'HOLDER', 'OTHER'), 'SEQUENCE内: 非当事者は不適用');
});
// タスク12(xliv)(a): BANISH_REDIRECT の target.filter（レベル/凍結/感染/チャーム限定）を被バニッシュシグニに評価。
// これが無いと「対戦相手の全バニッシュがトラッシュ送り」に過剰発火する（WXK10-053 レベル1以下・WXDi-P12-073 凍結・
// WX21-005 感染・WX18-038 チャーム）。banished 属性を渡すと一致しないバニッシュには適用しない。
test('BANISH_REDIRECT filter: 属性限定は被バニッシュシグニに一致するときだけ適用（タスク12(xliv)(a)）', () => {
  const lv1 = { type: 'BANISH_REDIRECT', target: { type: 'SIGNI', owner: 'opponent', count: 'ALL', filter: { cardType: 'シグニ', level: { max: 1 } } }, redirectTo: 'trash', until: 'PERMANENT' } as EffectAction;
  const frozen = { type: 'BANISH_REDIRECT', target: { type: 'SIGNI', owner: 'opponent', count: 'ALL', filter: { cardType: 'シグニ', isFrozen: true } }, redirectTo: 'trash', until: 'PERMANENT' } as EffectAction;
  const charm = { type: 'BANISH_REDIRECT', target: { type: 'SIGNI', owner: 'opponent', count: 'ALL', filter: { cardType: 'シグニ', hasCharm: true } }, redirectTo: 'trash', until: 'PERMANENT' } as EffectAction;
  const infected = { type: 'BANISH_REDIRECT', target: { type: 'SIGNI', owner: 'opponent', count: 'ALL', filter: { cardType: 'シグニ', infected: true } }, redirectTo: 'trash', until: 'PERMANENT' } as EffectAction;
  const noAttr = { frozen: false, hasCharm: false, infected: false };
  // レベル1以下: level<=1 は適用、level2 は不適用
  ok(banishRedirectAppliesFrom(lv1, 'H', 'H', { ...noAttr, level: 1 }), 'レベル1: 適用');
  ok(!banishRedirectAppliesFrom(lv1, 'H', 'H', { ...noAttr, level: 2 }), 'レベル2: 不適用');
  ok(!banishRedirectAppliesFrom(lv1, 'H', 'H', { ...noAttr, level: undefined }), 'レベル不明: 不適用（近似で過剰発火しない）');
  // 凍結/チャーム/感染: フラグ一致時のみ
  ok(banishRedirectAppliesFrom(frozen, 'H', 'H', { ...noAttr, frozen: true }), '凍結: 適用');
  ok(!banishRedirectAppliesFrom(frozen, 'H', 'H', noAttr), '非凍結: 不適用');
  ok(banishRedirectAppliesFrom(charm, 'H', 'H', { ...noAttr, hasCharm: true }), 'チャーム: 適用');
  ok(!banishRedirectAppliesFrom(charm, 'H', 'H', noAttr), '非チャーム: 不適用');
  ok(banishRedirectAppliesFrom(infected, 'H', 'H', { ...noAttr, infected: true }), '感染: 適用');
  ok(!banishRedirectAppliesFrom(infected, 'H', 'H', noAttr), '非感染: 不適用');
  // banished 未指定（効果経路など属性が取れない呼び出し）＝従来どおり限定を評価しない（後方互換）
  ok(banishRedirectAppliesFrom(lv1, 'H', 'H'), 'banished未指定: 後方互換で適用');
});
// タスク12(xliv)(a2): 効果経路（バトル/パワー0以外）のバニッシュでも、置換能力の持ち主 holder の場にある
// 【常】 BANISH_REDIRECT を on-the-fly で走査してトラッシュ送りにする（従来はターン内フラグしか見ず取りこぼしていた）。
test('BANISH_REDIRECT 効果経路: holder の【常】置換を走査しトラッシュ送り（タスク12(xliv)(a2)）', () => {
  const HOLDER = 'BR-EFFPATH-HOLDER';
  const mkBrEff = (filter: Record<string, unknown>, extra: Record<string, unknown> = {}, effExtra: Record<string, unknown> = {}) => ({
    effectId: 'br', effectType: 'CONTINUOUS',
    action: { type: 'BANISH_REDIRECT', target: { type: 'SIGNI', owner: 'opponent', count: 'ALL', filter }, redirectTo: 'trash', until: 'PERMANENT', ...extra },
    ...effExtra,
  }) as unknown as CardEffect;
  const cmWith = (eff: CardEffect) => {
    const cm = new Map(cardMap as Map<string, CardData>);
    cm.set(HOLDER, { CardNum: HOLDER, Type: 'シグニ', Power: '5000', Level: '3', effects: [eff] } as unknown as CardData);
    return cm;
  };
  const holder = mkState({ signi: [HOLDER, null, null] });
  const holderNoBr = mkState({ signi: [SIGNI_P3000, null, null] });
  const victim = mkState({ signi: [SIGNI, null, null] }); // removed 引数は trash/energy だけ見るので場の有無は不問
  const V = SIGNI;
  const attrs = (o: Record<string, unknown> = {}) => ({ frozen: false, hasCharm: false, infected: false, level: 3, ...o });
  // 無条件の【常】置換: 効果経路でもトラッシュへ
  {
    const cm = cmWith(mkBrEff({ cardType: 'シグニ' }));
    const { state } = banishDestination(victim, holder, V, { cardMap: cm, banished: attrs() });
    ok(state.trash.includes(V) && !state.energy.includes(V), '無条件置換: トラッシュへ（エナに置かない）');
    // 置換能力を持たない holder なら従来どおりエナ送り
    const { state: s2 } = banishDestination(victim, holderNoBr, V, { cardMap: cm, banished: attrs() });
    ok(s2.energy.includes(V) && !s2.trash.includes(V), '置換なし: エナ送り');
    // opts 未指定（後方互換）＝走査せずエナ送り
    const { state: s3 } = banishDestination(victim, holder, V);
    ok(s3.energy.includes(V) && !s3.trash.includes(V), 'opts未指定: 従来どおりエナ送り');
  }
  // 属性限定の【常】置換（感染）: 被バニッシュが感染時のみトラッシュ
  {
    const cm = cmWith(mkBrEff({ cardType: 'シグニ', infected: true }));
    const { state: hit } = banishDestination(victim, holder, V, { cardMap: cm, banished: attrs({ infected: true }) });
    ok(hit.trash.includes(V), '感染フィルタ一致: トラッシュへ');
    const { state: miss } = banishDestination(victim, holder, V, { cardMap: cm, banished: attrs({ infected: false }) });
    ok(miss.energy.includes(V) && !miss.trash.includes(V), '感染フィルタ不一致: エナ送り（過剰発火しない）');
  }
  // whenPowerZero 限定は効果経路では不適用（パワー0消滅専用）
  {
    const cm = cmWith(mkBrEff({ cardType: 'シグニ' }, { whenPowerZero: true }));
    const { state } = banishDestination(victim, holder, V, { cardMap: cm, banished: attrs() });
    ok(state.energy.includes(V) && !state.trash.includes(V), 'whenPowerZero: 効果経路では不適用＝エナ送り');
  }
  // bySource 限定（battle_with_this）は非バトル経路では不適用
  {
    const cm = cmWith(mkBrEff({ cardType: 'シグニ' }, { bySource: 'battle_with_this' }));
    const { state } = banishDestination(victim, holder, V, { cardMap: cm, banished: attrs() });
    ok(state.energy.includes(V) && !state.trash.includes(V), 'bySource: 効果経路では不適用＝エナ送り');
  }
  // DURING_ATTACK_PHASE 限定は phase 不明の効果経路では保守的にスキップ（過剰発火しない）／phase を渡せば適用
  {
    const cm = cmWith(mkBrEff({ cardType: 'シグニ' }, {}, { activeCondition: { type: 'DURING_ATTACK_PHASE' } }));
    const { state: skip } = banishDestination(victim, holder, V, { cardMap: cm, banished: attrs() });
    ok(skip.energy.includes(V) && !skip.trash.includes(V), 'DURING_ATTACK_PHASE + phase不明: スキップ＝エナ送り');
    const { state: onAtk } = banishDestination(victim, holder, V, { cardMap: cm, banished: attrs(), turnPhase: 'ATTACK_SIGNI' });
    ok(onAtk.trash.includes(V), 'DURING_ATTACK_PHASE + アタックフェイズ: トラッシュへ');
  }
});
test('BANISH_REDIRECT by_this 効果経路: 発生源シグニ自身だけ適用しバトル経路も維持（タスク12(xliv)(a3)）', () => {
  const savedCursor = cursor;
  try {
    const bases = ['WX09-022', 'WXK11-032', 'WXDi-D04-016'];
    const holders = bases.map((n, i) => `${n}#${i + 1}`);
    const victims = [`${SIGNI_L1}#701`, `${SIGNI_L2}#702`];
    const otherSource = `${SIGNI_L3}#703`;
    const enaje = 'WXK11-032#704';
    const spellBase = findCard(c => c.Type === 'スペル');
    const spell = `${spellBase}#705`;
    const cm = new Map(cardMap as Map<string, CardData>);
    for (const id of [...holders, ...victims, otherSource, enaje, spell]) {
      const base = getCardNumG(id);
      cm.set(id, { ...cardMap.get(base)!, CardNum: id });
    }
    const victimBefore = mkState({ signi: [victims[0], victims[1], null] });
    const emptyVictim = { ...victimBefore, field: { ...victimBefore.field, signi: [null, null, null] } } as PlayerState;
    for (const [i, holder] of holders.entries()) {
      const trashCondition = i === 0 ? [enaje] : i === 2 ? [spell] : [];
      const holderState = mkState({ signi: [holder, otherSource, null] });
      holderState.trash = trashCondition;
      const holderEffect = cm.get(holder)!.effects!.find(e => e.effectType === 'CONTINUOUS' && JSON.stringify(e.action).includes('BANISH_REDIRECT'))!;
      const hitCtx = { ...mkCtx({}, {}), ownerState: holderState, otherState: victimBefore, cardMap: cm, sourceCardNum: holder } as ExecCtx;
      const missCtx = { ...hitCtx, sourceCardNum: otherSource };
      const hit = banishDestination(emptyVictim, holderState, victims[0], banishRedirectOpts(hitCtx, victimBefore, victims[0])).state;
      const miss = banishDestination(emptyVictim, holderState, victims[1], banishRedirectOpts(missCtx, victimBefore, victims[1])).state;
      ok(hit.trash.includes(victims[0]) && !hit.energy.includes(victims[0]), `${bases[i]}: 自身の効果ならトラッシュ`);
      ok(miss.energy.includes(victims[1]) && !miss.trash.includes(victims[1]), `${bases[i]}: 別カードの効果ならエナ`);
      if (i !== 1) {
        const inactiveHolder = { ...holderState, trash: [] };
        const inactiveCtx = { ...hitCtx, ownerState: inactiveHolder };
        const inactive = banishDestination(emptyVictim, inactiveHolder, victims[0],
          banishRedirectOpts(inactiveCtx, victimBefore, victims[0])).state;
        ok(inactive.energy.includes(victims[0]) && !inactive.trash.includes(victims[0]), `${bases[i]}: activeCondition不成立ならエナ`);
      }
      ok(banishRedirectAppliesFrom(holderEffect.action, holder, holder), `${bases[i]}: 自身とのバトルは従来どおり適用`);
      ok(!banishRedirectAppliesFrom(holderEffect.action, holder, otherSource), `${bases[i]}: 別シグニのバトルは従来どおり不適用`);
    }
    // 実カード WX09-022 の【起】（相手2体までバニッシュ）を、能力保持シグニ自身を発生源にして完走する。
    const wx09State = mkState({ signi: [holders[0], otherSource, null] });
    wx09State.trash = [enaje];
    const wx09Ctx = { ...mkCtx({}, {}), ownerState: wx09State, otherState: victimBefore, cardMap: cm, sourceCardNum: holders[0] } as ExecCtx;
    const activated = cm.get(holders[0])!.effects!.find(e => e.effectId === 'WX09-022-E2')!;
    const result = finish(executeEffect(activated, wx09Ctx), wx09Ctx);
    ok(victims.every(n => result.otherState.trash.includes(n)) && victims.every(n => !result.otherState.energy.includes(n)),
      'WX09-022-E2: 対象2体ともトラッシュへ');
  } finally {
    cursor = savedCursor;
  }
});
// タスク12(xliv)(a3) の検証で発見した held ドリフト（Opus）: WX09-022 と同文型の
// 「あなたのトラッシュにカード名に《X》を含むカードがあるかぎり、」は WX12-033-E2 にもあるが、
// 同カードは E3 が MANUAL の PRESERVE カードのため build:effects が curated を温存し、
// parser 修正後も built JSON に activeCondition が届かず【ランサー】が無条件付与のままだった（ライブ過剰発火）。
test('WX12-033-E2: トラッシュに《セイリュ》があるかぎりランサー（activeCondition の held ドリフト是正）', () => {
  const savedCursor = cursor;
  try {
    const HOST = 'WX12-033';       // シグニ＝実戦どおりシグニゾーンへ置く
    const SEIRYU = 'WD04-009';     // 幻獣　セイリュ
    const my = mkState({ signi: [HOST, null, null] });
    const op = mkState({});
    const em = effectsMap;
    const cm = cardMap as Map<string, CardData>;
    const hit = collectContinuousGrantedKeywords({ ...my, trash: [SEIRYU] }, op, true, em, cm);
    ok(hit[HOST]?.includes('ランサー'), 'トラッシュに《セイリュ》があればランサー');
    const miss = collectContinuousGrantedKeywords({ ...my, trash: [SIGNI_L1] }, op, true, em, cm);
    ok(!miss[HOST]?.includes('ランサー'), 'トラッシュに《セイリュ》が無ければランサー不発');
  } finally {
    cursor = savedCursor;
  }
});
test('BANISH_REDIRECT 属性4種: 除去前state由来の属性一致だけトラッシュへ（PLAN §6.3(a)）', () => {
  const HOLDER = 'BR-ATTR-HOLDER';
  const HIT = 'BR-ATTR-HIT';
  const MISS = 'BR-ATTR-MISS';
  const filters = [
    { name: 'level', filter: { cardType: 'シグニ', level: { max: 1 } }, hitLevel: '1', missLevel: '2' },
    { name: 'frozen', filter: { cardType: 'シグニ', isFrozen: true }, hitLevel: '3', missLevel: '3', stateKey: 'signi_frozen' },
    { name: 'charm', filter: { cardType: 'シグニ', hasCharm: true }, hitLevel: '3', missLevel: '3', stateKey: 'signi_charms' },
    { name: 'infected', filter: { cardType: 'シグニ', infected: true }, hitLevel: '3', missLevel: '3', stateKey: 'signi_virus' },
  ] as const;
  for (const spec of filters) {
    const effect = { effectId: `br-${spec.name}`, effectType: 'CONTINUOUS', action: {
      type: 'BANISH_REDIRECT', target: { type: 'SIGNI', owner: 'opponent', count: 'ALL', filter: spec.filter },
      redirectTo: 'trash', until: 'PERMANENT',
    }, duration: 'PERMANENT', mandatory: true, parseStatus: 'MANUAL' } as unknown as CardEffect;
    const cm = new Map(cardMap as Map<string, CardData>);
    cm.set(HOLDER, { CardNum: HOLDER, Type: 'シグニ', Power: '5000', Level: '3', effects: [effect] } as unknown as CardData);
    cm.set(HIT, { CardNum: HIT, Type: 'シグニ', Power: '5000', Level: spec.hitLevel } as unknown as CardData);
    cm.set(MISS, { CardNum: MISS, Type: 'シグニ', Power: '5000', Level: spec.missLevel } as unknown as CardData);
    const holder = mkState({ signi: [HOLDER, null, null] });
    const withAttr = (num: string, enabled: boolean) => {
      const base = mkState({ signi: [num, null, null] });
      if (!('stateKey' in spec)) return base;
      const value = spec.stateKey === 'signi_charms' ? (enabled ? ['CHARM', null, null] : [null, null, null])
        : spec.stateKey === 'signi_virus' ? (enabled ? [1, 0, 0] : [0, 0, 0])
        : (enabled ? [true, false, false] : [false, false, false]);
      return { ...base, field: { ...base.field, [spec.stateKey]: value } } as PlayerState;
    };
    const hitBefore = withAttr(HIT, true);
    const missBefore = withAttr(MISS, false);
    const hitCtx = { ...mkCtx({}, {}), cardMap: cm } as ExecCtx;
    const hit = banishDestination(mkState({}), holder, HIT, banishRedirectOpts(hitCtx, hitBefore, HIT)).state;
    const miss = banishDestination(mkState({}), holder, MISS, banishRedirectOpts(hitCtx, missBefore, MISS)).state;
    ok(hit.trash.includes(HIT) && !hit.energy.includes(HIT), `${spec.name}一致: トラッシュ`);
    ok(miss.energy.includes(MISS) && !miss.trash.includes(MISS), `${spec.name}不一致: エナ`);
  }
});
test('BANISH_REDIRECT 単体対象: 選択した相手シグニだけをこのターン保持して配送する（PLAN §6.3(b)）', () => {
  const selected = SIGNI;
  const unselected = SIGNI_P3000;
  const action = { type: 'BANISH_REDIRECT', target: { type: 'SIGNI', owner: 'opponent', count: 1, filter: { cardType: 'シグニ' } }, redirectTo: 'trash', until: 'END_OF_TURN' } as EffectAction;
  const result = run(action, mkCtx({}, { signi: [selected, unselected, null] }));
  const owner = result.ownerState as PlayerState;
  eq((owner.banish_redirect_target_nums ?? []).join(','), selected, '選択対象だけを保持');
  eq(owner.banish_redirect, undefined, '全体フラグは立てない');
  const selectedDest = banishDestination(mkState({}), owner, selected).state;
  const otherDest = banishDestination(mkState({}), owner, unselected).state;
  ok(selectedDest.trash.includes(selected) && !selectedDest.energy.includes(selected), '選択対象はトラッシュ');
  ok(otherDest.energy.includes(unselected) && !otherDest.trash.includes(unselected), '非選択対象はエナ');
  ok(isSelectedBanishRedirect(owner, selected), 'バトル経路: 選択対象だけredirect判定');
  ok(!isSelectedBanishRedirect(owner, unselected), 'バトル経路: 非選択対象はredirectしない');
});
test('BANISH_REDIRECT targetsLastProcessed: 直前対象だけへ無選択で適用し、空振りはno-op（タスク12(xliv)(b1)）', () => {
  const savedCursor = cursor;
  try {
    const selected = SIGNI;
    const unselected = SIGNI_P3000;
    const action = {
      type: 'BANISH_REDIRECT',
      target: { type: 'SIGNI', owner: 'opponent', count: 1, filter: { cardType: 'シグニ' } },
      targetsLastProcessed: true,
      redirectTo: 'trash',
      until: 'END_OF_TURN',
    } as EffectAction;
    const hit = run(action, { ...mkCtx({}, { signi: [selected, unselected, null] }), lastProcessedCards: [selected] });
    eq((hit.ownerState.banish_redirect_target_nums ?? []).join(','), selected, '直前対象だけを保持');
    eq(hit.ownerState.banish_redirect, undefined, '全体フラグは立てない');
    ok(hit.done, '選択UIなしで完了');

    const miss = run(action, { ...mkCtx({}, { signi: [selected, unselected, null] }), lastProcessedCards: [] });
    eq(miss.ownerState.banish_redirect_target_nums, undefined, '直前対象なしなら何も記録しない');
    eq(miss.ownerState.banish_redirect, undefined, '空振りでも全体フラグは立てない');
  } finally {
    cursor = savedCursor;
  }
});
test('BANISH_REDIRECT 単体対象7効果: 群A built JSONは全4件count:1（タスク12(xliv)(b)）', () => {
  const ids = ['WXK06-048-E1', 'WXDi-P12-054-E2', 'WXDi-P15-044-E1', 'WX25-P2-060-E2'];
  const findRedirect = (action: EffectAction): import('../src/types/effects').BanishRedirectAction | undefined => {
    if (action.type === 'BANISH_REDIRECT') return action;
    if (action.type === 'SEQUENCE') {
      for (const step of action.steps) {
        const found = findRedirect(step);
        if (found) return found;
      }
    }
    if (action.type === 'CONDITIONAL') return findRedirect(action.then);
    return undefined;
  };
  for (const id of ids) {
    const cardNum = id.replace(/-E\d+$/, '');
    const effect = effectsMap.get(cardNum)?.find(e => e.effectId === id);
    const redirect = effect && findRedirect(effect.action);
    ok(redirect != null, `${id}: BANISH_REDIRECTあり`);
    eq(redirect!.target.count, 1, `${id}: built JSON count:1`);
    eq(redirect!.targetsLastProcessed, id === 'WXK06-048-E1' ? true : undefined,
      `${id}: 直前文の対象を受けるWXK06-048だけtargetsLastProcessed`);
  }
  const powerZero = effectsMap.get('WX25-P3-104')?.find(e => e.effectId === 'WX25-P3-104-E1');
  const powerZeroRedirect = powerZero && findRedirect(powerZero.action);
  eq(powerZeroRedirect?.targetsLastProcessed, undefined, 'WX25-P3-104-E1: 単独文型は自前選択のまま');
  eq(powerZeroRedirect?.whenPowerZero, true, 'WX25-P3-104-E1: パワー0以下限定を維持');
  // ⚠「レベル2以下」は matchesFilter が読める形（filter.level.max）でなければ効かない。
  // 旧 curated は未対応キー `levelMax` を持っており、engine が黙って無視して**レベル3以上も対象にできた**
  // （Opus 検証で実測。構造 assert だけでは死んだキーを固定してしまうので候補列挙でも確認する）。
  const savedCursorPZ = cursor;
  try {
    eq(powerZeroRedirect?.target.filter?.level?.max, 2, 'WX25-P3-104-E1: レベル2以下を engine が読める形で保持');
    const candCtx = mkCtx({}, { signi: [SIGNI_L1, SIGNI_L4, null] });
    const cand = executeEffect({ effectId: 't', effectType: 'AUTO', action: powerZeroRedirect as EffectAction,
      duration: 'INSTANT', mandatory: true } as CardEffect, candCtx);
    const list = (cand as { pending?: { candidates?: string[] } }).pending?.candidates ?? [];
    ok(list.includes(SIGNI_L1), 'WX25-P3-104-E1: レベル1は対象候補');
    ok(!list.includes(SIGNI_L4), 'WX25-P3-104-E1: レベル4は対象候補にならない');
  } finally {
    cursor = savedCursorPZ;
  }
});
