test('§6.3 M4: 正面以外／非アタックフェイズでは watcher が発火しない', () => {
  const merged = mergeManualEffects('WX15-055', effectsMap.get('WX15-055') ?? []);
  const em = new Map(effectsMap); em.set('WX15-055', merged);
  const beforeGuest = mkState({ signi: [null, null, SIGNI_L2] });
  const afterGuest = mkState({ signi: [null, null, null] });
  const host = mkState({ signi: ['WX15-055', null, null] });
  const attackCtx = { ...trigCtx(HOST, HOST), effectsMap: em, turnPhase: 'ATTACK_SIGNI' as const };
  const hit = collectBanishTriggers(attackCtx, SIGNI_L2, GUEST, host, afterGuest, beforeGuest);
  eq(fired(hit.entries, 'WX15-055-E1'), true, '正面＋アタックフェイズ＋アップで発火');
  const mainCtx = { ...attackCtx, turnPhase: 'MAIN' as const };
  const missPhase = collectBanishTriggers(mainCtx, SIGNI_L2, GUEST, host, afterGuest, beforeGuest);
  eq(fired(missPhase.entries, 'WX15-055-E1'), false, 'メインフェイズでは非発火');
  const sidePrev = mkState({ signi: [SIGNI_L2, null, null] });
  const missFront = collectBanishTriggers(attackCtx, SIGNI_L2, GUEST, host, afterGuest, sidePrev);
  eq(fired(missFront.entries, 'WX15-055-E1'), false, '正面以外では非発火');
  // 「あなたの」アタックフェイズ＝watcher所有者のターン限定（相手のアタックフェイズ中の正面被バニでは発火しない・検証是正）
  const oppTurnCtx = { ...trigCtx(GUEST, HOST), effectsMap: em, turnPhase: 'ATTACK_SIGNI' as const };
  const missTurn = collectBanishTriggers(oppTurnCtx, SIGNI_L2, GUEST, host, afterGuest, beforeGuest);
  eq(fired(missTurn.entries, 'WX15-055-E1'), false, '相手ターンのアタックフェイズでは非発火');
});

