test('WXDi-D08-012 挙動: 支払い→EXILE／スキップ→BANISH が同一の先行対象へ（skip側凍結の検証是正）', () => {
  // resume 後の ctx には storedTargetCards が生存しない（BattleScreen は永続化しない）＝
  // pay/skip 両オプションとも interaction 生成時に fixedCardNums へ凍結されていなければならない。
  const eff = mergeManualEffects('WXDi-D08-012', effectsMap.get('WXDi-D08-012') ?? []).find(e => e.effectId === 'WXDi-D08-012-E1');
  ok(!!eff, 'E1'); if (!eff) return;
  const target = SIGNI_P12000;
  const mk = () => {
    const c = mkCtx({}, { signi: [target, null, null] }, 'WXDi-D08-012');
    // エクシード4の原資＝センタールリグ下4枚（最上段はルリグ本体）
    c.ownerState.field.lrig = ['U1', 'U2', 'U3', 'U4', 'LRIG-TOP'];
    return c;
  };
  // 素の executeEffect で段階制御（run() は完走してしまう）：recorder SELECT_TARGET → 任意コスト CHOOSE
  const stepToChoose = (c: ExecCtx) => {
    let r = executeEffect({ effectId: 't', effectType: 'AUTO', action: eff.action, duration: 'INSTANT', mandatory: true } as CardEffect, c);
    ok(!r.done && (r as { pending: { type: string } }).pending.type === 'SELECT_TARGET', 'recorder が対象選択を出す');
    if (r.done) throw new Error('unreachable');
    r = resumeSelectTarget([target], r.pending as never, { ...c, ownerState: r.ownerState, otherState: r.otherState, logs: r.logs } as ExecCtx);
    ok(!r.done && (r as { pending: { type: string } }).pending.type === 'CHOOSE', '任意コスト CHOOSE');
    return r;
  };
  // 支払い経路：EXILE が先行対象へ・ルリグ下4枚がルリグトラッシュへ
  // ⚠resume ctx に storedTargetCards を渡さない＝BattleScreen の pause 跨ぎ実挙動（凍結が効いているかの検証）
  const finishSelect = (r: ExecResult, base: ExecCtx): ExecResult => {
    // EXILE/BANISH の対象選択（候補1でも SELECT_TARGET を出す慣例）を解決。
    // fixedCardNums 凍結の検証のため storedTargetCards は引き継がない。
    if (!r.done && (r as { pending: { type: string } }).pending.type === 'SELECT_TARGET') {
      return resumeSelectTarget([target], (r as { pending: unknown }).pending as never, { ...base, ownerState: r.ownerState, otherState: r.otherState, logs: r.logs } as ExecCtx);
    }
    return r;
  };
  const c1 = mk();
  const r1 = stepToChoose(c1);
  const pay = finishSelect(resumeChoose('pay', (r1 as { pending: unknown }).pending as never, { ...c1, ownerState: r1.ownerState, otherState: r1.otherState, logs: r1.logs } as ExecCtx), c1);
  eq(pay.otherState.field.signi[0], null, '支払い時は対象が場を離れる');
  ok((pay.otherState.excluded ?? []).includes(target), '支払い時は excluded へ');
  eq(pay.ownerState.lrig_trash.length, 4, 'エクシード4を実支払い');
  // スキップ経路：BANISH が同じ先行対象へ（＝エナへ。空振りしない）
  const c2 = mk();
  const r2 = stepToChoose(c2);
  const skip = finishSelect(resumeChoose('skip', (r2 as { pending: unknown }).pending as never, { ...c2, ownerState: r2.ownerState, otherState: r2.otherState, logs: r2.logs } as ExecCtx), c2);
  eq(skip.otherState.field.signi[0], null, '未払い時も対象が場を離れる（空振りしない）');
  ok(skip.otherState.energy.includes(target), '未払い時はバニッシュ＝エナへ');
  eq(skip.ownerState.lrig_trash.length, 0, '未払い時はエクシード消費なし');
});

test('WX16-033-BURST 挙動: 自シグニ選択の pause を跨いで先行対象へ TRASH（storedTargetCards 永続化の契約）', () => {
  // BattleScreen は pause 時に result.storedTargetCards を pending_effect に保存し resume ctx へ復元する
  // （PendingEffect.storedTargetCards＝triggeringCardNum と同型・検証是正）。その契約をここで固定する。
  const eff = mergeManualEffects('WX16-033', effectsMap.get('WX16-033') ?? []).find(e => e.effectId === 'WX16-033-BURST');
  ok(!!eff, 'BURST'); if (!eff) return;
  const target = SIGNI_P12000;
  const ctx = mkCtx({ signi: [SIGNI_L1, SIGNI_L2, null] }, { signi: [target, null, null] }, 'WX16-033');
  let r = executeEffect({ effectId: 't', effectType: 'AUTO', action: eff.action, duration: 'INSTANT', mandatory: true } as CardEffect, ctx);
  ok(!r.done && (r as { pending: { type: string } }).pending.type === 'SELECT_TARGET', '相手対象の選択');
  if (r.done) return;
  r = resumeSelectTarget([target], r.pending as never, { ...ctx, ownerState: r.ownerState, otherState: r.otherState, logs: r.logs } as ExecCtx);
  // 自シグニ2体 → バニッシュ対象選択で pause。ここで storedTargetCards が result に露出していること（永続化の前提）
  ok(!r.done && (r as { pending: { type: string } }).pending.type === 'SELECT_TARGET', '自シグニ選択で pause');
  ok((r.storedTargetCards ?? []).includes(target), 'pause 結果に storedTargetCards が露出（BattleScreen が保存できる）');
  if (r.done) return;
  // BattleScreen の resume と同様に storedTargetCards を復元して続行
  r = resumeSelectTarget([SIGNI_L1], r.pending as never, { ...ctx, ownerState: r.ownerState, otherState: r.otherState, logs: r.logs, storedTargetCards: r.storedTargetCards } as ExecCtx);
  if (!r.done && (r as { pending: { type: string } }).pending.type === 'SELECT_TARGET') {
    r = resumeSelectTarget([target], r.pending as never, { ...ctx, ownerState: r.ownerState, otherState: r.otherState, logs: r.logs, storedTargetCards: r.storedTargetCards } as ExecCtx);
  }
  ok(r.done, '完走');
  ok(r.ownerState.energy.includes(SIGNI_L1) || r.ownerState.trash.includes(SIGNI_L1), '自シグニはバニッシュ済み');
  eq(r.otherState.field.signi[0], null, '先行対象が場を離れる');
  ok(r.otherState.trash.includes(target), '「それをトラッシュに置く」＝バニッシュ（エナ）ではなくトラッシュへ');
});

