test('G072 WXEX2-23-E2: 被バニッシュレベル以下をSELECTし傀儡配置までresume', () => {
  const host = mkState({ signi: ['WXEX2-23', null, null] }); const guest = mkState({});
  guest.trash = [SIGNI_L1, SIGNI_L3];
  const ctx = { ...trigCtx(HOST, HOST), effectsMap: g072Map('WXEX2-23'), turnPhase: 'ATTACK_SIGNI' };
  const hit = collectBanishTriggers(ctx, SIGNI_L2, GUEST, host, guest);
  const entry = hit.entries.find(e => e.effectId === 'WXEX2-23-E2');
  eq(entry?.triggeringCardNum, SIGNI_L2, '被バニッシュカードをentryへ保持');
  eq(has(collectBanishTriggers({ ...ctx, turnPhase: 'MAIN' }, SIGNI_L2, GUEST, host, guest).entries, 'WXEX2-23-E2'), false, 'MAINでは非発火');
  ok(!!entry, 'collector発火'); if (!entry) return;
  const execCtx = { ...mkCtx({ signi: ['WXEX2-23', null, null] }, {}, 'WXEX2-23'), otherState: guest, triggeringCardNum: entry.triggeringCardNum } as ExecCtx;
  let r = executeEffect(entry.effect, execCtx);
  ok(!r.done && r.pending.type === 'SELECT_TARGET', '相手トラッシュ選択へpause'); if (r.done) return;
  eq(JSON.stringify(r.pending.candidates), JSON.stringify([SIGNI_L1]), 'レベル超のシグニは候補外');
  r = resumeSelectTarget([SIGNI_L1], r.pending as never, { ...execCtx, ownerState: r.ownerState, otherState: r.otherState, logs: r.logs });
  ok(r.done, 'resume完走');
  eq(r.otherState.trash.includes(SIGNI_L1), false, '相手トラッシュから除去');
  ok(r.ownerState.field.signi.some(z => z?.at(-1) === SIGNI_L1), '自分の場へ配置');
  ok((r.ownerState.field.puppet_signi ?? []).includes(SIGNI_L1), '傀儡状態を登録');
});
// G072 の entry.triggeringCardNum 追加で挙動が変わった既存 watcher の lock-in（Claude 検証で発見）：
// WXK11-020-E2「そのシグニよりパワーの低い対戦相手のシグニ1体をバニッシュ」の powerLtTrigger は
// 従来 ON_BANISH watcher entry に triggeringCardNum が無く未解決＝無制限バニッシュの潜在過剰効果だった。
// 今回の追加で被バニッシュシグニのパワー基準（cardMap 表記パワー）へ正しく解決される＝改善方向の挙動変化を固定する。
test('G072副作用 WXK11-020-E2: 被バニッシュのパワー未満だけが候補', () => {
  const banished = findCard(c => isSigni(c) && c.Power === '8000');
  const low = findCard(c => isSigni(c) && c.Power === '3000');
  const high = findCard(c => isSigni(c) && c.Power === '12000');
  const host = mkState({ signi: ['WXK11-020', null, null] });
  const guest = mkState({ signi: [low, high, null] });
  const ctx = trigCtx(HOST, HOST);
  const entry = collectBanishTriggers(ctx, banished, GUEST, host, guest).entries.find(e => e.effectId === 'WXK11-020-E2');
  eq(entry?.triggeringCardNum, banished, '被バニッシュカードをentryへ保持');
  ok(!!entry, 'collector発火'); if (!entry) return;
  const execCtx = { ...mkCtx({ signi: ['WXK11-020', null, null] }, {}, 'WXK11-020'), otherState: guest, triggeringCardNum: entry.triggeringCardNum } as ExecCtx;
  const r = executeEffect(entry.effect, execCtx);
  ok(!r.done && r.pending.type === 'SELECT_TARGET', '相手シグニ選択へpause'); if (r.done) return;
  eq(JSON.stringify(r.pending.candidates), JSON.stringify([low]), 'パワー8000以上（12000）は候補外・3000のみ');
});

