test('NEGATE_NTH_ATTACK honor: ルリグ対象なら消費し、対象外なら状態不変', () => {
  const base = mkState({});
  base.negate_opp_attacks = { remaining: 1, signi: true, lrig: true };
  const positive = consumeNthAttackNegation(base, 'lrig');
  ok(positive.negated, 'lrig:trueなら無効化するはず');
  eq(positive.remaining, 0);
  eq(positive.defender.negate_opp_attacks, undefined, '最終1回を消費したらフラグを除去');

  const signiOnly = mkState({});
  signiOnly.negate_opp_attacks = { remaining: 1, signi: true, lrig: false };
  const negative = consumeNthAttackNegation(signiOnly, 'lrig');
  ok(!negative.negated, 'lrig:falseなら無効化しないはず');
  eq(negative.defender, signiOnly, '対象外攻撃ではstateを変更しない');
  eq(negative.defender.negate_opp_attacks?.remaining, 1, '対象外攻撃では共有カウンタを消費しない');
});

test('POWER_PLUS_BANISHED_POWER: 被バニッシュ実効パワーを白シグニへ次の相手ターン終了時まで加算', () => {
  const white = findCard(c => isSigni(c) && c.Color?.includes('白'));
  const otherWhite = findCard(c => isSigni(c) && c.Color?.includes('白') && c.CardNum !== white);
  const banished = findCard(c => isSigni(c) && c.CardNum !== white && c.CardNum !== otherWhite);
  const effect = effectsMap.get('WX24-P2-049')?.find(e => e.effectId === 'WX24-P2-049-E1b');
  ok(!!effect && effect.action.type === 'STUB', 'WX24-P2-049-E1b の構造化STUBが必要');
  if (!effect || effect.action.type !== 'STUB') return;
  eq(JSON.stringify(effect.action.powerPlusBanishedPower), JSON.stringify({
    target: { type: 'SIGNI', owner: 'self', count: 1, filter: { color: '白' } },
    duration: 'UNTIL_OPP_TURN_END',
  }));

  const ctx = mkCtx({ signi: [white, otherWhite, null] }, {}, 'WX24-P2-049');
  ctx.triggeringCardNum = banished;
  ctx.banishedSigniPower = 8000;
  const result = executeEffect(effect, ctx);
  ok(!result.done && result.pending.type === 'SELECT_TARGET', '白シグニの対象選択になるはず');
  if (result.done || result.pending.type !== 'SELECT_TARGET') return;
  const resolved = resumeSelectTarget([otherWhite], result.pending, {
    ...ctx, ownerState: result.ownerState, otherState: result.otherState, logs: result.logs,
  });
  ok(resolved.done, '対象選択後に解決完了');
  ok((resolved.ownerState.power_mods_until_opp_turn ?? []).some(m => m.cardNum === otherWhite && m.delta === 8000),
    '選んだ白シグニへ+8000');
  ok(!(resolved.ownerState.temp_power_mods ?? []).some(m => m.cardNum === otherWhite),
    'UNTIL_OPP_TURN_END は temp_power_mods に入れない');
});

test('POWER_PLUS_BANISHED_POWER: 白シグニ不在またはパワー0はno-op', () => {
  const nonWhite = findCard(c => isSigni(c) && !c.Color?.includes('白'));
  const action = {
    type: 'STUB', id: 'POWER_PLUS_BANISHED_POWER',
    powerPlusBanishedPower: {
      target: { type: 'SIGNI', owner: 'self', count: 1, filter: { color: '白' } },
      duration: 'UNTIL_OPP_TURN_END',
    },
  } as EffectAction;
  const noTarget = mkCtx({ signi: [nonWhite, null, null] }, {});
  noTarget.banishedSigniPower = 8000;
  eq((run(action, noTarget).ownerState.power_mods_until_opp_turn ?? []).length, 0, '白シグニ不在');
  const zero = mkCtx({ signi: [findCard(c => isSigni(c) && c.Color?.includes('白')), null, null] }, {});
  zero.banishedSigniPower = 0;
  eq((run(action, zero).ownerState.power_mods_until_opp_turn ?? []).length, 0, 'パワー0');
});

test('VARIABLE_ENERGY_TRASH_LEVEL_BOUNCE: ブルアカ2枚を選んでトラッシュし相手レベル2をバウンス', () => {
  const blueArchive = [...cardMap.values()].filter(c => c.CardClass?.includes('ブルアカ')).slice(0, 3).map(c => c.CardNum);
  eq(blueArchive.length, 3, 'ブルアカ3枚のfixture');
  const effect = effectsMap.get('WX25-CP1-040')?.find(e => e.effectId === 'WX25-CP1-040-E1b');
  ok(!!effect && effect.action.type === 'STUB', 'WX25-CP1-040-E1b の構造化STUBが必要');
  if (!effect || effect.action.type !== 'STUB') return;
  eq(JSON.stringify(effect.action.variableEnergyTrashLevelBounce), JSON.stringify({ story: 'ブルアカ', maxCount: 3 }));

  const ctx = mkCtx({}, { signi: [SIGNI_L1, SIGNI_L2, SIGNI_L3] }, 'WX25-CP1-040');
  ctx.ownerState.energy = [...blueArchive];
  const first = executeEffect(effect, ctx);
  ok(!first.done && first.pending.type === 'SELECT_TARGET', 'エナ0〜3枚の選択になるはず');
  if (first.done || first.pending.type !== 'SELECT_TARGET') return;
  const afterCost = resumeSelectTarget(blueArchive.slice(0, 2), first.pending, {
    ...ctx, ownerState: first.ownerState, otherState: first.otherState, logs: first.logs,
  });
  ok(!afterCost.done && afterCost.pending.type === 'SELECT_TARGET', 'コスト後はレベル2の対象選択');
  if (afterCost.done || afterCost.pending.type !== 'SELECT_TARGET') return;
  eq(JSON.stringify(afterCost.pending.candidates), JSON.stringify([SIGNI_L2]), 'レベル2だけが候補');
  const resolved = resumeSelectTarget([SIGNI_L2], afterCost.pending, {
    ...ctx, ownerState: afterCost.ownerState, otherState: afterCost.otherState, logs: afterCost.logs,
  });
  ok(resolved.done, 'バウンス解決完了');
  eq(resolved.ownerState.energy.length, 1, 'エナから2枚減る');
  ok(blueArchive.slice(0, 2).every(n => resolved.ownerState.trash.includes(n)), '選択2枚がトラッシュへ');
  ok(resolved.otherState.hand.includes(SIGNI_L2), '相手レベル2が手札へ');
});

