test('WXK06-032-E1: 双方refresh履歴で同一対象の-4000を-12000へ置換', () => {
  const savedCursor = cursor;
  try {
    const effect = manualEffect('WXK06-032', 'WXK06-032-E1');
    const source = 'WXK06-032';
    const targets = [fresh(), fresh(), fresh()];
    const resolve = (ownerRefresh: number, otherRefresh: number) => {
      const ctx = mkCtx({ signi: [source, null, null] }, { signi: targets }, source);
      ctx.ownerState.refresh_count_this_turn = ownerRefresh;
      ctx.otherState.refresh_count_this_turn = otherRefresh;
      return finish(executeEffect(effect, ctx), ctx);
    };
    const plain = resolve(0, 0).otherState.temp_power_mods ?? [];
    eq(plain.filter(m => m.delta === -4000).length, 2, '履歴なし=-4000を2対象');
    eq(plain.filter(m => m.delta === -12000).length, 0, '履歴なし=-12000は走らない');

    const refreshed = resolve(0, 1).otherState.temp_power_mods ?? [];
    eq(refreshed.filter(m => m.delta === -12000).length, 2, '相手refresh履歴でも-12000を2対象');
    eq(refreshed.filter(m => m.delta === -4000).length, 0, '-4000加算なし（-16000化しない）');
    const affected = refreshed.filter(m => m.delta === -12000).map(m => m.cardNum);
    eq(JSON.stringify(affected), JSON.stringify(targets.slice(0, 2)), '最初に選んだ同一対象を保持し、3体目を選び直さない');
  } finally {
    cursor = savedCursor;
  }
});

test('§6.3 C WX24-P4-045 field target to life and self Double Crush', () => {
  const savedCursor = cursor;
  try {
    const localMap = new InstanceMap(cardMap);
    const self = 'WX24-P4-045#src', target = `${SIGNI_L2}#target`, other = `${SIGNI_L3}#other`;
    const redBase = findCard(c => c.Color === '赤'), colorlessBase = findCard(c => c.Color === '無');
    const red = `${redBase}#cost-r`, colorless = `${colorlessBase}#cost-n`;
    for (const [inst, base] of [[self, 'WX24-P4-045'], [target, SIGNI_L2], [other, SIGNI_L3], [red, redBase], [colorless, colorlessBase]] as const)
      localMap.set(inst, cardMap.get(base)!);
    const ctx = mkCtx({ signi: [self, null, null] }, { signi: [target, other, null] }, self);
    ctx.cardMap = localMap;
    ctx.ownerState = { ...ctx.ownerState, energy: [red, colorless] };
    const r = finishPayingCosts(executeEffect(manualEffect('WX24-P4-045', 'WX24-P4-045-E1'), ctx), ctx);
    ok(r.done); if (!r.done) return;
    // ⚠加える先は **あなたの** ライフクロス（2026-07-28 是正）。原文「それをライフクロスに加える」は
    //   加える先を修飾しない＝使用者側。旧 assert は otherState.life_cloth を期待しており、
    //   「相手にライフを与える」真逆の実装を固定してしまっていた。
    ok(!tops(r.otherState).includes(target) && r.ownerState.life_cloth.includes(target));
    ok(!r.otherState.life_cloth.includes(target), '相手のライフクロスには入らない');
    ok(tops(r.otherState).includes(other));
    ok((r.ownerState.keyword_grants ?? {})[self]?.includes('ダブルクラッシュ'));
  } finally { cursor = savedCursor; }
});

