test('task12(xxix) BET choices: 条件成立/不成立を両方向で盤面固定（A1/A3/A4）', () => {
  const savedCursor = cursor;
  try {
    const wx19005 = (cardMap.get('WX19-005')?.EffectText ?? '');
    const spk = (cardMap.get('SPK16-13E')?.EffectText ?? '');
    const energyGate = parseChoiceOptionsFromText(wx19005)[1].action;
    const energyChargeGate = parseChoiceOptionsFromText(spk)[1].action;
    const drawGate = parseChoiceOptionsFromText(spk)[2].action;

    const eNo = run(energyGate, mkCtx({}, { energy: 3, trash: 0 }));
    eq(eNo.otherState.energy.length, 3, 'A1不成立: 相手エナ3枚は維持');
    const eYes = run(energyGate, mkCtx({}, { energy: 4, trash: 0 }));
    eq(eYes.otherState.energy.length, 2, 'A1成立: 相手が選んだ2枚をトラッシュ');
    eq(eYes.otherState.trash.length, 2, 'A1成立: トラッシュが2枚増える');

    const ecNoCtx = mkCtx({ deckTop: [SIGNI_L1, SIGNI_L2, SIGNI_L3], energy: 0 }, {});
    const ecNo = run(energyChargeGate, ecNoCtx);
    eq(ecNo.ownerState.energy.length, 0, 'A3不成立: エナチャージしない');
    const ecYesCtx = { ...mkCtx({ deckTop: [SIGNI_L1, SIGNI_L2, SIGNI_L3], energy: 0 }, {}), ownerState: { ...ecNoCtx.ownerState, energy_trashed_by_opp_this_turn: 1 } };
    const ecYes = run(energyChargeGate, ecYesCtx);
    eq(ecYes.ownerState.energy.length, 3, 'A3成立: デッキ上3枚をエナへ');

    const dNoCtx = mkCtx({ hand: 2 }, {});
    const dNo = run(drawGate, dNoCtx);
    eq(dNo.ownerState.hand.length, 2, 'A4不成立: 6枚まで引かない');
    const dYesCtx = { ...mkCtx({ hand: 2 }, {}), ownerState: { ...dNoCtx.ownerState, hand_trashed_by_opp_this_turn: 1 } };
    const dYes = run(drawGate, dYesCtx);
    eq(dYes.ownerState.hand.length, 6, 'A4成立: 手札6枚まで引く');
  } finally { cursor = savedCursor; }
});

test('task12(lv) COLLAB: アシスト実戦ゾーン配置→共通【出】collector→任意コスト選択', () => {
  const savedCursor = cursor;
  try {
    const assist = 'WXDi-D06-006';
    const before = mkState({ assistL: [], assistR: [] });
    before.lrig_deck = [assist];
    const collab = executeEffect({
      effectId: 'golden-collab',
      effectType: 'AUTO',
      action: { type: 'STUB', id: 'COLLAB' },
      duration: 'INSTANT',
      mandatory: true,
    } as CardEffect, {
      ...mkCtx({}, {}, 'WXDi-CP01-006'),
      ownerState: before,
    });
    ok(collab.done, '強制COLLABは配置まで完了');
    eq(collab.ownerState.field.assist_lrig_l.at(-1), assist, 'assist_lrig_lへ実配置');
    eq(collab.ownerState.field.signi.filter(Boolean).length, 0, 'シグニゾーンには置かない');
    eq(collab.lastProcessedCards?.join(','), assist, '配置アシストをtrigger収集へsurface');

    const collected = collectPlacedSelfOnPlayTriggers(
      trigCtx(), assist, collab.ownerState, collab.otherState, 'host',
      { placedByEffect: true, sourceIsSigni: false },
    );
    const entry = collected.entries.find(e => e.effectId === 'WXDi-D06-006-E1');
    ok(!!entry, 'コスト付き【出】を1件積む');
    eq(collected.entries.filter(e => e.effectId === 'WXDi-D06-006-E1').length, 1, '重複して積まない');
    const seq = entry!.effect.action as SequenceAction;
    eq(seq.type, 'SEQUENCE', '任意コスト包み');
    eq((seq.steps[0] as import('../src/types/effects').StubAction).id, 'OPTIONAL_COST', '先頭にOPTIONAL_COST');

    const collabOnPlayCtx: ExecCtx = {
      ...mkCtx({}, {}, assist),
      ownerState: {
        ...collab.ownerState,
        hand: collab.ownerState.hand.slice(0, 2),
        deck: collab.ownerState.deck.slice(0, 4),
        trash: [],
      },
    };
    const offered = executeEffect(entry!.effect, collabOnPlayCtx);
    ok(!offered.done && offered.pending.type === 'CHOOSE', '支払い選択で停止');
    if (!offered.done && offered.pending.type === 'CHOOSE') {
      eq(offered.pending.options.map(o => o.id).join(','), 'pay,skip', '支払う/スキップを提示');
    }
    eq(offered.ownerState.hand.length, 2, '選択前に手札コストも効果の3枚ドローも動かない');
    eq(offered.ownerState.trash.length, 0, '選択前に捨て札なし');
    if (!offered.done && offered.pending.type === 'CHOOSE') {
      const paid = finish(
        resumeChoose('pay', offered.pending, {
          ...collabOnPlayCtx,
          ownerState: offered.ownerState,
          otherState: offered.otherState,
          logs: offered.logs,
        }),
        collabOnPlayCtx,
      );
      eq(paid.ownerState.hand.length, 4, '手札1枚を払ってから3枚引く（2-1+3）');
      eq(paid.ownerState.trash.length, 1, '手札コスト1枚がトラッシュへ移る');
      eq(paid.ownerState.deck.length, 1, '効果で3枚引く');
    }
  } finally {
    cursor = savedCursor;
  }
});

test('task12(lv) 通常アシスト配置: 実戦ゾーン→共通【出】collector→pay/skip', () => {
  const savedCursor = cursor;
  try {
    const assist = 'WXDi-D06-006';
    const before = mkState({ assistL: [], assistR: [] });
    const placed = {
      ...before,
      lrig_deck: before.lrig_deck.filter(n => getCardNumG(n) !== assist),
      field: { ...before.field, assist_lrig_l: [assist] },
      hand: before.hand.slice(0, 2),
      deck: before.deck.slice(0, 4),
      trash: [],
    };
    eq(placed.field.assist_lrig_l.at(-1), assist, 'assist_lrig_lへ実配置');
    eq(placed.field.signi.filter(Boolean).length, 0, 'シグニゾーンには置かない');

    const collected = collectAssistOnPlayTriggers(trigCtx(), assist, placed, mkState(), 'host');
    const entries = collected.entries.filter(e => e.effectId === 'WXDi-D06-006-E1');
    eq(entries.length, 1, '通常アシスト経路で任意コスト【出】を1件積む');
    const entry = entries[0]!;
    const seq = entry.effect.action as SequenceAction;
    eq(seq.type, 'SEQUENCE', '任意コスト包み');
    eq((seq.steps[0] as import('../src/types/effects').StubAction).id, 'OPTIONAL_COST', '先頭にOPTIONAL_COST');

    const onPlayCtx = { ...mkCtx({}, {}, assist), ownerState: placed } as ExecCtx;
    const offered = executeEffect(entry.effect, onPlayCtx);
    ok(!offered.done && offered.pending.type === 'CHOOSE', '支払い選択で停止');
    if (offered.done || offered.pending.type !== 'CHOOSE') return;
    eq(offered.pending.options.map(o => o.id).join(','), 'pay,skip', '支払う/スキップを提示');
    eq(offered.ownerState.hand.length, 2, '選択前は手札不変');
    eq(offered.ownerState.trash.length, 0, '選択前はトラッシュ不変');

    const resumeCtx = {
      ...onPlayCtx,
      ownerState: offered.ownerState,
      otherState: offered.otherState,
      logs: offered.logs,
    };
    const skipped = finish(resumeChoose('skip', offered.pending, resumeCtx), onPlayCtx);
    eq(skipped.ownerState.hand.length, 2, 'skipで手札不変');
    eq(skipped.ownerState.trash.length, 0, 'skipでトラッシュ不変');
    eq(skipped.ownerState.deck.length, 4, 'skipでデッキ不変');

    const paid = finish(resumeChoose('pay', offered.pending, resumeCtx), onPlayCtx);
    eq(paid.ownerState.hand.length, 4, 'payで手札1枚を払い3枚引く（2-1+3）');
    eq(paid.ownerState.trash.length, 1, 'payで手札コスト1枚をトラッシュへ');
    eq(paid.ownerState.deck.length, 1, 'payで3枚引く');
  } finally {
    cursor = savedCursor;
  }
});

test('task12(lv) 通常アシスト配置: 旧mandatory:false母集団160件のうち153件を収集し7件は据え置く', () => {
  const savedCursor = cursor;
  try {
    const assistNums = new Set(
      [...cardMap.values()].filter(c => c.Type === 'アシストルリグ').map(c => c.CardNum),
    );
    // WXDi-P15-034-E1 は今回 mandatory:true へ直したため、旧 false 母集団へ明示的に戻して比較する。
    const formerlyOptional = [...effectsMap.entries()].flatMap(([cardNum, effects]) =>
      !assistNums.has(cardNum) ? [] : effects.filter(e =>
        e.effectType === 'AUTO'
        && e.timing?.includes('ON_PLAY')
        && (e.mandatory === false || e.effectId === 'WXDi-P15-034-E1')
      ).map(e => ({ cardNum, effect: e })),
    );
    eq(formerlyOptional.length, 160, '旧mandatory:false母集団');
    eq(formerlyOptional.filter(({ effect }) =>
      effect.triggerCondition?.byEffect || effect.triggerCondition?.bySigniEffect
    ).length, 0, '通常配置で除外されるbyEffect/bySigniEffectは0件');

    let collectedCount = 0;
    const deferred: string[] = [];
    for (const { cardNum, effect } of formerlyOptional) {
      const state = mkState({ assistL: [cardNum], assistR: [] });
      const result = collectAssistOnPlayTriggers(trigCtx(), cardNum, state, mkState(), 'host');
      if (result.entries.some(e => e.effectId === effect.effectId)) collectedCount++;
      else deferred.push(effect.effectId);
    }
    eq(collectedCount, 158, '相互制約コスト対応を含む158件を通常アシスト経路で収集');
    eq(deferred.length, 2, '表現不能コスト2件は不発のまま据え置く');
  } finally {
    cursor = savedCursor;
  }
});

