test('task12(xxix) BET choices: 脱落サブアクションが盤面を変える（B1/B2/B3）', () => {
  const savedCursor = cursor;
  try {
    const wx19006 = cardMap.get('WX19-006')?.EffectText ?? '';
    const wx19005 = cardMap.get('WX19-005')?.EffectText ?? '';
    const prk072 = cardMap.get('PR-K072')?.EffectText ?? '';
    const exileDraw = parseChoiceOptionsFromText(wx19006)[2].action;
    const drawBlindTrash = parseChoiceOptionsFromText(wx19005)[2].action;
    const downDraw = parseChoiceOptionsFromText(prk072)[0].action;
    const spell1 = findCard(c => c.Type === 'スペル');
    const spell2 = findCard(c => c.Type === 'スペル' && c.CardNum !== spell1);
    const nonSpell = findCard(c => c.Type === 'シグニ' && c.CardNum !== spell1 && c.CardNum !== spell2);

    const exBase = mkCtx({ hand: 0 }, { trash: 0 });
    exBase.otherState = { ...exBase.otherState, trash: [spell1, spell2, nonSpell] };
    const ex = run(exileDraw, exBase);
    ok(!ex.otherState.trash.includes(spell1) && !ex.otherState.trash.includes(spell2), 'B1スペル2枚を除外');
    ok(ex.otherState.trash.includes(nonSpell), 'B1非スペルは相手トラッシュに残る');
    eq(ex.ownerState.hand.length, 2, `B1 2枚以上除外したので2ドロー logs=${JSON.stringify(ex.logs)} last=${JSON.stringify(ex.lastProcessedCards)}`);

    const blindBase = mkCtx({ hand: 2 }, {});
    const blind = run(drawBlindTrash, blindBase);
    eq(blind.ownerState.hand.length, 4, 'B2 3ドロー後にblind 1枚破棄（純増2）');
    eq(blind.ownerState.trash.length, blindBase.ownerState.trash.length + 1, 'B2 blind破棄がトラッシュを増やす');

    const victim = SIGNI_L2;
    const downBase = mkCtx({ hand: 0 }, { signi: [victim, null, null], down: [false, false, false] });
    const down = run(downDraw, downBase);
    ok(down.otherState.field.signi_down?.[0], 'B3 相手シグニをダウン');
    eq(down.ownerState.hand.length, 1, 'B3 1ドロー');
  } finally { cursor = savedCursor; }
});

test('task12(xxix) BET choices: 対象フィルタと移動種別を盤面固定（C1/C2）', () => {
  const savedCursor = cursor;
  try {
    const wx19006 = cardMap.get('WX19-006')?.EffectText ?? '';
    const wdk06 = cardMap.get('WDK06-R08')?.EffectText ?? '';
    const trashLv4 = parseChoiceOptionsFromText(wx19006)[0].action;
    const lowerThanRise = parseChoiceOptionsFromText(wdk06)[0].action;
    const c1Base = mkCtx({}, { signi: [SIGNI_L3, SIGNI_L4, null], trash: 0 });
    const c1 = run(trashLv4, c1Base);
    ok(tops(c1.otherState).includes(SIGNI_L3), 'C1 レベル3は対象外');
    ok(!tops(c1.otherState).includes(SIGNI_L4), 'C1 レベル4は場からトラッシュ');
    ok(c1.otherState.trash.includes(SIGNI_L4), 'C1 バニッシュでなく直接トラッシュ');
    eq(c1.otherState.energy.length, c1Base.otherState.energy.length, 'C1 バニッシュ先エナへ送らない');

    const rise = findCard(c => c.Type === 'シグニ' && (c.EffectText ?? '').includes('【ライズ】'));
    const high = findCard(c => c.Type === 'シグニ' && parseInt(c.Power || '0') >= 12000 && c.CardNum !== rise);
    const low = findCard(c => c.Type === 'シグニ' && parseInt(c.Power || '0') > 0 && parseInt(c.Power || '0') < parseInt(cardMap.get(rise)?.Power || '0'));
    const c2Base = mkCtx({ signi: [rise, null, null] }, { signi: [high, low, null] });
    const c2 = run(lowerThanRise, c2Base);
    ok(tops(c2.otherState).includes(high), 'C2 参照シグニ以上のパワーは対象外');
    ok(!tops(c2.otherState).includes(low), `C2 参照シグニ未満だけをバニッシュ rise=${rise}:${cardMap.get(rise)?.Power} high=${high}:${cardMap.get(high)?.Power} low=${low}:${cardMap.get(low)?.Power} logs=${JSON.stringify(c2.logs)} last=${JSON.stringify(c2.lastProcessedCards)}`);
  } finally { cursor = savedCursor; }
});

test('ON_PLAY watcher 34効果: [A]33件は本来契機だけで収集し、自身の通常召喚スタックは0件 / [B]1件は停止', () => {
  const savedCursor = cursor;
  const syntheticCards: string[] = [];
  try {
    const aIds = `WX05-026-E1 WX07-001-E1 WX07-003-E1 WX08-002-E1 WX08-003-E1
      WX08-042-E2 WX10-003-E1 WX14-024-E2 WX14-025-E1 WX16-002-E3 WX17-030-E2 WX18-071-E1 WX18-072-E1
      WX20-027-E1 WX22-Re08-E1 WX22-Re17-E1 WXEX1-08-E2 WXEX1-25-E1 WXEX2-25-E1
      WXEX2-58-E2 WXK10-021-E1 WXDi-P07-008-E1 WXDi-P09-078-E1 WXDi-P11-005-E1
      WXDi-CP01-050-E1 WX24-P2-092-E1 WX25-P2-026-E1 WX25-P2-077-E1
      WDK15-001-E1 WDK17-015-E1 PR-195-E1 PR-466-E2 WXEX1-15-E1`.split(/\s+/);
    const bIds = ['WXDi-P07-058-E1'];
    const localEffects = new Map(effectsMap);
    for (const id of [...aIds, ...bIds]) {
      const cardNum = id.replace(/-E\d+$/, '');
      localEffects.set(cardNum, parseCardEffects(cardMap.get(cardNum)!));
    }
    for (const id of aIds) {
      const cardNum = id.replace(/-E\d+$/, '');
      const eff = localEffects.get(cardNum)!.find(e => e.effectId === id)!;
      const filter = eff.triggerFilter;
      let triggering = [...cardMap.values()].find(c =>
        (c.Type === 'シグニ' || c.Type === 'レゾナ') && c.CardNum !== cardNum && (!filter || matchesFilter(c, filter)))?.CardNum;
      if (!triggering && (filter?.cardName || filter?.cardType === 'レゾナ')) {
        triggering = `TEST-WATCH-${syntheticCards.length}`;
        syntheticCards.push(triggering);
        cardMap.set(triggering, {
          CardNum: triggering, CardName: filter.cardName ?? triggering, Type: filter.cardType === 'レゾナ' ? 'レゾナ' : 'シグニ',
          CardClass: typeof filter.story === 'string' ? filter.story : '', Color: typeof filter.color === 'string' ? filter.color : '無',
        } as CardData);
      }
      ok(!!triggering, `${id}: triggerFilter一致fixture`);
      const ownerIsHost = eff.triggerScope !== 'any_opp';
      const watcher = mkState({});
      if (cardNum === 'WXEX2-58') watcher.trash = [cardNum];
      else if (cardMap.get(cardNum)?.Type === 'ルリグ') watcher.field.lrig = [cardNum];
      else watcher.field.signi = [[cardNum], null, null];
      const openZone = watcher.field.signi.findIndex(s => !s);
      if (openZone >= 0) watcher.field.signi[openZone] = [triggering];
      const triggerOwner = mkState({ signi: [triggering!, null, null] });
      if (eff.triggerCondition?.placedDown) {
        const state = ownerIsHost ? watcher : triggerOwner;
        const zi = state.field.signi.findIndex(s => s?.at(-1) === triggering);
        state.field.signi_down![zi] = true;
      }
      const opts = {
        placedByEffect: !!(eff.triggerCondition?.byEffect || eff.triggerCondition?.bySigniEffect),
        placeSourceIsSigni: !!eff.triggerCondition?.bySigniEffect,
        placedFromTrash: !!eff.triggerCondition?.placedFromTrash,
        placedFromZone: eff.triggerCondition?.placedFromTrash
          ? 'trash' as const
          : eff.triggerCondition?.fromZones?.includes('energy') ? 'energy' as const : undefined,
      };
      const active = ownerIsHost ? HOST : GUEST;
      const ctx = { ...trigCtx(active, active), effectsMap: localEffects };
      const r = ownerIsHost
        ? collectFieldTriggers(ctx, 'ON_PLAY', triggering!, watcher, mkState({}), HOST, opts)
        : collectFieldTriggers(ctx, 'ON_PLAY', triggering!, triggerOwner, watcher, HOST, opts);
      eq(r.entries.filter(e => e.effectId === id).length, 1, `${id}: 本来契機のstack件数`);
      eq(isMandatoryOwnOnPlayForNormalSummon(eff) ? 1 : 0, 0, `${id}: 自身の通常召喚stack件数`);
    }
    for (const id of bIds) {
      const cardNum = id.replace(/-E\d+$/, '');
      const eff = localEffects.get(cardNum)!.find(e => e.effectId === id)!;
      eq(eff.timing?.length ?? 0, 0, `${id}: 表現不能限定はtiming停止`);
      eq(isMandatoryOwnOnPlayForNormalSummon(eff) ? 1 : 0, 0, `${id}: 自身の通常召喚stack件数`);
    }

    // triggerFilter の実効性：古代兵器でないシグニは WX05-026 watcher を発火させない。
    const watcher = mkState({ signi: ['WX05-026', null, null] });
    const mismatch = findCard(c => c.Type === 'シグニ' && !(c.CardClass ?? '').includes('古代兵器'));
    const mismatchResult = collectFieldTriggers(
      { ...trigCtx(HOST, HOST), effectsMap: localEffects },
      'ON_PLAY', mismatch, watcher, mkState({}), HOST, { placedFromTrash: true },
    );
    eq(mismatchResult.entries.filter(e => e.effectId === 'WX05-026-E1').length, 0, 'WX05-026-E1: 非＜古代兵器＞はstack 0件');
  } finally {
    for (const id of syntheticCards) cardMap.delete(id);
    cursor = savedCursor;
  }
});

