test('task12(xxix)(1) wave14 E2E: 実戦同様のシグニゾーンからON_PLAY 2件を収集・横断支払い', () => {
  const savedCursor = cursor;
  try {
    for (const effectId of ['WXK08-051-E1', 'WXK08-082-E1']) {
      const cardNum = effectId.replace(/-E\d+$/, '');
      const count = effectId === 'WXK08-082-E1' ? 2 : 1;
      const owner = mkState({});
      owner.field.signi = [['UNDER-A', cardNum], ...(count === 2 ? [['UNDER-B', 'HOST-B'] as string[]] : [null]), null];
      owner.deck = ['DECK-PAYLOAD'];
      const other = mkState({ signi: ['OPP-SIGNI', null, null] });
      const collected = collectPlacedSelfOnPlayTriggers(
        trigCtx(), cardNum, owner, other, 'host', { placedByEffect: true, sourceIsSigni: true },
      );
      const entry = collected.entries.find(e => e.effectId === effectId);
      ok(!!entry, `${effectId}: collectPlacedSelfOnPlayTriggersで収集`);
      const ctx = mkCtx({}, {}, cardNum);
      ctx.ownerState = owner;
      ctx.otherState = other;
      const offered = executeEffect(entry!.effect, ctx);
      ok(!offered.done && offered.pending.type === 'CHOOSE', `${effectId}: pay/skip`);
      if (!offered.done && offered.pending.type === 'CHOOSE') {
        eq(offered.pending.options.find(o => o.id === 'pay')?.available, true, `${effectId}: pay可能`);
        const paid = finish(resumeChoose('pay', offered.pending, {
          ...ctx, ownerState: offered.ownerState, otherState: offered.otherState, logs: offered.logs,
        }), ctx);
        eq(paid.ownerState.trash.filter(n => n.startsWith('UNDER-')).length, count, `${effectId}: 必要枚数をトラッシュ`);
        ok(paid.ownerState.field.signi.some(s => s?.at(-1) === cardNum), `${effectId}: 発生源は実戦ゾーンに残る`);
      }
      const short = { ...owner, field: { ...owner.field, signi: [[cardNum], null, null] as (string[] | null)[] } };
      const shortCollected = collectPlacedSelfOnPlayTriggers(
        trigCtx(), cardNum, short, other, 'host', { placedByEffect: true, sourceIsSigni: true },
      );
      const shortEntry = shortCollected.entries.find(e => e.effectId === effectId)!;
      const shortCtx = mkCtx({}, {}, cardNum);
      shortCtx.ownerState = short;
      shortCtx.otherState = other;
      const blocked = executeEffect(shortEntry.effect, shortCtx);
      ok(!blocked.done && blocked.pending.type === 'CHOOSE', `${effectId}: 不足時もskip`);
      if (!blocked.done && blocked.pending.type === 'CHOOSE') {
        eq(blocked.pending.options.find(o => o.id === 'pay')?.available, false, `${effectId}: 不足時pay unavailable`);
      }
    }
  } finally {
    cursor = savedCursor;
  }
});

test('task12(xxix)(1) wave15 E2E: 可変チャーム/ルリグダウンを0・途中・最大で支払い倍率へ反映', () => {
  const savedCursor = cursor;
  try {
    const oppSigni = findCard(c => c.Type === 'シグニ');
    for (const n of [0, 1, 3]) {
      const cardNum = 'WX07-045';
      const owner = mkState({ signi: [cardNum, null, null] });
      owner.field.signi_charms = ['CHARM-A', 'CHARM-B', 'CHARM-C'];
      const other = mkState({ signi: [oppSigni, null, null] });
      const entry = collectPlacedSelfOnPlayTriggers(
        trigCtx(), cardNum, owner, other, 'host', { placedByEffect: true, sourceIsSigni: true },
      ).entries.find(e => e.effectId === 'WX07-045-E1');
      ok(!!entry, `WX07-045-E1: collector収集 n=${n}`);
      const ctx = { ...mkCtx({}, {}, cardNum), ownerState: owner, otherState: other };
      const offered = executeEffect(entry!.effect, ctx);
      ok(!offered.done && offered.pending.type === 'CHOOSE', `WX07-045-E1: 枚数CHOOSE n=${n}`);
      if (!offered.done && offered.pending.type === 'CHOOSE') {
        const paid = finish(resumeChoose(`variable_cost_${n}`, offered.pending, {
          ...ctx, ownerState: offered.ownerState, otherState: offered.otherState, logs: offered.logs,
        }), ctx);
        eq(paid.ownerState.last_charm_trash_count, n, `WX07-045-E1: 支払い枚数記録 n=${n}`);
        eq(paid.ownerState.trash.length, owner.trash.length + n, `WX07-045-E1: 実トラッシュ n=${n}`);
        const charmDelta = (paid.otherState.temp_power_mods ?? [])
          .filter(m => m.cardNum === oppSigni).reduce((sum, m) => sum + m.delta, 0);
        eq(charmDelta, -7000 * n, `WX07-045-E1: -7000×${n}`);
      }
    }

    const lrigByLevel = [1, 2, 3].map(level => findCard(c => c.Type === 'ルリグ' && Number(c.Level) === level));
    for (const n of [0, 1, 3]) {
      const cardNum = 'WX24-P4-103';
      const owner = mkState({ signi: [cardNum, null, null] });
      owner.field.lrig = [lrigByLevel[0]];
      owner.field.assist_lrig_l = [lrigByLevel[1]];
      owner.field.assist_lrig_r = [lrigByLevel[2]];
      owner.field.lrig_down = owner.field.assist_lrig_l_down = owner.field.assist_lrig_r_down = false;
      const other = mkState({ signi: [oppSigni, null, null] });
      const entry = collectPlacedSelfOnPlayTriggers(
        trigCtx(), cardNum, owner, other, 'host', { placedByEffect: true, sourceIsSigni: true },
      ).entries.find(e => e.effectId === 'WX24-P4-103-E1');
      ok(!!entry, `WX24-P4-103-E1: collector収集 n=${n}`);
      const ctx = { ...mkCtx({}, {}, cardNum), ownerState: owner, otherState: other };
      const offered = executeEffect(entry!.effect, ctx);
      ok(!offered.done && offered.pending.type === 'CHOOSE', `WX24-P4-103-E1: 枚数CHOOSE n=${n}`);
      if (!offered.done && offered.pending.type === 'CHOOSE') {
        const paid = finish(resumeChoose(`variable_cost_${n}`, offered.pending, {
          ...ctx, ownerState: offered.ownerState, otherState: offered.otherState, logs: offered.logs,
        }), ctx);
        const levelSum = n === 0 ? 0 : n === 1 ? 1 : 6;
        eq(paid.ownerState.last_lrig_down_level_sum, levelSum, `WX24-P4-103-E1: レベル合計 n=${n}`);
        const lrigDelta = (paid.otherState.temp_power_mods ?? [])
          .filter(m => m.cardNum === oppSigni).reduce((sum, m) => sum + m.delta, 0);
        eq(lrigDelta, -1000 * levelSum, `WX24-P4-103-E1: -1000×レベル合計${levelSum}`);
      }
    }
  } finally {
    cursor = savedCursor;
  }
});

test('task12(l) POWER_MODIFY_PER_HAND_COUNT: owner/count/filter/until/excludeSelf を実経路で評価', () => {
  const source = 'WX26-CP1-076';
  const otherPrio = findCard(c => c.Type === 'シグニ' && (c.CardClass ?? '').includes('プリオケ') && c.CardNum !== source);
  const owner = mkState({ signi: [source, otherPrio, null], hand: 3 });
  const ctx = { ...mkCtx({}, {}, source), ownerState: owner };
  const r = run({
    type: 'POWER_MODIFY_PER_HAND_COUNT',
    target: { type: 'SIGNI', owner: 'self', count: 'ALL', filter: { story: 'プリオケ' } },
    deltaPerCard: 1000, handOwner: 'self', excludeSelf: true, until: 'UNTIL_OPP_TURN_END',
  } as EffectAction, ctx);
  const mods = r.ownerState.power_mods_until_opp_turn ?? [];
  ok(!mods.some(m => m.cardNum === source), '効果元自身を除外');
  ok(mods.some(m => m.cardNum === otherPrio && m.delta === 3000), '他の＜プリオケ＞へ手札3枚×1000');
  eq((r.otherState.temp_power_mods ?? []).length, 0, '相手側を誤って強化しない');
});

test('task12(l) SONG/TRAPを含むfresh全効果: AUTOの未展開GRANT_EFFECTは0件', () => {
  const bad: string[] = [];
  const walk = (a: EffectAction, id: string) => {
    if (a.type === 'GRANT_EFFECT' && a.rawText && !a.effect) bad.push(id);
    if (a.type === 'SEQUENCE') a.steps.forEach(s => walk(s, id));
    if (a.type === 'CONDITIONAL') { walk(a.then, id); if (a.else) walk(a.else, id); }
    if (a.type === 'CHOOSE') a.choices.forEach(c => walk(c.action, id));
  };
  for (const card of cardMap.values()) {
    for (const e of parseCardEffects(card)) if (e.parseStatus === 'AUTO') walk(e.action, e.effectId);
  }
  eq(bad.length, 0, `未展開AUTO: ${bad.join(',')}`);
});

test('task12(l) WDK04-006: 防御側collector→相手偶奇宣言resume→公開レベル不一致時だけLRIGアタック無効', () => {
  const lrig = findCard(c => c.Type === 'ルリグ');
  const odd = findCard(c => c.Type === 'シグニ' && Number(c.Level) % 2 === 1);
  const granted = mergeManualEffects('WDK04-006', effectsMap.get('WDK04-006') ?? [])[0]
    .action as import('../src/types/effects').GrantLrigAbilityAction;
  const ability = granted.abilities![0];
  const defender = mkState({ deckTop: [odd], lrig: [lrig] });
  defender.lrig_granted_auto_effects = [ability];
  const attacker = mkState({ lrig: [lrig] });
  const collected = collectLrigAttackDefenderTriggers(trigCtx(), defender, 'host').entries;
  const entry = collected.find(e => e.effectId === 'WDK04-006-E1-G');
  ok(!!entry, 'collectLrigAttackDefenderTriggers が防御側付与を収集');
  const ctx = { ...mkCtx({}, {}, lrig), ownerState: defender, otherState: attacker };
  const offered = executeEffect(entry!.effect, ctx);
  ok(!offered.done && offered.pending.type === 'CHOOSE' && offered.pending.opponentResponds === true, '相手応答の偶奇CHOOSE');
  if (!offered.done && offered.pending.type === 'CHOOSE') {
    const resumed = resumeChoose('parity_even', offered.pending, {
      ...ctx, ownerState: offered.ownerState, otherState: offered.otherState, logs: offered.logs,
    });
    const done = finish(resumed, ctx);
    ok((done.otherState.negated_attacks ?? []).includes(lrig), '奇数Lvと偶数宣言の不一致で相手LRIGアタックを無効');
    ok(done.ownerState.deck.includes(odd), '公開カードはデッキへ戻り消滅しない');
  }
});

test('task12(l) 任意場トラッシュ→UP: pay/skipが分離され、PR-461兄弟effectIdは維持', () => {
  const effs = mergeManualEffects('PR-461', effectsMap.get('PR-461') ?? []);
  eq(effs.map(e => e.effectId).join(','), 'PR-461-E1,PR-461-E2,PR-461-E3', '兄弟効果不変');
  const e2 = effs.find(e => e.effectId === 'PR-461-E2')!;
  ok(e2.action.type === 'CHOOSE', 'E2はCHOOSE');
  if (e2.action.type === 'CHOOSE') {
    const pay = e2.action.choices.find(c => c.choiceId === 'trash_and_up')!.action;
    const skip = e2.action.choices.find(c => c.choiceId === 'skip')!.action;
    ok(pay.type === 'SEQUENCE' && pay.steps[0]?.type === 'TRASH' && pay.steps[1]?.type === 'UP', 'payだけがコスト後UP');
    ok(skip.type === 'SEQUENCE' && skip.steps.length === 0, 'skipはno-op');
  }
});

test('task12(l) DECK_REVEAL_UNTIL: 未移行MANUAL 4効果を live STUBのままE2E固定', () => withSavedCursor(() => {
  const findStub = (node: unknown): EffectAction | null => {
    if (!node || typeof node !== 'object') return null;
    const obj = node as Record<string, unknown>;
    if (obj.type === 'STUB' && obj.id === 'DECK_REVEAL_UNTIL') return node as EffectAction;
    for (const value of Object.values(obj)) {
      if (Array.isArray(value)) { for (const child of value) { const hit = findStub(child); if (hit) return hit; } }
      else { const hit = findStub(value); if (hit) return hit; }
    }
    return null;
  };
  const non = findCard(c => c.Type !== 'シグニ' && c.Type !== 'ルリグ');
  const signi1 = findCard(c => isSigni(c));
  const signi2 = findCard(c => isSigni(c) && c.CardNum !== signi1);
  const runLive = (cardNum: string, effectId: string, deck: string[], declaredName?: string) => {
    const effect = manualEffect(cardNum, effectId);
    ok(!JSON.stringify(effect.action).includes('"type":"REVEAL_UNTIL"'), `${effectId}: 今回は移行しない`);
    const stub = findStub(effect.action); ok(!!stub, `${effectId}: live DECK_REVEAL_UNTILを維持`);
    const ctx = mkCtx({}, {}, cardNum); ctx.ownerState.deck = deck;
    if (declaredName) ctx.ownerState.declared_card_name = declaredName;
    const before = trackedCardCount(ctx.ownerState);
    const done = run(stub!, ctx);
    eq(trackedCardCount(done.ownerState), before, `${effectId}: 公開札消滅なし`);
    return { ctx, done };
  };
  const wdk04 = runLive('WDK04-006', 'WDK04-006-E1-G', [non, signi1]);
  eq(wdk04.done.lastProcessedCards?.length, 2, 'WDK04-006-E1-G: 最初のシグニまで公開');
  eq(wdk04.done.ownerState.deck.length, 2, 'WDK04-006-E1-G: 全公開札をデッキ下へ');
  const wdk13 = runLive('WDK13-017', 'WDK13-017-E1', [non, signi1, signi2]);
  eq(wdk13.done.lastProcessedCards?.length, 3, 'WDK13-017-E1: シグニ2枚まで公開');
  eq(wdk13.done.ownerState.deck.length, 0, 'WDK13-017-E1: 全公開札をトラッシュ');
  const wx22 = runLive('WX22-021', 'WX22-021-E2', [non, signi1], cardMap.get(signi1)!.CardName);
  ok(wx22.done.ownerState.hand.includes(signi1), 'WX22-021-E2: 宣言札を手札へ');
  eq(wx22.done.ownerState.deck.length, 1, 'WX22-021-E2: 公開した他の札はデッキ下へ');
  const wxk10 = runLive('WXK10-031', 'WXK10-031-E1', [non, signi1]);
  eq(wxk10.done.lastProcessedCards?.length, 2, 'WXK10-031-E1: 最初のシグニまで公開');
  eq(wxk10.done.ownerState.deck.length, 0, 'WXK10-031-E1: 公開札すべてトラッシュ');
}));

