// ── §6.4 O-3（続き491）: ターンプレイヤー交代の判定を1関数へ集約 ──
test('§6.4 O-3: resolveTurnHandover が追加ターンと次ターンスキップを同じ1点で解決する', () => {
  const base = mkCtx({}, {}, SIGNI).ownerState as PlayerState;
  const plain = resolveTurnHandover(base, base);
  eq(plain.keepTurn, false, '予約なしなら普通に交代する');
  const extra = resolveTurnHandover({ ...base, extra_turn: true }, base);
  eq(extra.keepTurn, true, '追加ターンなら交代しない');
  eq(extra.consumeTurnEnder({ ...base, extra_turn: true }).extra_turn, undefined, '予約を消費する（無限ループにしない）');
  const skip = resolveTurnHandover(base, { ...base, skip_next_turn: true });
  eq(skip.keepTurn, true, '次のターンプレイヤーがスキップ予約を持つなら交代しない');
  eq(skip.consumeOpponent({ ...base, skip_next_turn: true }).skip_next_turn, undefined, 'スキップ予約を消費する');
  // ⚠両方立っている場合は追加ターンが先＝スキップ予約は次の交代機会まで残す。
  const both = resolveTurnHandover({ ...base, extra_turn: true }, { ...base, skip_next_turn: true });
  eq(both.consumeOpponent({ ...base, skip_next_turn: true }).skip_next_turn, true, '追加ターン優先＝スキップ予約は残る');
});

// ── §6.4 O-3（続き492）: 「ルリグによってダメージを受けない」の期間軸・走査軸 ──
test('§6.4 O-3: 期間つきルリグダメージ無効を `PREVENT_DAMAGE{scope:LRIG}` 1本に集約する', () => {
  const runEff = (cardNum: string, effectId: string) => {
    const eff = effectsMap.get(cardNum)!.find(e => e.effectId === effectId)!;
    const ctx = mkCtx({ signi: [SIGNI, SIGNI, null] }, { signi: [SIGNI, null, null] }, cardNum);
    return finish(executeEffect(eff, ctx), ctx);
  };
  // 🔴従来は `prevent_lrig_damage` フラグ＝**ターン終了時にクリアされる**ので「次のターンの間」が
  //   一度も効かず（`WXK10-019-E2`）、「このターン」も1回防いだ時点で消えていた。
  const nextTurn = runEff('WXK10-019', 'WXK10-019-E2');
  const winN = (nextTurn.ownerState as PlayerState).prevent_damage_windows ?? [];
  eq(JSON.stringify(winN), JSON.stringify([{ scope: 'LRIG', expires: 'NEXT_TURN_START' }]), '次のターン予約として積む');
  eq(hasActivePreventDamageWindow(nextTurn.ownerState as PlayerState, 'LRIG'), false, '予約は張ったターンには効かない');
  const promoted = clearTurnEndScopedState(nextTurn.ownerState as PlayerState);
  eq(hasActivePreventDamageWindow(promoted, 'LRIG'), true, 'ターン境界で昇格して次のターンを丸ごと守る');
  eq(hasActivePreventDamageWindow(clearTurnEndScopedState(promoted), 'LRIG'), false, 'その次の境界で消える');

  const thisTurn = runEff('PR-K019', 'PR-K019-E3');
  eq(hasActivePreventDamageWindow(thisTurn.ownerState as PlayerState, 'LRIG'), true, 'このターン版は即座に有効');
  // ⚠期間内は**回数無制限**（旧フラグは1回で消費されていた）。
  eq(hasActivePreventDamageWindow(thisTurn.ownerState as PlayerState, 'LRIG'), true, '同一ターンの2回目も防ぐ');
  eq(hasActivePreventDamageWindow(clearTurnEndScopedState(thisTurn.ownerState as PlayerState), 'LRIG'), false, 'ターン終了で消える');
});

test('§6.4 O-3: ルリグダメージ無効の走査軸はシグニだけでは足りない', () => {
  const cm = cardMap as Map<string, CardData>;
  // `WXK03-001-E1`＝**ルリグ本体**の【常】（手札0枚のかぎり）。🔴従来の判定は自分のシグニしか
  //   走査しておらず、この宣言は一度も読まれていなかった。
  const lrigDeclarer = { ...mkState({ signi: [SIGNI, null, null] }), hand: [] as string[] };
  lrigDeclarer.field.lrig = ['WXK03-001'];
  const attacker = mkState({});
  ok(isLrigDamagePrevented({ defender: lrigDeclarer, attacker, cardMap: cm, effectsMap }), 'ルリグ本体の【常】を読む');
  // 対照＝activeCondition（手札0枚）を満たさなければ効かない。
  ok(!isLrigDamagePrevented({ defender: { ...lrigDeclarer, hand: [SIGNI] }, attacker, cardMap: cm, effectsMap }),
    '条件を満たさなければ防がない');
  // `WXK11-012-E2`＝**キー**の【常】かつ「レベル2以下のルリグによって」限定。
  const keyDeclarer = mkState({ signi: [SIGNI, null, null] });
  keyDeclarer.field.key_piece = 'WXK11-012';
  const lowLv = [...cm.entries()].find(([, c]) => c.Type === 'ルリグ' && parseInt(c.Level ?? '', 10) <= 2)?.[0];
  const highLv = [...cm.entries()].find(([, c]) => c.Type === 'ルリグ' && parseInt(c.Level ?? '', 10) >= 4)?.[0];
  ok(!!lowLv && !!highLv, 'レベル比較用のルリグが見つかる');
  ok(isLrigDamagePrevented({ defender: keyDeclarer, attacker, cardMap: cm, effectsMap, attackingLrigNum: lowLv }),
    'レベル2以下のルリグからは守る');
  // 🔴限定を落とすと「すべてのルリグからのダメージを無効」の過剰効果になる。
  ok(!isLrigDamagePrevented({ defender: keyDeclarer, attacker, cardMap: cm, effectsMap, attackingLrigNum: highLv }),
    'レベル上限を超えるルリグからは守らない');
});

test('§6.4 O-10（続き508）: 【ゲート】同ゾーンの引用付与クラスは全件が同じ形（`WXDi-P16-062-E1` の取り残しガード）', () => {
  // 🔑この defer は**新機構を要らなかった**＝原文 regex（「同じシグニゾーンに【ゲート】」）で数えた同族は
  //   20効果あり、うち引用付与形は**すべて「引用を平らにして `SAME_ZONE_HAS_GATE` を条件に持つ」形**で
  //   実装済みだった。1件だけ defer のまま残っていた＝**在庫表ではなく原文で数えると見つかる**型。
  const srcText: Record<string, string> = JSON.parse(fs.readFileSync(join(root, 'docs/_effect_srctext.json'), 'utf-8'));
  const quoted = Object.keys(srcText).filter(id =>
    /この(?:シグニ|カード)は同じシグニゾーンに【ゲート】があるかぎり[、,]「/.test(srcText[id]));
  ok(quoted.length >= 10, `引用付与形の母集団（${quoted.length}効果）`);
  for (const effectId of quoted) {
    const cardNum = effectId.replace(/-E\d+$/, '');
    const eff = mergeManualEffects(cardNum, effectsMap.get(cardNum) ?? []).find(e => e.effectId === effectId)!;
    const json = JSON.stringify(eff);
    ok(json.includes('SAME_ZONE_HAS_GATE'), `${effectId}: 同ゾーンゲート条件を持つ`);
    ok(!json.includes('DEFERRED_'), `${effectId}: defer が残っていない`);
  }
  // `WXDi-P16-062-E1` の中身＝「各アタックフェイズ開始時」＋「相手が《無》を支払わないかぎり能力を失う」。
  const e = mergeManualEffects('WXDi-P16-062', effectsMap.get('WXDi-P16-062') ?? [])
    .find(x => x.effectId === 'WXDi-P16-062-E1')!;
  eq(e.effectType, 'AUTO', '引用【自】は AUTO へ平らにする');
  eq(e.timing?.join(','), 'ON_ATTACK_PHASE_START', 'アタックフェイズ開始時');
  eq(e.triggerScope, 'any', '⚠「**各**アタックフェイズ」＝両プレイヤー分（self にすると自分のターンだけになる）');
  const json062 = JSON.stringify(e.action);
  ok(json062.includes('OPPONENT_PAY_OPTIONAL'), '支払い回避（対戦相手が払う）を持つ');
  ok(json062.includes('REMOVE_ABILITIES'), '払わなければ能力を失う');
});

test('§6.4 O-10（続き518）: ピース応答窓＝候補が出るのは窓が開いた盤面だけ（負方向＋対照の対）', () => {
  const cm = cardMap as Map<string, CardData>;
  const em = new Map(effectsMap);
  em.set('WXDi-P05-006', mergeManualEffects('WXDi-P05-006', effectsMap.get('WXDi-P05-006') ?? []));
  // 応答側＝きゅるきゅるーん☆のルリグ3体＋ルリグデッキに WXDi-P05-006。
  const teamLrigs = [...cm.values()].filter(c => (c.Team ?? '').includes('きゅるきゅるーん')).map(c => c.CardNum);
  ok(teamLrigs.length >= 3, `＜きゅるきゅるーん☆＞のルリグが3体以上ある（${teamLrigs.length}）`);
  const responder: PlayerState = {
    ...mkState({ lrig: [teamLrigs[0]], assistL: [teamLrigs[1]], assistR: [teamLrigs[2]] }),
    lrig_deck: ['WXDi-P05-006'],
  };
  const caster = mkState({});
  // 使われた側＝【使用条件】【チーム】を持つピース。
  const teamPiece = [...cm.values()].find(c => c.Type === 'ピース' && (c.EffectText ?? '').includes('【使用条件】【チーム】'))!;
  ok(!!teamPiece, '【使用条件】【チーム】を持つピースが見つかる');
  const call = (used: CardData | undefined, r: PlayerState = responder) =>
    collectPieceCutinCandidates({ responder: r, caster, usedPieceCard: used, cardMap: cm, effectsMap: em });
  eq(call(teamPiece).length, 1, '対照＝チームピースの使用にはカットインできる');
  eq(call(teamPiece)[0].instanceId, 'WXDi-P05-006', '候補はルリグデッキのそのピース');
  // 🔴負方向①＝【使用条件】【チーム】を持たないピースの使用では窓が開かない。
  const plainPiece = [...cm.values()].find(c => c.Type === 'ピース' && !(c.EffectText ?? '').includes('【使用条件】【チーム】'));
  eq(call(plainPiece).length, 0, '🔴チーム条件を持たないピースにはカットインできない');
  eq(call(undefined).length, 0, 'ピースでなければ窓は開かない');
  // 🔴負方向②＝チームが揃っていなければ候補にならない（同居条件の脱落ガード）。
  const soloTeam: PlayerState = { ...responder, field: { ...responder.field, assist_lrig_l: [], assist_lrig_r: [] } };
  eq(call(teamPiece, soloTeam).length, 0, '🔴チーム3体が揃っていなければカットインできない');
  // 🔴負方向③＝ルリグデッキに札が無ければ候補0（＝窓を開かない＝従来と同じ即時解決経路）。
  eq(call(teamPiece, { ...responder, lrig_deck: [] }).length, 0, '🔴札が無ければ窓は開かない');
  // 条件評価の単体＝窓フラグが唯一の読み手。
  const ctx = mkCtx({}, {});
  eq(evalUseCondition({ type: 'OPP_USING_TEAM_PIECE' } as never, ctx.ownerState, ctx.otherState, cm, 'x', 'MAIN'),
     false, '窓が閉じていれば false');
  eq(evalUseCondition({ type: 'OPP_USING_TEAM_PIECE' } as never,
     { ...ctx.ownerState, team_piece_cutin_window: true }, ctx.otherState, cm, 'x', 'MAIN'),
     true, '窓が開いていれば true');
  // ①＝打ち消しは「使った側にフラグを立てる」だけ（除外は窓を閉じる側が行う＝id を知っているのはそちら）。
  const counterCtx = mkCtx({}, {});
  const r = run({ type: 'STUB', id: 'COUNTER_TEAM_PIECE_AND_EXILE' } as unknown as EffectAction, counterCtx);
  eq(r.otherState.piece_use_countered, true, '打ち消しフラグはピースを使った側に立つ');
  eq(r.ownerState.piece_use_countered, undefined, '⚠自分側には立てない（向きを取り違えると自爆する）');
  // live 表現＝defer は解体済み。
  const act = JSON.stringify(mergeManualEffects('WXDi-P05-006', effectsMap.get('WXDi-P05-006') ?? [])
    .find(e => e.effectId === 'WXDi-P05-006-E1')!.action);
  ok(act.includes('COUNTER_TEAM_PIECE_AND_EXILE') && !act.includes('DEFERRED_'), 'defer は解体済み');
});

test('§6.4 O-10（続き517）: カットイン専用ピースの使用条件を復元（過剰実行→宣言済みの過少）', () => {
  // 🔴従来 `WXDi-P05-006-E1` は `condition` が丸ごと無く、**チームが揃っていなくても・カットイン窓でなくても**
  //    メイン／アタックフェイズにいつでも撃てた（選択肢②＝「1枚引き＋エナチャージ1」が《青×0》で撃ち放題）。
  const eff = mergeManualEffects('WXDi-P05-006', effectsMap.get('WXDi-P05-006') ?? [])
    .find(e => e.effectId === 'WXDi-P05-006-E1')!;
  const cond = JSON.stringify(eff.condition ?? {});
  ok(cond.includes('LRIG_TEAM_COUNT') && cond.includes('きゅるきゅるーん☆'),
     '【使用条件】【チーム】＜きゅるきゅるーん☆＞（同族11効果と同じ形）');
  ok(cond.includes('"value":3'), 'チームは3体');
  ok(cond.includes('OPP_USING_TEAM_PIECE'), '🔴「カットインして使用できる」＝窓限定の使用条件');
  // ⚠窓が無い間は**常に false**＝使えない（宣言済みの過少）。ここが true に化けたら過剰実行に戻る。
  const ctx = mkCtx({}, {});
  eq(evalUseCondition({ type: 'OPP_USING_TEAM_PIECE' } as never, ctx.ownerState, ctx.otherState,
     cardMap as Map<string, CardData>, 'WXDi-P05-006', 'MAIN'), false,
     '🔴応答窓が無い間は常に false（＝通常タイミングで撃てない）');
  // 選択肢②は窓が出来たらそのまま動く形で残してある（消さない）。
  const act = JSON.stringify(eff.action);
  ok(act.includes('"type":"DRAW"') && act.includes('ENERGY_CHARGE_FROM_DECK'), '②は実装済みのまま残す');
  ok(act.includes('COUNTER_TEAM_PIECE_AND_EXILE'), '①も続き518 で実装済み（応答窓ごと）');
});

test('§6.4 O-10（続き516）: 対象になったら裏返って対象から外れる（負方向＋対照の対）', () => {
  // 🔑`ON_TARGETED` トリガーは `resumeSelectTarget` が効果を適用し**終えた後**に積まれる（続き511 で特定）＝
  //   トリガーとしては表現できないので、**対象宣言の直後・適用の前**の1点で解決する。
  const cm = cardMap as Map<string, CardData>;
  const other = findCard(c => isSigni(c) && (c.CardClass ?? '').includes('ブルアカ') && c.CardNum !== 'WX25-CP1-060');
  const em = new Map(effectsMap);
  em.set('WX25-CP1-060', mergeManualEffects('WX25-CP1-060', effectsMap.get('WX25-CP1-060') ?? []));
  const mk = (signi: (string | null)[]) => mkState({ signi });
  const src = mkState({});
  const call = (owner: PlayerState, isOwnerTurn = false) => resolveTargetDodgeFlip({
    targeted: ['WX25-CP1-060'], targetOwnerState: owner, sourceState: src,
    isTargetOwnerTurn: isOwnerTurn, cardMap: cm, effectsMap: em,
  });
  // 対照＝相手ターン＋他の＜ブルアカ＞がいる → 対象から外れる。
  const okState = mk(['WX25-CP1-060', other, null]);
  const hit = call(okState);
  eq(hit.dodged.join(','), 'WX25-CP1-060', '対象から外れる');
  eq(hit.state.lost_ability_effect_ids_this_turn?.join(','), 'WX25-CP1-060-E2',
     '⚠失うのは**この効果1つ**（abilities_removed だと同居する【常】E1/【絆常】E3 まで消える）');
  // 🔴負方向①＝他の＜ブルアカ＞がいなければ回避しない（使用条件の脱落ガード）。
  eq(call(mk(['WX25-CP1-060', null, null])).dodged.length, 0, '🔴単騎では回避しない');
  // 🔴負方向②＝自分のターンには回避しない（《相手ターン》の脱落ガード）。
  eq(call(okState, true).dodged.length, 0, '🔴自分のターンには回避しない');
  // 🔴負方向③＝同じターンの2回目は回避しない（1回で【自】を失う）。
  eq(call(hit.state).dodged.length, 0, '🔴一度回避したらそのターンは回避しない');
  eq(call(clearTurnEndScopedState(hit.state)).dodged.length, 1, 'ターンが変われば再び回避する');
  // 🔴無関係な盤面では**完全に不活性**（ホットパスに足した分岐の安全条件）。
  const plain = mk([SIGNI, null, null]);
  const inert = resolveTargetDodgeFlip({ targeted: [SIGNI], targetOwnerState: plain, sourceState: src,
    isTargetOwnerTurn: false, cardMap: cm, effectsMap: em });
  eq(inert.dodged.length, 0, '宣言を持たないシグニでは何も起きない');
  eq(JSON.stringify(inert.state), JSON.stringify(plain), '🔴state も 1バイトも変わらない');
  // live 表現＝defer は解体済み＆死んだ REMOVE_ABILITIES が消えている。
  const act = JSON.stringify(mergeManualEffects('WX25-CP1-060', effectsMap.get('WX25-CP1-060') ?? [])
    .find(e => e.effectId === 'WX25-CP1-060-E2')!.action);
  ok(act.includes('FLIP_SELF_ON_TARGETED') && !act.includes('DEFERRED_'), 'defer は解体済み');
  ok(!act.includes('REMOVE_ABILITIES'),
     '🔴カード単位の能力喪失（同居能力の巻き添え）へ戻っていない');
});

test('§6.4 O-10（続き515）: チェックゾーン裏返し→無償グロウ（負方向＋対照の対）', () => {
  // 🔑**旧・据置理由「B面が CardData CSV に無い」は古かった**＝`WXDi-P16-001B`（ルリグ Lv4）は
  //   `CardData_TK.csv` に入っている。**前提は着手のたびに grep で確かめる。**
  const bSide = cardMap.get('WXDi-P16-001B');
  ok(!!bSide, 'B面がカードデータにある');
  eq(bSide?.Type, 'ルリグ', 'B面はルリグ');
  eq(bSide?.Level, '4', 'B面は Lv4');
  // live 表現＝グロウ先は**カード名**で載る（CardNum は原文に無い）。
  const act = (effectsMap.get('WXDi-P16-001A') ?? []).find(e => e.effectId === 'WXDi-P16-001A-E1')!.action as
    { type: string; id?: string; value?: unknown };
  eq(act.id, 'CHECK_ZONE_FLIP_FREE_GROW', 'defer は解体済み');
  eq(act.value, bSide?.CardName, 'グロウ先はカード名で載る（engine が cardMap で解決）');
  // 対照＝このターン未グロウなら予約が立つ。
  const ctx = mkCtx({ lrig: ['WXDi-P16-001A'] }, {}, 'WXDi-P16-001A');
  ctx.ownerState.lrig_trash = ['WXDi-P16-001A'];
  const ok1 = run(act as unknown as EffectAction, ctx);
  eq(ok1.ownerState.pending_flip_grow_card, 'WXDi-P16-001B', 'グロウ予約が立つ（CardNum へ解決済み）');
  ok(!ok1.ownerState.lrig_trash.includes('WXDi-P16-001A'),
     '⚠裏返して**ルリグになる**ので、自分自身はルリグトラッシュに残さない');
  // 🔴負方向＝このターン既にグロウしていれば何も起きない。
  const grown = { ...ctx, ownerState: { ...ctx.ownerState, lrig_grew_this_turn: true } } as ExecCtx;
  eq(run(act as unknown as EffectAction, grown).ownerState.pending_flip_grow_card, undefined,
     '🔴このターン既にグロウしていたら予約が立たない');
  // グロウ履歴はターン境界で消える＝次のターンにはまた使える。
  eq(clearTurnEndScopedState(grown.ownerState as PlayerState).lrig_grew_this_turn, undefined, 'ターン境界で消える');
  // ⚠**実グロウは BattleScreen の正規経路**（engine が field.lrig へ直接 push しない＝
  //    グロウ時トリガー・リミット再計算・コイン獲得を落とさない）。
  const src = fs.readFileSync(join(root, 'src/screens/BattleScreen.tsx'), 'utf8');
  ok(/pending_flip_grow_card/.test(src), 'BattleScreen が予約を消費する');
  ok(/lrig_grew_this_turn: true/.test(src), 'グロウ履歴を立てる地点がある');
  // 🔴2→1（続き552d・§8 `O-1` (d)）＝**CPU の手書きグロウを削除して `performGrow` に統合した**ので
  //    履歴を立てる地点は1つで正しい。⚠**2つに戻ったら CPU 経路が再分岐した合図**（＝軸が食い違う）。
  eq((src.match(/lrig_grew_this_turn: true/g) ?? []).length, 1,
     '🔴グロウの実行経路は1本（人間・CPU 共通の `performGrow`）＝履歴を立てる地点も1つ');
  ok(/const performGrow = async/.test(src), 'グロウ実行は owner パラメータ化された1本');
  ok(src.includes("energyPayPool: cpuGrowPool,") && src.includes("onCostOnPlay: 'auto',"),
     'CPU も同じ `performGrow` を呼ぶ（コスト付き任意【出】は auto）');
});

test('§6.4 O-10（続き514）: 相手トラッシュの「能力を失い、効果を受けない」（負方向＋対照の対）', () => {
  // 🔑据置理由「相手トラッシュに触る全効果に及ぶ」は**古かった**＝トラッシュを発生源にする候補列は
  //   `movableTrashCandidates` の**1点 funnel**（8呼び出しが全部そこを通る）。
  const cm = cardMap as Map<string, CardData>;
  const trashed = findCard(c => isSigni(c));
  // 宣言者（WX12-023）が**自分の場**にいる → 相手のトラッシュが免疫。
  const withDeclarer = mkCtx({ signi: ['WX12-023', null, null] }, {});
  withDeclarer.otherState.trash = [trashed];
  eq(movableTrashCandidates('opponent', withDeclarer.otherState, undefined, cm, withDeclarer).length, 0,
     '🔴相手のトラッシュは効果の対象にできない');
  // 対照＝宣言者がいなければ普通に対象にできる。
  const noDeclarer = mkCtx({ signi: [SIGNI, null, null] }, {});
  noDeclarer.otherState.trash = [trashed];
  ok(movableTrashCandidates('opponent', noDeclarer.otherState, undefined, cm, noDeclarer).length > 0,
     '対照＝宣言が無ければ対象にできる');
  // ⚠**主語を問わない**＝持ち主自身の回収も止まる（原文は「効果を受けない」としか書いていない）。
  const ownTrash = mkCtx({ signi: [SIGNI, null, null] }, { signi: ['WX12-023', null, null] });
  ownTrash.ownerState.trash = [trashed];
  eq(movableTrashCandidates('self', ownTrash.ownerState, undefined, cm, ownTrash).length, 0,
     '🔴宣言者が相手の場にあるとき、自分のトラッシュ回収も止まる');
  // 判定関数の単体＝宣言の有無だけを見る。
  ok(isTrashImmuneByOpponent(withDeclarer.ownerState, cm), '宣言者が場にあれば true');
  ok(!isTrashImmuneByOpponent(noDeclarer.ownerState, cm), '宣言者がいなければ false');
  // live 表現＝defer は解体済み。
  const act = JSON.stringify(mergeManualEffects('WX12-023', effectsMap.get('WX12-023') ?? [])
    .find(e => e.effectId === 'WX12-023-E1')!.action);
  ok(act.includes('TRASH_ABILITY_LOSS_AND_IMMUNITY') && !act.includes('DEFERRED_'), 'defer は解体済み');
  // 「能力を失う」の読み手2つが UI に配線されている（実挙動は §7 実機検証）。
  // 🆕2026-08-18（§6.4 O-1 (f)）＝**継承【起】ぶんの読み手は `lrigActivateGate.ts` へ移った**
  //   （人間のボタン生成と CPU の候補フィルタが同じ funnel を通るようにしたため）。
  const src = fs.readFileSync(join(root, 'src/screens/BattleScreen.tsx'), 'utf8');
  const gateSrc = fs.readFileSync(join(root, 'src/screens/battle/lrigActivateGate.ts'), 'utf8');
  eq((src.match(/isTrashImmuneByOpponent\(/g) ?? []).length, 1,
     'トラッシュ起動【起】は BattleScreen 側で見る');
  eq((gateSrc.match(/isTrashImmuneByOpponent\(/g) ?? []).length, 1,
     'ルリグトラッシュ継承【起】は lrigActivateGate 側で見る（人間/CPU 共通）');
});

test('§6.4 O-18（続き513）: スペル使用の封じ3軸が1関数に集約され、ボタン生成側からも見られている', () => {
  // 🔴続き460 で `USE_SPELL` だけボタン生成側へ足したが、`PLAY_COLORLESS`（無色スペル封じ）と
  //    `BLOCK_NON_WHITE_SPELL`（白以外スペル封じ）は**実行入口にしかガードが無く**、
  //    封じ中でも「発動」ボタンが出て押しても何も起きない**無言の no-op** だった。
  // ⚠実 UI は BattleScreen のクロージャなので、ここでは**軸の集約と呼び出し箇所**を固定する
  //    （実挙動は §7 実機検証＝負方向＋対照の対）。
  // 続き552（§8 O-1 (b)）＝funnel 本体は `spellUseGate.ts` の pure 関数へ移した
  // （CPU のスペル候補フィルタも同じ関数を呼ぶ）。
  const src = fs.readFileSync(join(root, 'src/screens/BattleScreen.tsx'), 'utf8');
  const gate = fs.readFileSync(join(root, 'src/screens/battle/spellUseGate.ts'), 'utf8');
  const fn = gate.slice(gate.indexOf('export function isSpellUseBlockedFor'), gate.indexOf('export function isSpellUseBlockedFor') + 700);
  ok(/export function isSpellUseBlockedFor\(/.test(gate), 'スペル封じの判定が1関数に集約されている');
  for (const axis of ['USE_SPELL', 'PLAY_COLORLESS', 'BLOCK_NON_WHITE_SPELL']) {
    ok(fn.includes(axis), `🔴${axis} が判定に含まれる（軸の脱落ガード）`);
  }
  ok(/PLAY_COLORLESS'\)\s*&&\s*card\?\.Color === '無'/.test(fn), '無色スペルだけを止める（全スペルに広げない）');
  ok(/BLOCK_NON_WHITE_SPELL'\)\s*&&\s*!card\?\.Color\?\.includes\('白'\)/.test(fn), '白以外だけを止める');
  // ⚠**提示ゲート（`checkSpellUse`）と実行入口（`performSpell`）の両方**から呼ぶ。
  ok(/!isSpellUseBlockedFor\(my, payer\.blockedSelf, card\)/.test(gate), '提示ゲート（checkSpellUse）から呼ぶ');
  ok(/isSpellUseBlockedFor\(my, p\.blockedSelf, card\)/.test(src), '実行ゲート（performSpell）から呼ぶ');
  // ⚠BattleScreen 側は薄いラッパー1本だけ（スペル/クラフトのボタン生成が呼ぶ）。
  eq((src.match(/isSpellUseBlocked\(/g) ?? []).length, 1, 'BattleScreen 側の呼び出しはスペル/クラフトの1箇所だけ（手札スペルは checkSpellUse 経由）');
  // 軸の直書きが funnel の外へ復活していないこと（＝また片側だけ塞ぐ回帰のガード）。
  eq((src.match(/isActionBlocked\('BLOCK_NON_WHITE_SPELL'\)/g) ?? []).length, 0,
     'BLOCK_NON_WHITE_SPELL を BattleScreen で直接見ない');
  eq((gate.match(/isActionBlocked\('BLOCK_NON_WHITE_SPELL'\)/g) ?? []).length, 1,
     'BLOCK_NON_WHITE_SPELL を見るのは funnel の1箇所だけ');
});

test('§6.4 O-10（続き512）: 無色のカードではエナコストを支払えない（負方向＋対照の対）', () => {
  const cards = [...cardMap.values()] as CardData[];
  const colorless = findCard(c => (c.Color ?? '') === '無' && c.Type === 'シグニ');
  const red = findCard(c => (c.Color ?? '') === '赤' && c.Type === 'シグニ');
  // 対照＝制限が無ければ無色カードでも《無》×1 を払える。
  eq(canAffordGrowCost([colorless], cards, '《無》×1'), true, '通常は無色カードで《無》を払える');
  // 🔴負方向＝制限中は払えない（⚠**《無》スロットの充当にも使えない**＝ここを緩めると制限が骨抜き）。
  eq(canAffordGrowCost([colorless], cards, '《無》×1', undefined, undefined, undefined, undefined, undefined,
     undefined, undefined, undefined, undefined, true), false, '🔴制限中は無色カードで払えない');
  // 対照＝有色カードは制限中でも払える。
  eq(canAffordGrowCost([red], cards, '《無》×1', undefined, undefined, undefined, undefined, undefined,
     undefined, undefined, undefined, undefined, true), true, '有色カードは制限を受けない');
  eq(canAffordGrowCost([red], cards, '《赤》×1', undefined, undefined, undefined, undefined, undefined,
     undefined, undefined, undefined, undefined, true), true, '色指定も同様');
  // ⚠制限はアタックフェイズ限定だが**境界は turn-end**（相手側 state に載るため）＝ターンで消える。
  const banned = { ...mkState({}), cannot_pay_colorless_this_attack_phase: true } as PlayerState;
  eq(clearTurnEndScopedState(banned).cannot_pay_colorless_this_attack_phase, undefined, 'ターン境界で解ける');
});

test('§6.4 O-10（続き512）: ARTS_LIMIT_1 が実際にアーツ使用を止める（未消費 BLOCK_ACTION id の解消）', () => {
  // 🔴`ARTS_LIMIT_1` は parser が生成するのに **engine/UI の誰も読んでいなかった**＝
  //    `WX13-007-E1`「対戦相手は各ターンに一度しかアーツを使用できない」が恒久 no-op だった。
  //    実 UI ゲート（`isArtsUseBlocked`）は BattleScreen のクロージャなので、ここでは
  //    **live 表現＋判定式の存在**を固定する（実挙動は §7 実機検証）。
  const e1 = (effectsMap.get('WX13-007') ?? []).find(e => e.effectId === 'WX13-007-E1')!;
  const act = e1.action as { type: string; actionId?: string; target?: { owner?: string } };
  eq(act.type, 'BLOCK_ACTION', 'BLOCK_ACTION で表す');
  eq(act.actionId, 'ARTS_LIMIT_1', 'id は ARTS_LIMIT_1');
  eq(act.target?.owner, 'opponent', '止まるのは対戦相手');
  // 続き552（§8 O-1 (a)）＝ゲート本体は `artsUseGate.ts` の pure 関数へ移した（CPU の応答アーツも
  // 同じ関数を呼ぶ）。判定式の存在をここで固定する（実挙動は §7 実機検証）。
  const gate = fs.readFileSync(join(root, 'src/screens/battle/artsUseGate.ts'), 'utf8');
  ok(/export function isArtsUseBlockedFor\(/.test(gate), 'アーツ使用ゲートが1関数に集約されている');
  ok(/ARTS_LIMIT_1/.test(gate), "🔴`ARTS_LIMIT_1` を UI が読む（未消費 id へ戻っていない）");
  // ⚠**表示ゲートと実行ゲートの両方**で呼ぶ（片方だけだと「押せるのに無反応」か「UI 迂回で使える」）。
  ok(/isArtsUseBlockedFor\(my, payer\.blockedSelf\)/.test(gate), '表示ゲート（checkArtsUse）から呼ぶ');
  const src = fs.readFileSync(join(root, 'src/screens/BattleScreen.tsx'), 'utf8');
  ok(/isArtsUseBlockedFor\(my, p\.blockedSelf\)/.test(src), '実行ゲート（performArts）から呼ぶ');
});

test('§6.4 O-10（続き510）: 相手ターンのアーツコスト軽減は1回だけ（負方向＋対照の対）', () => {
  const cm = cardMap as Map<string, CardData>;
  const st = mkState({ signi: [null, 'WXK03-071', null] });   // 中央（zone1）に置く
  const op = mkState({});
  const em = new Map(effectsMap);
  em.set('WXK03-071', mergeManualEffects('WXK03-071', effectsMap.get('WXK03-071') ?? []));
  const get = (owner: PlayerState, isOwnerTurn: boolean) =>
    collectOppTurnArtsCostReductions(owner, op, isOwnerTurn, cm, em);
  // 対照＝相手ターン・中央なら軽減が出る。
  const got = get(st, false);
  eq(got.length, 1, '相手ターンなら軽減が1件出る');
  eq(got[0].color, '無', '《無》の軽減');
  eq(got[0].reduction, 2, '⚠枚数は宣言から読む（2枚）');
  eq(got[0].effectId, 'WXK03-071-E1', '消費する effectId を返す');
  // 🔴負方向①＝自分のターンには効かない（落とすと常時軽減になる）。
  eq(get(st, true).length, 0, '🔴自分のターンには軽減しない');
  // 🔴負方向②＝中央でなければ効かない（activeCondition）。
  const side = mkState({ signi: ['WXK03-071', null, null] });
  eq(get(side, false).length, 0, '🔴左のシグニゾーンでは軽減しない');
  // 🔴負方向③＝一度使ったら「この能力を失う」＝同じターンの2回目は出ない。
  const used: PlayerState = { ...st, lost_ability_effect_ids_this_turn: ['WXK03-071-E1'] };
  eq(get(used, false).length, 0, '🔴1回使ったらそのターンは軽減しない');
  eq(get(clearTurnEndScopedState(used), false).length, 1, 'ターンが変われば戻る');
  // funnel＝`computeArtsEffectiveCost` の `artsThresholdReductions`（minTotalCost:0）で実際に引ける。
  // ⚠`findCard` は **CardNum（文字列）**を返す＝カード実体は cardMap から引く。
  const arts = cm.get(findCard(c => c.Type === 'アーツ' && /《無》×[２2]/.test(c.Cost ?? '')))!;
  ok(!!arts?.Cost, '《無》×2 以上のアーツが見つかる');
  const before = computeArtsEffectiveCost(arts, st, undefined, undefined, undefined, cm, undefined, []);
  const after = computeArtsEffectiveCost(arts, st, undefined, undefined, undefined, cm, undefined,
    got.map(r => ({ minTotalCost: 0, color: r.color, reduction: r.reduction })));
  ok(after !== before, `軽減が実コストへ効く（${before} → ${after}）`);
  // live 表現＝defer は解体済み。
  const e1 = JSON.stringify(mergeManualEffects('WXK03-071', effectsMap.get('WXK03-071') ?? [])
    .find(e => e.effectId === 'WXK03-071-E1')!);
  ok(e1.includes('OPP_TURN_ARTS_COST_REDUCTION_ONCE') && e1.includes('IS_SELF_IN_CENTER_ZONE'), '宣言＋中央条件');
  ok(!e1.includes('DEFERRED_'), 'defer は残っていない');
});

test('§6.4 O-10（続き510）: 「あなたの効果によってシグニのアタックは無効にならない」（負方向＋対照の対）', () => {
  // 🔑ちより／【マジックボックス】系は「【ライフバースト】を持たない場合、**このアタックを無効にし**、〈利得〉」＝
  //   **自分の効果で自分のアタックを無効にする**足枷を持つ。`WX24-P4-016-E3` はその足枷をターン中だけ外す。
  // ⚠**利得側**なので落ちていても盤面は壊れず「使ってもデメリットが消えない」過少実行として現れる
  //   （A群にも映らない型）＝ここが唯一の見張り。
  const cancel = { type: 'STUB', id: 'SET_CANCEL_ATTACK_FLAG' } as unknown as EffectAction;
  const plain = mkCtx({ signi: [SIGNI, null, null] }, {});
  eq(run(cancel, plain).ownerState.cancel_current_signi_attack, true, '対照＝通常はアタックが無効になる');
  const immune = { ...plain, ownerState: { ...plain.ownerState, own_effects_cannot_negate_signi_attack_this_turn: true } } as ExecCtx;
  eq(run(cancel, immune).ownerState.cancel_current_signi_attack, undefined,
     '🔴免疫があると自分の効果ではアタックが無効にならない');
  // 守備用途（`SET_CANCEL_OPP_ATTACK_FLAG`）にも同じ免疫が掛かる（原文は主語を「シグニのアタック」としか言わない）。
  const cancelOpp = { type: 'STUB', id: 'SET_CANCEL_OPP_ATTACK_FLAG' } as unknown as EffectAction;
  eq(run(cancelOpp, plain).otherState.cancel_current_signi_attack, true, '対照＝通常は相手のアタックも無効にできる');
  eq(run(cancelOpp, immune).otherState.cancel_current_signi_attack, undefined, '免疫中は相手のアタックも無効にできない');
  // ⚠**ルリグのアタック無効化は通す**（原文は「シグニのアタック」）。
  const oppLrig = findCard(c => c.Type === 'ルリグ' && c.Level === '3');
  const negLrig = { type: 'NEGATE_ATTACK', target: { type: 'LRIG', owner: 'opponent', count: 1 } } as unknown as EffectAction;
  const lrigCtx = { ...immune, otherState: { ...immune.otherState, field: { ...immune.otherState.field, lrig: [oppLrig] } } } as ExecCtx;
  ok(JSON.stringify(run(negLrig, lrigCtx).otherState).includes('negated_attacks'),
     '🔴ルリグのアタック無効化まで止めない（限定の落とし忘れガード）');
  // 免疫はターン境界で消える。
  eq(clearTurnEndScopedState(immune.ownerState as PlayerState).own_effects_cannot_negate_signi_attack_this_turn,
     undefined, 'ターン終了で免疫が切れる');
  // live 表現＝defer は解体済み。
  const e3 = JSON.stringify(mergeManualEffects('WX24-P4-016', effectsMap.get('WX24-P4-016') ?? [])
    .find(e => e.effectId === 'WX24-P4-016-E3')!.action);
  ok(e3.includes('SELF_SIGNI_ATTACK_NEGATE_IMMUNITY'), 'WX24-P4-016-E3: 免疫を宣言する');
  ok(!e3.includes('DEFERRED_'), 'WX24-P4-016-E3: defer は残っていない');
});

test('§6.4 O-10（続き508）: 【コンバート《色》】がエナの追加色 funnel に載る（負方向＋対照の対）', () => {
  // 🔑旧 defer 理由「色照合が costs.ts に5箇所散っていて 1点 funnel が無い」は**古かった**＝
  //   追加色の funnel（`canAffordGrowCost` の `extraColorMap`）は既にあり、
  //   `FIELD_ENERGY_SIGNI_GAIN_COLOR` / `ALL_ZONE_BLACK` が同じ経路で動いている。
  const conv: [string, string, string][] = [
    ['WXEX1-54', 'WXEX1-54-E3', '青'],
    ['WXEX1-56', 'WXEX1-56-E2', '緑'],
    ['WXEX2-56', 'WXEX2-56-E3', '青'],
  ];
  for (const [cardNum, effectId, color] of conv) {
    const act = mergeManualEffects(cardNum, effectsMap.get(cardNum) ?? [])
      .find(e => e.effectId === effectId)!.action as { type: string; id?: string; value?: unknown };
    eq(act.id, 'CONVERT_ENERGY_COLOR', `${effectId}: 宣言型 STUB`);
    eq(act.value, color, `${effectId}: 色は原文から読む（engine で再パースしない）`);
  }
  // 収集＝**エナゾーンだけ**を見る（場に出ていても意味は無い）。
  const st = mkState({ signi: ['WXEX1-54', null, null] });
  st.energy = ['WXEX1-56'];
  const map = collectConvertEnergyColors(st, effectsMap);
  eq(map.get('WXEX1-56'), '緑', 'エナゾーンのカードは追加色を宣言する');
  eq(map.get('WXEX1-54'), undefined, '⚠場に出ているだけのカードは対象外');
  // 支払い判定＝《緑》×1 は WXEX1-56（印刷は白/黒）では本来払えないが、追加色で通る。
  const cards = [...cardMap.values()] as CardData[];
  eq(canAffordGrowCost(['WXEX1-56'], cards, '《緑》×1', undefined, undefined, undefined, undefined, undefined, map),
     true, '【コンバート《緑》】で《緑》を払える');
  eq(canAffordGrowCost(['WXEX1-56'], cards, '《緑》×1'),
     false, '🔴負方向＝追加色を渡さない経路では払えない（渡し忘れの検知）');
  eq(canAffordGrowCost(['WXEX1-56'], cards, '《赤》×1', undefined, undefined, undefined, undefined, undefined, map),
     false, '対照＝宣言していない色は払えない');
});

test('§6.4 O-10（続き508）: 引用【自】のルリグ付与が実体化している（`WXDi-P00-026-E1`）', () => {
  // 原文「あなたの＜さんばか＞のルリグ１体を対象とし、ターン終了時まで、それは
  //      「【自】《ターン１回》：このルリグがアタックしたとき、このルリグをアップする。」を得る」。
  // 🔑**parser は既に正しい形を作れていた**＝live の `MANUAL` 刻印だけが古い defer を固定していた
  //   （`build:effects` は MANUAL を触らない＝§6.4 O-6 の第3の死角）。
  const eff = mergeManualEffects('WXDi-P00-026', effectsMap.get('WXDi-P00-026') ?? [])
    .find(e => e.effectId === 'WXDi-P00-026-E1')!;
  const act = eff.action as { type: string; target?: { type?: string }; duration?: string; effect?: CardEffect };
  eq(act.type, 'GRANT_EFFECT', 'ルリグへの能力付与');
  eq(act.target?.type, 'LRIG', '付与先はルリグ');
  eq(act.duration, 'UNTIL_END_OF_TURN', 'ターン終了時まで');
  eq(act.effect?.timing?.join(','), 'ON_ATTACK_LRIG', '内側は「このルリグがアタックしたとき」');
  eq(act.effect?.action.type, 'UP', '内側の帰結は「このルリグをアップする」');
  eq(act.effect?.usageLimit, 'once_per_turn', '⚠《ターン１回》を落とすと無限アタックになる');
  ok(!JSON.stringify(eff).includes('DEFERRED_'), 'defer は解体済み');
});

test('§6.4 O-10: 「代わりにダメージを受けず、ターン終了時まで、この能力を失う」は1回だけ（負方向＋対照の対）', () => {
  const cm = cardMap as Map<string, CardData>;
  // `WXK01-002-E1`＝「【常】：あなたの手札が０枚であるかぎり、あなたが対戦相手のルリグによって
  // ダメージを受ける場合、代わりにダメージを受けず、ターン終了時まで、この能力を失う。」
  const base = { ...mkState({ signi: [SIGNI, null, null] }), hand: [] as string[] };
  base.field.lrig = ['WXK01-002'];
  const attacker = mkState({});
  const first = resolveLrigDamageShield({ defender: base, attacker, cardMap: cm, effectsMap });
  eq(first.prevented, true, '手札0枚なら1回目は防ぐ');
  eq(first.loseEffectId, 'WXK01-002-E1', '「この能力を失う」宣言なので消費する effectId を返す');
  // 🔴負方向＝防いだ側が刻んだあとの2回目。`PREVENT_LRIG_DAMAGE` の既定は**回数無制限**なので、
  //    刻みを見ないと同じターンに何度でも防ぐ＝無限バリアになる。
  const after: PlayerState = { ...base, lost_ability_effect_ids_this_turn: [first.loseEffectId!] };
  eq(resolveLrigDamageShield({ defender: after, attacker, cardMap: cm, effectsMap }).prevented, false,
     '能力を失ったあとは防がない（同一ターンの2回目）');
  // 対照①＝ターン境界で戻る（原文「ターン終了時まで」）。
  eq(clearTurnEndScopedState(after).lost_ability_effect_ids_this_turn, undefined, 'ターン終了で失効が解ける');
  // 対照②＝activeCondition（手札0枚）を満たさなければそもそも防がない。
  eq(resolveLrigDamageShield({ defender: { ...base, hand: [SIGNI] }, attacker, cardMap: cm, effectsMap }).prevented,
     false, '手札があれば防がない');
  // 対照③＝`loseAbilityAfterUse` を持たない宣言（`WXK03-001-E1`）は刻まない＝回数無制限のまま。
  const unlimited = { ...mkState({ signi: [SIGNI, null, null] }), hand: [] as string[] };
  unlimited.field.lrig = ['WXK03-001'];
  const u = resolveLrigDamageShield({ defender: unlimited, attacker, cardMap: cm, effectsMap });
  eq(u.prevented, true, '無制限型も防ぐ');
  eq(u.loseEffectId, undefined, '⚠無制限型に消費を足さない（原文に「この能力を失う」が無い）');
});

test('§6.4 O-3: `WXK01-002-E2`（次のあなたのメインフェイズまで）の3機構と即時ドローの脱落', () => {
  const eff = effectsMap.get('WXK01-002')!.find(e => e.effectId === 'WXK01-002-E2')!;
  const ctx = mkCtx({}, {}, 'WXK01-002');
  const handBefore = (ctx.ownerState as PlayerState).hand.length;
  const r = finish(executeEffect(eff, ctx), ctx);
  const s = r.ownerState as PlayerState;
  // 🔴従来は受け皿 STUB（3機構が丸ごと no-op）＋**原文に無い即時ドロー1枚**（過剰実行）だった。
  eq(s.hand.length, handBefore, '即時ドローしない（置換の fromCount を実ドローに読まない）');
  eq(s.lrig_base_limit_override, 12, '基本リミットを12に置き換える');
  eq(JSON.stringify(s.draw_phase_replacement), JSON.stringify({ fromCount: 1, toCount: 2 }), 'ドローフェイズ置換を予約する');
  eq(applyLrigDrawPhaseReplacement(s, 1), 2, '1枚引く場合は2枚になる');
  eq(applyLrigDrawPhaseReplacement(s, 2), 2, '2枚引く場合は変えない（fromCount 一致のみ）');
  eq(hasActivePreventDamageWindow(s, 'LRIG'), true, 'ルリグダメージ無効が即座に有効');
  // 🔑期間は**ターン境界を跨ぐ**（相手のターンを丸ごと含む）＝turn-end で消してはいけない。
  const afterTurnEnd = clearTurnEndScopedState(s);
  eq(hasActivePreventDamageWindow(afterTurnEnd, 'LRIG'), true, 'ターン終了では消えない');
  eq(afterTurnEnd.lrig_base_limit_override, 12, '基本リミット上書きもターン終了では消えない');
  eq(afterTurnEnd.draw_phase_replacement?.toCount, 2, 'ドロー置換もターン終了では消えない');
  // 失効は「自分が次にメインフェイズへ入る」1点だけ。
  const atMain = clearMainPhaseScopedState(clearTurnEndScopedState(afterTurnEnd));
  eq(hasActivePreventDamageWindow(atMain, 'LRIG'), false, '次のメインフェイズで失効する');
  eq(atMain.lrig_base_limit_override, undefined, '基本リミット上書きも失効する');
  eq(atMain.draw_phase_replacement, undefined, 'ドロー置換も失効する');
});

// ── §6.4 O-3（続き493）: 「対戦相手の効果によって移動しない」の期間軸 ──
test('§6.4 O-3: 期間つき移動不可はターン数カウントダウンで失効する', () => {
  const runEff = (cardNum: string, effectId: string) => {
    const eff = effectsMap.get(cardNum)!.find(e => e.effectId === effectId)!;
    const ctx = mkCtx({ signi: [SIGNI, null, null] }, {}, cardNum);
    return finish(executeEffect(eff, ctx), ctx);
  };
  // 🔴従来は `prevent_opp_trash_from` を立てるだけで**失効地点が1つも無く永続していた**
  //   （`WXK10-083-E1` の原文は「このターンと次のターンの間」）。
  const r = runEff('WXK10-083', 'WXK10-083-E1');
  const s0 = r.ownerState as PlayerState;
  eq(JSON.stringify(s0.opp_move_immunity), JSON.stringify([{ zones: ['energy'], turnsRemaining: 2 }]), '2ターンぶん積む');
  eq(JSON.stringify(activeOppMoveImmunityZones(s0)), JSON.stringify(['energy']), '張ったターンから有効');
  const s1 = clearTurnEndScopedState(s0);
  eq(JSON.stringify(activeOppMoveImmunityZones(s1)), JSON.stringify(['energy']), '次のターンも有効');
  const s2 = clearTurnEndScopedState(s1);
  eq(s2.opp_move_immunity, undefined, '2つ目の境界で消える（永続しない）');
  eq(JSON.stringify(activeOppMoveImmunityZones(s2)), JSON.stringify([]), '失効後は保護しない');
});

test('§6.4 O-3: 期間つき移動不可が実際に相手効果のトラッシュを止める', () => withSavedCursor(() => {
  // ⚠**state だけの検査では「読まれているか」が分からない**＝実際の消費地点（`applyTrashEnergy` /
  //   `applyTrashHand`）を通す。`ExecCtx.otherProtectedZones` を渡さない経路でも効くこと（state 直読み）。
  const base = mkCtx({ signi: [SIGNI, null, null] }, {}, SIGNI);
  const guarded: ExecCtx = {
    ...base,
    otherState: { ...base.otherState, energy: [SIGNI, SIGNI], hand: [SIGNI], opp_move_immunity: [{ zones: ['energy'], turnsRemaining: 2 }] },
  };
  const trashEnergy = { type: 'TRASH', target: { type: 'ENERGY_CARD', owner: 'opponent', count: 1 } } as unknown as EffectAction;
  eq((run(trashEnergy, guarded).otherState as PlayerState).energy.length, 2, 'エナは保護され1枚も落ちない');
  // 対照＝予約が切れていれば通る（保護が「常に true」になっていないことの確認）。
  const expired: ExecCtx = { ...guarded, otherState: { ...guarded.otherState, opp_move_immunity: undefined } };
  eq((run(trashEnergy, expired).otherState as PlayerState).energy.length, 1, '対照: 予約なしなら落ちる');
  // 手札は宣言していないので保護されない（ゾーン限定を落としていないことの確認）。
  const trashHand = { type: 'TRASH', target: { type: 'HAND_CARD', owner: 'opponent', count: 1 } } as unknown as EffectAction;
  eq((run(trashHand, guarded).otherState as PlayerState).hand.length, 0, 'エナ限定の宣言で手札まで守らない');
}));

test('§6.4 O-3: `WXK10-004-E1`（場以外の領域）と `WXEX2-06-E3`（ダメージ＋移動不可の複文）', () => {
  const run1 = (cardNum: string, effectId: string) => {
    const eff = effectsMap.get(cardNum)!.find(e => e.effectId === effectId)!;
    const ctx = mkCtx({}, {}, cardNum);
    return finish(executeEffect(eff, ctx), ctx);
  };
  // 受け皿 STUB（恒久 no-op）だった `WXK10-004-E1`。⚠保護できるのは hand/energy だけ（既存と同じ近似）。
  const a = run1('WXK10-004', 'WXK10-004-E1').ownerState as PlayerState;
  eq(JSON.stringify(activeOppMoveImmunityZones(a).sort()), JSON.stringify(['energy', 'hand']), '手札とエナを保護');
  // 🔴`WXEX2-06-E3` は「ダメージを受けず」だけ拾われ**移動不可が丸ごと落ちていた**（片側採用）。
  const b = run1('WXEX2-06', 'WXEX2-06-E3').ownerState as PlayerState;
  eq(JSON.stringify(activeOppMoveImmunityZones(b).sort()), JSON.stringify(['energy', 'hand']), '移動不可の半分も効く');
  eq(hasActivePreventDamageWindow(clearTurnEndScopedState(b), 'LRIG'), true, 'ダメージ側は次の相手ターンに有効');
});

test('§6.4 O-3: 「次の対戦相手のターン終了時、〜」の本体を即時実行しない', () => {
  // 🔴`WXDi-P16-002-E1` は**使った瞬間に**1枚引き【エナチャージ１】していた（過剰実行）。
  //   `WXDi-P09-066-E1` は無関係な汎用 `STUB{LOOK_AND_REORDER}` に落ちて計器にも映らなかった。
  // 🆕続き497 で予約機構（`DELAY_TO_NEXT_OPP_TURN_END`）が入ったので、**本文が解ける側は予約へ格上げ**した。
  // 🆕続き498 で `WXDi-P09-066-E1` の照応（「**その**カードを手札に加える」）も解けた＝参照先を
  //   `facedown_lrig_zone_cards` に永続化してあるので、発火時に state から復元する
  //   （`RETURN_FACEDOWN_LRIG_ZONE_TO_HAND`）。⚠単独文として読むと `TRANSFER_TO_HAND{DECK_CARD}`
  //   ＝デッキから引く、へ化けるので**照応先が state にある形だけ**を格上げしている。
  for (const [cardNum, effectId] of [
    ['WXDi-P16-002', 'WXDi-P16-002-E1'],
    ['WXDi-P09-066', 'WXDi-P09-066-E1'],
  ] as const) {
    const eff = effectsMap.get(cardNum)!.find(e => e.effectId === effectId)!;
    const json = JSON.stringify(eff.action);
    ok(json.includes('DELAY_TO_NEXT_OPP_TURN_END'), `${cardNum}: 遅延本体が予約へ格上げされていない`);
    ok(!json.includes('DEFERRED_NEXT_OPP_TURN_END_BODY'), `${cardNum}: 受け皿 STUB が残っている`);
    const ctx = mkCtx({}, {}, cardNum);
    const handBefore = (ctx.ownerState as PlayerState).hand.length;
    const r = finish(executeEffect(eff, ctx), ctx);
    // 予約の本文（ドロー／手札戻し）はこの時点で走ってはいけない＝手札は増えない。
    ok((r.ownerState as PlayerState).hand.length <= handBefore, `${cardNum}: 即時に手札が増えている`);
  }
  // `WXDi-P09-066-E1` の照応先＝この方法で裏向きに置いたカードが state に残ること（予約の解決材料）。
  {
    const eff = effectsMap.get('WXDi-P09-066')!.find(e => e.effectId === 'WXDi-P09-066-E1')!;
    const json = JSON.stringify(eff.action);
    ok(json.includes('PLACE_FACEDOWN_LRIG_ZONE'), '裏向きで置く側が no-op STUB のまま');
    ok(json.includes('RETURN_FACEDOWN_LRIG_ZONE_TO_HAND'), '予約された本文が「そのカードを手札に加える」でない');
  }
  // 予約された本体は「引く＋エナチャージ」のセット（片方だけ落ちていないこと）
  const reserved = JSON.stringify(effectsMap.get('WXDi-P16-002')!.find(e => e.effectId === 'WXDi-P16-002-E1')!.action);
  ok(reserved.includes('"DRAW"') && reserved.includes('ENERGY_CHARGE_FROM_DECK'), '予約された本体が欠けている');
  // `WXDi-P16-002-E1` は【使用条件】ヘッダが `GRANT_KEYWORD{keyword:"使用条件"}` に化けていた（続き490 と同じクラス）。
  const piece = effectsMap.get('WXDi-P16-002')!.find(e => e.effectId === 'WXDi-P16-002-E1')!;
  ok(!JSON.stringify(piece.action).includes('使用条件'), 'ゴミ keyword 付与が消えている');
  eq(piece.condition?.type, 'AND', '使用条件は condition として載る');
});

test('§6.4 O-3: `WD20-006-E1` の次ターンスキップは「相手ターン かつ 非ベット」でだけ発火する', () => {
  const eff = effectsMap.get('WD20-006')!.find(e => e.effectId === 'WD20-006-E1')!;
  const mk = (isOwnerTurn: boolean, betting: boolean) => {
    const ctx = mkCtx({}, { signi: [SIGNI, SIGNI, null] }, 'WD20-006');
    return { ...ctx, isOwnerTurn, ownerState: { ...ctx.ownerState, is_betting_this_effect: betting || undefined } } as ExecCtx;
  };
  const oppTurnNoBet = mk(false, false);
  eq((finish(executeEffect(eff, oppTurnNoBet), oppTurnNoBet).ownerState as PlayerState).skip_next_turn, true,
    '相手ターン＋非ベット＝次の自分のターンをスキップ');
  // 🔴条件節を落として実装すると、以下の2つも常にスキップになる（過剰実行）。
  const oppTurnBet = mk(false, true);
  eq((finish(executeEffect(eff, oppTurnBet), oppTurnBet).ownerState as PlayerState).skip_next_turn, undefined,
    'ベットしていればスキップしない');
  const myTurnNoBet = mk(true, false);
  eq((finish(executeEffect(eff, myTurnNoBet), myTurnNoBet).ownerState as PlayerState).skip_next_turn, undefined,
    '自分のターンに撃った場合はスキップしない');
});

// ── ADD_EXTRA_ATTACK_PHASE（§6.4 O-3「追加のアタックフェイズを加える」）──
test('ADD_EXTRA_ATTACK_PHASE: キューに積むだけで onStart は即時実行しない', () => withSavedCursor(() => {
  const ctx = mkCtx({ signi: [SIGNI, null, null] }, {}, SIGNI);
  const down = { ...ctx.ownerState, field: { ...ctx.ownerState.field, signi_down: [true, true, true] as boolean[] } };
  const r = run(
    { type: 'ADD_EXTRA_ATTACK_PHASE', onStart: { type: 'UP', target: { type: 'SIGNI', owner: 'self', count: 'ALL' } } } as unknown as EffectAction,
    { ...ctx, ownerState: down } as ExecCtx);
  const queued = (r.ownerState as PlayerState).extra_attack_phases_this_turn ?? [];
  eq(queued.length, 1, '追加フェイズが1件キューに載る');
  eq(queued[0].sourceCardNum, SIGNI, '効果元が記録される');
  // 🔴従来は後続文が即時実行され、メインフェイズ中に全シグニがアップしていた（過剰実行）。
  eq(JSON.stringify((r.ownerState as PlayerState).field.signi_down), JSON.stringify([true, true, true]),
    'onStart はこの時点で実行してはいけない');
}));
test('resolveNextPhaseAfterAttack: ATTACK_LRIG の次を END ではなく ATTACK_ARTS に戻し、キューを1件消費する', () => withSavedCursor(() => {
  const base = mkState({});
  const noQueue = resolveNextPhaseAfterAttack('ATTACK_LRIG', base);
  eq(noQueue.next, 'END', '予約が無ければ従来どおり END');
  eq(noQueue.addedExtraPhase, false, '予約が無ければ追加しない');
  const onStart = { type: 'UP', target: { type: 'SIGNI', owner: 'self', count: 'ALL' } } as unknown as EffectAction;
  const queued: PlayerState = { ...base, extra_attack_phases_this_turn: [{ sourceCardNum: SIGNI, onStart }] };
  const first = resolveNextPhaseAfterAttack('ATTACK_LRIG', queued);
  eq(first.next, 'ATTACK_ARTS', '予約があればアタックフェイズへ戻る');
  eq(first.state.extra_attack_phases_this_turn, undefined, 'キューを消費する（無限ループにしない）');
  eq(first.state.pending_extra_attack_phase_start_effects?.length, 1, '開始時本文を pending へ移す');
  // 2周目は予約が空なので END へ抜ける＝ループしない
  eq(resolveNextPhaseAfterAttack('ATTACK_LRIG', first.state).next, 'END', '2周目は END へ抜ける');
  // ⚠ATTACK_SIGNI 等の途中ステップでは消費しない（END へ向かう遷移だけが対象）
  eq(resolveNextPhaseAfterAttack('ATTACK_SIGNI', queued).next, 'ATTACK_LRIG', '途中ステップでは消費しない');
  eq(resolveNextPhaseAfterAttack('ATTACK_SIGNI', queued).addedExtraPhase, false, '途中ステップでは追加しない');
  // 未消化のキューはターンを跨がない
  eq(clearTurnEndScopedState(queued).extra_attack_phases_this_turn, undefined, '未消化キューはターン終了で失効');
}));
test('RESOLVE_EXTRA_ATTACK_PHASE_START: pending を1件取り出して実行する', () => withSavedCursor(() => {
  const ctx = mkCtx({ signi: [SIGNI, null, null] }, {}, SIGNI);
  const onStart = { type: 'UP', target: { type: 'SIGNI', owner: 'self', count: 'ALL' } } as unknown as EffectAction;
  const pendingState: PlayerState = {
    ...ctx.ownerState,
    field: { ...ctx.ownerState.field, signi_down: [true, true, true] as boolean[] },
    pending_extra_attack_phase_start_effects: [{ sourceCardNum: SIGNI, action: onStart }],
  };
  const r = run({ type: 'STUB', id: 'RESOLVE_EXTRA_ATTACK_PHASE_START' } as EffectAction,
    { ...ctx, ownerState: pendingState } as ExecCtx);
  eq((r.ownerState as PlayerState).field.signi_down?.[0], false, '追加フェイズ開始時に onStart が走る');
  eq((r.ownerState as PlayerState).pending_extra_attack_phase_start_effects, undefined, '実行した予約は消える');
}));
