// ── §5d-0(i) 配線ギャップ 第18バッチ: 「Nまで」上限スロット ──
// live JSON を executor へ通し、0枚選択・外部からの上限超過入力・owner/excludeSelf を盤面で固定する。
test('§5d-0(i) WXDi-P10-008-E1: 手札のカードを3枚まで＝0枚可・4枚入力は3枚で打ち切り・スペルも選べる', () => withSavedCursor(() => {
  const effect = (effectsMap.get('WXDi-P10-008') ?? []).find(e => e.effectId === 'WXDi-P10-008-E1');
  ok(!!effect, 'WXDi-P10-008-E1: live effect exists');
  if (!effect) return;

  const s1 = fresh(), s2 = fresh(), s3 = fresh();
  const spell = findCard(c => c.Type === 'スペル');
  const base = mkCtx({ hand: 0, energy: 0 }, {});
  const ctx: ExecCtx = {
    ...base,
    ownerState: { ...base.ownerState, hand: [s1, s2, s3, spell], energy: [] },
  };
  const resumeCtx = (r: ExecResult): ExecCtx => ({
    ...ctx,
    ownerState: r.ownerState,
    otherState: r.otherState,
    logs: r.logs,
    lastProcessedCards: r.lastProcessedCards,
  });

  const zeroPending = runEffect(effect.action, ctx);
  ok(!zeroPending.done && zeroPending.pending.type === 'SELECT_TARGET', '0～3枚の選択待ちになる');
  if (zeroPending.done || zeroPending.pending.type !== 'SELECT_TARGET') return;
  eq(zeroPending.pending.count, 3, '選択上限は3枚');
  eq(zeroPending.pending.optional, true, '「まで」は0枚選択可');
  ok(zeroPending.pending.candidates.includes(spell), '「カード」なのでスペルも候補に含む');
  const zero = resumeSelectTarget([], zeroPending.pending, resumeCtx(zeroPending));
  ok(zero.done, '0枚選択でも効果解決が完了する');
  eq(zero.ownerState.hand.length, 4, '0枚選択なら手札は減らない');
  eq(zero.ownerState.energy.length, 0, '0枚選択ならエナは増えない');

  const overPending = runEffect(effect.action, ctx);
  ok(!overPending.done && overPending.pending.type === 'SELECT_TARGET', '上限超過入力の選択待ちになる');
  if (overPending.done || overPending.pending.type !== 'SELECT_TARGET') return;
  const over = resumeSelectTarget(overPending.pending.candidates.slice(0, 4), overPending.pending, resumeCtx(overPending));
  ok(over.done, '上限超過入力も安全に解決する');
  eq(over.ownerState.energy.length, 3, '4枚を渡しても3枚までしかエナへ置かない');
  eq(over.ownerState.hand.length, 1, '上限を超えた1枚は手札に残る');

  const spellPending = runEffect(effect.action, ctx);
  ok(!spellPending.done && spellPending.pending.type === 'SELECT_TARGET', 'スペル単独選択の待ちになる');
  if (spellPending.done || spellPending.pending.type !== 'SELECT_TARGET') return;
  const spellOnly = resumeSelectTarget([spell], spellPending.pending, resumeCtx(spellPending));
  ok(spellOnly.done && spellOnly.ownerState.energy.includes(spell), 'スペル1枚も実際にエナへ置ける');
}));

test('§5d-0(i) WXDi-P01-042-E2: 他の自シグニ2体まで＝0体可・自身/相手は対象外', () => withSavedCursor(() => {
  const effect = (effectsMap.get('WXDi-P01-042') ?? []).find(e => e.effectId === 'WXDi-P01-042-E2');
  ok(!!effect, 'WXDi-P01-042-E2: live effect exists');
  if (!effect) return;

  const source = 'WXDi-P01-042';
  const ally1 = fresh(), ally2 = fresh(), opponent = fresh();
  const ctx = mkCtx({ signi: [source, ally1, ally2] }, { signi: [opponent, null, null] }, source);
  const resumeCtx = (r: ExecResult): ExecCtx => ({
    ...ctx,
    ownerState: r.ownerState,
    otherState: r.otherState,
    logs: r.logs,
    lastProcessedCards: r.lastProcessedCards,
  });

  const zeroPending = runEffect(effect.action, ctx);
  ok(!zeroPending.done && zeroPending.pending.type === 'SELECT_TARGET', '0～2体の選択待ちになる');
  if (zeroPending.done || zeroPending.pending.type !== 'SELECT_TARGET') return;
  eq(zeroPending.pending.count, 2, '選択上限は2体');
  eq(zeroPending.pending.optional, true, '「まで」は0体選択可');
  eq(zeroPending.pending.candidates.length, 2, '候補は他の自シグニ2体だけ');
  ok(zeroPending.pending.candidates.includes(ally1) && zeroPending.pending.candidates.includes(ally2), '自分の他のシグニを候補にする');
  ok(!zeroPending.pending.candidates.includes(source), '効果元自身を候補にしない');
  ok(!zeroPending.pending.candidates.includes(opponent), '相手シグニを候補にしない');
  const zero = resumeSelectTarget([], zeroPending.pending, resumeCtx(zeroPending));
  ok(zero.done, '0体選択でも効果解決が完了する');
  eq(zero.ownerState.temp_power_mods?.length ?? 0, 0, '0体選択ならパワー修正なし');

  const applyPending = runEffect(effect.action, ctx);
  ok(!applyPending.done && applyPending.pending.type === 'SELECT_TARGET', '2体適用の選択待ちになる');
  if (applyPending.done || applyPending.pending.type !== 'SELECT_TARGET') return;
  const applied = resumeSelectTarget(applyPending.pending.candidates, applyPending.pending, resumeCtx(applyPending));
  ok(applied.done, '自分の他の2体への適用が完了する');
  const modified = applied.ownerState.temp_power_mods ?? [];
  eq(modified.length, 2, '自分の他の2体だけに修正を載せる');
  ok(modified.some(m => m.cardNum === ally1 && m.delta === 5000), '1体目に+5000');
  ok(modified.some(m => m.cardNum === ally2 && m.delta === 5000), '2体目に+5000');
  eq(applied.otherState.temp_power_mods?.length ?? 0, 0, '相手シグニには修正を載せない');
}));


// ── §5d-0(ii) 機構ギャップ: GRANT_KEYWORD の「N体まで」上限（続き377n）──
// `execGrantKeyword` は `selectOrInteract(cands, count, false, …)` と第3引数をハードコードしており、
// parser が `upToCount` を載せても**死にフラグ**で N体の強制選択のままだった。
test('続き377n engine: GRANT_KEYWORD の upToCount は上限（0体選択でも解決する）', () => withSavedCursor(() => {
  const a1 = fresh(), a2 = fresh();
  const ctx = mkCtx({ signi: [a1, a2, null] }, {});
  const act = { type: 'GRANT_KEYWORD', target: { type: 'SIGNI', owner: 'self', count: 2, upToCount: true }, keyword: 'ランサー', duration: 'UNTIL_END_OF_TURN' } as EffectAction;
  const r = runEffect(act, ctx);
  ok(!r.done && r.pending.type === 'SELECT_TARGET', 'upToCount は選択待ちになる');
  if (r.done || r.pending.type !== 'SELECT_TARGET') return;
  eq(r.pending.count, 2, '選択上限は2体');
  eq(r.pending.optional, true, '「まで」は0体選択可');
  const zero = resumeSelectTarget([], r.pending, { ...ctx, ownerState: r.ownerState, otherState: r.otherState, logs: r.logs });
  ok(zero.done, '0体選択でも効果解決が完了する');
  eq(Object.keys(zero.ownerState.keyword_grants ?? {}).length, 0, '0体選択なら誰にも付与しない');
  // 対照＝upToCount 無しは従来どおり「強制N体」（既存挙動を変えていないことの固定）
  const r2 = runEffect({ type: 'GRANT_KEYWORD', target: { type: 'SIGNI', owner: 'self', count: 2 }, keyword: 'ランサー', duration: 'UNTIL_END_OF_TURN' } as EffectAction, ctx);
  ok(!r2.done && r2.pending.type === 'SELECT_TARGET', '上限なしも選択待ち');
  if (r2.done || r2.pending.type !== 'SELECT_TARGET') return;
  eq(r2.pending.optional, false, 'upToCount 無しは強制選択のまま');
}));

// live JSON 側＝対象名詞句そのものから所有者・体数・上限・パワー条件を取る（`signiClauseTargetSpec`）。
test('続き377n: 「あなたの〈修飾〉シグニをN体まで対象とし」が owner/count/upToCount/filter へ載る', () => withSavedCursor(() => {
  const tgt = (card: string, effId: string): Record<string, unknown> => {
    const e = (effectsMap.get(card) ?? []).find(x => x.effectId === effId);
    ok(!!e, `${effId}: live effect exists`);
    return ((e?.action as unknown as { target?: Record<string, unknown> })?.target) ?? {};
  };
  // ⚠owner:'any' は engine で **tgtOwner='opponent'** に解決される＝「あなたの…シグニ」への付与が
  //   **対戦相手のシグニ**に付いていた（`execGrantKeyword` の `tgt.owner === 'any' ? 'opponent'`）。
  const p00 = tgt('WXDi-P00-004', 'WXDi-P00-004-E1');
  eq(p00.owner, 'self', 'WXDi-P00-004-E1: あなたのシグニ＝self（any だと相手へ付与されていた）');
  eq(p00.count, 2, 'WXDi-P00-004-E1: ２体');
  eq(p00.upToCount, true, 'WXDi-P00-004-E1: 「まで」');
  eq(JSON.stringify((p00.filter as Record<string, unknown>)?.powerRange), '{"min":15000}', 'WXDi-P00-004-E1: パワー15000以上');
  const p09 = tgt('WXDi-P09-053', 'WXDi-P09-053-E1');
  eq(p09.count, 2, 'WXDi-P09-053-E1: ２体');
  eq(p09.upToCount, true, 'WXDi-P09-053-E1: 「まで」');
  const d01 = tgt('WXDi-D01-014', 'WXDi-D01-014-E2');
  eq(d01.owner, 'self', 'WXDi-D01-014-E2: self');
  eq(JSON.stringify((d01.filter as Record<string, unknown>)?.powerRange), '{"min":15000}', 'WXDi-D01-014-E2: パワー15000以上');
}));

// ⚠トリップワイヤ①＝**「ターン終了時まで」で upToCount を立てない**。素の `t.includes('まで')` で判定すると
//   ほぼ全ての付与効果が「0体でもよい」に化ける（＝対象を取らずに解決できてしまう過小実行）。
// ⚠トリップワイヤ②＝**「＜A＞か＜B＞」の OR を1クラスへ潰さない**。`signiClause*Filter` は隣接する1つしか
//   返さないので、枝が既に決めた filter キーを上書きすると原文と逆の過小実行になる（A/B で6効果が退化した）。
test('続き377n トリップワイヤ: 「ターン終了時まで」で upToCount を立てず、クラスORも潰さない', () => withSavedCursor(() => {
  const act = (card: string, effId: string): string => {
    const e = (effectsMap.get(card) ?? []).find(x => x.effectId === effId);
    ok(!!e, `${effId}: live effect exists`);
    return JSON.stringify(e?.action ?? {});
  };
  for (const [card, effId] of [
    ['WXDi-P06-027', 'WXDi-P06-027-E2'], ['WXDi-P02-063', 'WXDi-P02-063-E1'], ['WX13-045', 'WX13-045-E1'],
  ] as [string, string][]) {
    eq(act(card, effId).includes('"upToCount":true'), false, `${effId}: 「N体」指定が無いので upToCount は立てない`);
  }
  for (const [card, effId, want] of [
    ['WX02-055', 'WX02-055-E1', '["鉱石","宝石","ウェポン"]'],
    ['WX05-041', 'WX05-041-E1', '["空獣","地獣"]'],
    ['WX19-070', 'WX19-070-E1', '["空獣","地獣"]'],
    ['WXEX2-43', 'WXEX2-43-E1', '["空獣","地獣"]'],
  ] as [string, string, string][]) {
    eq(act(card, effId).includes(`"story":${want}`), true, `${effId}: クラスORを保つ`);
  }
  // ⚠トリップワイヤ③＝**対象句と枝の所有者が食い違うときは体数を広げない**＝
  //   `WXK05-052-E1` は条件節の【シード】をキーワードと誤読した構造混線（§5d-0(iii) 在庫）で、
  //   体数だけ2体へ広げると**誤りを2体ぶんに増幅**する。
  eq(act('WXK05-052', 'WXK05-052-E1').includes('"count":2'), false,
    'WXK05-052-E1: 所有者が食い違う（対象は相手・枝は自分）ので体数を広げない');
}));


// ── §5d-0(ii) 機構ギャップ: `classMatchesDiscardSigni` が REVEAL_AND_PICK 経路で解決されていなかった（続き377n）──
// 語彙は型にも engine（`resolveDiscardLevelFilter`）にもあったが、解決していたのは SEARCH と ADD_TO_FIELD だけで、
// `execRevealAndPick` は素の `resolveDynamicFilter` しか通さず**キーを黙って無視**していた（＝公開札から何でも拾えた）。
test('続き377n: WXK10-029-E2 はコストで捨てたシグニと共通クラスの札だけ拾える', () => withSavedCursor(() => {
  const effect = (effectsMap.get('WXK10-029') ?? []).find(e => e.effectId === 'WXK10-029-E2');
  ok(!!effect, 'WXK10-029-E2: live effect exists');
  if (!effect) return;
  eq(JSON.stringify(effect?.action ?? {}).includes('"classMatchesDiscardSigni":true'), true, 'filter に載っている');

  // 捨てたシグニのクラスを持つ札／持たない札を1枚ずつデッキトップへ置く。
  const classOf = (n: string) => (cardMap.get(n)?.CardClass ?? '');
  const discarded = findCard(c => isSigni(c) && (c.CardClass ?? '').includes('精像'));
  const same = findCard(c => isSigni(c) && c.CardNum !== discarded && (c.CardClass ?? '').includes('精像'));
  const diff = findCard(c => isSigni(c) && !(c.CardClass ?? '').includes('精像') && (c.CardClass ?? '') !== '');
  const filler = fresh();
  const base = mkCtx({ trash: 0 }, {});
  const ctx: ExecCtx = {
    ...base,
    ownerState: { ...base.ownerState, deck: [same, diff, filler, ...base.ownerState.deck], last_discarded_signi_class: classOf(discarded) },
  };
  const r = runEffect(effect.action, ctx);
  ok(!r.done && r.pending.type === 'SEARCH', '公開3枚から選択待ちになる');
  if (r.done || r.pending.type !== 'SEARCH') return;
  ok(r.pending.visibleCards.includes(same), '共通クラスの札は候補');
  ok(!r.pending.visibleCards.includes(diff), '別クラスの札は候補外（従来は何でも拾えた）');

  // 対照＝捨てクラスが記録されていない場合は絞り込まない（参照不能時のフォールバックは従来どおり）。
  const ctx2: ExecCtx = { ...base, ownerState: { ...base.ownerState, deck: [same, diff, filler, ...base.ownerState.deck] } };
  const r2 = runEffect(effect.action, ctx2);
  ok(!r2.done && r2.pending.type === 'SEARCH', '記録なしでも選択待ち');
  if (r2.done || r2.pending.type !== 'SEARCH') return;
  ok(r2.pending.visibleCards.includes(diff), '記録が無ければクラス制限なし（無言 no-op にしない）');
}));


// ── §5d-0(ii) 機構ギャップ: ATTACH_CHARM の複数ペア（続き377n）──
// `execAttachCharm` は `charmSrc.deck.slice(0, 1)` と `charmCands[0] × toCands[0]` で**1組しか処理しない**ため、
// 「カードN枚まで × シグニN体まで」が常に1組の過小実行だった。ペア数＝min(候補, 候補, charm.count, to.count)。
test('続き377n engine: ATTACH_CHARM は N枚×N体をペアで付与する（デッキ上）', () => withSavedCursor(() => {
  const effect = (effectsMap.get('WXK07-070') ?? []).find(e => e.effectId === 'WXK07-070-E1');
  ok(!!effect, 'WXK07-070-E1: live effect exists');
  if (!effect) return;
  const a1 = fresh(), a2 = fresh(), a3 = fresh();
  const d1 = fresh(), d2 = fresh();
  const base = mkCtx({ signi: [a1, a2, a3] }, {});
  const ctx: ExecCtx = { ...base, ownerState: { ...base.ownerState, deck: [d1, d2, ...base.ownerState.deck] } };
  const r = runEffect(effect.action, ctx);
  ok(r.done, 'デッキ上からの付与は選択を挟まず解決する');
  const charms = r.ownerState.field.signi_charms ?? [];
  eq(charms.filter(Boolean).length, 2, '2組つく（従来は1組だけだった）');
  eq(charms[0], d1, '1体目にはデッキ1枚目');
  eq(charms[1], d2, '2体目にはデッキ2枚目');
  eq(r.ownerState.deck[0], base.ownerState.deck[0], 'デッキからは2枚だけ減る');
}));

