  ok(paidCharm.my.trash.includes(SIGNI), '外した【チャーム】はトラッシュへ');
  eq(payTrashActivateCost(charmEff, base, mkState({}), { energy: new Set(), handDiscard: new Set(), exceed: new Set() }, cardMap), null,
     '【チャーム】がなければ支払わない');
