// ══════════════════════════════════════════════════════════════════════════════
// §6.4 O-20: 実行時に「カード全文」を regex で読む層（別能力の文で意味が決まる）
// 🔴**この層の事故は golden も census も緑のまま素通りする**（続き459 の LRIG_GROW_RESTRICT／
//   続き463 の inferTriggerScope はどちらも全ゲート緑だった）＝計器に映らないので、
//   ここで「ブロック限定読みが効いていること」を明示的に固定する。
// ══════════════════════════════════════════════════════════════════════════════
test('§6.4 O-20: 能力ブロック解決が根拠カードで効いている（全文なら別能力の文を拾う）', () => {
  const blk = (num: string, effId: string): string => abilityBlockTextOf(cardMap.get(num), effId);
  const full = (num: string): string =>
    (cardMap.get(num)?.EffectText ?? '') + ' ' + (cardMap.get(num)?.BurstText ?? '');

  // ① 奇偶2能力の同居（対象が反転する）
  ok(/レベルが奇数の対戦相手/.test(blk('WXK10-084', 'WXK10-084-E2')),
    '🔴WXK10-084-E2 のブロックは「奇数の対戦相手」を対象にする');
  eq(full('WXK10-084').match(/レベルが(奇数|偶数)の対戦相手/)?.[1], '偶数',
    '全文だと先頭 E1 の「偶数」に一致する＝ブロックを読まないと対象が反転する');

  // ② 保護ゾーン（E2 の「手札」を拾って過剰保護）
  const tmb = blk('WXK10-083', 'WXK10-083-E1');
  ok(tmb.includes('エナゾーン') && !tmb.includes('手札'),
    '🔴WXK10-083-E1 はエナ限定＝手札を含まない');
  ok(full('WXK10-083').includes('手札'), '全文には別能力の「手札」がある');

  // ③ ドロー枚数（E2 の「２枚引く」を拾って余分な2ドロー）
  ok(!/カードを[０-９\d]+枚引く/.test(blk('WXDi-P10-006', 'WXDi-P10-006-E3')),
    '🔴WXDi-P10-006-E3 のブロックに「N枚引く」は無い');
  ok(/カードを２枚引く/.test(full('WXDi-P10-006')), '全文には別能力の「２枚引く」がある');

  // ④ 付与対象のクラス（E2 の＜紅蓮＞で無指定の対象が限定される）
  ok(!blk('WXK04-002', 'WXK04-002-E3').includes('紅蓮'),
    '🔴WXK04-002-E3 のブロックにクラス限定は無い');
  ok(full('WXK04-002').includes('紅蓮'), '全文には別能力の＜紅蓮＞がある');

  // ⑤ 配置替えの側（別能力の「対戦相手のシグニ」で自シグニ対象が相手化）
  ok(!blk('WXDi-P00-015', 'WXDi-P00-015-E1').includes('対戦相手'),
    '🔴WXDi-P00-015-E1 のブロックに「対戦相手」は無い＝自分のシグニを配置替えする');
  ok(full('WXDi-P00-015').includes('対戦相手のシグニ'), '全文には別能力の「対戦相手のシグニ」がある');
});

test('§6.4 O-20 トリップワイヤ: 変換済みサイトが「カード全文」読みへ戻っていない', () => {
  // 各ファイルで sourceAbilityText を使っている箇所数を凍結する。
  // 減ったら「全文読みへ差し戻された」＝無言で別能力の文に従い始めるので赤にする。
  const FROZEN: Record<string, number> = {
    'src/engine/execStubPart1.ts': 7,
    // 9 → 8（2026-08-15 §6.4 O-22(a)）＝`CHARM_CONDITIONAL_POWER` ハンドラを削除したぶん。
    // 差し戻しではなく**サイトごと消えた**（帰結は parser の「代わりに」置換 fixup が構造で持つ）。
    // 8 → 7（2026-08-15 §6.4 O-3 続き493）＝`PREVENT_ZONE_MOVE_BY_OPP` の実行時ゾーン判定を廃止。
    // 期間つきは `ZONE_MOVE_IMMUNITY`（zones を構造で持つ）へ、【常】は `collectProtectedZones` 側の
    // ブロック読みへ寄せたので、**実行時に原文を読む必要がなくなった**（差し戻しではない）。
    'src/engine/execStubPart2.ts': 7,
    'src/engine/execStubPart3.ts': 3,
    'src/engine/effectExecutor.ts': 2,
  };
  for (const [f, n] of Object.entries(FROZEN)) {
    const src = fs.readFileSync(join(root, f), 'utf8');
    const hits = (src.match(/sourceAbilityText\(/g) ?? []).length;
    eq(hits, n, `${f} の sourceAbilityText 使用箇所（増＝新規変換なら期待値を更新／減＝全文読みへの差し戻し）`);
  }
  // ctx を持たない走査側（CONTINUOUS 収集）も同様にブロックを読む
  const eng = fs.readFileSync(join(root, 'src/engine/effectEngine.ts'), 'utf8');
  ok(/PREVENT_ZONE_MOVE_BY_OPP'\) \{[\s\S]{0,400}?abilityBlockTextOf\(card, eff\.effectId\)/.test(eng),
    'collectProtectedZones は効果ごとのブロックを読む（execStubPart2 側と二重配線なので必ず対で保つ）');
  // 実アプリと同じく解決中の effectId が ctx に載ることを固定する（載らないとブロックを特定できず全文へ落ちる）
  const exe = fs.readFileSync(join(root, 'src/engine/effectExecutor.ts'), 'utf8');
  ok(/ctx\.sourceEffectId \? ctx : \{ \.\.\.ctx, sourceEffectId: effect\.effectId \}/.test(exe),
    'executeEffect が sourceEffectId を補完する（O-20 の source 配線の入口）');
});


// ══════════════════════════════════════════════════════════════════════════════
// §6.4 O-21: 同じ STUB id を受けるハンドラの重複（dispatch は part1 → part2 → part3 の先着勝ち）
// 🔴**二番手は永久に呼ばれない**ので、(a)そこを直しても何も起きない (b)本物の実装がそこに居ると
//   先着の no-op に潰される。実際 `BET_CONDITION` は execStubPart3 に実装があるのに
//   execStubPart1 の3行 no-op が先着で潰していた（根拠＝`WDK01-010-E1`）。
// ══════════════════════════════════════════════════════════════════════════════
test('§6.4 O-21: 同じ STUB id の後発ハンドラが到達不能になっていない', () => {
  // 同じ id を受けるトップレベル分岐が複数あること自体は正当（「特定形を先に処理して素通り→一般形」）。
  // 🔴**駄目なのは先着が必ず return する形**＝後発は永久に呼ばれない。
  //   意図的な素通りは「条件に追加ガードがある（`&& targetsStored` 等）」か「ブロックが return で終わらない」。
  type Site = { at: string; alwaysReturns: boolean };
  const seen = new Map<string, Site[]>();
  for (const f of ['src/engine/execStubPart1.ts', 'src/engine/execStubPart2.ts', 'src/engine/execStubPart3.ts']) {
    const src = fs.readFileSync(join(root, f), 'utf8');
    const lines = src.split(/\r?\n/);
    for (let i = 0; i < lines.length; i++) {
      const ln = lines[i];
      if (!/^ {2}if \(.*stub\.id === '/.test(ln)) continue;
      const guarded = ln.includes('&&');
      let alwaysReturns: boolean;
      if (/\{\s*$/.test(ln)) {
        // 対応する閉じ波括弧まで降りて、ブロック末尾の実文が return かを見る
        let depth = 0, endLine = i;
        for (let j = i; j < lines.length; j++) {
          for (const ch of lines[j]) { if (ch === '{') depth++; else if (ch === '}') depth--; }
          if (depth === 0 && j > i) { endLine = j; break; }
        }
        const body = lines.slice(i + 1, endLine).map(l => l.trim()).filter(l => l && !l.startsWith('//'));
        alwaysReturns = /^\}?\s*return\b/.test(body[body.length - 1] ?? '');
      } else {
        alwaysReturns = /\)\s*return\b/.test(ln);
      }
      if (guarded) alwaysReturns = false; // 追加ガードつき＝素通りしうる
      for (const m of ln.matchAll(/stub\.id === '([A-Z_0-9]+)'/g)) {
        if (!seen.has(m[1])) seen.set(m[1], []);
        seen.get(m[1])!.push({ at: `${f.split('/').pop()}:${i + 1}`, alwaysReturns });
      }
    }
  }
  const dead = [...seen]
    .filter(([, sites]) => sites.length > 1 && sites[0].alwaysReturns)
    .map(([id, sites]) => `${id}(先着 ${sites[0].at} が必ず return → ${sites.slice(1).map(x => x.at).join(',')} が到達不能)`);
  eq(dead.join(' '), '',
    `後発ハンドラが到達不能になっている（先着を素通りさせるか、後発を消すこと）: ${dead.join(' ')}`);
});

test('§6.4 O-21: BET_CONDITION がベット時に追加対象を出す（先着 no-op に潰されていない）', () => {
  // `WDK01-010`「…シグニを３枚まで対象とし、それらを手札に加える。あなたがベットしていた場合、
  //  ３枚の代わりに４枚まで対象とし、それらを手札に加える。」＝差分1枚を追加で選ばせる。
  const src = 'WDK01-010';
  const signiInTrash = [...cardMap.values()].filter(c => c.Type === 'シグニ').slice(0, 3).map(c => c.CardNum);
  const mk = (betting: boolean): ExecCtx => {
    const c = mkCtx({}, {});
    c.sourceCardNum = src;
    c.sourceEffectId = 'WDK01-010-E1';
    c.ownerState = { ...c.ownerState, trash: [...signiInTrash] };
    (c.ownerState as unknown as { is_betting_this_effect?: boolean }).is_betting_this_effect = betting;
    return c;
  };
  const act = { type: 'STUB', id: 'BET_CONDITION' } as unknown as EffectAction;
  const bet = executeEffect({ effectId: 'WDK01-010-E1', effectType: 'ACTIVATED', action: act, duration: 'INSTANT', mandatory: true } as CardEffect, mk(true));
  eq((bet as { pending?: { count?: number } }).pending?.count, 1,
    '🔴ベット時は「４枚まで」との差分1枚をトラッシュから追加で選べる（先着 no-op に潰されていた）');
  const noBet = executeEffect({ effectId: 'WDK01-010-E1', effectType: 'ACTIVATED', action: act, duration: 'INSTANT', mandatory: true } as CardEffect, mk(false));
  ok((noBet as { pending?: unknown }).pending === undefined, '非ベット時は追加対象を出さない');
  ok((noBet as { logs: string[] }).logs.some(l => l.includes('ベットなし')), '非ベット時は素通りログ');
});

// ─── §6.4 O-22(a) / O-23 / O-24（2026-08-15 続き484）────────────────────────
// いずれも「STUB のハンドラが原文と別のものを実行していた」型。live JSON の形と engine の主語を固定する。

test('§6.4 O-22(a): 「代わりに－N」の置換が加算モデルで live に載っている（恒久 no-op に戻さない）', () => {
  // ⚠加算モデル＝base の POWER_MODIFY はそのまま、条件成立時に**差分だけ**を
  //   `POWER_MODIFY{targetsLastProcessed}` で同じ対象へ足す。else 置換にすると
  //   `LAST_PROCESSED_MATCHES` が対象選択**前**に評価されて常に偽＝恒久 no-op になる。
  const stepsOf = (cardNum: string, effectId: string) => {
    const eff = (effectsMap.get(cardNum) ?? []).find(e => e.effectId === effectId);
    ok(!!eff, `${effectId} が live に存在する`);
    const a = eff!.action as unknown as { type: string; steps?: Array<Record<string, unknown>> };
    eq(a.type, 'SEQUENCE', `${effectId} は SEQUENCE`);
    return a.steps ?? [];
  };
  // ① 主語「あなたのシグニに」＝自分の場のチャーム総数（CHARM_COUNT）
  const s1 = stepsOf('WX07-031', 'WX07-031-BURST');
  eq((s1[0] as { delta?: number }).delta, -10000, 'base は原文どおり －10000');
  const c1 = s1[1] as { type: string; condition?: { type?: string; owner?: string; value?: number }; then?: { delta?: number; targetsLastProcessed?: boolean } };
  eq(c1.type, 'CONDITIONAL', '🔴置換側は STUB ではなく CONDITIONAL（STUB は効果元＝場に無い LB へ delta を当てて恒久 no-op だった）');
  eq(c1.condition?.type, 'CHARM_COUNT', '「あなたのシグニに」＝自分の場のチャーム枚数で判定');
  eq(c1.condition?.owner, 'self', '主語はあなた');
  eq(c1.then?.delta, -10000, '合計 －20000 になるよう差分 －10000 を足す');
  eq(c1.then?.targetsLastProcessed, true, '「それ」＝直前 POWER_MODIFY で選んだ同じ相手シグニ');
  // ② 主語「それに」＝直前対象そのもののゾーン（LAST_PROCESSED_MATCHES{hasCharm}）
  const s2 = stepsOf('WX08-032', 'WX08-032-BURST');
  eq((s2[0] as { delta?: number }).delta, -8000, 'base は原文どおり －8000');
  const c2 = s2[1] as { type: string; condition?: { type?: string; filter?: { hasCharm?: boolean } }; then?: { delta?: number; targetsLastProcessed?: boolean } };
  eq(c2.condition?.type, 'LAST_PROCESSED_MATCHES', '「それに」＝対象自身のゾーン状態');
  eq(c2.condition?.filter?.hasCharm, true, 'hasCharm で判定');
  eq(c2.then?.delta, -7000, '合計 －15000 になるよう差分 －7000 を足す');
  eq(c2.then?.targetsLastProcessed, true, '同じ対象へ足す');
  // ③ 削除したハンドラ／STUB id が復活していない
  const part2 = fs.readFileSync(join(root, 'src/engine/execStubPart2.ts'), 'utf8');
  ok(!/stub\.id === 'CHARM_CONDITIONAL_POWER'/.test(part2),
    '🔴CHARM_CONDITIONAL_POWER のハンドラは削除済み（効果元へ delta を当てる誤実装）');
  // ④ 倍率形（WX25-P2-103②）＝§6.4 O-10（続き507）で defer 解体。倍率は**原文から読む**。
  const p2103 = (effectsMap.get('WX25-P2-103') ?? []).find(e => e.effectId === 'WX25-P2-103-E1');
  const txt = JSON.stringify(p2103?.action ?? {});
  ok(txt.includes('"id":"CHARM_POWER_MINUS_MULTIPLIER"'),
    '「代わりに３倍－される」は倍率つき機構（power_minus_multipliers_this_turn）で実装済み');
  ok(txt.includes('"value":3'), '倍率は焼き込まず原文の「３倍」から読む');
  ok(!txt.includes('DEFERRED_'), 'defer 宣言は残っていない');
  ok(!txt.includes('CHARM_CONDITIONAL_POWER'), '旧 id は残っていない');
  // ⑤ 2倍軸（選択肢①）と倍率軸（選択肢②）は**別の state** に載る＝二重掛けしない。
  const partsMul = fs.readFileSync(join(root, 'src/engine/effectEngine.ts'), 'utf8');
  ok(/Math\.max\([\s\S]{0,400}power_minus_multipliers_this_turn/.test(partsMul),
    '倍率は 2倍軸と Math.max で合成する（掛け算で重ねない）');
});

test('§6.4 O-23: 「アタックしたそのシグニのレベル」は triggeringCardNum で解く（効果元で代用しない）', () => withSavedCursor(() => {
  // `WXK10-084`（Level 3）は `triggerScope:'any_ally'`＝**別の味方がアタックしても発火する**ので、
  // 効果元の Level を使うと倍率が常に 3 に固定される（＝アタッカーが L1 でも L4 でも －3000）。
  const src = 'WXK10-084';
  eq(cardMap.get(src)?.Level, '3', '前提：効果元は Level 3（旧実装はこの値に固定されていた）');
  const modOf = (effectId: string, attacker: string, oppTarget: string) => {
    const base = mkCtx({ signi: [src, attacker, null] }, { signi: [oppTarget, null, null] }, src);
    const ctx = { ...base, sourceCardNum: src, sourceEffectId: effectId, triggeringCardNum: attacker } as ExecCtx;
    const r = run({ type: 'STUB', id: 'POWER_MOD_BY_ATTACKER_LEVEL' } as unknown as EffectAction, ctx);
    return (r.otherState.temp_power_mods ?? []).find(m => m.cardNum === oppTarget)?.delta;
  };
  // E1＝奇数アタッカー→偶数の相手シグニが対象。L1 のアタッカーなら 1×－1000。
  eq(modOf('WXK10-084-E1', SIGNI_L1, SIGNI_L2), -1000,
    '🔴アタッカー L1 → －1000（効果元 L3 を使うと －3000 になる）');
  // E2＝偶数アタッカー→奇数の相手シグニが対象。L4 のアタッカーなら 4×－1000。
  eq(modOf('WXK10-084-E2', SIGNI_L4, SIGNI_L3), -4000,
    '🔴アタッカー L4 → －4000（効果元 L3 を使うと －3000 になる）');
}));

test('§6.4 O-22(b): WX12-037-E2 は「両者5枚ミル→《メツム》があれば繰り返してもよい」', () => withSavedCursor(() => {
  // ⚠旧 `STUB{CONDITIONAL_PER_TRASH}`（トラッシュ枚数条件でドロー）は**別物**で、この効果には
  //   条件句が無いため恒久 no-op だった。ミルごと1 STUB へ畳み込むのは、条件が見るのが
  //   「この方法で」置いた**両プレイヤー分**だから（SEQUENCE は step ごとに lastProcessedCards を上書きする）。
  const eff = (effectsMap.get('WX12-037') ?? []).find(e => e.effectId === 'WX12-037-E2');
  const a = eff!.action as unknown as { type: string; id?: string; millEachRepeatOnName?: { count: number; name: string } };
  eq(a.type, 'STUB'); eq(a.id, 'MILL_EACH_REPEAT_ON_NAME');
  eq(a.millEachRepeatOnName?.count, 5, '各プレイヤー5枚');
  eq(a.millEachRepeatOnName?.name, 'メツム', '名前は《メツム》（この効果元《メツミ》ではない）');
  const metsumu = [...cardMap.values()].find(c => (c.CardName ?? '').includes('メツム'));
  ok(!!metsumu, '前提：カード名に「メツム」を含むカードが実在する');
  const plain = [...cardMap.values()].filter(c => c.Type === 'シグニ' && !(c.CardName ?? '').includes('メツム')).map(c => c.CardNum);
  const runMill = (myTop: string[]) => {
    const ctx = mkCtx({ deckTop: myTop }, { deckTop: plain.slice(0, 6) }, 'WX12-037');
    return run(a as unknown as EffectAction, ctx);
  };
  // ① ヒットなし＝繰り返しを問わずに終わる（10枚だけトラッシュへ）
  const miss = runMill(plain.slice(6, 12));
  ok(miss.done, 'ヒットなしなら対話は出ない');
  eq(miss.ownerState.trash.length - 3, 5, '自分のデッキから5枚がトラッシュへ（初期trash 3枚ぶんを差し引く）');
  eq(miss.otherState.trash.length - 3, 5, '相手のデッキからも5枚');
  ok(miss.logs.some(l => l.includes('繰り返さない')), '繰り返さないログ');
  // ② ヒットあり＝「繰り返す／繰り返さない」を問う（autopilot は先頭＝繰り返すを選ぶので raw で見る）
  const hitCtx = mkCtx({ deckTop: [metsumu!.CardNum, ...plain.slice(12, 16)] }, { deckTop: plain.slice(16, 22) }, 'WX12-037');
  const raw = executeEffect({ effectId: 'WX12-037-E2', effectType: 'AUTO', action: a as unknown as EffectAction, duration: 'INSTANT', mandatory: true } as CardEffect, hitCtx);
  const pend = (raw as { pending?: { type?: string; options?: Array<{ id?: string; action?: { id?: string } }> } }).pending;
  eq(pend?.type, 'CHOOSE', '🔴《メツム》が落ちたら繰り返しを問う（旧実装は無言 no-op）');
  eq(pend?.options?.[0]?.action?.id, 'MILL_EACH_REPEAT_ON_NAME', '「繰り返す」は同じ STUB の再入＝任意回ループできる');
  eq(pend?.options?.[1]?.id, 'stop', '辞退の枝がある（原文は「繰り返しても**よい**」）');
}));

