// ── §5d-0 (i) 2026-08-18：「それぞれ〜異なる」の種別を手書き表に書かせないトリップワイヤ ──
// 旧実装は `DISTINCT_BATCH5C`（effectId → 'level'|'name'|'class'）の**値を手で書いて**おり、
// **7効果が原文と食い違ったまま全ゲート緑**だった（構造は正しく、制約の「軸」だけ別物＝
// `distinct:'name'` は同名を弾くだけでレベルが揃った組を通す）。値は原文から導く実装へ移したので、
// ここで **表の値 == 原文から導いた値** を全件固定する＝新しい効果を表へ足すときに軸を間違えたら落ちる。
test('§5d-0(i) DISTINCT_BATCH5C: 「それぞれ〜異なる」の種別が全件で原文と一致する', () => {
  const mismatches: string[] = [];
  const noPhrase: string[] = [];
  for (const [effectId, declared] of Object.entries(DISTINCT_BATCH5C)) {
    // effectId → CardNum は「効果サフィックスを剥がす」ではなく **cardMap に実在する最長前方一致**で引く
    // （`WXDi-CP01-008-E3` のようにハイフンを含むカード番号があるため）。
    let cardNum: string | undefined;
    for (let i = effectId.length; i > 0; i--) {
      const cand = effectId.slice(0, i);
      if (cardMap.has(cand)) { cardNum = cand; break; }
    }
    const text = cardNum ? (cardMap.get(cardNum)?.EffectText ?? '') : '';
    const inferred = inferDistinctKind(text);
    if (!inferred) { noPhrase.push(`${effectId}(card=${cardNum ?? '?'})`); continue; }
    if (inferred !== declared) mismatches.push(`${effectId}: 表=${declared} 原文=${inferred}`);
  }
  eq(mismatches.length, 0, `表の種別が原文と食い違う: ${mismatches.join(' / ')}`);
  // 原文から一意に決まらない効果は「表の値がフォールバックとして効いている」ので、
  // **増えたら気づけるように件数を固定**する（0 が理想だが、引用能力など原文を持たない効果がありうる）。
  eq(noPhrase.length, 0, `原文から種別を導けない効果（表の値へフォールバック中）: ${noPhrase.join(', ')}`);
});

test('§5d-0(i) distinctConstraintOf: color だけ sharedColor へ落ちる', () => {
  eq(JSON.stringify(distinctConstraintOf('level')), '{"distinct":"level"}');
  eq(JSON.stringify(distinctConstraintOf('name')), '{"distinct":"name"}');
  eq(JSON.stringify(distinctConstraintOf('class')), '{"distinct":"class"}');
  // 「共通する色を持たない」は複数色カードがあるので集合の重なりで見る＝`distinct` では表せない
  eq(JSON.stringify(distinctConstraintOf('color')), '{"sharedColor":"none"}');
});

// live 側の実値も固定する（parser を直しても live へ届いていなければ意味がない＝続き377g の教訓）。
const distinctLiveCases = [
  { effectId: 'WX14-030-E1', want: 'level', why: 'それぞれレベルの異なる無色ではないシグニ４枚' },
  { effectId: 'WX17-025-E3', want: 'level', why: 'それぞれレベルの異なる＜怪異＞のシグニ４枚' },
  { effectId: 'WX19-080-E1', want: 'level', why: 'それぞれレベルの異なる＜微菌＞のシグニ３枚' },
  { effectId: 'WXDi-P07-090-E1', want: 'level', why: 'それぞれレベルの異なる＜天使＞のシグニ３枚' },
  { effectId: 'WXEX2-31-E3', want: 'level', why: 'それぞれレベルの異なる＜天使＞のシグニ４枚' },
  { effectId: 'WXDi-P00-023-E1', want: 'class', why: 'それぞれ異なるクラスを持つシグニ７枚' },
  { effectId: 'WXDi-CP01-008-E3', want: 'name', why: 'それぞれ名前の異なるカード３枚' },
] as const;
for (const spec of distinctLiveCases) {
  test(`§5d-0(i) live ${spec.effectId}: selectionConstraint が原文の軸（${spec.why}）`, () => {
    let cardNum: string | undefined;
    for (let i = spec.effectId.length; i > 0; i--) {
      const cand = spec.effectId.slice(0, i);
      if (effectsMap.has(cand)) { cardNum = cand; break; }
    }
    const eff = (effectsMap.get(cardNum ?? '') ?? []).find(e => e.effectId === spec.effectId);
    ok(!!eff, `${spec.effectId}: live 効果が存在`);
    if (!eff) return;
    const s = JSON.stringify(eff.action);
    ok(s.includes(`"distinct":"${spec.want}"`),
      `原文の軸は ${spec.want}（実際 ${s.match(/"selectionConstraint":\{[^}]*\}/)?.[0] ?? '(制約なし)'}）`);
  });
}

// ── §5d-0 (i) 2026-08-18：「傀儡状態であなたの場に出す」8効果を STEAL_OPP_TRASH_PUPPET へ ──
// 🔴従来は汎用「トラッシュから…場に出す」へ落ちて `ADD_TO_FIELD{TRASH_CARD, owner:'self'}`＝
//   **自分のトラッシュから自分のシグニを蘇生する完全な別物**（傀儡状態にもならない）だった。
//   `WXK10-091-E2` は「＜美巧＞**ではない**」を `story:'美巧'` と読んで**条件が反転**していた。
const puppetLiveCases = [
  { effectId: 'WDK17-001-E2', filter: null },
  { effectId: 'WDK17-012-E2', filter: null },
  { effectId: 'WDK17-013-E1', filter: '"level":{"max":3}' },
  { effectId: 'WDK17-017-E1', filter: '"level":1' },
  { effectId: 'WXEX2-23-E4', filter: null },
  { effectId: 'WXK09-034-E2', filter: null },
  { effectId: 'WXK09-096-E2', filter: null },
  { effectId: 'WXK10-091-E2', filter: '"cardClassExclude":"美巧"' },
] as const;
for (const spec of puppetLiveCases) {
  test(`§5d-0(i) live ${spec.effectId}: 相手トラッシュ→傀儡配置の STUB へ載っている`, () => {
    let cardNum: string | undefined;
    for (let i = spec.effectId.length; i > 0; i--) {
      const cand = spec.effectId.slice(0, i);
      if (effectsMap.has(cand)) { cardNum = cand; break; }
    }
    const eff = (effectsMap.get(cardNum ?? '') ?? []).find(e => e.effectId === spec.effectId);
    ok(!!eff, `${spec.effectId}: live 効果が存在`);
    if (!eff) return;
    const s = JSON.stringify(eff.action);
    ok(s.includes('"STEAL_OPP_TRASH_PUPPET"'), `STEAL_OPP_TRASH_PUPPET へ載る（実際 ${s.slice(0, 140)}）`);
    // 🔴自分のトラッシュから蘇生する旧形へ戻っていないこと（この2語が同居したら退化）
    ok(!/"ADD_TO_FIELD"[\s\S]*"TRASH_CARD"/.test(s), '🔴自分トラッシュからの ADD_TO_FIELD へ戻っていない');
    if (spec.filter) ok(s.includes(spec.filter), `原文の絞り込み ${spec.filter} が載る（実際 ${s.slice(0, 200)}）`);
  });
}
test('§5d-0(i) WXEX2-23-E4: 「それの【出】能力は発動しない」が STUB の配置アンカーへ畳み込まれている', () => {
  const eff = (effectsMap.get('WXEX2-23') ?? []).find(e => e.effectId === 'WXEX2-23-E4');
  ok(!!eff, 'live 効果が存在');
  const s = JSON.stringify(eff!.action);
  ok(s.includes('"suppressOnPlay":true'), 'suppressOnPlay が残る（落ちると奪ったシグニの【出】が発動する）');
  ok(!s.includes('BLOCK_ACTION'), '未消費の BLOCK_ACTION が残っていない');
});
test('§5d-0(i) engine: STEAL_OPP_TRASH_PUPPET の puppetParams.filter が候補を絞る', () => {
  const lv1 = findCard(c => isSigni(c) && c.Level === '1');
  const lv4 = findCard(c => isSigni(c) && c.Level === '4');
  const base = mkCtx({ signi: [null, null, null] }, {});
  const ctx: ExecCtx = { ...base, otherState: { ...base.otherState, trash: [lv1, lv4] } };
  const stub = { type: 'STUB', id: 'STEAL_OPP_TRASH_PUPPET',
    puppetParams: { count: 1, filter: { cardType: 'シグニ', level: { max: 3 } } } } as unknown as EffectAction;
  const r = executeEffect({ effectId: 't', effectType: 'AUTO', action: stub, duration: 'INSTANT', mandatory: true } as CardEffect, ctx);
  ok(!r.done && r.pending.type === 'SELECT_TARGET', '相手トラッシュ選択へ pause');
  if (r.done || r.pending.type !== 'SELECT_TARGET') return;
  eq(JSON.stringify(r.pending.candidates), JSON.stringify([lv1]), 'レベル3以下だけが候補（レベル4は候補外）');
});
test('§5d-0(i) engine: filter 無しなら従来どおり相手トラッシュのシグニ全部が候補', () => {
  const lv1 = findCard(c => isSigni(c) && c.Level === '1');
  const lv4 = findCard(c => isSigni(c) && c.Level === '4');
  const base = mkCtx({ signi: [null, null, null] }, {});
  const ctx: ExecCtx = { ...base, otherState: { ...base.otherState, trash: [lv1, lv4] } };
  const stub = { type: 'STUB', id: 'STEAL_OPP_TRASH_PUPPET', puppetParams: { count: 1 } } as unknown as EffectAction;
  const r = executeEffect({ effectId: 't', effectType: 'AUTO', action: stub, duration: 'INSTANT', mandatory: true } as CardEffect, ctx);
  ok(!r.done && r.pending.type === 'SELECT_TARGET', '相手トラッシュ選択へ pause');
  if (r.done || r.pending.type !== 'SELECT_TARGET') return;
  eq(r.pending.candidates.length, 2, '絞り込み無しは全シグニ候補（既存挙動を変えない）');
});
test('§5d-0(i) parser: 「傀儡状態の」連体形はトリガー文なので配置 STUB に化けない（WDK17-001-E1）', () => {
  const eff = (effectsMap.get('WDK17-001') ?? []).find(e => e.effectId === 'WDK17-001-E1');
  ok(!!eff, 'live 効果が存在');
  const s = JSON.stringify(eff!.action);
  ok(!s.includes('STEAL_OPP_TRASH_PUPPET'), '「あなたの傀儡状態のシグニ1体が場に出たとき」は CHOOSE のまま');
  ok(s.includes('CHOOSE'), '本体は3択のまま');
});

// ── §5d-0 (ii) 2026-08-18：`cost.energyTrash` の集合制約が「捕捉されて捨てられて」いた ──
// 🔴parser の regex は5つの言い回しを**捕捉していたのに switch が2つしか写していなかった**ので、
//   「エナゾーンからそれぞれレベルの異なるシグニ３枚をトラッシュに置く」は**同じレベル3枚でも払えた**。
//   さらに UI 側は `size >= count` しか見ておらず、型にあった `selectionConstraint` は**完全な死フラグ**だった。
const energyTrashCostCases = [
  { effectId: 'WD18-001-E2', want: '"distinct":"level"', why: 'それぞれレベルの異なる＜調理＞のシグニ４枚（後置き形）' },
  { effectId: 'WXDi-P09-008-E1', want: '"distinct":"level"', why: 'それぞれレベルの異なるシグニ３枚' },
  { effectId: 'WXDi-P04-028-E3', want: '"distinct":"class"', why: 'それぞれ共通するクラスを持たないシグニ７枚' },
  { effectId: 'WX11-052-E3', want: '"distinct":"name"', why: '名前の異なる＜精元＞のシグニ８枚' },
  { effectId: 'WXK11-047-E3', want: '"distinct":"name"', why: 'それぞれ名前の異なる《サーバント》１５枚' },
  { effectId: 'WXK09-052-E2', want: '"distinct":"level"', why: 'レベル１～４のシグニを1枚ずつ＝各レベル1枚' },
  { effectId: 'WXK10-050-E2', want: '"distinct":"level"', why: 'レベル１～４のシグニを1枚ずつ＝各レベル1枚' },
] as const;
for (const spec of energyTrashCostCases) {
  test(`§5d-0(ii) live ${spec.effectId}: energyTrash コストに集合制約が載る（${spec.why}）`, () => {
    let cardNum: string | undefined;
    for (let i = spec.effectId.length; i > 0; i--) {
      const cand = spec.effectId.slice(0, i);
      if (effectsMap.has(cand)) { cardNum = cand; break; }
    }
    const eff = (effectsMap.get(cardNum ?? '') ?? []).find(e => e.effectId === spec.effectId);
    ok(!!eff, `${spec.effectId}: live 効果が存在`);
    if (!eff) return;
    const s = JSON.stringify(eff.cost?.energyTrash ?? {});
    ok(s.includes(spec.want), `原文の集合制約 ${spec.want}（実際 ${s}）`);
  });
}

test('§5d-0(ii) energyTrashCostSatisfied: 枚数を満たしても制約違反なら払えない', () => {
  const lv1a = findCard(c => isSigni(c) && c.Level === '1');
  const lv1b = findCard(c => isSigni(c) && c.Level === '1' && c.CardNum !== lv1a);
  const lv2 = findCard(c => isSigni(c) && c.Level === '2');
  const energy = [lv1a, lv1b, lv2];
  const cm = cardMap as Map<string, CardData>;
  const spec = { count: 2, selectionConstraint: { distinct: 'level' as const } };
  ok(!energyTrashCostSatisfied(energy, new Set([0, 1]), spec, cm), '🔴同レベル2枚は払えない');
  ok(energyTrashCostSatisfied(energy, new Set([0, 2]), spec, cm), 'レベルが異なれば払える');
  ok(!energyTrashCostSatisfied(energy, new Set([0]), spec, cm), '枚数不足は払えない');
  // 制約が無いコストは従来どおり枚数だけで判定する（既存挙動を変えない）
  ok(energyTrashCostSatisfied(energy, new Set([0, 1]), { count: 2 }, cm), '制約なしは同レベル2枚でも払える');
  ok(energyTrashCostSatisfied(energy, new Set(), undefined, cm), 'コスト自体が無ければ常に true');
});

test('§5d-0(ii) canAddEnergyTrashIndex: 制約を壊す組み合わせは選べない（選ばせてから赤くしない）', () => {
  const lv1a = findCard(c => isSigni(c) && c.Level === '1');
  const lv1b = findCard(c => isSigni(c) && c.Level === '1' && c.CardNum !== lv1a);
  const lv2 = findCard(c => isSigni(c) && c.Level === '2');
  const energy = [lv1a, lv1b, lv2];
  const cm = cardMap as Map<string, CardData>;
  const spec = { count: 2, selectionConstraint: { distinct: 'level' as const } };
  ok(canAddEnergyTrashIndex(energy, new Set(), 0, spec, cm), '1枚目はどれでも選べる');
  ok(!canAddEnergyTrashIndex(energy, new Set([0]), 1, spec, cm), '🔴同レベルの2枚目は選べない');
  ok(canAddEnergyTrashIndex(energy, new Set([0]), 2, spec, cm), '別レベルなら選べる');
  ok(canAddEnergyTrashIndex(energy, new Set([0]), 0, spec, cm), '選択済みの解除は常に可');
  ok(!canAddEnergyTrashIndex(energy, new Set([0, 2]), 1, spec, cm), '枚数上限に達したら選べない');
  ok(!canAddEnergyTrashIndex(energy, new Set(), 0, undefined, cm), 'コスト自体が無ければ選べない');
});

test('§5d-0(ii) 支払いUI3経路すべてが共有判定を通る（1つ落とすとその入口だけ制約なしで払える）', () => {
  // ⚠続き546 の教訓「支払い地点と提示地点は別々に数える」＝モーダルごとに写経されていた
  //   `size >= count` を1本の純関数へ寄せたので、**3ファイルすべてで呼ばれていること**を固定する。
  for (const f of ['SigniActivatedModal', 'LrigGrantedModal', 'SigniOnPlayCostModal']) {
    const src = fs.readFileSync(join(root, `src/screens/battle/modals/${f}.tsx`), 'utf8');
    ok(src.includes('energyTrashCostSatisfied('), `${f}: 支払い可否が共有判定を通る`);
    ok(src.includes('canAddEnergyTrashIndex('), `${f}: 候補の選択可否が共有判定を通る`);
    // 旧実装（写経された枚数比較）が残っていたら、その入口だけ制約を無視して払える
    ok(!/EnergyTrash\.size\s*>=/.test(src), `🔴${f}: 旧 size>=count の写経が残っていない`);
  }
});

// ── §5d-0 (ii) 2026-08-18：盤面状態（覚醒／傀儡）の条件節が丸ごと落ちて無条件発火していた3効果 ──
// 🔴engine は両評価器（`evalCondition` / `checkActiveCondition`）とも `isAwakened`/`isPuppet` を実装済みで、
//   落ちていたのは parser だけ。⚠**「がある場合」形の規則はあったが「あるかぎり」形（＝【常】の
//   activeCondition 経路）に無かった**＝同じ文型なのに一部だけ直らないときは「どの表に居るか」を疑う。
const boardStateCondCases = [
  { effectId: 'WXDi-P14-050-E1', slot: 'activeCondition', want: '"isAwakened":true',
    why: '【常】レベル３の覚醒状態のシグニがあるかぎり→無条件で相手の【ガード】に追加コストを課していた' },
  { effectId: 'WXDi-P14-062-E1', slot: 'activeCondition', want: '"isAwakened":true',
    why: '【常】レベル３の覚醒状態のシグニがあるかぎり→無条件で能力付与していた' },
  { effectId: 'WXK09-061-E1', slot: 'action', want: '"isPuppet":true',
    why: '【出】傀儡状態のシグニがある場合→無条件で−3000していた' },
] as const;
for (const spec of boardStateCondCases) {
  test(`§5d-0(ii) live ${spec.effectId}: 盤面状態の条件節が載る（${spec.why}）`, () => {
    let cardNum: string | undefined;
    for (let i = spec.effectId.length; i > 0; i--) {
      const cand = spec.effectId.slice(0, i);
      if (effectsMap.has(cand)) { cardNum = cand; break; }
    }
    const eff = (effectsMap.get(cardNum ?? '') ?? []).find(e => e.effectId === spec.effectId);
    ok(!!eff, `${spec.effectId}: live 効果が存在`);
    if (!eff) return;
    const s = JSON.stringify(spec.slot === 'activeCondition' ? eff.activeCondition ?? null : eff.action);
    ok(s.includes('HAS_CARD_IN_FIELD') && s.includes(spec.want),
      `${spec.slot} に盤面状態ゲートが載る（実際 ${s.slice(0, 200)}）`);
  });
}

test('§5d-0(ii) engine: 「場に覚醒状態のシグニがあるかぎり」は覚醒していなければ成立しない', () => {
  const eff = (effectsMap.get('WXDi-P14-062') ?? []).find(e => e.effectId === 'WXDi-P14-062-E1');
  ok(!!eff?.activeCondition, 'activeCondition が存在');
  if (!eff?.activeCondition) return;
  const lv3 = findCard(c => isSigni(c) && c.Level === '3');
  const lv3b = findCard(c => isSigni(c) && c.Level === '3' && c.CardNum !== lv3);
  const cm = cardMap as Map<string, CardData>;
  const notAwake = mkState({ signi: [lv3, null, null] });
  ok(!checkActiveCondition(eff.activeCondition, notAwake, mkState({}), true, cm, lv3),
    '🔴覚醒していないレベル3が居るだけでは成立しない（旧実装は無条件成立）');
  const awake = { ...notAwake, awakened_signi: [lv3] };
  ok(checkActiveCondition(eff.activeCondition, awake, mkState({}), true, cm, lv3),
    '覚醒したレベル3が居れば成立');
  // レベル違いは成立しない（原文の「レベル３の」を落としていないことの負方向）
  const lv1 = findCard(c => isSigni(c) && c.Level === '1');
  const awakeWrongLv = { ...mkState({ signi: [lv1, null, null] }), awakened_signi: [lv1] };
  ok(!checkActiveCondition(eff.activeCondition, awakeWrongLv, mkState({}), true, cm, lv1),
    '覚醒していてもレベルが違えば成立しない');
  ok(!!lv3b, '対照カードが引ける');
});

test('§5d-0(ii) engine parity: isPuppet 条件でルリグゾーンを数えない（判定器2つの片方だけ穴が空く型）', () => {
  // ⚠`matchesFilter` は `isPuppet` を見ないので、ルリグ走査へ落ちると**ルリグが「傀儡状態のシグニ」として
  //   数えられる**。`execUtils.evalCondition` は4状態とも除外していたが `effectEngine` 側は3つだけだった。
  const cond: ActiveCondition = { type: 'HAS_CARD_IN_FIELD', owner: 'self', filter: { cardType: 'シグニ', isPuppet: true } };
  const lrig = findCard(c => c.Type === 'ルリグ');
  const signi = findCard(c => isSigni(c));
  const cm = cardMap as Map<string, CardData>;
  const onlyLrig = mkState({ lrig: [lrig], signi: [null, null, null] });
  ok(!checkActiveCondition(cond, onlyLrig, mkState({}), true, cm, signi),
    '🔴ルリグだけの盤面で「傀儡状態のシグニがある」が成立しない');
  const withPuppet = { ...mkState({ lrig: [lrig], signi: [signi, null, null] }),
    field: { ...mkState({ lrig: [lrig], signi: [signi, null, null] }).field, puppet_signi: [signi] } };
  ok(checkActiveCondition(cond, withPuppet, mkState({}), true, cm, signi),
    '傀儡状態のシグニが居れば成立');
});

// ── §5d-0 2026-08-18：【常】先頭の「〜あるかぎり、」が activeCondition ごと落ちて無条件成立していた35効果 ──
// 🔴常在能力のゲートが落ちる＝**基本パワーが常に上書き／常に効果耐性／常にキーワード付与**という重い過剰効果で、
//   しかも構造は正しいので smoke/fuzz/逆翻訳のどれにも映らない。真因は先頭条件節テーブルの**綴りの穴**：
//   ①通常トラッシュのカード種別版が無い（ルリグトラッシュ版はあった）②「が**いる**かぎり」③「このシグニ**は**アクセ」
//   ④＜クラス＞側だけ「の」を飲まない ⑤エナ条件がレベル前置を受けない ⑥チャーム/アップダウン/下カードの綴り無し。
const kagiriCases = [
  { effectId: 'WX14-073-E1', want: '"TRASH_HAS_CARD"', why: 'トラッシュにスペルがあるかぎり基本パワー8000' },
  { effectId: 'WX09-018-E1', want: '"minCount":5', why: 'トラッシュにスペルが5枚以上' },
  { effectId: 'WX24-P1-039-E1', want: '"cardName":"月日の巫女　タマヨリヒメ"', why: '場に《X》が「いる」かぎり' },
  { effectId: 'WX15-038-E1', want: '"IS_SELF_ACCED"', why: 'このシグニ「は」アクセされているかぎり' },
  { effectId: 'WDK12-015-E1', want: '"IS_SELF_CHARMED"', why: 'このシグニに【チャーム】が付いているかぎり' },
  { effectId: 'WXDi-P04-050-E1', want: '"IS_SELF_UP"', why: 'このシグニがアップ状態であるかぎり' },
  { effectId: 'WXDi-P08-059-E1', want: '"IS_SELF_DOWN"', why: 'このシグニがダウン状態であるかぎり' },
  { effectId: 'WXDi-P10-059-E1', want: '"isFrozen":true', why: '対戦相手の場に凍結状態のシグニがあるかぎり' },
  { effectId: 'WX19-021-E1', want: '"story":"ウェポン"', why: '場に＜C＞の（←「の」）シグニがあるかぎり' },
  { effectId: 'WXK09-082-E1', want: '"ENERGY_HAS_CARD"', why: 'エナにレベル4の＜電機＞のシグニがあるかぎり' },
  { effectId: 'WXK08-085-E1', want: '"THIS_CARD_HAS_UNDER"', why: 'このシグニの下にカードがあるかぎり' },
] as const;
for (const spec of kagiriCases) {
  test(`§5d-0 live ${spec.effectId}: 【常】のゲートが activeCondition に載る（${spec.why}）`, () => {
    let cardNum: string | undefined;
    for (let i = spec.effectId.length; i > 0; i--) {
      const cand = spec.effectId.slice(0, i);
      if (effectsMap.has(cand)) { cardNum = cand; break; }
    }
    const eff = (effectsMap.get(cardNum ?? '') ?? []).find(e => e.effectId === spec.effectId);
    ok(!!eff, `${spec.effectId}: live 効果が存在`);
    if (!eff) return;
    ok(!!eff.activeCondition, '🔴activeCondition が落ちていない（落ちると常時発動＝重い過剰効果）');
    const s = JSON.stringify(eff.activeCondition ?? null);
    ok(s.includes(spec.want), `原文どおりのゲート ${spec.want}（実際 ${s}）`);
  });
}

test('§5d-0 engine: IS_SELF_UP はアップのときだけ成立し、場に居ないときは成立しない', () => {
  const signi = findCard(c => isSigni(c));
  const cm = cardMap as Map<string, CardData>;
  const up = mkState({ signi: [signi, null, null] });
  ok(checkActiveCondition({ type: 'IS_SELF_UP' } as ActiveCondition, up, mkState({}), true, cm, signi), 'アップなら成立');
  const down = { ...up, field: { ...up.field, signi_down: [true, false, false] } };
  ok(!checkActiveCondition({ type: 'IS_SELF_UP' } as ActiveCondition, down, mkState({}), true, cm, signi), 'ダウンなら不成立');
  // ⚠場に居ない効果元で「ダウンしていない＝アップ」に倒すと、離場後も常時成立してしまう
  ok(!checkActiveCondition({ type: 'IS_SELF_UP' } as ActiveCondition, mkState({}), mkState({}), true, cm, signi),
    '🔴場に居なければ不成立（ダウン判定の単純反転にしない）');
  ok(!checkActiveCondition({ type: 'IS_SELF_UP' } as ActiveCondition, up, mkState({}), true, cm, undefined),
    '効果元が特定できなければ不成立');
});

test('§5d-0 engine: TRASH_HAS_CARD{cardType:スペル} が枚数どおり成立/不成立する', () => {
  const eff = (effectsMap.get('WX09-018') ?? []).find(e => e.effectId === 'WX09-018-E1');
  ok(!!eff?.activeCondition, 'activeCondition が存在');
  if (!eff?.activeCondition) return;
  const spell = findCard(c => c.Type === 'スペル');
  const spell2 = findCard(c => c.Type === 'スペル' && c.CardNum !== spell);
  const signi = findCard(c => isSigni(c));
  const cm = cardMap as Map<string, CardData>;
  const mk = (trash: string[]) => ({ ...mkState({ signi: [signi, null, null] }), trash });
  ok(!checkActiveCondition(eff.activeCondition, mk([]), mkState({}), true, cm, signi),
    '🔴トラッシュが空なら成立しない（旧実装は無条件成立）');
  ok(!checkActiveCondition(eff.activeCondition, mk([spell, spell2, spell, spell2]), mkState({}), true, cm, signi),
    'スペル4枚では5枚以上を満たさない');
  ok(checkActiveCondition(eff.activeCondition, mk([spell, spell2, spell, spell2, spell]), mkState({}), true, cm, signi),
    'スペル5枚で成立');
  ok(!checkActiveCondition(eff.activeCondition, mk([signi, signi, signi, signi, signi]), mkState({}), true, cm, signi),
    'シグニ5枚では成立しない（cardType が効いている）');
});


// ── §8／§6.4 O-1: CPU のメインフェイズ【起】能動使用（続き551）──────────────────────
// ⚠**人間のボタン生成と CPU の候補フィルタは同じ関数**（`listActivatableSigniEffects`）＝
//   ここが割れると「人間には見えない【起】を CPU だけが撃つ」型の無言のズレになる。
const mkAct = (id: string, extra: Partial<CardEffect> = {}): CardEffect => ({
  effectId: id, effectType: 'ACTIVATED', duration: 'INSTANT', timing: ['MAIN'],
  action: { type: 'DRAW', owner: 'self', count: 1 },
  ...extra,
} as CardEffect);

test('O-1 signiActivateGate: 【起】の提示は timing・能力喪失・使用制限・costUnparsed で切れる', () => withSavedCursor(() => {
  const cm = cardMap as Map<string, CardData>;
  const my = mkState({ signi: [SIGNI, null, null] });
  const op = mkState({});
  const list = (effs: CardEffect[], state: PlayerState = my, phase: 'MAIN' | 'ATTACK_ARTS' = 'MAIN') =>
    listActivatableSigniEffects({
      my: state, op, zoneIndex: 0, phase, isMyTurn: true,
      effectsMap: new Map([[SIGNI, effs]]), cardMap: cm,
    }).map(e => e.effectId);
  eq(list([mkAct('T-ACT1')]).join(','), 'T-ACT1', '素の盤面では提示される');
  eq(list([mkAct('T-ACT1')], my, 'ATTACK_ARTS').length, 0, '《アタックフェイズアイコン》無しはアタックフェイズに出ない');
  eq(list([mkAct('T-ACT1', { timing: ['ATTACK_ARTS'] })], my, 'ATTACK_ARTS').join(','), 'T-ACT1', 'アイコン付きはアタックフェイズに出る');
  eq(list([mkAct('T-ACT1')], { ...my, abilities_removed: [SIGNI] }).length, 0, '能力を失っていれば提示しない');
  eq(list([mkAct('T-ACT1')], { ...my, blocked_actions: ['USE_ACT'] }).length, 0, 'USE_ACT 封じ');
  eq(list([mkAct('T-ACT1')], { ...my, blocked_actions: ['T-ACT1'] }).length, 0, 'effectId 名指しの封じ');
  eq(list([mkAct('T-ACT1', { usageLimit: 'once_per_turn' })], { ...my, actions_done: ['T-ACT1'] }).length, 0, '《ターン1回》消化済み');
  eq(list([mkAct('T-ACT1', { usageLimit: 'once_per_game' })], { ...my, game_actions_done: ['T-ACT1'] }).length, 0, '《ゲーム1回》消化済み');
  // 🔴コストを表現できていない効果を提示すると**コストを踏み倒して撃てる**（§6.4 O-11）
  eq(list([mkAct('T-ACT1', { costUnparsed: true } as Partial<CardEffect>)]).length, 0, '🔴costUnparsed は提示しない');
  eq(list([mkAct('T-ACT1', { cost: { down_self: true } })], { ...my, field: { ...my.field, signi_down: [true, false, false] } }).length, 0,
    'ダウン済みでは down_self コストを払えない');
  eq(list([mkAct('T-ACT1', { cost: { discard: 3 } })], mkState({ signi: [SIGNI, null, null], hand: 2 })).length, 0, '手札不足では提示しない');
}));

test('O-1 cpuActivate: 支払い内訳が要るコストは CPU が撃たない（allowlist・未知キーは撃たない側へ倒れる）', () => withSavedCursor(() => {
  const st = mkState({ signi: [SIGNI, null, null], coins: 1 });
  const can = (cost: Record<string, unknown>, state: PlayerState = st) =>
    cpuCanAutoPayActivatedCost(mkAct('T', { cost: cost as never }), state, SIGNI);
  ok(can({}), 'コストなしは撃てる');
  ok(can({ energy: [{ color: '赤', count: 1 }] }), 'エナは内訳を自動で決められる');
  ok(can({ down_self: true }), 'down_self は自動支払い');
  ok(can({ lrigDown: { count: 1 } }), 'lrigDown は自動支払い');
  ok(!can({ discard: 1 }), '🔴手札の何を捨てるかは盤面評価＝撃たない');
  ok(!can({ discardVariable: { min: 1 } }), '可変手札捨ては撃たない');
  ok(!can({ fieldTrash: { count: 1 } }), '場のどのシグニを捨てるかは撃たない');
  ok(!can({ beat_signi: 1 }), '【ビート】選択は撃たない');
  ok(!can({ underSelfTrash: { count: 1 } }), '下カード選択は撃たない');
  ok(!can({ energyTrash: { count: 1 } }), 'エナ指定トラッシュは撃たない');
  ok(!can({ trashExile: { count: 1 } }), 'トラッシュ除外（選択あり）は撃たない');
  ok(can({ trashExile: { self: true } }), 'trashExile.self は自動');
  // 🔴allowlist であることの固定＝新しいコストキーが増えても「撃たない」側へ倒れる
  ok(!can({ handToEnergy: { count: 1 } }), '🔴allowlist に無いキーは撃たない');
  ok(!CPU_AUTO_PAYABLE_COST_KEYS.has('discard'), 'allowlist に手札捨ては含めない');
  ok(!can({ coin: 4 }), 'コイン不足では撃たない');
  ok(can({ coin: 1 }), 'コインが足りれば撃てる');
}));

test('O-1 cpuActivate: エナコストの支払い index は色を先に充当し、払えなければ null', () => withSavedCursor(() => {
  const allCards = [...cardMap.values()];
  const red = findCard(c => isSigni(c) && (c.Color ?? '') === '赤');
  const blue = findCard(c => isSigni(c) && (c.Color ?? '') === '青');
  const isAffordable = (nums: string[], costStr: string) => canAffordGrowCost(nums, allCards, costStr);
  const pick = (poolNums: string[], costStr: string) =>
    selectEnergyIndicesForCost({ poolNums, cards: allCards, costStr, isAffordable });
  eq(pick([red, blue], '')?.size, 0, 'コスト0は空の選択で成立');
  const p1 = pick([blue, red], '《赤》×1');
  ok(!!p1 && p1.size === 1 && [...p1][0] === 1, '🔴色指定は該当色から取る（先頭の別色で潰さない）');
  const p2 = pick([blue, red], '《無》×1');
  ok(!!p2 && p2.size === 1, '《無》は先頭から1枚');
  eq(pick([blue], '《赤》×1'), null, '払えなければ null（撃たない）');
  eq(pick([], '《無》×1'), null, 'エナが無ければ null');
  const p3 = pick([red, blue, red], '《赤》×2《無》×1');
  ok(!!p3 && p3.size === 3, '色2＋無1は3枚');
}));

test('O-1 cpuActivate: CPU の【起】選択は「撃てる・自動で払える・未使用」の3条件をすべて満たす1件', () => withSavedCursor(() => {
  const allCards = [...cardMap.values()];
  const cm = cardMap as Map<string, CardData>;
  const actor = mkState({ signi: [SIGNI, SIGNI_P3000, null], energy: 0 });
  const opponent = mkState({});
  const isAffordable = (nums: string[], costStr: string) => canAffordGrowCost(nums, allCards, costStr);
  const pickFor = (effs: Map<string, CardEffect[]>, already: string[] = [], state: PlayerState = actor) =>
    pickCpuSigniActivated({
      actor: state, opponent, effectsMap: effs, cardMap: cm, cards: allCards,
      phase: 'MAIN', energyPoolNums: state.energy, alreadyActivated: already, isAffordable,
    });
  const free = new Map<string, CardEffect[]>([[SIGNI, [mkAct('Z-FREE')]]]);
  eq(pickFor(free)?.effect.effectId, 'Z-FREE', 'コストなしの【起】を選ぶ');
  eq(pickFor(free, ['Z-FREE']), null, '🔴同じ効果はこのターン撃ち直さない（無限ループ防止）');
  // 支払えないコストの効果しか無ければ何も選ばない＝現状（何もしない）と同じ安全側
  const paid = new Map<string, CardEffect[]>([[SIGNI, [mkAct('Z-DISCARD', { cost: { discard: 1 } })]]]);
  eq(pickFor(paid), null, '支払い内訳の要る【起】は選ばない');
  // ゾーン順の決定論＝ゾーン0が撃てなければゾーン1へ進む
  const twoZones = new Map<string, CardEffect[]>([
    [SIGNI, [mkAct('Z-DISCARD', { cost: { discard: 1 } })]],
    [SIGNI_P3000, [mkAct('Z-FREE2')]],
  ]);
  const got = pickFor(twoZones);
  eq(got?.effect.effectId, 'Z-FREE2', 'ゾーン0が不可ならゾーン1から選ぶ');
  eq(got?.zoneIndex, 1, 'ゾーン index が返る');
  // エナコスト：足りなければ選ばず、足りれば index つきで返る
  const enaEff = new Map<string, CardEffect[]>([[SIGNI, [mkAct('Z-ENA', { cost: { energy: [{ color: '無', count: 2 }] } })]]]);
  eq(pickFor(enaEff), null, 'エナ0では選ばない');
  const rich = { ...actor, energy: [SIGNI_L1, SIGNI_L2] } as PlayerState;
  const gotEna = pickFor(enaEff, [], rich);
  eq(gotEna?.costIndices.size, 2, 'エナ2枚ぶんの index が返る');
  eq(activatedEnergyCostStr(mkAct('x', { cost: { energy: [{ color: '赤', count: 2 }] } })), '《赤》×2', 'コスト文字列は《色》×N 形式（parseGrowCost が読める唯一の綴り）');
  // 🆕続き552c＝窓が2つになった（`MAIN` と `ATTACK_ARTS`）。判定は同じ gate で `phase` だけが違う。
  const pickPhase = (effs: Map<string, CardEffect[]>, phase: 'MAIN' | 'ATTACK_ARTS') =>
    pickCpuSigniActivated({
      actor, opponent, effectsMap: effs, cardMap: cm, cards: allCards,
      phase, energyPoolNums: actor.energy, alreadyActivated: [], isAffordable,
    });
  const iconEff = new Map<string, CardEffect[]>([[SIGNI, [mkAct('Z-ICON', { timing: ['ATTACK_ARTS'] })]]]);
  eq(pickPhase(iconEff, 'MAIN'), null, '🔴《アタックフェイズアイコン》付きはメイン窓では撃たない');
  eq(pickPhase(iconEff, 'ATTACK_ARTS')?.effect.effectId, 'Z-ICON', 'アタック窓では撃つ');
  eq(pickPhase(free, 'ATTACK_ARTS'), null, '対照：無印【起】はアタック窓では撃たない');
}));

// ── §8／§6.4 `O-1` (a)：CPU が相手のアタックフェイズに応答アーツで守る ──────────────
const ART_RED = findCard(c => isSigni(c) && (c.Color ?? '') === '赤');
const mkArts = (o: Partial<CardData> = {}): CardData => ({
  CardNum: 'T-ARTS-1', CardName: 'テストアーツ', Type: 'アーツ', Cost: '《赤》×1',
  Timing: 'アタックフェイズ', Color: '赤', Restriction: '', EffectText: '', Level: '', Power: '',
  CardClass: '', ImgURL: '', ...o,
} as unknown as CardData);
const mkArtsEff = (action: unknown, extra: Partial<CardEffect> = {}): CardEffect => ({
  effectId: 'T-ARTS-1-E1', effectType: 'ACTIVATED', duration: 'INSTANT', mandatory: false,
  action: action as never, ...extra,
} as CardEffect);
/** 合成アーツを載せた cardMap / effectsMap と、その支払い ctx を1回で組む。 */
const artsFixture = (p: {
  card?: Partial<CardData>; effs?: CardEffect[];
  actor?: PlayerState; opponent?: PlayerState;
  /** 自ターンの窓を組むときに渡す（既定＝相手ターンの応答窓）。 */
  turnPhase?: TurnPhase; isActorTurn?: boolean;
}) => {
  const card = mkArts(p.card);
  const cm = new Map(cardMap) as Map<string, CardData>;
  cm.set(card.CardNum, card);
  const em = new Map(effectsMap);
  em.set(card.CardNum, p.effs ?? [mkArtsEff({ type: 'NEGATE_ATTACK', target: { type: 'SIGNI', owner: 'opponent', count: 1 } })]);
  const actor = p.actor ?? ({ ...mkState({ energy: 0 }), lrig_deck: [card.CardNum], energy: [ART_RED] } as PlayerState);
  const opponent = p.opponent ?? mkState({ signi: [SIGNI, null, null] });
  const payer = buildArtsPayerCtx({
    actor, opponent, isActorTurn: p.isActorTurn ?? false,
    turnPhase: p.turnPhase ?? 'ATTACK_ARTS_OP', cardMap: cm, effectsMap: em,
  });
  return { card, cm, em, actor, opponent, payer };
};

test('O-1 artsUseGate: アーツの提示は限定・フェイズ/Timing・ARTS_LIMIT_1・使用条件・支払いで切れる', () => withSavedCursor(() => {
  const allCards = [...cardMap.values()];
  const check = (o: Parameters<typeof artsFixture>[0], turnPhase: TurnPhase = 'ATTACK_ARTS_OP', isMyTurn = false) => {
    const f = artsFixture(o);
    return checkArtsUse({
      card: f.card, my: f.actor, op: f.opponent, isMyTurn, turnPhase,
      cards: allCards, cardMap: f.cm, effectsMap: f.em, payer: f.payer,
    });
  };
  ok(check({}).usable, '素の盤面（相手ターンのアーツステップ）では使える');
  eq(check({}).effectiveCost, '《赤》×1', '請求額は印刷コスト');
  eq(check({}).effectiveCostForModal, null, '印刷コストから動いていなければ支払いUIへ持ち込まない');
  ok(!check({}, 'MAIN', false).usable, '相手のメインフェイズには使えない');
  ok(!check({}, 'ATTACK_ARTS_OP', true).usable, '🔴自分がターンプレイヤーなら ATTACK_ARTS_OP は自分の窓ではない');
  ok(!check({ card: { Timing: 'メインフェイズ' } }).usable, 'CSV Timing にアタックフェイズが無ければ使えない');
  // 「〇〇限定」＝実効ルリグクラスで見る（センタールリグを置いた盤面で対照を取る）。
  const lrigNum = findCard(c => c.Type === 'ルリグ' && !!(c.CardClass ?? '').trim());
  const lrigClass0 = (cardMap.get(lrigNum)?.CardClass ?? '').split(/[/／]/)[0].trim();
  const withLrig = (restriction: string) => check({
    card: { Restriction: restriction },
    actor: { ...mkState({ energy: 0, lrig: [lrigNum] }), lrig_deck: ['T-ARTS-1'], energy: [ART_RED] } as PlayerState,
  });
  ok(withLrig(`${lrigClass0}限定`).usable, '対照：ルリグクラスが合えば使える');
  ok(!withLrig('#限定').usable, '「〇〇限定」はルリグクラスが合わなければ使えない');
  const mkActor = (extra: Partial<PlayerState>) =>
    ({ ...mkState({ energy: 0 }), lrig_deck: ['T-ARTS-1'], energy: [ART_RED], ...extra } as PlayerState);
  ok(!check({ actor: mkActor({ energy: [] }) }).usable, 'エナが無ければ使えない');
  ok(!check({ actor: mkActor({ blocked_actions: ['USE_ARTS'] }) }).usable, 'USE_ARTS 封じ');
  // 🔴`ARTS_LIMIT_1`＝「対戦相手は各ターンに一度しかアーツを使用できない」（§6.4 O-10 続き512）
  ok(check({ actor: mkActor({ blocked_actions: ['ARTS_LIMIT_1'] }) }).usable, 'ARTS_LIMIT_1 でも1枚目は使える');
  ok(!check({ actor: mkActor({ blocked_actions: ['ARTS_LIMIT_1'], actions_done: ['USE_ARTS'] }) }).usable, '🔴ARTS_LIMIT_1 は2枚目を止める');
  // カード名指定の使用封じ（§6.4 O-3）
  ok(!check({ actor: mkActor({ blocked_card_names: ['テストアーツ'] }) }).usable, 'カード名指定の封じ');
}));

test('O-1 artsUseGate: 相手ターンの代替コスト（altCostOppTurn）がそのまま請求額になる', () => withSavedCursor(() => {
  const allCards = [...cardMap.values()];
  // 🔴従来この読み替えは**ルリグデッキのカード詳細だけ**にあり、コスト計算の入口が分かれていた
  //   （PLAN §4 教訓 (d)）。gate へ集約した今は CPU の応答アーツも同じ請求額を見る。
  const effs = [mkArtsEff(
    { type: 'NEGATE_ATTACK', target: { type: 'SIGNI', owner: 'opponent', count: 1 } },
    { altCostOppTurn: [{ color: '無', count: 1 }] } as Partial<CardEffect>,
  )];
  const f = artsFixture({ card: { Cost: '《赤》×3' }, effs });
  const args = {
    card: f.card, my: f.actor, op: f.opponent, cards: allCards,
    cardMap: f.cm, effectsMap: f.em, payer: f.payer,
  };
  const onOppTurn = checkArtsUse({ ...args, isMyTurn: false, turnPhase: 'ATTACK_ARTS_OP' as TurnPhase });
  eq(onOppTurn.effectiveCost, '《無》×1', '相手ターンは代替コストが請求額');
  eq(onOppTurn.effectiveCostForModal, '《無》×1', '支払いUIにも代替コストを持ち込む');
  ok(onOppTurn.usable, 'エナ1枚で払えるので使える');
  // 対照＝自分のターンなら代替コストは効かない（印刷コスト《赤》×3 はエナ1枚では払えない）。
  const onOwnTurn = checkArtsUse({ ...args, isMyTurn: true, turnPhase: 'ATTACK_ARTS' as TurnPhase });
  eq(onOwnTurn.effectiveCost, '《赤》×3', '自分のターンは印刷コスト');
  ok(!onOwnTurn.usable, '対照：印刷コストは払えない');
}));

test('O-1 cpuArts: 守りの分類は「無効化→除去→軽減」で、STUB と自分対象は数えない', () => withSavedCursor(() => {
  const kind = (a: unknown) => defensiveKindOf(a as never);
  eq(kind({ type: 'NEGATE_ATTACK', target: { type: 'SIGNI', owner: 'opponent' } }), 'negate', 'アタック無効化は最優先');
  eq(kind({ type: 'BANISH', target: { type: 'SIGNI', owner: 'opponent', count: 1 } }), 'removal', '相手シグニのバニッシュは除去');
  eq(kind({ type: 'DOWN', target: { type: 'SIGNI', owner: 'opponent', count: 1 } }), 'removal', 'ダウンもアタックを止める');
  eq(kind({ type: 'PREVENT_DAMAGE', owner: 'self', until: 'TURN_END' }), 'prevent', 'ダメージ軽減は守り');
  eq(kind({ type: 'BANISH', target: { type: 'SIGNI', owner: 'self', count: 1 } }), null, '🔴自分のシグニを飛ばす効果は守りではない');
  eq(kind({ type: 'BANISH', target: { type: 'LRIG', owner: 'opponent', count: 1 } }), null, 'シグニ以外の対象は除去に数えない');
  eq(kind({ type: 'DRAW', owner: 'self', count: 1 }), null, 'ドローは守りではない');
  eq(kind({ type: 'STUB', id: 'SOMETHING_DEFENSIVE' }), null, '🔴STUB は id ごとに意味が違う＝機械的に守りと決めつけない');
  // 入れ子（SEQUENCE / CHOOSE）も歩いて、より優先度の高い分類を採る。
  eq(kind({ type: 'SEQUENCE', steps: [{ type: 'DRAW', owner: 'self', count: 1 }, { type: 'NEGATE_ATTACK', target: { type: 'SIGNI', owner: 'opponent' } }] }), 'negate', '入れ子の無効化を拾う');
  eq(kind({ type: 'CHOOSE', choices: [{ action: { type: 'PREVENT_DAMAGE', owner: 'self', until: 'TURN_END' } }, { action: { type: 'BANISH', target: { type: 'SIGNI', owner: 'opponent', count: 1 } } }] }), 'removal', '選択肢のうち優先度の高い分類を採る');
}));

test('O-1 cpuArts: 脅威判定は「正面が空いたアップの相手シグニ」か「ライフ1枚以下」', () => withSavedCursor(() => {
  // 相手ゾーン0の正面は自分ゾーン2（engine 共通規約の facing ＝ 2 - zi）。
  const attacker = mkState({ signi: [SIGNI, null, null] });
  ok(hasIncomingThreat(mkState({}), attacker), '正面が空いていればライフクラッシュが通る＝守る');
  ok(!hasIncomingThreat(mkState({ signi: [null, null, SIGNI] }), attacker), '正面が埋まっていれば（この判定では）脅威なし');
  ok(hasIncomingThreat(mkState({ signi: [SIGNI, null, null] }), attacker), '🔴正面はゾーン2＝同じ番号のゾーン0を埋めても止まらない');
  ok(!hasIncomingThreat(mkState({}), mkState({})), '相手にシグニがいなければ脅威なし');
  ok(!hasIncomingThreat(mkState({}), mkState({ signi: [SIGNI, null, null], down: [true, false, false] })), 'ダウン状態はアタックできない');
  ok(hasIncomingThreat(mkState({ life: 1 }), mkState({})), '🔴ライフ1枚以下は常に守る（CPU はガードしないので詰む）');
}));

test('O-1 cpuArts: CPU は「守りの札・エナだけで払える・未使用」の3条件を満たす1枚を選ぶ', () => withSavedCursor(() => {
  const allCards = [...cardMap.values()];
  const pick = (o: Parameters<typeof artsFixture>[0], already: string[] = []) => {
    const f = artsFixture(o);
    return pickCpuResponseArts({
      actor: f.actor, opponent: f.opponent, cards: allCards, cardMap: f.cm, effectsMap: f.em,
      payer: f.payer, turnPhase: 'ATTACK_ARTS_OP', alreadyUsedNums: already,
      isAffordable: (nums, costStr, extra) => canAffordWithExtraCost(nums, allCards, costStr, extra),
    });
  };
  const got = pick({});
  eq(got?.card.CardNum, 'T-ARTS-1', '守りのアーツを選ぶ');
  eq(got?.kind, 'negate', '分類が返る');
  eq(got?.costIndices.size, 1, 'エナ1枚ぶんの index が返る');
  eq(pick({}, ['T-ARTS-1']), null, '🔴このターン使った札は選び直さない（応答窓で止まらないための安全弁）');
  eq(pick({ opponent: mkState({}) }), null, '脅威が無ければ使わない（開幕に撃ち尽くさない）');
  eq(pick({ effs: [mkArtsEff({ type: 'DRAW', owner: 'self', count: 2 })] }), null, '守りでないアーツは使わない');
  eq(pick({ effs: [mkArtsEff(
    { type: 'NEGATE_ATTACK', target: { type: 'SIGNI', owner: 'opponent', count: 1 } },
    { cost: { discard: 1 } } as Partial<CardEffect>,
  )] }), null, '🔴効果側コスト（手札を捨てる等）があれば内訳に盤面評価が要る＝使わない');
  const payOnly = (cost?: Record<string, unknown>) =>
    cpuCanPayArtsWithEnergyOnly([mkArtsEff({ type: 'DRAW', owner: 'self', count: 1 }, { cost } as Partial<CardEffect>)]);
  ok(payOnly(undefined), 'コストなしはエナだけで払える');
  ok(payOnly({ energy: [{ color: '赤', count: 1 }] }), 'エナ宣言（CSV Cost の写し）は払える');
  ok(!payOnly({ discard: 1 }), 'discard コストがあれば false');
  // 🔴allowlist は `energy` 1本＝**`performArts` はエナ以外の宣言コストを払わない**ので、
  //   シグニ【起】で自動支払いできるキーを足すと「宣言だけして踏み倒す」ことになる。
  ok(!payOnly({ down_self: true }), '🔴down_self はアーツでは払われない＝使わない側へ倒す');
  ok(!payOnly({ lrigDown: { count: 1 } }), '🔴lrigDown も同じ（allowlist に足さない）');
}));

